window.MTEC_ARCHIVE = {"_info": {"beschreibung": "News & Leaks-Archiv: Einträge, die älter als 7 Tage sind. Bilder werden beim Archivieren gelöscht (Text bleibt).", "regel": "älter als 7x24 h ab 'datum'; der Ticker behält mindestens die 4 neuesten Einträge", "stand": "2026-11-21T07:27:43.699Z", "zeitzone": "Europe/Vienna"}, "eintraege": [{"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.417Z"}, "id": "2026-11-14-wine-11-22-avx-arm", "datum": "2026-11-14T02:35:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux"], "kategorie": "Software", "titel": "Wine 11.22 emuliert AVX auf ARM64 und behebt 34 Fehler, unter anderem in Guild Wars 2 und Star Citizen", "schlagzeile": "Wine 11.22: Windows-Programme mit AVX laufen jetzt auch auf ARM", "kurz": "Die Entwicklerversion Wine 11.22 kann AVX-Befehle in der x86-Emulation auf ARM64 nachbilden. Damit laufen mehr moderne Windows-Programme auf ARM-Rechnern unter Linux. Dazu kommen 34 Fehlerkorrekturen, auch für Spiele.", "zusammenfassung": "Das Wine-Projekt hat die Entwicklerversion 11.22 veröffentlicht. Wichtigste Neuerung ist laut Phoronix die Unterstützung von AVX-Befehlen in der x86-Emulation unter ARM64. Viele moderne Windows-Programme setzen AVX voraus und liefen bisher auf ARM-Systemen mit Wine nicht oder nur eingeschränkt. Mit ARM64EC-Builds lassen sich diese Befehle jetzt emulieren. Das ist vor allem für Linux auf ARM-Rechnern interessant. Außerdem aktualisiert Wine 11.22 die Sprachdaten auf Unicode CLDR 49, führt eine Zufallsverteilung des Adressraums ein und verbessert die Darstellung der Schrift Tahoma. Insgesamt behebt die Version 34 bekannte Fehler, unter anderem in Guild Wars 2, Star Citizen und der Logos Bible Software. Wine ist die Grundlage von Valves Proton, mit dem Windows-Spiele unter Linux und auf dem Steam Deck laufen. Neuerungen aus Wine landen aber erst mit der Zeit in Proton. Es handelt sich um eine Entwicklerversion; die stabile Version Wine 12.0 wird für Anfang 2027 vorbereitet.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Wine-11.22-Released"}, "weitere_links": [], "tags": ["Wine", "Linux", "ARM64", "AVX", "Proton"], "archiviert_am": "2026-11-21T07:27:43.693Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.290Z"}, "id": "2026-11-14-windows11-neuer-ausfuehren", "datum": "2026-11-14T02:30:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Windows 11 bekommt im Dezember den neuen Ausführen-Dialog, der Durchsuchen-Knopf fällt weg", "schlagzeile": "Win+R wird modern: Neuer Ausführen-Dialog kommt im Dezember für alle", "kurz": "Der neu gestaltete Ausführen-Dialog von Windows 11 ist im Release-Preview-Kanal angekommen. Er soll mit dem Patchday am 8. Dezember auf alle PCs mit 25H2 und 26H2 kommen. Der alte Dialog bleibt per Schalter verfügbar.", "zusammenfassung": "Microsoft bringt den modernisierten Ausführen-Dialog (Win+R) zu allen Windows-11-Nutzern. Laut Windows Latest steckt er jetzt in den Release-Preview-Builds 26200.10066 (25H2) und 26300.10066 (26H2). Normalerweise folgt darauf Ende des Monats ein optionales Update und am 8. Dezember die Verteilung an alle per Patchday. Die Einführung erfolgt schrittweise, nicht jeder PC bekommt den Dialog sofort. Der neue Dialog basiert auf WinUI 3, unterstützt den Dark Mode und öffnet laut Microsoft im Mittel in 94 Millisekunden statt 103 Millisekunden beim alten. Der Knopf „Durchsuchen“ fällt weg: Laut Microsoft hat ihn in einer Stichprobe von 35 Millionen Nutzern nur 0,0038 Prozent je angeklickt. Pfade lassen sich weiter eintippen, und die neue Abkürzung ~\\ springt in den Benutzerordner. Frühere Befehle erscheinen über dem Eingabefeld und lassen sich mit den Pfeiltasten durchblättern. Wer den alten Dialog lieber mag, schaltet unter Einstellungen > System > Erweitert zurück. Microsoft will nach und nach weitere alte Dialoge auf WinUI 3 umstellen, etwa die Eigenschaften im Datei-Explorer.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/14/windows-11s-modern-run-box-arrives-for-everyone-in-december-and-microsoft-found-almost-nobody-ever-clicked-browse-in-the-old-one/"}, "weitere_links": [{"name": "Windows Insider Blog", "url": "https://blogs.windows.com/windows-insider/2026/11/13/announcing-new-builds-for-13-november-2026/"}], "tags": ["Windows 11", "Ausführen", "WinUI 3", "Release Preview"], "archiviert_am": "2026-11-21T07:27:43.693Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.938Z"}, "id": "2026-11-14-blade-runner-aaa-spiel", "datum": "2026-11-14T00:49:00+01:00", "label": "News", "bereich": "games", "themen": ["Blade Runner"], "kategorie": "Spiele", "titel": "Blade-Runner-Rechteinhaber Alcon spricht über ein AAA-Videospiel zur Filmreihe", "schlagzeile": "Blade Runner als AAA-Spiel? Rechteinhaber bestätigt Gespräche", "kurz": "Alcon Entertainment, Besitzer der Blade-Runner-Marke, führt Gespräche über ein großes AAA-Spiel. Das bestätigten die beiden Alcon-Chefs im Gespräch mit IGN. Details wie Studio, Plattformen oder Termin gibt es noch nicht.", "zusammenfassung": "Die Filmreihe Blade Runner könnte ein großes Videospiel bekommen. Andrew Kosove und Broderick Johnson, die Chefs des Rechteinhabers Alcon Entertainment, haben laut IGN bestätigt, dass es Gespräche über ein AAA-Spiel gibt. Die Aussage fiel in einem Interview zur neuen Serie Blade Runner 2099, die am 25. November bei Prime Video startet. Auf die Frage, warum es nach dem Erfolg von Cyberpunk 2077 kein großes Blade-Runner-Spiel gibt, antwortete Kosove mit „Ja“ und betonte ausdrücklich das „AAA“. Spieler sollen mit der Welt von Blade Runner interagieren können. Mehr wollte er nicht verraten. Ein Entwicklerstudio, Plattformen oder ein Zeitraum sind damit nicht bekannt, und Gespräche bedeuten noch kein angekündigtes Spiel. Die Marke hat bisher wenig Glück mit Spielen: Als Klassiker gilt nur das Adventure von Westwood aus dem Jahr 1997, das 2022 ein Remaster bekam. Das 2023 angekündigte Blade Runner 2033: Labyrinth von Annapurna gilt als eingestellt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/blade-runner-2099-executive-producers-confirm-franchise-owners-are-in-talks-for-aaa-video-game-adaptation"}, "weitere_links": [], "tags": ["Blade Runner", "Alcon Entertainment", "AAA", "Cyberpunk"], "archiviert_am": "2026-11-21T07:27:43.695Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.843Z"}, "id": "2026-11-14-pearl-abyss-ki-pipeline", "datum": "2026-11-13T23:17:00+01:00", "label": "News", "bereich": "games", "themen": ["Crimson Desert"], "kategorie": "Spiele", "titel": "Crimson-Desert-Studio Pearl Abyss will KI in seiner gesamten Entwicklung ausbauen, DokeV soll 2028 erscheinen", "schlagzeile": "Trotz Ärger um Crimson Desert: Pearl Abyss setzt noch stärker auf KI", "kurz": "Pearl Abyss, das Studio hinter Crimson Desert, will KI künftig in der gesamten Spieleentwicklung einsetzen. Das steht im Brief zu den Quartalszahlen. Zugleich nennt das Studio ein Ziel für DokeV: zweite Jahreshälfte 2028.", "zusammenfassung": "Pearl Abyss baut den Einsatz von KI in der Spieleentwicklung aus. Das geht laut PC Gamer und Eurogamer aus dem Brief des Studios zu den Zahlen des dritten Quartals 2026 hervor. Demnach prüft das Team neue Spielsysteme inzwischen mit KI, bevor sie aufwendig von Hand umgesetzt werden. KI soll außerdem wiederkehrende Aufgaben automatisieren, bei der Erstellung von Inhalten helfen und Tests optimieren, und zwar in der gesamten Entwicklungs-Pipeline. Pearl Abyss betont, KI sei nur ein Werkzeug und kein Ersatz für Entwickler; Gameplay und Inhalte würden weiterhin vom Team gestaltet. Das Thema ist heikel: Anfang des Jahres musste sich das Studio entschuldigen, weil in Crimson Desert KI-generierte 2D-Grafiken entdeckt wurden. Damals hieß es, diese hätten eigentlich vor dem Release ersetzt werden sollen, und man habe den KI-Einsatz nicht klar genug offengelegt. Welche Spiele genau betroffen sind und wie viel KI-Inhalt am Ende im fertigen Spiel landet, sagt der Brief nicht. Außerdem nennt Pearl Abyss ein Ziel für DokeV: Das bunte Actionspiel soll in der zweiten Jahreshälfte 2028 erscheinen.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/software/ai/dont-like-ai-in-games-crimson-desert-studio-pearl-abyss-aint-care-its-expanding-ai-use-throughout-our-entire-development-pipeline/"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/crimson-desert-devs-proudly-using-ai/"}], "tags": ["Pearl Abyss", "Crimson Desert", "DokeV", "KI", "Spieleentwicklung"], "archiviert_am": "2026-11-21T07:27:43.696Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.547Z"}, "id": "2026-11-14-nvidia-ceo-suche-haas", "datum": "2026-11-13T22:03:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "Nvidia-Chefsuche: Verwaltungsrat soll Arm-Chef Rene Haas angesprochen haben, Nvidia nennt Spekulationen verfrüht", "schlagzeile": "Wird der Arm-Chef neuer Nvidia-Boss? Verwaltungsrat bremst", "kurz": "Laut Financial Times hat Nvidias Verwaltungsrat Arm-Chef Rene Haas als möglichen Nachfolger von Jensen Huang angesprochen. Nvidia selbst sagt, man suche erst eine Personalberatung und habe noch keine Kandidaten offiziell kontaktiert. Gleichzeitig kursiert ein angeblicher Mitarbeiterbrief für Huangs Rückkehr, den ein Nvidia-Manager als Fälschung bezeichnet.", "zusammenfassung": "Nach dem Rücktritt von Jensen Huang sucht Nvidia einen neuen Chef. Laut einem Bericht der Financial Times, zusammengefasst von Tom's Hardware, hat der Verwaltungsrat Arm-Chef Rene Haas als möglichen Nachfolger angesprochen. Haas soll einer von mehreren Kandidaten sein; ob er ein Angebot bekommt oder annehmen würde, ist offen. Er arbeitete bis 2013 rund sieben Jahre bei Nvidia, unter anderem an Notebook-GPUs und Tegra-Chips, und führt Arm seit 2022. Nvidia hat auf den Bericht reagiert: Gegenüber CNBC erklärte der Verwaltungsrat, man wähle gerade erst eine Personalberatung aus und habe noch keine Kandidaten offiziell kontaktiert. Spekulationen über einzelne Namen seien verfrüht. Bis auf Weiteres führt Finanzchefin Colette Kress das Unternehmen kommissarisch. Intern ist die Stimmung laut WIRED, zitiert von PCGH, gespalten: Ein Beitrag in Nvidias interner Ideenbox sammelte über 1.600 Kommentare, überwiegend für eine Rückkehr Huangs. Ein im Netz verbreiteter Brief, angeblich von Nvidia-Führungskräften unterschrieben, ist dagegen laut dem Nvidia-Forschungschef Bryan Catanzaro eine Fälschung; er habe ihn nicht unterschrieben und stehe hinter dem Verwaltungsrat. Elon Musk kündigte laut Wccftech an, eine Petition für Huangs Rückkehr zu unterschreiben. Eine Wiedereinsetzung Huangs ist von Nvidia nicht angekündigt. Für GeForce-Kunden gibt es laut PCGH bisher keine bekannten Auswirkungen auf Produkte oder Preise. Am 17. November legt Nvidia erstmals ohne Huang Quartalszahlen vor.", "quelle": {"name": "Tom's Hardware", "url": "https://www.tomshardware.com/pc-components/gpus/nvidia-board-reportedly-approached-arm-ceo-rene-haas-during-replacement-search-jensen-huangs-transgressions-leave-nvidia-scrambling-to-fill-a-massive-void"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/Jensen-Huang-Ruecktritt-Mitarbeiter-fordern-Rueckkehr-1559985/"}, {"name": "Wccftech", "url": "https://wccftech.com/letter-seeking-ex-ceo-jensen-huangs-return-is-obviously-fake-says-nvidia-vp-after-he-is-made-a-named-signatory-alongside-top-leadership-at-firm/"}, {"name": "CNBC", "url": "https://www.cnbc.com/2026/11/13/nvidia-huang-ceo-replacement-search.html"}], "tags": ["NVIDIA", "Rene Haas", "Arm", "Jensen Huang", "Colette Kress"], "archiviert_am": "2026-11-21T07:27:43.697Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.024Z"}, "id": "2026-11-14-pioner-eingestellt", "datum": "2026-11-13T21:37:00+01:00", "label": "News", "bereich": "games", "themen": ["Survival-Shooter"], "kategorie": "Spiele", "titel": "Survival-Shooter Pioner wird eingestellt, das Studio hat kein Geld mehr für Entwicklung und Server", "schlagzeile": "Aus nach elf Monaten: Survival-Shooter Pioner macht dicht", "kurz": "Der Survival-Shooter Pioner wird weniger als ein Jahr nach dem Start im Early Access eingestellt. Entwickler GFAGames hat keine Finanzierung für Weiterentwicklung und Server gefunden. Wann die Server abgeschaltet werden, ist noch offen.", "zusammenfassung": "Der Survival-Shooter Pioner ist am Ende. Laut PC Gamer hat Entwickler GFAGames auf Steam angekündigt, die Entwicklung einzustellen und das Spiel zu schließen. Gespräche mit bestehenden und neuen Partnern über eine Finanzierung seien gescheitert. Das Studio habe nicht mehr genug eigenes Geld, um weiterzuentwickeln und die Server zu betreiben. Pioner galt seit seiner Vorstellung 2021 als Mischung aus Stalker, Metro und Escape from Tarkov, mit Einzelspieler-Kampagne sowie Koop- und PvP-Modus in einer spätsowjetischen Welt. Seit Dezember 2025 war es im Early Access und erreichte auf Steam in der Spitze 1.686 gleichzeitige Spieler. Nach technischen Problemen und langsamen Updates brachen die Zahlen im Sommer ein, Mitte September spielten nur noch ein paar Dutzend Menschen. Viele Käufer fordern unter der Ankündigung eine Rückerstattung. Dazu hat sich GFAGames noch nicht geäußert. Auch ein Termin für die Abschaltung der Server fehlt noch.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/fps/a-survival-game-we-once-called-stalker-and-tarkovs-alien-baby-is-closing-down-less-than-a-year-after-launch/"}, "weitere_links": [], "tags": ["Pioner", "GFAGames", "Early Access", "Survival-Shooter"], "archiviert_am": "2026-11-21T07:27:43.697Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.499Z"}, "id": "2026-11-14-euro-office-desktop", "datum": "2026-11-13T21:14:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Office"], "kategorie": "Software", "titel": "Europäische Office-Alternative Euro-Office gibt es jetzt als Desktop-App für Windows, macOS und Linux", "schlagzeile": "Europas Office-Alternative gibt es jetzt auch offline auf dem Desktop", "kurz": "Euro-Office, die europäische Alternative zu Microsoft 365, gibt es jetzt als kostenlose Desktop-App namens Nextcloud Office Desktop. Sie läuft offline unter Windows, macOS und Linux. Technisch ist sie ein Ableger von ONLYOFFICE.", "zusammenfassung": "Euro-Office ist jetzt auch als klassische Desktop-Anwendung verfügbar. Laut OMG! Ubuntu heißt die App Nextcloud Office Desktop und ist kostenlos sowie quelloffen. Euro-Office wurde im März 2026 als europäische Alternative zu Microsoft 365 angekündigt und lief bisher nur über einen Server im Browser oder per Mobil-App. Die Desktop-Version funktioniert dagegen ohne eigenen Server und offline. Sie bietet Textverarbeitung, Tabellenkalkulation, Präsentationen und PDF-Werkzeuge. Microsoft-Formate wie DOCX, XLSX und PPTX werden ebenso unterstützt wie offene Formate wie ODT. Zusätzlich lässt sich die App mit Nextcloud oder anderen Servern für gemeinsames Bearbeiten verbinden. Installer gibt es für Windows und macOS auf x86 und ARM64 sowie für Linux auf x86 als DEB- und RPM-Paket. Technisch basiert Euro-Office auf ONLYOFFICE, dessen Hersteller den Ableger kritisch sieht. Auch aus dem LibreOffice-Lager gibt es Kritik. OMG! Ubuntu merkt an, dass die App derzeit vor allem wie ein umbenanntes ONLYOFFICE wirkt.", "quelle": {"name": "OMG! Ubuntu", "url": "https://www.omgubuntu.co.uk/2026/11/euro-office-desktop-apps-nextcloud"}, "weitere_links": [{"name": "Dr. Windows", "url": "https://www.drwindows.de/news/euro-office-offizielle-desktop-app-wurde-veroeffentlicht"}], "tags": ["Euro-Office", "Nextcloud", "ONLYOFFICE", "Open Source", "Digitale Souveränität"], "archiviert_am": "2026-11-21T07:27:43.698Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.200Z"}, "id": "2026-11-14-m365-stoerung-ursache", "datum": "2026-11-13T20:54:00+01:00", "label": "News", "bereich": "software", "themen": ["Microsoft 365"], "kategorie": "Software", "titel": "Microsoft entschuldigt sich für die Microsoft-365-Großstörung und nennt ein Netzwerk-Upgrade als Ursache", "schlagzeile": "Microsoft-365-Ausfall: Kein Hack, keine KI – ein Netzwerk-Upgrade war schuld", "kurz": "Microsoft hat sich für die weltweite Störung von Outlook, Teams und Co. entschuldigt. Ursache war laut Microsoft ein Fehler aus einem früheren Netzwerk-Upgrade, nicht ein Angriff oder KI. Ein ausführlicher Bericht soll folgen.", "zusammenfassung": "Microsoft hat die Ursache der großen Microsoft-365-Störung vom 12. November genannt. Laut PC Gamer entschuldigte sich das Unternehmen in einer Stellungnahme ausdrücklich bei Kunden und Partnern. Der Fehler sei bei einem früheren Ausbau der Netzwerkkapazität entstanden und erst nach einer späteren Netzwerkänderung zum Problem geworden. Ein Cyberangriff oder KI-Agenten seien nicht beteiligt gewesen. Im Netz war zuvor spekuliert worden, ob KI-generierter Code den Ausfall verursacht hat. Microsoft gibt an, die eigentliche Ursache behoben zu haben, und meldet eine breite Erholung der Dienste. Die Wiederherstellung sei bewusst schrittweise erfolgt, um die Stabilität zu prüfen, und habe deshalb länger gedauert. Am Samstag teilte Microsoft mit, dass die Dienste für die zuletzt betroffenen Kunden und Regionen vollständig wiederhergestellt sind. Betroffen waren unter anderem Outlook, Teams, SharePoint und Copilot. Einen ausführlichen Bericht will Microsoft nach Abschluss der internen Prüfung veröffentlichen. Firmenkunden können je nach Vertrag eine SLA-Gutschrift prüfen.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/software/microsoft-deeply-apologizes-for-global-service-outage-says-no-ai-or-hackers-are-to-blame/"}, "weitere_links": [{"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/14/microsoft-is-begging-you-not-to-blame-ai-for-the-microsoft-365-outage-insisting-it-was-a-botched-network-upgrade/"}, {"name": "Associated Press", "url": "https://apnews.com/article/microsoft-outage-outlook-email-365-recover-ca395c0f1e51af784b6d70afb6554f6a"}], "tags": ["Microsoft 365", "Outlook", "Teams", "Störung"], "archiviert_am": "2026-11-21T07:27:43.698Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.116Z"}, "id": "2026-11-14-windows-oob-aktivierung", "datum": "2026-11-13T20:32:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Microsoft veröffentlicht Notfall-Update gegen Aktivierungsfehler nach dem November-Patchday", "schlagzeile": "Notfall-Update: Microsoft repariert Windows-Aktivierung nach Patchday", "kurz": "Microsoft hat außerplanmäßige Updates veröffentlicht, die den Aktivierungsfehler 0x80041008 nach dem November-Patchday beheben. Betroffen waren vor allem Firmen, die Windows über slmgr.vbs aktivieren. Die Updates gibt es für Windows 11 23H2, Windows 10 und Windows Server.", "zusammenfassung": "Microsoft hat den Aktivierungsfehler nach dem November-Patchday mit einem Notfall-Update behoben. Das berichtet Neowin. Nach den Sicherheitsupdates scheiterten Aktivierungs- und Lizenzbefehle über das Tool slmgr.vbs mit dem Fehler 0x80041008. Betroffen waren vor allem Firmen, die Aktivierung und Produktschlüssel per Skript verwalten. Die außerplanmäßigen Updates gibt es für Windows Server 2025 (KB5136489), Windows Server 2022 (KB5136487), Windows Server 2019 und Windows 10 Enterprise LTSC 2019 (KB5136490), Windows 11 23H2 (KB5136483) sowie Windows 10 22H2 mit ESU und Windows 10 Enterprise LTSC 2021 (KB5136493). Es sind kumulative Updates, die auch alle bisherigen Korrekturen enthalten. Windows Server und Windows 10 erhalten sie über den Microsoft Update Catalog, Windows 11 23H2 zusätzlich über die optionalen Updates in Windows Update. Für die neueren Versionen 24H2, 25H2 und 26H2 nennt der Bericht kein eigenes Update. Das ebenfalls bestätigte Druckproblem nach dem Patchday behebt dieses Update laut Bericht nicht. Microsoft empfiehlt ohnehin, für die Automatisierung künftig PowerShell statt slmgr.vbs zu nutzen.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-releases-emergency-oob-windows-update-to-fix-licensing-and-activation-issues/"}, "weitere_links": [], "tags": ["Windows 11", "Windows 10", "Windows Server", "Out-of-Band-Update", "Aktivierung"], "archiviert_am": "2026-11-21T07:27:43.699Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.660Z"}, "id": "2026-11-14-nvidia-wsj-knappheit", "datum": "2026-11-13T20:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA", "GPU"], "kategorie": "Unternehmen", "titel": "WSJ-Bericht: Huang soll KI-Startups finanziert haben, damit sie Nvidias überschüssige GPUs abnehmen", "schlagzeile": "Bericht: Hat Nvidia KI-Startups bezahlt, damit sie GPUs kaufen?", "kurz": "Laut Wall Street Journal hat Jensen Huang mit Nvidias Geld KI-Startups und Rechenzentren finanziert, die dann Nvidia-GPUs kauften. Hintergrund soll ein Überangebot an bestellten TSMC-Chips gewesen sein. Finanzchefin Colette Kress soll dagegen gehalten haben.", "zusammenfassung": "Ein neuer Bericht des Wall Street Journal wirft ein Schlaglicht auf Nvidias Finanzpraktiken unter Jensen Huang. TechPowerUp und Wccftech fassen ihn zusammen. Demnach hat Nvidia KI-Startups und kleinere Cloud-Anbieter finanziell unterstützt, die mit dem Geld wiederum Nvidia-GPUs kauften und Rechenzentren bauten. Grund soll gewesen sein, dass große Cloud-Konzerne verstärkt eigene Chips einsetzen und Nvidia bei TSMC mehr Chips bestellt hatte, als direkt Abnehmer da waren. Huang soll intern von einer „Lawine“ gesprochen haben, die auf ihn zukomme. Laut dem Bericht kam es im August zu einem Streit mit Finanzchefin und heutiger Interimschefin Colette Kress, die solche Kreisfinanzierungen zurückfahren wollte, unter anderem den milliardenschweren Deal mit OpenAI. Laut Wccftech setzte Kress durch, dass die Garantien für OpenAI-Rechenleistung von bis zu 250 auf bis zu 125 Milliarden US-Dollar sinken. Huang soll sie daraufhin herabsetzend kritisiert haben. Kress soll auch gewarnt haben, dass sich viele der kleinen Cloud-Anbieter die GPUs eigentlich nicht leisten können. Ob diese Praxis die GPU- und Speicherpreise für Spieler direkt nach oben getrieben hat, belegt der Bericht nicht; das ist eine Einordnung von Wccftech. Nvidia hat sich laut den vorliegenden Berichten nicht dazu geäußert. Die Vorwürfe stammen aus anonymen Quellen und sind nicht offiziell bestätigt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354814/nvidia-allegedly-engineered-scarcity-by-funding-ai-startups-to-buy-its-gpus"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/jensen-huang-financed-ai-startups-absorb-excess-silicon/"}], "tags": ["NVIDIA", "Wall Street Journal", "TSMC", "OpenAI", "GPU-Preise"], "archiviert_am": "2026-11-21T07:27:43.699Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.753Z"}, "id": "2026-11-14-core-ultra-7-260k", "datum": "2026-11-13T19:44:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Intel", "CPU"], "kategorie": "Prozessoren", "titel": "Intel Core Ultra 7 260K erscheint ohne Ankündigung, vorerst nur in zwei Newegg-Komplett-PCs", "schlagzeile": "Heimlich gestartet: Intels Core Ultra 7 260K gibt es nur im Fertig-PC", "kurz": "Intel hat mit dem Core Ultra 7 260K still und leise eine neue Desktop-CPU gestartet. Sie steckt bisher nur in zwei Gaming-PCs von Newegg und wird nicht einzeln verkauft. Technisch ist sie ein leicht gedrosselter Core Ultra 7 265K.", "zusammenfassung": "Intel hat eine neue Desktop-CPU auf den Markt gebracht, ohne sie anzukündigen. Der Core Ultra 7 260K ist laut TechPowerUp nur in zwei Gaming-PCs der Newegg-Eigenmarke ABS erhältlich. Das Modell Kaze II Aqua kombiniert sie mit einer RTX 5060 für 1.699,99 US-Dollar, der Flux II Aqua mit einer RTX 5070 für 1.999,99 US-Dollar. Newegg bestätigt, dass der Prozessor exklusiv bleibt und nicht einzeln verkauft wird. Intel spricht laut Tom's Hardware von einem Modell mit begrenzter Verfügbarkeit ohne Boxed-Version. Technisch entspricht der Chip weitgehend dem Core Ultra 7 265K: 8 Performance- und 12 Effizienzkerne, 30 MB L3-Cache und 125 Watt Basisleistung. Der maximale Takt der P-Kerne liegt mit 5,4 GHz aber 100 MHz niedriger. Da er nur DDR5-6400 unterstützt, gehört er zur ursprünglichen Arrow-Lake-Familie und nicht zum Refresh mit DDR5-7200. Die ersten Newegg-Einträge waren widersprüchlich, teils stand dort 260KF oder ein Boost von 5,2 GHz. Benchmarks gibt es noch nicht. Für Selbstbauer ist die CPU damit uninteressant, und Preise oder Verfügbarkeit in Europa sind nicht bekannt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354821/intel-core-ultra-7-260k-arrives-without-an-announcement-limited-to-two-prebuilt-desktops"}, "weitere_links": [{"name": "VideoCardz", "url": "https://videocardz.com/newz/intel-core-ultra-7-260k-launches-as-newegg-exclusive-cpu-now-available-in-prebuilt-gaming-pcs"}, {"name": "Wccftech", "url": "https://wccftech.com/intel-core-ultra-7-260k-quietly-launches-as-newegg-exclusive-cpu/"}], "tags": ["Intel", "Core Ultra 7 260K", "Arrow Lake", "Newegg"], "archiviert_am": "2026-11-21T07:27:43.699Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.966Z"}, "id": "2026-11-13-rainbow-six-vegas-leak", "datum": "2026-11-13T18:10:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Ubisoft"], "kategorie": "Spiele", "titel": "Bericht: Ubisoft Montreal arbeitet an neuem Rainbow Six: Vegas mit dem Codenamen Spades", "schlagzeile": "Leak: Kehrt Rainbow Six: Vegas nach 18 Jahren zurück?", "kurz": "Laut Insider Gaming hat Ubisoft ein neues Rainbow Six: Vegas freigegeben, Codename Spades. Das Spiel soll sich bei Ubisoft Montreal in einer frühen Entwicklungsphase befinden. Ubisoft hat das nicht bestätigt, eine Ankündigung dürfte noch Jahre entfernt sein.", "zusammenfassung": "Die Rainbow-Six-Vegas-Reihe könnte nach fast zwei Jahrzehnten zurückkehren. Insider Gaming berichtet unter Berufung auf anonyme Quellen, dass Ubisoft ein neues Vegas-Spiel mit dem Codenamen Spades freigegeben hat. Es soll bei Ubisoft Montreal in einer frühen Entwicklungsphase sein. Insgesamt seien dort drei neue Projekte gestartet worden, ein weiteres davon soll ebenfalls im Rainbow-Six-Universum spielen. Laut den Quellen handelt es sich eher um ein Vegas 3 als um ein Remake, sicher ist das aber nicht. Der letzte Teil, Rainbow Six: Vegas 2, erschien 2008. Seitdem lag der Fokus vor allem auf Rainbow Six Siege. Die Marke gehört inzwischen zu Vantage Studios, einer Ubisoft-Tochter, an der Tencent 26,32 Prozent hält. Ubisoft hat sich nicht geäußert, das Projekt ist also unbestätigt. Insider Gaming selbst rechnet damit, dass eine offizielle Ankündigung noch einige Jahre dauert.", "quelle": {"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/rainbow-six-vegas-3/"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354797/leak-tips-rainbow-six-vegas-series-slated-to-return-from-18-year-hiatus"}], "ursprungsquelle": "Insider Gaming (Tom Henderson), anonyme Quellen", "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Exklusivbericht von Insider Gaming mit anonymen Quellen; Tom Henderson hat eine gute Trefferquote bei Ubisoft-Projekten. TechPowerUp gibt nur den Bericht wieder, keine unabhängige Zweitquelle. Ubisoft hat nicht bestätigt."}, "tags": ["Rainbow Six", "Rainbow Six Vegas", "Ubisoft", "Tom Clancy"], "archiviert_am": "2026-11-20T18:43:08.152Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.560Z"}, "id": "2026-11-13-word-kompatibilitaet-layout", "datum": "2026-11-13T17:35:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Microsoft entfernt alte Kompatibilitätsoptionen aus Word, ältere Dokumente können ab Dezember ihr Layout verlieren", "schlagzeile": "Word bricht ab Dezember das Layout alter Dokumente – so sicherst du sie", "kurz": "Microsoft streicht einige alte Kompatibilitätseinstellungen aus Word. Dokumente, die mit Word 2010 oder älter gespeichert wurden, können danach anders umbrechen. Unter Windows startet die Umstellung im Dezember 2026, auf dem Mac Anfang 2027.", "zusammenfassung": "Microsoft räumt in Word auf und entfernt einige ältere Kompatibilitätsoptionen. Das berichtet heise unter Berufung auf die Message-Center-Mitteilung MC1551147. Betroffen sind Dokumente, die in Word 2010 oder früher erstellt oder zuletzt gespeichert wurden und diese Einstellungen nutzen. In solchen Dateien kann der Text künftig anders umbrechen. Abstände und Seitenzahlen können sich ändern, Bilder und Formen auf eine andere Seite rutschen. Welche Optionen genau wegfallen, sagt Microsoft nicht. Der Kompatibilitätsmodus selbst bleibt erhalten. Unter Windows läuft die Umstellung im Lauf des Dezembers 2026, auf dem Mac Anfang 2027. Eine Möglichkeit zum Aufschieben nennt Microsoft nicht. Wer auf das exakte Layout angewiesen ist, sollte wichtige alte Dokumente vorher prüfen und als PDF exportieren. Eine Umwandlung ins neue Word-Format hilft laut heise nicht, weil dabei die alten Kompatibilitätseinstellungen ebenfalls verloren gehen.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Vorsicht-Umbruch-Word-zerschiesst-bald-das-Layout-alter-Dokumente-11524878.html"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-is-retiring-some-compatibility-mode-options-in-word-and-old-documents-may-break/"}], "tags": ["Microsoft Word", "Office", "Microsoft 365", "Kompatibilität"], "archiviert_am": "2026-11-20T18:43:08.153Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.066Z"}, "id": "2026-11-13-ps5-qssr-sechs-spiele", "datum": "2026-11-13T17:35:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Konsolen-Update", "titel": "Sonys KI-Upscaling QSSR kommt für sechs weitere Spiele auf die normale PS5, darunter Spider-Man 2 und Arc Raiders", "schlagzeile": "KI-Upscaling für die normale PS5: Sechs Spiele werden schärfer", "kurz": "Sonys KI-Upscaler QSSR kommt in sechs weitere PS5-Spiele, darunter Marvel's Spider-Man 2, Control Resonant und Arc Raiders. QSSR basiert auf PSSR der PS5 Pro, läuft aber auf der normalen PS5. Spider-Man 2 hat das Update bereits erhalten.", "zusammenfassung": "Sony bringt seine KI-Hochskalierung Quick Spectral Super Resolution, kurz QSSR, in weitere Spiele auf der Standard-PS5. Bestätigt sind Marvel's Spider-Man 2, Control Resonant, The Finals, ARC Raiders, No Man's Sky und Hell Let Loose: Vietnam. Laut PlayStation auf X startet Spider-Man 2 heute, VGC meldet die übrigen als aktualisiert oder in Kürze. QSSR baut auf der gleichen Grundlage wie PSSR der PS5 Pro auf. Die ersten Spiele mit QSSR waren Marvel's Wolverine und Ghost of Yōtei. Insomniac verspricht für Spider-Man 2 stabileres und schärferes Bild im Qualitäts- und im Performance-Modus. Remedy spricht bei Control Resonant von spürbar besserer Bildstabilität und feineren Details. Auch für Arc Raiders, No Man's Sky und Hell Let Loose: Vietnam nennen die Studios ein schärferes, saubereres Bild. Digital Foundry hatte das Potenzial der Technik als bemerkenswert bezeichnet, gerade weil viele Spiele dieser Generation mit niedriger Auflösung und schwachem Upscaling kämpfen. Messwerte zu Bildrate oder Auflösung nennen die Studios nicht. Ob QSSR Leistung kostet, ist daher noch offen.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/news/6-more-games-receive-ps5-performance-updates-via-qssr-including-arc-raiders-and-control-resonant/"}, "weitere_links": [{"name": "PlayStation auf X", "url": "https://x.com/PlayStation/status/2121241936681976081"}, {"name": "Insider Gaming", "url": "https://insider-gaming.com/5-big-ps5-games-will-receive-qssr-update/"}], "tags": ["PS5", "QSSR", "PSSR", "Upscaling", "Spider-Man 2", "Arc Raiders"], "archiviert_am": "2026-11-20T18:43:08.154Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.162Z"}, "id": "2026-11-13-gta6-day-one-patch-macca", "datum": "2026-11-13T17:32:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6 eine Woche vor Release: erstes Update 1.002 wird verteilt, erster Teaser zur In-Game-Zeichentrickserie Macca & Friends", "schlagzeile": "GTA 6: Erstes Update vor Release – und eine eigene Zeichentrickserie", "kurz": "Rockstar verteilt eine Woche vor dem Start ein erstes, rund 1 GB großes Update für GTA 6, ohne Patch-Notes. Außerdem gibt es einen ersten Blick auf Macca & Friends, eine Zeichentrickserie, die im Spiel läuft. Laut Guardian waren fast 5.000 Menschen an GTA 6 beteiligt.", "zusammenfassung": "Kurz vor dem Release am 19. November bekommt GTA 6 bereits sein erstes Update. Laut Polygon erhielten einige Spieler am Freitag eine Benachrichtigung über Version 1.002, die rund ein Gigabyte groß ist. Rockstar hat keine Patch-Notes veröffentlicht, vermutlich auch, um nichts zu spoilern. Das Update wird offenbar gestaffelt verteilt, nicht alle sehen es sofort. Weitere Updates bis zum Start sind laut Polygon möglich. Außerdem hat der X-Account DiscussingFilm einen ersten Teaser zu Macca & Friends veröffentlicht, einer von Rockstar für das Spiel produzierten Serie, berichtet IGN. Die Zeichentrickserie über den Alligator Macca und seine Freunde läuft im Spiel auf dem Sender Weazel. Rob Nelson, einer der Studioleiter von Rockstar North, brauchte laut New York Times rund 80 Stunden für einen Durchgang. Laut einem Guardian-Bericht, zusammengefasst von Golem, waren fast 5.000 Menschen an der Entwicklung beteiligt. Wie viele davon externe Dienstleister waren, ist nicht bekannt. Laut Bloomberg hat Rockstar heute 4.711 Beschäftigte an zwölf Standorten. GTA 6 erscheint für PS5 und Xbox Series X/S, eine PC-Version ist nicht angekündigt.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/gta-6-nov-13-patch-102-what-is-download-size-ps5-xbox/"}, "weitere_links": [{"name": "IGN", "url": "https://www.ign.com/articles/gta-6-has-a-whole-animated-tv-series-you-can-watch-in-game"}, {"name": "Golem.de", "url": "https://www.golem.de/news/rockstar-games-fast-5-000-menschen-haben-an-gta-6-gearbeitet-2611-215191.html"}], "tags": ["GTA 6", "Rockstar Games", "Patch", "Day-One-Patch"], "archiviert_am": "2026-11-20T18:43:08.154Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.263Z"}, "id": "2026-11-13-gow-sons-of-sparta-ps4", "datum": "2026-11-13T17:17:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Spiele", "titel": "God of War: Sons of Sparta erscheint am 16. November für PS4 und bekommt zwei neue Spielmodi", "schlagzeile": "God of War: Sons of Sparta kommt auf die PS4 – mit zwei neuen Modi", "kurz": "Der 2D-Ableger God of War: Sons of Sparta erscheint am 16. November auch für die PS4. Gleichzeitig bekommen PS4 und PS5 per Gratis-Update zwei neue Modi: einen Speedrun-Modus und einen Modus, in dem jeder Treffer tödlich ist.", "zusammenfassung": "Sony bringt God of War: Sons of Sparta auf eine weitere Plattform. Der 2D-Action-Plattformer erscheint am 16. November um Mitternacht Ortszeit für die PlayStation 4, das hat PlayStation auf X bestätigt. Zeitgleich kommt ein kostenloses Update mit zwei neuen Modi für die PS4- und die PS5-Version. Der Hermes-Modus ist ein Speedrun-Modus mit Split-Timer und dauerhafter Bestenliste. Er wird nach dem Durchspielen freigeschaltet oder über einen Code im Startmenü, berichtet VGC. Im Erebus-Modus reicht für Kratos und die Gegner jeweils ein einziger Treffer. Diesen Modus wählt man beim Start eines neuen Spiels. Sons of Sparta wurde von Mega Cat Studios zusammen mit Santa Monica Studio entwickelt und erschien im Februar für die PS5. Das Spiel erzählt eine kanonische Geschichte aus Kratos' Jugend während seiner Ausbildung in Sparta mit seinem Bruder Deimos. Einen Preis für die PS4-Version nennt der Bericht nicht.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/news/playstations-god-of-war-spin-off-is-coming-to-ps4-and-getting-new-modes/"}, "weitere_links": [{"name": "PlayStation auf X", "url": "https://x.com/PlayStation/status/2121257001262969225"}, {"name": "Polygon", "url": "https://www.polygon.com/god-of-war-sons-of-sparta-new-update-ps4-release/"}], "tags": ["God of War", "PS4", "PS5", "Santa Monica Studio", "Update"], "archiviert_am": "2026-11-20T18:43:08.154Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.646Z"}, "id": "2026-11-13-tsmc-mitarbeiterdaten-leak", "datum": "2026-11-13T16:48:00+01:00", "label": "News", "bereich": "hardware", "themen": ["TSMC"], "kategorie": "Unternehmen", "titel": "TSMC bestätigt Datenleck: Daten von Mitarbeitern tauchen im Netz auf, angeblich für drei Bitcoin angeboten", "schlagzeile": "TSMC-Datenleck: Mitarbeiterdaten angeblich für drei Bitcoin im Angebot", "kurz": "TSMC hat in einer Pflichtmitteilung an die US-Börsenaufsicht bestätigt, dass Daten aktueller und ehemaliger Mitarbeiter unerlaubt auf einer externen Website aufgetaucht sind. Die Daten stammen laut TSMC aus Diensten eines Cloud-Anbieters, die eigenen Systeme seien nicht kompromittiert. Kundendaten sind laut TSMC nicht betroffen.", "zusammenfassung": "Der weltgrößte Auftragsfertiger für Chips hat ein Datenleck bestätigt. In einer Form-6-K-Mitteilung an die US-Börsenaufsicht SEC schreibt TSMC, dass Daten aktueller und ehemaliger Mitarbeiter ohne Erlaubnis auf einer externen Website verfügbar gemacht wurden. Laut Seeking Alpha, zitiert von PC Gamer, geht es um mehr als 46.000 Datensätze. TSMC zufolge stimmen die Daten mit Informationen überein, die bei einem nicht genannten Cloud-Dienstleister gespeichert waren. Hinweise auf einen Einbruch in die eigenen Systeme gebe es nicht. Betroffene seien informiert, außerdem arbeite man mit dem Cloud-Anbieter, Ermittlungsbehörden und einer externen Sicherheitsfirma zusammen. Die taiwanische United Daily News berichtet, Hacker hätten 6,9 GB an Daten in einem Untergrundforum für drei Bitcoin angeboten. Eine veröffentlichte Stichprobe soll unter anderem Ausweisnummern, Adressen und Bankdaten enthalten; das ist von TSMC nicht bestätigt. Laut TSMC haben die Daten nichts mit dem Geschäftsbetrieb oder Kundeninformationen zu tun. Chipdesigns oder Kundendaten von Firmen wie Nvidia, AMD oder Apple sind nach jetzigem Stand also nicht betroffen. Bereits 2023 war TSMC über einen gehackten Zulieferer in die Schlagzeilen geraten.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/chipmaking-giant-tsmc-discovers-major-employee-data-leak-reports-say-info-was-up-for-sale-for-three-bitcoin-on-shady-forums/"}, "weitere_links": [], "tags": ["TSMC", "Datenleck", "Sicherheit", "Chipfertigung"], "archiviert_am": "2026-11-20T18:43:08.155Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.756Z"}, "id": "2026-11-13-intel-desktop-marktanteil", "datum": "2026-11-13T16:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["CPU"], "kategorie": "Prozessoren", "titel": "Mercury Research: Intel gewinnt im dritten Quartal 2026 rund fünf Prozentpunkte Desktop-Marktanteil von AMD zurück", "schlagzeile": "Überraschung: Intel nimmt AMD bei Desktop-CPUs Marktanteile ab", "kurz": "Laut Mercury Research ist AMDs Anteil bei Desktop-Prozessoren im dritten Quartal 2026 von rund 35 auf 29,9 Prozent gefallen. Die Marktforscher vermuten, dass Intel mehr Chips in den Desktop-Markt umgeleitet hat. AMD könnte zudem darunter leiden, dass der Gaming-PC-Markt schwächelt.", "zusammenfassung": "Bei Desktop-Prozessoren hat Intel im dritten Quartal 2026 deutlich Boden gutgemacht. Laut den neuen Zahlen von Mercury Research, über die PC Gamer berichtet, sank AMDs Desktop-Anteil von rund 35 Prozent im zweiten Quartal auf 29,9 Prozent. Das ist ein Rückschritt um etwa fünf Prozentpunkte innerhalb von drei Monaten. Mercury Research ist sich selbst nicht ganz sicher, woran das liegt. Die Marktforscher vermuten, dass Intel wegen schwacher Notebook-Nachfrage mehr Chips in den Desktop-Markt lenken konnte, der im dritten Quartal saisonal stärker ist. AMD habe dagegen kein saisonales Wachstum gezeigt. Als zweiten Grund nennt Mercury AMDs stärkere Abhängigkeit vom Gaming-Markt, der unter knappen und teuren Grafikkarten leidet. Dazu kommen hohe Preise für RAM und SSDs, die viele vom Kauf eines neuen PCs abhalten. Intel ist bei Komplett-PC-Herstellern stark vertreten, die auch günstige Systeme mit älteren DDR4-Plattformen bauen. PC Gamer betont, dass das kein Zeichen für einen gesunden Markt ist: Beide Hersteller sollen im dritten Quartal mehr als zehn Prozent weniger Notebook-Chips ausgeliefert haben. Bei der Gaming-Leistung liegt AMD mit den X3D-Modellen weiterhin vorne.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/processors/intel-takes-massive-chunk-out-of-amds-desktop-cpu-market-share-in-unexpected-turnaround-may-be-due-to-the-red-teams-dominance-in-gaming-chips-weirdly/"}, "weitere_links": [], "tags": ["Intel", "AMD", "Ryzen", "Marktanteil", "Mercury Research"], "archiviert_am": "2026-11-20T18:43:08.155Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.522Z"}, "id": "2026-11-13-huang-kongress-anhoerung", "datum": "2026-11-13T14:09:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "US-Kongress lädt Ex-Nvidia-Chef Jensen Huang mit Subpoena-Drohung vor, Trump schlägt Tim Cook als Nachfolger vor", "schlagzeile": "Kongress droht Huang mit Vorladung – Trump will Tim Cook als Nvidia-Chef", "kurz": "Drei Ausschüsse des US-Repräsentantenhauses wollen Jensen Huang Anfang Dezember befragen und drohen bei Nichterscheinen mit einer Vorladung. Zusätzlich soll er öffentlich vor dem Bankenausschuss des Senats aussagen. US-Präsident Trump empfiehlt unterdessen Apples Tim Cook als neuen Nvidia-Chef.", "zusammenfassung": "Der Druck auf den zurückgetretenen Nvidia-Gründer Jensen Huang wächst weiter. Laut PC Gamer haben die Vorsitzenden dreier Ausschüsse des US-Repräsentantenhauses Huang und Nvidias Chefjuristen Tim Teter zu nichtöffentlichen, protokollierten Befragungen am 1. und 2. Dezember geladen. Kommen die beiden nicht, droht eine Vorladung per Subpoena. Themen sind der mutmaßliche Schmuggel von KI-Chips, die Nutzung von Nvidia-Produkten durch gegnerische Militärs und Berichte über eine Einflussnahme auf US-Exportkontrollen, unter anderem rund um die Firma MegaSpeed aus Singapur. Ein früheres Schreiben vor Huangs Rücktritt war noch deutlich freundlicher formuliert. Zusätzlich hat Senator Tim Scott Huang für den 3. Dezember zu einer öffentlichen Anhörung im Bankenausschuss des Senats geladen, ebenso Handelsminister Howard Lutnick. Laut BBC, zitiert von PC Gamer, ist Huang bereit, vor dem Kongress zu erscheinen. Parallel dazu hat US-Präsident Donald Trump auf Truth Social einen Wunschnachfolger genannt: Tim Cook, der Apple-Chef bis September war und jetzt Executive Chairman ist, berichtet Golem. Entscheiden wird darüber aber der Nvidia-Verwaltungsrat, der interne und externe Kandidaten prüfen will. Bis dahin führt Finanzchefin Colette Kress das Unternehmen kommissarisch. Ob Cook überhaupt Interesse hat, ist nicht bekannt.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/clear-national-security-concerns-that-need-to-be-addressed-immediately-new-letters-to-jensen-huang-from-congress-strike-a-tougher-tone-for-the-ex-nvidia-ceo/"}, "weitere_links": [{"name": "Golem.de", "url": "https://www.golem.de/news/nvidia-chefposten-trump-empfiehlt-tim-cook-als-nachfolger-von-jensen-huang-2611-215166.html"}], "tags": ["NVIDIA", "Jensen Huang", "US-Kongress", "Exportkontrollen", "Tim Cook"], "archiviert_am": "2026-11-20T18:43:08.155Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.470Z"}, "id": "2026-11-13-november-patch-druck-aktivierung", "datum": "2026-11-13T13:27:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Microsoft bestätigt: November-Updates für Windows verursachen Druckfehler und Aktivierungsprobleme", "schlagzeile": "Windows-Patch im November: Drucken und Aktivierung machen Ärger", "kurz": "Microsoft hat zwei neue Probleme mit den November-Sicherheitsupdates bestätigt. Dokumente mit unsichtbaren Bildern lassen sich teils nicht drucken, und bestimmte Aktivierungsbefehle scheitern mit Fehler 0x80041008. Ein Fix für die Aktivierung soll in den nächsten Tagen kommen.", "zusammenfassung": "Der November-Patchday sorgt für weitere Probleme. Laut BleepingComputer hat Microsoft bestätigt, dass Drucken nach den Updates fehlschlagen kann. Betroffen sind Dokumente mit Bildern, die bei der gewählten Druckauflösung eine Höhe oder Breite von null haben. Solche unsichtbaren Bilder stecken etwa in Wasserzeichen oder Layout-Ankern von Word-Dokumenten. Das Problem betrifft vor allem den Druck über die Windows-Grafikschnittstelle GDI, ab Windows 10 und Windows Server 2016. Zusätzlich scheitern Aktivierungsbefehle über das Tool slmgr.vbs mit dem Fehler 0x80041008. Das betrifft vor allem Firmen, die Aktivierung und KMS-Server automatisieren. Bereits aktivierte Geräte bleiben laut Microsoft aktiviert. Ein Fix soll in den kommenden Tagen erscheinen, bis dahin hilft nur der Business-Support. Für das Druckproblem nennt der Bericht noch keinen Termin. Diese Woche hatte Microsoft außerdem bestätigt, dass die November-Updates auf Systemen mit dem Oktober-Vorschauupdate nicht installiert werden. Privatnutzer sind vor allem vom Druckfehler betroffen.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-says-november-security-updates-cause-printing-issues/"}, "weitere_links": [{"name": "BleepingComputer (Aktivierung)", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-confirms-windows-activation-failures-after-november-updates/"}], "tags": ["Windows 11", "Windows 10", "Patchday", "Drucken", "Aktivierung"], "archiviert_am": "2026-11-20T18:43:08.155Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.866Z"}, "id": "2026-11-13-xbox-25-konsole-ausverkauft", "datum": "2026-11-13T13:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Xbox"], "kategorie": "Konsolen", "titel": "Xbox Series X zum 25. Jubiläum in Sekunden ausverkauft, Scalper verlangen bis zu 2.500 Dollar", "schlagzeile": "Jubiläums-Xbox in Sekunden weg – Scalper verlangen bis zu 2.500 Dollar", "kurz": "Die transparent-grüne Xbox Series X zum 25. Jubiläum war im Microsoft Store innerhalb von Sekunden ausverkauft. Fans sind wütend über die knappe Stückzahl und fehlende Schutzmaßnahmen gegen Bots. Auf eBay wurden Konsolen laut IGN schon für 1.500 bis 2.500 Dollar verkauft.", "zusammenfassung": "Der Verkaufsstart der limitierten Xbox Series X zum 25. Geburtstag der Marke ist für viele Fans schiefgegangen. Laut IGN war die Konsole im Microsoft Store innerhalb von Sekunden vergriffen. Microsoft hatte vorab nur eine begrenzte Stückzahl angekündigt, die je nach Markt und Händler unterschiedlich ausfällt. Die Konsole kostet regulär 999 Dollar. GameStop bot sein Kontingent laut IGN zeitweise für 4.950 Dollar an, auch das ist inzwischen ausverkauft. Auf eBay hat IGN Dutzende bereits verkaufte Exemplare für 1.500 bis 2.500 Dollar gefunden. Fans kritisieren vor allem, dass Microsoft keine Warteschlange und keine Beschränkung auf echte Xbox-Konten eingeführt hat. Manche berichten, der Warenkorb sei während des Kaufs einfach verschwunden. Xbox-Chefin Asha Sharma hatte im Oktober gesagt, die Nachfrage nach Konsolen sei größer als das Angebot. Ob Microsoft nachliefert, ist nicht bekannt. Preise und Verfügbarkeit in Europa nennt der Bericht nicht.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/xbox-25th-anniversary-console-stock-sells-out-in-seconds-sparking-fan-fury-over-scalping-and-limited-supply"}, "weitere_links": [], "tags": ["Xbox", "Xbox Series X", "25 Jahre Xbox", "Scalper"], "archiviert_am": "2026-11-20T18:43:08.155Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.378Z"}, "id": "2026-11-13-gdc-ps6-helix-ki", "datum": "2026-11-13T11:20:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation", "Xbox"], "kategorie": "Spielebranche", "titel": "GDC-Umfrage: 10 Prozent der Entwickler arbeiten schon an PS6-Spielen, 8 Prozent an Project Helix, 40 Prozent nutzen generative KI", "schlagzeile": "Schon in Arbeit: Jeder zehnte Entwickler baut ein Spiel für die PS6", "kurz": "In der GDC-Umfrage sagen 10 Prozent der Entwickler mit laufendem Projekt, dass ihr Spiel für die nächste PlayStation geplant ist. 8 Prozent nennen Microsofts Project Helix. Außerdem nutzen 40 Prozent generative KI, aber 55 Prozent halten sie für schädlich.", "zusammenfassung": "Der neue State of the Game Industry Report der Game Developers Conference zeigt, dass die nächste Konsolengeneration schon in Arbeit ist. Laut Golem geben 10 Prozent der Befragten mit einem laufenden Projekt an, dass ihr Spiel für Sonys kommende PlayStation vorgesehen ist. 8 Prozent nennen Microsofts nächste Xbox mit dem Codenamen Project Helix. Mehrfachnennungen waren möglich, wie viele verschiedene Spiele das sind, ist also unklar. Wichtigste Plattform bleibt der PC mit 81 Prozent, gefolgt von PS5 mit 45 und Xbox Series X/S mit 37 Prozent. Das Steam Deck kommt auf 32, die Switch 2 auf 29 und Valves Steam Machine auf 21 Prozent. Zweites großes Thema ist KI: Laut Eurogamer nutzen 40 Prozent der Befragten generative KI bei der Arbeit, vier Prozentpunkte mehr als im Vorjahr. Gleichzeitig sagen 55 Prozent, dass KI der Spielebranche schadet. In AAA-Studios fühlen sich 27 Prozent zur KI-Nutzung gedrängt oder ermutigt, bei Indie-Entwicklern nur 9 Prozent. Zur Zahl der Befragten nennt Golem mehr als 2.600, Eurogamer mehr als 2.300. Die Entlassungszahlen aus derselben Umfrage standen bereits gestern im Ticker.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/next-gen-jeder-zehnte-entwickler-arbeitet-an-spiel-fuer-playstation-6-2611-215177.html"}, "weitere_links": [{"name": "Eurogamer", "url": "https://www.eurogamer.net/gdc-report-40-percent-developers-generative-ai"}], "tags": ["GDC", "PS6", "Project Helix", "Xbox", "Generative KI", "Spielebranche"], "archiviert_am": "2026-11-20T18:43:08.155Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.343Z"}, "id": "2026-11-13-microsoft-365-grossstoerung", "datum": "2026-11-13T05:50:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Großstörung bei Microsoft 365: Outlook, Exchange, Teams und Copilot stundenlang gestört, Erholung nur schrittweise", "schlagzeile": "Outlook und Teams down: Microsoft 365 kämpft mit Großstörung", "kurz": "Seit Donnerstagabend ist Microsoft 365 weltweit massiv gestört, betroffen sind unter anderem Outlook, Exchange Online, Teams und Copilot. Laut Microsoft sind zahlreiche Server unerwartet ausgefallen, ein Cyberangriff sei es nicht. Am Freitagmorgen zeigt Microsofts Statusseite weiter eine Dienstbeeinträchtigung; eine durchgehende Erholung ist noch nicht erreicht.", "zusammenfassung": "Am Donnerstag, dem 12. November, kam es zu einer der größten Microsoft-365-Störungen der letzten Zeit. Laut BleepingComputer begann der Vorfall mit der Kennung MO1550821 um 13:26 Uhr US-Ostküstenzeit, in Mitteleuropa also am Abend. Betroffen waren unter anderem Exchange Online und Outlook, Teams, SharePoint Online, Microsoft 365 Copilot und Defender XDR, und zwar in allen Regionen. Microsoft nennt als Ursache eine Reihe von Servern, die unerwartet nicht mehr verfügbar waren und so die übrige Infrastruktur überlasteten. Das Unternehmen stoppte alle Deployments, verteilte den Datenverkehr um und startete Server neu. Laut Neowin wirkten erste Gegenmaßnahmen nicht wie erhofft, ein Kernprozess auf den betroffenen Servern sei überlastet gewesen. Microsoft-Manager Charles Lamanna entschuldigte sich und erklärte, es gebe keine Hinweise auf einen Angriff. In der Nacht meldete Microsoft eine langsame Erholung, am Freitagmorgen zeigt die offizielle Statusseite aber weiter eine Dienstbeeinträchtigung; Microsoft spricht nur von teilweisem Erfolg, eine durchgehende Erholung ist noch nicht erreicht. Firmenkunden können laut Windows Latest über das Microsoft-365-Admin-Center eine SLA-Gutschrift beantragen. Ob und in welcher Höhe es Geld zurückgibt, hängt von der tatsächlich betroffenen Nutzerzahl und Dauer ab. Privatnutzer von Outlook.com haben in der Regel keinen Anspruch.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/massive-microsoft-365-outage-disrupts-outlook-teams-copilot-worldwide/"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-regrets-outlook-exchange-sharepoint-outage-after-admitting-it-still-cant-fix/"}, {"name": "heise online", "url": "https://www.heise.de/news/Microsoft-365-Stoerung-Serverausfaelle-legen-Teams-Exchange-und-Copilot-lahm-11523565.html"}, {"name": "Golem.de", "url": "https://www.golem.de/news/cloud-serverausfaelle-stoeren-outlook-und-microsoft-365-2611-215165.html"}, {"name": "Windows Latest (SLA-Gutschrift)", "url": "https://www.windowslatest.com/2026/11/13/microsoft-365-outage-you-may-get-money-off-your-bill-if-you-use-it-for-work-but-youll-have-to-ask-microsoft-for-it-as-a-server-failure-takes-down-outlook-teams-and-exchange/"}], "tags": ["Microsoft 365", "Outlook", "Teams", "Exchange", "Störung"], "archiviert_am": "2026-11-20T07:22:05.437Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.568Z"}, "id": "2026-11-13-nvidia-doj-ermittlungen", "datum": "2026-11-13T05:03:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Nvidia"], "kategorie": "Unternehmen", "titel": "Berichte: US-Justizministerium ermittelt nach Huang-Rücktritt gegen Nvidia, Supermicro und Megaspeed", "schlagzeile": "Nach Huangs Rücktritt: US-Justiz soll Ermittlungen gegen Nvidia starten", "kurz": "Laut Semafor haben mehrere Abteilungen des US-Justizministeriums Untersuchungen eingeleitet, die Nvidia, Supermicro und Megaspeed betreffen. Im Kern geht es um mutmaßlich nach China gelieferte KI-Beschleuniger. Anzeichen für eine Anklage gegen Nvidia oder Ex-CEO Jensen Huang gibt es bisher nicht.", "zusammenfassung": "Einen Tag nach dem Rücktritt von Jensen Huang wird es für Nvidia nicht ruhiger. Laut heise berichtet Semafor unter Berufung auf zwei Regierungsvertreter, dass verschiedene Abteilungen des US-Justizministeriums Untersuchungen eingeleitet haben. Betroffen sind demnach Nvidia, der Serverhersteller Supermicro und das in Singapur ansässige Unternehmen Megaspeed. Megaspeed wird vorgeworfen, Nvidia-KI-Beschleuniger trotz US-Exportbeschränkungen nach China geliefert zu haben. Im Mittelpunkt soll die Rolle einer früheren leitenden Megaspeed-Mitarbeiterin stehen, mit der Huang eine Beziehung gehabt haben soll. Laut heise gibt es bislang keine Anzeichen, dass das Ministerium Anklage gegen Nvidia oder Huang erheben wird. Nvidia und das Justizministerium wollten sich nicht äußern. Supermicro erklärte, Megaspeed sei nie Kunde gewesen, und sagte Kooperation mit den Behörden zu. Zusätzlich berichtet Reuters von einer weiteren Beziehung Huangs zu einer Nvidia-Mitarbeiterin. Für Käufer von GeForce-Karten hat das vorerst keine bekannten Folgen. Am 17. November legt Nvidia seine Quartalszahlen vor, dort dürfte das Thema zur Sprache kommen.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Berichte-ueber-kartellrechtliche-Pruefung-Nvidias-und-weitere-Affaere-des-Ex-Chefs-11523636.html"}, "weitere_links": [{"name": "PC Games Hardware (Quartalszahlen am 17.11.)", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Geforce-62124-Dawn-of-War-4-Huang-Ruecktritt-1559859/"}], "tags": ["Nvidia", "Jensen Huang", "Justizministerium", "Megaspeed", "Export"], "archiviert_am": "2026-11-20T07:22:05.438Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.608Z"}, "id": "2026-11-13-codex-radeon-r600-fix", "datum": "2026-11-13T02:41:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "AMD", "Treiber"], "kategorie": "Linux", "titel": "Mit Hilfe von OpenAI Codex: Fast 20 Jahre alter Videodekoder-Fehler bei Radeon-HD-2000/3000-Karten unter Linux behoben", "schlagzeile": "KI findet uralten Radeon-Bug: Fix für HD 2000/3000 kommt in Linux 7.5", "kurz": "Ein Hobby-Entwickler hat mit Hilfe von OpenAI Codex einen Videofehler bei fast 20 Jahre alten Radeon-GPUs der R600-Ära gefunden und behoben. Der Patch hält Videodaten im VRAM und landet in Linux 7.5. AMD pflegt diese Karten seit Jahren nicht mehr.", "zusammenfassung": "Unter den AMD-Grafiktreiber-Patches für Linux 7.5 steckt laut Phoronix eine ungewöhnliche Korrektur. Sie betrifft den Videodekoder UVD von Radeon-Karten der R600-Generation, also der Radeon HD 2000 und 3000 von vor fast 20 Jahren. Der Entwickler Ted Bullock bemerkte auf einem alten iMac mit RV610-Chip beschädigte Videobilder. Die Fehler traten auf, wenn der Dekoder komprimierte Videodaten aus dem Arbeitsspeicher las, während die GPU gleichzeitig zeichnete. Lagen die Daten im Grafikspeicher, liefen die Videos sauber. Sein Patch hält die UVD-Puffer deshalb für die Chips RV610, RV620, RV630, RV635 und RV670 im VRAM. Getestet hat er nur auf seiner eigenen Hardware, für die anderen Chips fehlt noch eine Bestätigung. Bullock schreibt offen, dass er OpenAI Codex bei Analyse, Tests und Patch genutzt hat. Der Patch wurde angenommen und kommt mit Linux 7.5. Die Merge-Phase dafür beginnt um den Jahreswechsel.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Codex-R600-UVD-FIx-Linux-7.5"}, "weitere_links": [], "tags": ["Linux", "Radeon", "AMD", "Treiber", "KI", "Retro"], "archiviert_am": "2026-11-20T07:22:05.438Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.516Z"}, "id": "2026-11-13-windhawk-patchday-fix", "datum": "2026-11-13T01:44:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "November-Patchday legt Windhawk-Mods lahm, Entwickler liefert Workaround", "schlagzeile": "Patchday legt Windhawk-Mods lahm – so laufen sie wieder", "kurz": "Nach dem November-Update KB5132061 funktionieren viele Mods des Anpassungs-Tools Windhawk nicht mehr, vor allem für Taskleiste und Explorer. Grund sind fehlende Debug-Symbole von Microsoft. Der Entwickler hat einen Workaround veröffentlicht, Mods einfach aus- und wieder einschalten.", "zusammenfassung": "Windhawk ist ein beliebtes Tool, mit dem sich Windows per Mods anpassen lässt, etwa die Taskleiste oder der Datei-Explorer. Seit dem November-Patchday melden Nutzer laut Neowin, dass ihre Mods nicht mehr laden. Das Problem tauchte am 10. November kurz nach dem Update KB5132061 in einem GitHub-Eintrag auf, betroffen sind Windows 11 und Windows 10. Windhawk-Entwickler Michael Maltsev bestätigte den Fehler. Ursache ist, dass Microsoft einige Debug-Symbole für die neuen Windows-Versionen nicht veröffentlicht hat. Windhawk braucht diese Symbole, um die Stellen im System zu finden, die eine Mod verändert. Laut Maltsev ist das nicht das erste Mal, dass Microsoft Symbole verspätet oder gar nicht bereitstellt. Als Lösung gibt es eine manuelle Zuordnung über den Symbol-Cache von Windhawk, die die meisten betroffenen Mods wieder zum Laufen bringt. Sie ist bereits im Online-Cache enthalten. Wer noch Probleme hat, sollte die betroffenen Mods in Windhawk deaktivieren und wieder aktivieren.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/patch-tuesday-updates-break-popular-windows-customization-tool-windhawk-but-theres-a-fix/"}, "weitere_links": [], "tags": ["Windows 11", "Windows 10", "Windhawk", "KB5132061", "Patchday"], "archiviert_am": "2026-11-20T07:22:05.439Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.684Z"}, "id": "2026-11-13-wolfenstein-3-offiziell", "datum": "2026-11-13T01:01:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Xbox bestätigt: Wolfenstein 3 ist bei MachineGames offiziell in Produktion", "schlagzeile": "Endlich offiziell: Wolfenstein 3 ist bei MachineGames in Arbeit", "kurz": "Xbox hat bei der FanFest zum 25-jährigen Jubiläum bestätigt, dass Wolfenstein 3 bei MachineGames in Produktion ist. Die Sprecher von B.J. Blazkowicz und Grace Walker sind wieder dabei. Einen Termin oder Plattformen gibt es noch nicht.", "zusammenfassung": "Lange wurde spekuliert, jetzt ist es offiziell: Wolfenstein 3 ist in Produktion. Xbox-Chefin Asha Sharma bestätigte das Projekt auf X im Rahmen der Xbox FanFest in Seattle. Entwickelt wird es erneut vom schwedischen Studio MachineGames, das zuletzt Indiana Jones und der Große Kreis gemacht hat. MachineGames zeigte dazu eine Seite aus dem Drehbuch mit dem Satz „His reputation precedes him“. Auf einem Foto aus dem Motion-Capture-Studio sind Brian Bloom und Debra Wilson zu sehen, die erneut B.J. Blazkowicz und Grace Walker spielen. Der Vorgänger Wolfenstein 2: The New Colossus erschien 2017. Studiochef Jerk Gustafsson hatte schon früher erklärt, B.J.s Geschichte sei immer als Trilogie geplant gewesen. Einen Trailer, Termin oder Plattformen hat Xbox noch nicht genannt. Parallel entsteht bei Amazon eine Wolfenstein-Serie.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/wolfenstein-3-confirmed-to-be-in-development-at-machinegames"}, "weitere_links": [{"name": "IGN Deutschland", "url": "https://de.ign.com/wolfenstein-iii/157214/es-ist-offiziell-wolfenstein-3-ist-gerade-bei-machinegames-in-entwicklung"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2121030203439010175"}], "tags": ["Wolfenstein 3", "MachineGames", "Xbox", "Bethesda", "Shooter"], "archiviert_am": "2026-11-20T07:22:05.442Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.251Z"}, "id": "2026-11-13-pocketpair-gta6-urlaub", "datum": "2026-11-12T23:08:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Palworld-Studio Pocketpair schickt seine Belegschaft zum GTA-6-Start auf „Dienstreise nach Vice City“", "schlagzeile": "GTA-6-Fieber: Palworld-Studio gibt allen zum Launch frei", "kurz": "Das Palworld-Studio Pocketpair stellt alle Mitarbeitenden, die GTA 6 spielen wollen, in der Launch-Woche frei. Offiziell heißt das „dringende Dienstreise nach Vice City“. Auch Logitech und weitere Firmen geben zum Launch frei.", "zusammenfassung": "GTA 6 erscheint am 19. November für Konsolen, und manche Firmen planen schon um. Das japanische Studio Pocketpair, bekannt für Palworld, hat auf X eine augenzwinkernde Mitteilung veröffentlicht. Alle Mitarbeitenden, die GTA 6 spielen wollen, werden vom 19. bis 23. November von ihren Aufgaben befreit und zu einer „Dienstreise nach Vice City“ ermutigt. Da in den Zeitraum ein Wochenende fällt, sind es effektiv drei freie Arbeitstage. Pocketpair betont, dass die Updates für Palworld und Craftopia trotzdem wie geplant kommen sollen. Laut PC Gamer ist das Studio nicht allein: Logitech gibt seinen rund 7.000 Beschäftigten am 19. November mit dem „Logi Game Day“ frei, wobei jedes Spiel erlaubt ist. Auch der US-Tuningteilehersteller Burger Motorsports und der kanadische Lkw-Hersteller Edison Motors haben freie Tage zum Launch angekündigt. Eine PC-Version von GTA 6 hat Rockstar weiterhin nicht terminiert.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/grand-theft-auto/palworld-developer-pocketpair-gives-employees-time-off-for-a-5-day-business-trip-in-vice-city-when-gta-6-launches/"}, "weitere_links": [], "tags": ["GTA 6", "Pocketpair", "Palworld", "Logitech"], "archiviert_am": "2026-11-20T07:22:05.443Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.975Z"}, "id": "2026-11-13-og-xbox-pc-21-spiele", "datum": "2026-11-12T23:01:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox", "PC"], "kategorie": "Spiele", "titel": "Xbox bringt 21 weitere Spiele der ersten Xbox auf den PC, vier Klassiker erhalten erstmals Erfolge", "schlagzeile": "KOTOR, Morrowind & Co.: 21 Ur-Xbox-Klassiker laufen jetzt am PC", "kurz": "Über die Abwärtskompatibilität auf dem PC laufen jetzt 21 weitere Spiele der ersten Xbox, insgesamt sind es 25. Dabei sind unter anderem Morrowind, beide KOTOR-Teile und TimeSplitters 2. Vier Spiele bekommen erstmals Erfolge.", "zusammenfassung": "Vier Monate nach dem Start der Abwärtskompatibilität für Spiele der ersten Xbox auf dem PC legt Microsoft nach. 21 weitere Titel sind hinzugekommen, damit umfasst der PC-Katalog nun 25 Spiele. Dazu gehören laut VGC und Thurrott unter anderem The Elder Scrolls III: Morrowind, Star Wars: Knights of the Old Republic I und II, Jedi Academy, Jedi Outcast, TimeSplitters 2 und Crimson Skies. Morrowind und Grabbed by the Ghoulies sind auch im Game Pass enthalten. Erstmals gibt es Erfolge für vier Klassiker: beide KOTOR-Teile, Blinx: The Time Sweeper und Conker: Live and Reloaded. Laut Xbox lassen sie sich am PC und auf der Konsole freischalten. Xbox-Vizepräsident Jason Ronald schreibt außerdem, die ersten vier Spiele liefen jetzt stabiler und schneller, und alle Titel unterstützten Maus und Tastatur. Weitere Spiele sollen folgen. Die Ankündigung gehört zur Xbox FanFest rund um das 25-jährige Jubiläum am 15. November.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/uncategorised/21-original-xbox-games-are-now-on-pc-via-backward-compatibility/"}, "weitere_links": [{"name": "Thurrott.com", "url": "https://www.thurrott.com/games/xbox/343819/microsoft-brings-21-more-og-xbox-games-to-pc-via-backward-compatibility"}, {"name": "Xbox auf X", "url": "https://x.com/XBOX/status/2120986769974083713"}], "tags": ["Xbox", "Abwärtskompatibilität", "PC", "KOTOR", "Morrowind", "Retro"], "archiviert_am": "2026-11-20T07:22:05.443Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.431Z"}, "id": "2026-11-13-geforce-621-24", "datum": "2026-11-12T23:00:00+01:00", "label": "News", "bereich": "software", "themen": ["GPU", "Nvidia", "Treiber"], "kategorie": "Treiber", "titel": "Nvidia GeForce 621.24 WHQL: Game Ready für Dawn of War 4 und Assetto Corsa Rally, Vorbereitung auf DLSS 5 in Where Winds Meet", "schlagzeile": "GeForce 621.24: Neuer Treiber für Dawn of War 4 und DLSS 5", "kurz": "Nvidia hat den GeForce-Treiber 621.24 WHQL veröffentlicht, nur acht Tage nach 621.14. Er ist Game Ready für Dawn of War 4 und Assetto Corsa Rally und bereitet DLSS 5 in Where Winds Meet vor. Behoben werden nur zwei Fehler, die vor allem Profi- und Videoanwendungen betreffen.", "zusammenfassung": "Mit GeForce 621.24 WHQL liefert Nvidia den vierten Treiber innerhalb von 22 Tagen. Im Mittelpunkt steht laut PCGH Warhammer 40.000: Dawn of War 4, das am 3. Dezember erscheint, Käufer der Commander Edition dürfen schon am 30. November spielen. Auch Assetto Corsa Rally ist optimiert, die Rallye-Simulation soll am 19. November ein Update mit DLSS 4.5 und Dynamic Multi Frame Generation erhalten. Diese Bildgenerierung setzt eine GeForce RTX 5000 voraus. Am 23. November soll Where Winds Meet DLSS 5 mit neuem Neural Rendering bekommen, laut PCGH nur für Blackwell-Karten und RTX-Spark-Systeme. Behoben wurden zwei Fehler: Der OptiX-Denoiser in Chaos Vantage konnte bei hohen Auflösungen versagen, und H.265-Videos von DJI im D-Log-Profil wurden in Windows-Apps mit falschen Farben gezeigt. Offene Fehler nennen die Release Notes zum Start nicht. Neu ist außerdem CUDA 13.5. Unterstützt werden Desktop-Karten von der GTX 1630 bis zur RTX 5090, Pascal und Maxwell sind nicht mehr dabei. Wer keines der genannten Spiele spielt, muss nicht sofort aktualisieren.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Geforce-62124-Dawn-of-War-4-Huang-Ruecktritt-1559859/"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354746/nvidia-geforce-621-24-whql-game-ready-drivers-released"}], "tags": ["Nvidia", "GeForce", "Treiber", "DLSS 5", "Dawn of War 4"], "archiviert_am": "2026-11-20T07:22:05.444Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.458Z"}, "id": "2026-11-13-amd-china-gpu-kuerzung", "datum": "2026-11-12T22:14:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["GPU", "AMD"], "kategorie": "Grafikkarten", "titel": "Bericht: AMD soll die Lieferungen von Gaming-GPUs in China seit Oktober um 20 bis 50 Prozent gekürzt haben", "schlagzeile": "Leak: Kürzt AMD die Radeon-Lieferungen in China um bis zu 50 %?", "kurz": "AMD soll seine Gaming-GPU-Lieferungen an Boardpartner in China seit Oktober um 20 bis 50 Prozent gekürzt haben. Das berichtet das chinesische Forum Board Channels, die Knappheit soll bis Januar anhalten. AMD hat sich dazu nicht geäußert.", "zusammenfassung": "Laut einem Beitrag im chinesischen Branchenforum Board Channels vom 12. November hat AMD die Menge an Gaming-Grafikchips für seine Boardpartner in China seit Beginn des vierten Quartals deutlich reduziert. Die Rede ist von mindestens 20 bis 50 Prozent weniger, die monatlichen Zuteilungen sollen weiter sinken. Die Lage sei damit inzwischen ähnlich knapp wie bei Nvidia. Die Quelle erwartet, dass das Angebot bis Januar sehr knapp bleibt. Radeon-Preise in China sollen jedes Quartal steigen, begründet wird das mit höheren Kosten für Speicher und GPUs. AMD soll den Preis seiner Pakete aus GPU und GDDR6 in diesem Monat erneut anheben, nach einer Erhöhung im Oktober. TechPowerUp weist darauf hin, dass der Bericht keine konkreten Stückzahlen, betroffenen Modelle oder Gründe nennt. Er betrifft zudem nur China, ob Europa oder die USA ähnliche Kürzungen sehen, ist offen. AMD hat den Bericht nicht kommentiert. Die Angaben sind unbestätigt und sollten als Hinweis auf die Marktlage verstanden werden, nicht als Fakt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354757/amd-reportedly-cuts-gaming-gpu-supply-in-china-by-up-to-50"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Ursprung ist ein Beitrag im chinesischen Branchenforum Board Channels (via VideoCardz, TechPowerUp); keine Zahlen zu Modellen oder Stückzahlen, von AMD nicht bestätigt. Board Channels lag bei Liefer- und Preisthemen schon öfter richtig."}, "tags": ["AMD", "Radeon", "China", "Preise", "Lieferengpass"], "archiviert_am": "2026-11-20T07:22:05.444Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.881Z"}, "id": "2026-11-13-fable-gameplay-4-minuten", "datum": "2026-11-12T21:16:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Xbox zeigt vier Minuten neues Gameplay aus Fable, Release am 23. Februar 2027", "schlagzeile": "Vier Minuten neues Fable: Kämpfe, Magie und ein düsterer Wald", "kurz": "Xbox hat vier Minuten neues Gameplay aus dem Fable-Reboot von Playground Games veröffentlicht. Zu sehen sind Nahkampf, Fernkampf und Magie, aufgenommen auf dem PC in Ultra-Einstellungen. Fable erscheint am 23. Februar 2027 für Xbox Series X|S, PS5 und PC.", "zusammenfassung": "Zum 25-jährigen Xbox-Jubiläum hat Xbox-Chefin Asha Sharma ein neues Gameplay-Video zu Fable geteilt. Die vier Minuten zeigen laut IGN vor allem Kämpfe mit Schwert, Fernkampfwaffen und Magie. Aufgenommen wurde auf dem PC mit Ultra-Grafikeinstellungen. Inhaltlich geht es um den Helden von Briar Hill, der mit einer einheimischen Heldin im Wald Deepwood seltsamen magischen Vorfällen nachgeht. Entwickelt wird das Spiel von Playground Games, bekannt für die Forza-Horizon-Reihe. Fable war ursprünglich für diesen Herbst geplant und wurde auf den 23. Februar 2027 verschoben. Es erscheint für Xbox Series X|S, PS5 und PC, auf Steam ist es bereits vorbestellbar. Die Reaktionen sind gemischt: PC Gamer findet, das Video wirke düster und eher gewöhnlich und erinnere wenig an die bunte, schräge Fable-Reihe. In den YouTube-Kommentaren fiel das Echo dagegen überwiegend positiv aus. Ein kurzer Clip zeigt naturgemäß nur einen kleinen Ausschnitt des Spiels.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/fable-drops-four-minutes-of-new-gameplay"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/games/rpg/new-4-minute-fable-gameplay-trailer-shows-a-game-that-doesnt-look-much-like-fable/"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120955243790057796"}], "tags": ["Fable", "Playground Games", "Xbox", "PS5", "Rollenspiel"], "archiviert_am": "2026-11-20T07:22:05.444Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.789Z"}, "id": "2026-11-13-id-software-neues-spiel", "datum": "2026-11-12T21:00:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "id Software bestätigt neues Spiel unter Regie von Hugo Martin, Doom: The Dark Ages bekommt Slaughter Mode", "schlagzeile": "Doom-Macher id Software arbeitet schon am nächsten Spiel", "kurz": "id Software arbeitet an einem neuen Spiel, das wieder Hugo Martin als Game Director leitet. Welche Marke es wird, ist offen. Zuvor bekommt Doom: The Dark Ages am 16. November einen kostenlosen Slaughter Mode für Besitzer der Revelations-Erweiterung.", "zusammenfassung": "Xbox-Chefin Asha Sharma hat während der Xbox FanFest bestätigt, dass id Software bereits am nächsten Spiel arbeitet. Das Studio selbst schrieb auf X, das Projekt entstehe in den Teams in Texas und Frankfurt, Game Director sei erneut Hugo Martin. Martin war Creative Director bei Doom (2016) und Doom Eternal sowie Game Director von Doom: The Dark Ages. Ob es ein neues Doom, ein Quake oder etwas ganz anderes wird, verrät id nicht. Laut id wird es noch einige Zeit dauern, bis es mehr zu zeigen gibt, das Projekt steht also wohl noch am Anfang. VGC erinnert daran, dass id Software zuletzt stark von den Xbox-Entlassungen betroffen war, insgesamt verloren dort 136 Menschen ihre Jobs. Zuvor kommt am 16. November der Slaughter Mode für Doom: The Dark Ages. Der endlose Einzelspieler-Modus ist ein kostenloses Update für alle, die die Erweiterung Revelations besitzen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/doom-developer-id-software-confirms-work-on-new-game-will-be-directed-by-hugo-martin"}, "weitere_links": [{"name": "VGC", "url": "https://www.videogameschronicle.com/news/id-software-confirms-its-working-on-a-new-game-after-layoffs/"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/fps/doom-studio-id-software-confirms-its-working-on-a-new-game/"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120969774062817747"}], "tags": ["id Software", "Doom", "Hugo Martin", "Xbox", "Shooter"], "archiviert_am": "2026-11-20T07:22:05.444Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.320Z"}, "id": "2026-11-13-cmp170hx-80gb-hack", "datum": "2026-11-12T20:52:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia", "KI"], "kategorie": "Grafikkarten", "titel": "Hardware-Hack: Nvidias Mining-Karte CMP 170HX lässt sich auf 80 GB HBM2e und bis zu 126 SMs freischalten", "schlagzeile": "Aus 8 werden 80 GB: Hack macht Nvidias Mining-Karte zur KI-Karte", "kurz": "Eine Entwicklerin hat bei Nvidias alter Mining-Karte CMP 170HX per Spannungs-Trick die vollen 80 GB HBM2e statt 8 GB freigeschaltet. Auch bis zu 126 statt 70 Recheneinheiten ließen sich aktivieren. Der Umbau erfordert Löten, ist dauerhaft und kann die Karte zerstören.", "zusammenfassung": "Die CMP 170HX hat Nvidia 2021 als reinen Ethereum-Beschleuniger verkauft, im Inneren steckt aber derselbe GA100-Chip wie in der Rechenzentrumskarte A100. Ab Werk sind nur 8 GB der eigentlich verbauten 80 GB HBM2e nutzbar, dazu 70 von 128 Streaming-Multiprozessoren. Mit dem Software-Tool cmpunlocker ließen sich schon seit dem Sommer bis zu 64 GB freischalten. Eine Entwicklerin namens Kate geht mit einem am 10. November veröffentlichten Hardware-Hack weiter: Eine kleine Zusatzplatine mit STM32-Mikrocontroller erzeugt gezielte Spannungseinbrüche und bringt so den eFuse-Controller dazu, gesperrte Einstellungen wieder anzunehmen. Laut ComputerBase lieferten neun von zehn getesteten Karten danach die vollen 80 GB, eine kam auf 64 GB. Je nach Exemplar wurden außerdem 120 bis 126 SMs aktiv. In einem OpenCL-FP16-Test erreichte die umgebaute Karte 85,9 TFLOPS und lag damit vor einer regulären A100 mit 72,5 TFLOPS. Dieser Wert lässt sich laut ComputerBase aber nicht direkt auf echte KI-Anwendungen übertragen. Auch PCIe 4.0 x16 und NVLink sollen sich mit zusätzlichen Anpassungen freischalten lassen. Der Haken: Der Eingriff braucht Lötarbeiten und laut der Entwicklerin zwischen einer und 48 Stunden Versuche. Die Änderungen an den eFuses sind dauerhaft, ein Fehler kann die Karte unbrauchbar machen. Dass auch andere Exemplare so viel funktionsfähige Hardware haben, ist nicht garantiert.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/grafikkarten/nvidia-mining-gpu-80-gb-statt-8-gb-vram-und-80-prozent-mehr-kerne-per-hack.100309/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Nvidia-CMP-170HX-A100-Hack-80-GiB-VRAM-Voltage-Glitching-1559861/"}], "tags": ["Nvidia", "CMP 170HX", "GA100", "HBM2e", "Mod", "KI"], "archiviert_am": "2026-11-20T07:22:05.445Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.158Z"}, "id": "2026-11-13-game-awards-disney-plus", "datum": "2026-11-12T20:17:00+01:00", "label": "News", "bereich": "games", "themen": [], "kategorie": "Spiele", "titel": "The Game Awards 2026 laufen erstmals auch auf Disney+", "schlagzeile": "The Game Awards 2026 laufen erstmals auch auf Disney+", "kurz": "Die Game Awards 2026 werden erstmals auch auf Disney+ übertragen. Twitch, YouTube und weitere Plattformen bleiben dabei, die Show steigt am 10. Dezember in Los Angeles.", "zusammenfassung": "Die Game Awards bekommen in diesem Jahr einen neuen Partner: Laut IGN wird die Show erstmals auch auf Disney+ gestreamt. Daneben läuft sie wie gewohnt auf Twitch und YouTube sowie unter anderem auf Steam, TikTok, X, Facebook und Kick. Die Verleihung findet am Donnerstag, 10. Dezember, im Peacock Theater in Los Angeles statt. Los geht es um 19:30 Uhr Ostküstenzeit, in Mitteleuropa ist das in der Nacht auf den 11. Dezember um 1:30 Uhr. Moderiert wird wieder von Geoff Keighley. Laut Variety will Disney die Partnerschaft nutzen, um eigene Spiele- und Animationsprojekte zu bewerben. Zu den Favoriten zählt IGN unter anderem Resident Evil Requiem, 007 First Light und das Ocarina-of-Time-Remake. GTA 6 erscheint am 19. November und ist damit gerade noch für die diesjährigen Awards zugelassen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/the-game-awards-2026-are-coming-to-disney"}, "weitere_links": [], "tags": ["The Game Awards", "Disney+", "Geoff Keighley", "GTA 6"], "archiviert_am": "2026-11-20T07:22:05.445Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.063Z"}, "id": "2026-11-13-halo-ce-firefight", "datum": "2026-11-12T19:46:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Halo: Campaign Evolved bekommt diesen Winter Firefight als kostenloses Update", "schlagzeile": "Halo: Campaign Evolved bekommt gratis Firefight-Modus", "kurz": "Das Halo-Remake Campaign Evolved erhält diesen Winter den Firefight-Modus als kostenloses Update. Bis zu vier Spieler kämpfen darin gemeinsam gegen Gegnerwellen. Mehr Details soll es beim Halo Fest Mitte Dezember geben.", "zusammenfassung": "Xbox hat bei der FanFest angekündigt, dass Halo: Campaign Evolved einen Firefight-Modus bekommt. Firefight ist ein kooperativer PvE-Modus für bis zu vier Spieler, der schon in mehreren Halo-Teilen enthalten war. Das Update kommt kostenlos irgendwann in diesem Winter, ein genaues Datum gibt es noch nicht. Besucher der FanFest sollten den Modus laut VGC bereits vor Ort anspielen können. Weitere Details will Xbox beim Halo Fest am 12. und 13. Dezember nennen. Halo: Campaign Evolved ist ein Remake der Kampagne des ersten Halo und erschien im Juli. VGC weist darauf hin, dass das kleiner gewordene Halo Studios nach den Xbox-Entlassungen nur noch bestehende Halo-Spiele betreut. Ein neues Halo entsteht laut VGC bei Activision.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/news/halo-campaign-evolved-is-getting-firefight-in-a-free-update/"}, "weitere_links": [{"name": "Thurrott.com", "url": "https://www.thurrott.com/games/343808/halo-campaign-evolved-to-get-firefight-mode"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120925412788498530"}], "tags": ["Halo", "Halo Studios", "Xbox", "Koop", "Update"], "archiviert_am": "2026-11-20T07:22:05.445Z"}, {"id": "2026-11-12-amd-26-11-1-ssd-fix", "datum": "2026-11-12T18:42:00+01:00", "label": "News", "bereich": "software", "themen": ["Treiber", "AMD"], "kategorie": "Treiber", "titel": "AMD Adrenalin 26.11.1 behebt das dauerhafte Schreiben auf SSDs", "schlagzeile": "Radeon-Treiber 26.11.1: AMD stoppt endlich das SSD-Dauerschreiben", "kurz": "AMD hat den optionalen Treiber Adrenalin 26.11.1 veröffentlicht. Er behebt offiziell den Fehler, durch den der Treiber im Hintergrund ständig Daten auf die SSD schrieb. Die Liste der bekannten Probleme ist allerdings länger geworden.", "zusammenfassung": "Radeon-Nutzer hatten entdeckt, dass der Adrenalin-Treiber im Hintergrund dauerhaft Daten auf das Laufwerk schreibt, selbst im Leerlauf. Heise warnte, dass das die Lebensdauer von SSDs gefährden kann, zuletzt half nur ein Gratis-Tool aus der Community. Jetzt hat AMD laut Wccftech und Neowin den optionalen Treiber 26.11.1 veröffentlicht, der das Problem offiziell beheben soll. Betroffen waren laut den Versionshinweisen Besitzer von Radeon RX 7000 und RX 9000, auch beim Verschieben oder Vergrößern von Fenstern trat der Fehler auf. Die Liste der bekannten Probleme umfasst neun neue Einträge, vor allem Abstürze und Treiber-Timeouts in einzelnen Spielen wie Cyberpunk 2077 und War Thunder. Auf RX-9000-Karten nennt AMD zudem Bildfehler in Phantom Blade Zero. Wer vom SSD-Problem betroffen ist, sollte das Update installieren und kann das Community-Tool danach entfernen.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/amd-pushes-excessive-ssd-writes-fix-via-latest-adrenalin-edition-26-11-1-optional-driver/"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/amd-outs-must-install-26111-emergency-driver-to-fix-drive-bug-that-kept-writing-non-stop/"}, {"name": "heise online", "url": "https://www.heise.de/news/SSD-Lebensdauer-gefaehrdet-AMD-Treiber-verursacht-hohe-Schreiblast-11522544.html"}], "tags": ["AMD", "Adrenalin", "Treiber", "SSD", "Radeon"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.674Z"}, "archiviert_am": "2026-11-19T18:25:35.288Z"}, {"id": "2026-11-12-gdc-umfrage-entlassungen", "datum": "2026-11-12T18:04:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spiele", "titel": "GDC-Umfrage: Jede dritte befragte Person in der Spielebranche wurde in zwei Jahren entlassen", "schlagzeile": "GDC-Umfrage: Jeder dritte Befragte aus der Spielebranche wurde entlassen", "kurz": "In der neuen GDC-Umfrage unter über 2.600 Branchenleuten gaben 34 Prozent an, in den letzten zwei Jahren entlassen worden zu sein. Mehr als die Hälfte davon ist noch ohne Job. Die Stimmung in der Branche ist laut Umfrage schlecht.", "zusammenfassung": "Die 15. Ausgabe der Umfrage „State of the Game Industry“ der GDC hat über 2.600 Branchenleute weltweit befragt, berichtet VGC. 34 Prozent gaben an, in den letzten zwei Jahren entlassen worden zu sein, in den USA sogar 39 Prozent. In der Umfrage vom Januar lag der Wert noch bei 28 Prozent. Von den Entlassenen sind 54 Prozent weiterhin arbeitslos, 27 Prozent haben mindestens 100 Bewerbungen geschrieben. 17 Prozent wurden in zwei Jahren sogar zweimal entlassen. Nur 45 Prozent der Beschäftigten halten ihren Job für die nächsten zwölf Monate zumindest etwas für sicher. 81 Prozent machen sich Sorgen um ihre Zukunft in der Branche.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/one-in-three-games-industry-professionals-surveyed-by-gdc-were-laid-off-in-the-past-two-years-more-than-in-its-last-report/"}, "weitere_links": [], "tags": ["GDC", "Entlassungen", "Spielebranche", "Umfrage"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.482Z"}, "archiviert_am": "2026-11-19T18:25:35.304Z"}, {"id": "2026-11-12-steam-pruefstau-ki", "datum": "2026-11-12T17:06:00+01:00", "label": "News", "bereich": "games", "themen": ["Steam", "KI"], "kategorie": "Spiele", "titel": "Steam-Prüfstau durch KI-Spieleflut: Weitere Indie-Spiele müssen verschoben werden", "schlagzeile": "KI-Spieleflut auf Steam: Indie-Games hängen in Valves Prüfschlange", "kurz": "Valves Prüfung neuer Spiele auf Steam dauert derzeit bis zu zwölf Tage, laut Entwicklern wegen einer Flut minderwertiger KI-Spiele. Mehrere Indie-Titel mussten ihren Release verschieben. Valve hat die Einreichregeln verschärft, Kritiker halten das für zu wenig.", "zusammenfassung": "Seit Anfang November klagen Entwickler über lange Wartezeiten bei Valves Freigabe neuer Spiele und Builds auf Steam. Valve erklärte laut Eurogamer, dass Prüfungen wegen der Menge an erneut zu prüfenden Einreichungen bis zu zwölf Tage dauern können. Als Ursache gilt eine Flut von Billigspielen, die mit generativer KI erstellt wurden. Das Tower-Defense-Spiel Australia Did It von Rami Ismail und Aesthetician Labs sollte am 10. November erscheinen und wartet weiterhin auf die Freigabe. Auch Amazing Slot Survivor musste seinen Termin am 13. November zurückziehen, weitere Indie-Spiele sind betroffen. Valve hat strengere Einreichregeln eingeführt, um komplett KI-generierte Spiele früher auszusortieren. Ismail meint, Valve könne beim Thema KI nicht neutral bleiben, ohne echten Entwicklern zu schaden.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/steam-game-submission-review-backlog-ai-slop-approval-delays"}, "weitere_links": [], "tags": ["Steam", "Valve", "KI", "Indie"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.379Z"}, "archiviert_am": "2026-11-19T18:25:35.305Z"}, {"id": "2026-11-12-windows-signdrop-zero-day", "datum": "2026-11-12T17:04:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows", "Sicherheit"], "kategorie": "Sicherheit", "titel": "SignDrop: Neue Windows-Zero-Day-Lücke verschafft SYSTEM-Rechte, noch kein Patch", "schlagzeile": "Windows-Zero-Day SignDrop: SYSTEM-Rechte und noch kein Patch", "kurz": "Ein Sicherheitsforscher hat mit SignDrop eine neue, ungepatchte Windows-Lücke samt Exploit veröffentlicht. Sie soll Angreifern SYSTEM-Rechte verschaffen und den Selbstschutz von Virenscannern aushebeln. Laut dem Forscher sind rund 80 Prozent der Windows-Installationen betroffen.", "zusammenfassung": "Der Forscher Abdelhamid Naceri, bekannt als Nightmare Eclipse, hat laut BleepingComputer einen neuen Zero-Day-Exploit für Windows veröffentlicht. SignDrop nutzt ausgerechnet eine Schutzmaßnahme aus, die Microsoft im Oktober 2025 für den Common Log File System-Treiber (CLFS) eingeführt hat. Über einen Umweg können privilegierte Prozesse wie Windows Defender dazu gebracht werden, Dateien mit SYSTEM-Rechten anzulegen. Laut Naceri lässt sich so auch der Manipulationsschutz von Antiviren- und EDR-Software umgehen. Getestet hat er Windows 11 26H2 und Windows Server 2025, er schätzt, dass rund 80 Prozent der Installationen verwundbar sind. Anfällig sind Systeme, bei denen der Registry-Wert für den CLFS-Authentifizierungsmodus auf 0 oder 1 steht. Einen Workaround gibt es laut Naceri nicht, Nutzer müssen auf einen Patch von Microsoft warten. Eine Stellungnahme von Microsoft nennt der Bericht nicht.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/new-windows-signdrop-zero-day-gives-hackers-system-privileges/"}, "weitere_links": [], "tags": ["Windows 11", "Zero-Day", "Sicherheitslücke", "CLFS"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:23.019Z"}, "archiviert_am": "2026-11-19T18:25:35.305Z"}, {"id": "2026-11-12-gta6-karte-leak", "datum": "2026-11-12T16:40:00+01:00", "label": "Leak", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6: Gedruckte Karte aus der Collector's Edition soll über ein Merch-Event geleakt sein", "schlagzeile": "Leak: Ist die GTA-6-Karte schon eine Woche vor Release im Netz?", "kurz": "Im Netz kursieren Fotos einer gedruckten, stilisierten Karte von Leonida, die aus der GTA-6-Collector's-Edition stammen soll. Die Bilder sollen von einer Merch-Aktion bei Selfridges in Großbritannien stammen. Rockstar hat sich nicht geäußert, und die Karte ist wohl keine exakte Kopie der Spielwelt.", "zusammenfassung": "Eine Woche vor dem Release von GTA 6 am 19. November tauchen laut VGC und Insider Gaming Fotos einer Karte auf. Sie sollen die gedruckte Karte aus der Collector's Edition zeigen und von einer GTA-6-Aktion der Kaufhauskette Selfridges stammen. Das deutlichste Bild kam laut VGC von einem inzwischen gelöschten Instagram-Konto, ein weiteres Foto zeigt die Karte gefaltet in einer Vitrine in Manchester. Laut Insider Gaming soll ein Selfridges-Mitarbeiter die Quelle sein, das ist aber nicht belegt. Die Karte zeigt Leonida stilisiert mit Bezirken und Clipart-artigen Motiven, wie Monstertrucks, ein UFO und Flugzeuge. Insider Gaming geht davon aus, dass sie die Spielwelt nicht exakt wiedergibt. Rockstar hat die Bilder nicht bestätigt. Wer sich nicht spoilern lassen will, sollte in sozialen Netzwerken vorsichtig sein.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/gta-6-map-seemingly-leaks-at-selfridges-merch-drop/"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/gta-6-full-map-leak-online-from-collectors-box/"}, {"name": "Polygon", "url": "https://www.polygon.com/gta-6-map-leonidas-leak-merch-drop/"}], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Fotos eines physischen Merch-Artikels, von VGC, Insider Gaming und Polygon aufgegriffen; Herkunft und Echtheit nicht bestätigt, Rockstar/Take-Two schweigen. Nach Ticker-Regel gilt bei GTA 6 nur Rockstar/Take-Two als bestätigt."}, "tags": ["GTA 6", "Rockstar", "Karte", "Leonida", "Collector's Edition"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.022Z"}, "archiviert_am": "2026-11-19T18:25:35.305Z"}, {"id": "2026-11-12-xbox-25-sharma-memo", "datum": "2026-11-12T16:15:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox", "KI"], "kategorie": "Spiele", "titel": "25 Jahre Xbox: Asha Sharma deutet in Memo KI-Entwicklung an, dazu Halo-Firefight und Xbox Playback", "schlagzeile": "25 Jahre Xbox: Chefin will mit kleinen Teams riesige Welten bauen", "kurz": "Zum 25. Geburtstag der Xbox hat Chefin Asha Sharma ein Memo veröffentlicht, das stark nach generativer KI klingt. Kleine Teams sollen künftig Welten bauen, für die heute Hunderte Entwickler nötig sind. Dazu kündigte Xbox einen Firefight-Modus für Halo: Campaign Evolved und den Jahresrückblick Xbox Playback an.", "zusammenfassung": "Xbox-Chefin Asha Sharma hat zum 25-jährigen Jubiläum ein Memo mit dem Titel „25 Years of Xbox“ veröffentlicht. Am Ende schreibt sie, zu viele Ideen würden nie zu Spielen, und das müsse sich ändern. Bald werde ein einzelner Mensch Fähigkeiten haben, für die früher ganze Nationen nötig waren, und kleine Teams könnten Welten bauen, die heute Hunderte Entwickler erfordern. Das Wort generative KI fällt laut Eurogamer nicht, die Formulierungen deuten aber stark darauf hin. Sharma kommt aus dem KI-Bereich von Microsoft, hatte zum Start als Xbox-Chefin aber gesagt, sie habe „keine Toleranz für schlechte KI“. Zum Jubiläum kündigte sie außerdem auf X einen Firefight-Modus für Halo: Campaign Evolved an, der als kostenloses Update im Winter kommt; laut Insider Gaming ist es ein PvE-Modus für vier Spieler. Zusätzlich rollt Xbox Playback aus, ein Rückblick auf die eigenen Spiele und Erfolge auf Xbox. Konkrete KI-Projekte hat Xbox in dem Memo nicht genannt.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/microsoft-xbox-gen-ai-asha-sharma-memo"}, "weitere_links": [{"name": "IGN", "url": "https://www.ign.com/articles/as-xbox-turns-25-ceo-asha-sharma-says-a-single-person-will-soon-be-able-to-wield-capabilities-that-once-required-entire-nations"}, {"name": "Insider Gaming", "url": "https://insider-gaming.com/xbox-ceo-asha-sharmas-full-memo-on-25-years-of-xbox/"}, {"name": "Asha Sharma auf X (Halo Firefight)", "url": "https://x.com/asha_shar/status/2120925412788498530"}], "tags": ["Xbox", "Asha Sharma", "KI", "Halo", "Xbox Playback"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.190Z"}, "archiviert_am": "2026-11-19T18:25:35.306Z"}, {"id": "2026-11-12-gta6-suedkorea-freigabe", "datum": "2026-11-12T15:26:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6 hätte in Südkorea wegen Nacktszenen beinahe keine Altersfreigabe bekommen", "schlagzeile": "GTA 6 fast verboten? Südkorea stritt wochenlang über Nacktszenen", "kurz": "Die südkoreanische Prüfstelle GCRB konnte sich bei GTA 6 lange nicht auf eine Einstufung einigen. Knackpunkt war Nacktheit ohne sexuellen Kontext. Am Ende gab es mit acht zu eins Stimmen die Freigabe „nur für Erwachsene“.", "zusammenfassung": "Rockstar hat laut IGN Deutschland am 1. September eine Altersfreigabe in Südkorea beantragt. Die erste Abstimmung der Prüfstelle GCRB am 10. September endete unentschieden, drei Mitglieder wollten die Einstufung verweigern, drei waren für „nur für Erwachsene“. Laut den Sitzungsprotokollen, die InvenGlobal erhalten hat, störten sich einige Mitglieder an Nacktszenen ohne sexuellen Zusammenhang. Die Entscheidung wurde vertagt, bis eine spielbare Version vorlag, mehrere Termine wurden verschoben. Am 18. Oktober beschloss der Ausschuss dann mit acht zu einer Stimme die Einstufung „nur für Erwachsene“. Eine Verweigerung hätte den Verkauf in Südkorea komplett verhindert. GTA 6 erscheint am 19. November für PS5 und Xbox Series X und S.", "quelle": {"name": "IGN Deutschland", "url": "https://de.ign.com/grand-theft-auto-vi/157197/gta-6-ware-in-sudkorea-wegen-nackter-genitalien-beinahe-keine-altersfreigabe-erteilt-worden"}, "weitere_links": [{"name": "Polygon", "url": "https://www.polygon.com/gta-6-south-korea-rating-male-nudity/"}], "tags": ["GTA 6", "Altersfreigabe", "Südkorea", "Rockstar"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.107Z"}, "archiviert_am": "2026-11-19T18:25:35.306Z"}, {"id": "2026-11-12-nvidia-linux-nvroot-forgeptr", "datum": "2026-11-12T15:17:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit", "Treiber"], "kategorie": "Sicherheit", "titel": "NvRoot und ForgePtr: Zwei Sicherheitslücken im Nvidia-Linux-Treiber veröffentlicht, 25 weitere angekündigt", "schlagzeile": "Nvidia-Linux-Treiber: Lücke macht Container-Prozesse zu Root", "kurz": "Die Sicherheitsfirma Stealthium hat zwei Lücken in Nvidias offenen Linux-Kernelmodulen veröffentlicht. Über ForgePtr kann ein Prozess in einem GPU-Container Root auf dem Host werden. Patches gibt es bereits, weitere 25 Meldungen sollen folgen.", "zusammenfassung": "Laut Phoronix sind die ersten zwei von insgesamt 27 angekündigten Sicherheitslücken in Nvidias Treiber-Stack öffentlich. ForgePtr (CVE-2026-47501) erlaubt einem nicht privilegierten Prozess in einem GPU-Container, Root-Rechte auf dem Host zu erlangen. Mit NvRoot (CVE-2026-47591) kann die GPU Dateien überschreiben, die das Betriebssystem als schreibgeschützt markiert hat. Beide Lücken stecken seit rund vier Jahren in Nvidias offenen Kernelmodulen und sind als hoch (CVSS 7,8) eingestuft. Besonders betroffen sind Cloud-Anbieter, die GPUs an mehrere Kunden vermieten. NvRoot ist mit den Treibern 610.57.04, 595.91.07 und 580.178.04 behoben, ForgePtr mit 615.71.09. Stealthium hat laut Phoronix 25 weitere Meldungen zum KI-Software-Stack von Nvidia angekündigt. Wer Nvidia-GPUs unter Linux nutzt, vor allem in Containern, sollte den Treiber aktualisieren.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/NVIDIA-NvRoot-ForgePtr"}, "weitere_links": [], "tags": ["Nvidia", "Linux", "Sicherheitslücke", "Treiber", "Cloud"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.892Z"}, "archiviert_am": "2026-11-19T18:25:35.306Z"}, {"id": "2026-11-12-huang-ruecktritt-kress", "datum": "2026-11-12T15:04:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Unternehmen", "titel": "Jensen Huang tritt nach 33 Jahren als Nvidia-CEO zurück, CFO Colette Kress übernimmt vorübergehend", "schlagzeile": "Ende einer Ära: Jensen Huang tritt bei Nvidia zurück", "kurz": "Nvidia hat den Rücktritt von Mitgründer und CEO Jensen Huang bekanntgegeben, er legt alle Ämter mit sofortiger Wirkung nieder. Finanzchefin Colette Kress führt das Unternehmen vorerst als Interims-CEO. Den Vorsitz im Verwaltungsrat übernimmt Harvey C. Jones.", "zusammenfassung": "Nach Tagen der Krise ist es offiziell: Jensen Huang tritt nach 33 Jahren an der Spitze von Nvidia zurück. Laut ComputerBase legt er seine Ämter als Präsident, CEO und Mitglied des Verwaltungsrats nieder, laut PC Gamer mit sofortiger Wirkung. Huang wurde nicht entlassen, er hat laut TechPowerUp ein Rücktrittsschreiben unterzeichnet. Auslöser waren Berichte über zwei außereheliche Beziehungen, darunter eine zu einer Managerin, die ihm direkt unterstellt war. Zuvor hatte der Verwaltungsrat in einer außerplanmäßigen Sitzung beraten, laut Bloomberg wurde bereits eine externe Firma für die Nachfolgesuche eingeschaltet. Finanzchefin Colette Kress leitet die Geschäfte vorübergehend als CEO und bleibt parallel CFO. Den Vorsitz im Verwaltungsrat übernimmt Harvey C. Jones. Kress kündigte an, auf dem Fundament aufzubauen, das Huang in 33 Jahren geschaffen habe. Ob Huang künftig noch eine Rolle im Unternehmen spielt, geht aus der Mitteilung nicht hervor. Wer dauerhaft CEO wird, ist offen; dazu gibt es bisher nur Spekulationen. Auswirkungen auf GeForce-Produkte, Preise oder Treiber sind derzeit nicht bekannt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/mr-nvidia-muss-gehen-jensen-huang-tritt-nach-33-jahren-als-ceo-zurueck.100305/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Nvidia-Jensen-Huang-Ruecktritt-CEO-Colette-Kress-Nachfolgerin-1559816/"}, {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354732/nvidia-co-founder-and-ceo-jensen-huang-officially-resigns"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/jensen-huang-resigns-cfo-colette-kress-appointed-interim-ceo-at-nvidia/"}, {"name": "heise online", "url": "https://www.heise.de/news/Nach-Bekanntwerden-einer-zweiten-Affaere-Nvidia-CEO-Jensen-Huang-abgetreten-11522193.html"}], "tags": ["Nvidia", "Jensen Huang", "Colette Kress", "Unternehmen"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.539Z"}, "archiviert_am": "2026-11-19T18:25:35.306Z"}, {"id": "2026-11-12-paradox-wester-ruecktritt", "datum": "2026-11-12T14:22:00+01:00", "label": "News", "bereich": "games", "themen": ["Paradox"], "kategorie": "Spiele", "titel": "Paradox-Chef Frederik Wester tritt ab, Mattias Lilja übernimmt im Januar", "schlagzeile": "Nach Bloodlines-2-Flop: Paradox bekommt einen neuen Chef", "kurz": "Paradox-Interactive-CEO Frederik Wester gibt seinen Posten ab und wechselt in den Verwaltungsrat. Sein Stellvertreter Mattias Lilja übernimmt am 4. Januar 2027. Hinter dem Publisher liegen mehrere schwierige Jahre.", "zusammenfassung": "Frederik Wester tritt laut Eurogamer als CEO von Paradox Interactive zurück und soll sich künftig als Mitglied des Verwaltungsrats um die langfristige Entwicklung kümmern. Nachfolger wird der bisherige Vize-CEO Mattias Lilja ab dem 4. Januar 2027, bis dahin bleibt Wester im Amt. Wester führte Paradox von 2009 bis 2018 und erneut seit 2021. In seine zweite Amtszeit fielen die schwierige Entwicklung von Vampire: The Masquerade Bloodlines 2, dessen kommerzieller Misserfolg den operativen Gewinn stark einbrechen ließ. Dazu kamen die Einstellung von Life by You, die Verschiebung von Prison Architect 2 und der holprige Start von Cities: Skylines 2, dessen Konsolenversion noch immer fehlt. Lilja will stärker ins Kerngeschäft investieren und enger mit Spielern und Moddern arbeiten. Als nächste Spiele stehen Lego Skylines und das Strategiespiel Afterworld an.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/paradox-ceo-frederik-wester-stepping-down"}, "weitere_links": [], "tags": ["Paradox", "Cities Skylines", "Stellaris", "Unternehmen"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.284Z"}, "archiviert_am": "2026-11-19T18:25:35.307Z"}, {"id": "2026-11-12-siren-halo-gddr7", "datum": "2026-11-12T14:04:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["CPU", "APU", "AMD"], "kategorie": "Prozessoren", "titel": "Gerücht: AMDs Siren Halo soll GDDR7-Grafikspeicher statt nur LPDDR5X nutzen", "schlagzeile": "Leak: Bekommt AMDs Mega-APU Siren Halo echten GDDR7-Speicher?", "kurz": "Laut einem Leaker soll AMDs kommende Halo-APU Siren Halo mit GDDR7-Speicher arbeiten. Bisherige Halo-Chips nutzen gemeinsamen LPDDR5X-Speicher für CPU und GPU. Bestätigt ist nichts.", "zusammenfassung": "Der Hardware-Leaker Gotou_kai3 behauptet, dass AMDs Siren Halo GDDR7-Speicher bekommen soll, berichten Wccftech und PCGH. Siren Halo soll wie Medusa Halo auf Zen 6 und RDNA 5 setzen, aber als eigentlicher Nachfolger gelten und nicht als einfacher Refresh. Aktuelle Halo-Chips wie Strix Halo nutzen LPDDR5X als gemeinsamen Speicher für CPU und GPU. GDDR7 würde deutlich mehr Speicherbandbreite bringen, was vor allem der Grafikeinheit in Spielen helfen könnte. Unklar ist laut Wccftech, ob CPU und GPU beide Speicherpools nutzen können oder ob GDDR7 nur der Grafik vorbehalten wäre. Für KI-Anwendungen wäre eine reine GDDR7-Grafiklösung womöglich weniger flexibel als der große gemeinsame Speicher der heutigen Ryzen-AI-Max-Chips. AMD hat Siren Halo nicht angekündigt, Termine und Spezifikationen sind unbekannt.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/CPU-CPU-154106/News/AMD-Siren-Halo-mit-GDDR7-Grafikspeicher-1559803/"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/amds-siren-halo-will-reportedly-support-gddr7-memory/"}], "zuverlaessigkeit": {"stufe": "niedrig bis mittel", "begruendung": "Einzelner Leaker (Gotou_kai3) ohne Belege; über PCGH und Wccftech verbreitet; von AMD nicht bestätigt."}, "tags": ["AMD", "Siren Halo", "APU", "GDDR7", "RDNA 5", "Zen 6"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.758Z"}, "archiviert_am": "2026-11-19T18:25:35.307Z"}, {"id": "2026-11-12-apache-http2-luecke", "datum": "2026-11-12T13:43:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit"], "kategorie": "Sicherheit", "titel": "Kritische Lücke im HTTP/2-Modul von Apache: Update auf 2.4.71 empfohlen", "schlagzeile": "Kritische Apache-Lücke: Webserver mit HTTP/2 sofort updaten", "kurz": "Im Webserver Apache steckt eine kritische Lücke im Modul mod_http2, die Codeausführung aus der Ferne ermöglichen könnte. Betroffen sind nur Server mit aktiviertem HTTP/2. Version 2.4.71 behebt den Fehler.", "zusammenfassung": "Laut heise steckt die Lücke CVE-2026-119618 in der Funktion assign_headers() des Moduls mod_http2. Eine Speichermanipulation könnte dort zur Ausführung von Schadcode aus der Ferne führen. Red Hat bewertet die Lücke laut Golem mit 9,8 von 10 Punkten. Gefunden haben sie ein OSS-Scanner von Anthropic und zwei Forscher von Google Cloud Vulnerability Research. Da mod_http2 standardmäßig nicht aktiv ist, sind nur Server betroffen, die HTTP/2 nutzen. Experten wie Kevin Beaumont halten einen Exploit wegen Schutzmechanismen wie ASLR für schwierig. Trotzdem sollten Admins auf Apache 2.4.71 aktualisieren, die zwei weitere Lücken schließt. Wer nicht sofort updaten kann, sollte HTTP/2 vorerst abschalten.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Kritische-Sicherheitsluecke-in-Apache2-ermoeglicht-Codeeinschleusung-11523150.html"}, "weitere_links": [{"name": "Golem.de", "url": "https://www.golem.de/news/red-hat-kritische-sicherheitsluecke-in-apache-http-server-entdeckt-2611-215134.html"}], "tags": ["Apache", "Linux", "Webserver", "Sicherheitslücke"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:23.124Z"}, "archiviert_am": "2026-11-19T18:25:35.307Z"}, {"id": "2026-11-12-rtx5090-96gb-mod", "datum": "2026-11-12T11:17:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Grafikkarten", "titel": "Umgebaute RTX 5090 mit 96 GB Speicher taucht auf chinesischem Gebrauchtmarkt auf", "schlagzeile": "RTX 5090 mit 96 GB: China-Mod für rund 900.000 Dollar aufgetaucht", "kurz": "Auf der chinesischen Plattform Xianyu wird eine modifizierte GeForce RTX 5090 mit 96 GB Videospeicher angeboten. Der Platzhalterpreis liegt bei umgerechnet rund 900.000 US-Dollar, verhandelt wird privat. Ob die Karte wirklich funktioniert, ist nicht belegt.", "zusammenfassung": "Chinesische Modder bauen Desktop-GPUs auf eigene Platinen um und vervielfachen so den Speicher für KI-Anwendungen. Jetzt ist laut Wccftech und PCGH ein Angebot für eine RTX 5090 mit 96 GB aufgetaucht, so viel Speicher wie bei der RTX Pro 6000. Entdeckt hat es der Reparaturspezialist VIK-on auf Alibabas Gebrauchtmarkt Xianyu, zuerst berichtete VideoCardz. Der GB202-Chip sitzt auf einer eigenen Platine mit Samsung-Speicherchips auf beiden Seiten. Der Verkäufer bietet neben der Karte auch Platinenpläne und ein gepatchtes BIOS an, richtet sich aber nur an Geschäftskunden mit Vertraulichkeitsvereinbarung. Der angegebene Preis von 6.488.888 Yuan, rund 900.000 US-Dollar, ist ein Platzhalter, der tatsächliche Preis wird privat ausgehandelt. Benchmarks gibt es keine, die Funktion der Karte ist daher unbestätigt.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Geforce-RTX-5090-Grafikkarte-281029/News/96-GiByte-Speicher-Modifikation-1559779/"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/modded-rtx-5090-96gb-vram-china-listing/"}], "tags": ["RTX 5090", "Mod", "VRAM", "China", "KI"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.848Z"}, "archiviert_am": "2026-11-19T18:25:35.308Z"}, {"id": "2026-11-12-swtor-directx12-test", "datum": "2026-11-12T11:15:00+01:00", "label": "News", "bereich": "games", "themen": ["DirectX", "MMORPG"], "kategorie": "Spiele", "titel": "Star Wars: The Old Republic startet öffentlichen DirectX-12-Test, Grafik zunächst bewusst reduziert", "schlagzeile": "SWTOR bekommt DirectX 12 – und sieht erst mal schlechter aus", "kurz": "Fast 15 Jahre nach dem Release testet Star Wars: The Old Republic einen DirectX-12-Client. Der öffentliche Test startet noch diese Woche direkt im normalen Launcher. Viele Grafikeffekte fehlen anfangs absichtlich.", "zusammenfassung": "Entwickler Broadsword modernisiert laut PC Games die Technik des MMORPGs Star Wars: The Old Republic. Noch diese Woche startet ein öffentlicher Test des neuen DirectX-12-Clients, ohne Anmeldung oder Zugangscode. Im normalen Launcher lässt sich über einen kleinen Pfeil zwischen alter und neuer Version wählen, beide nutzen dieselben Live-Server und Charaktere. Viele Umgebungsdetails und Effekte fehlen im neuen Client noch oder sind vereinfacht, auch die Grafikoptionen sind eingeschränkt. Das ist Absicht: Zunächst geht es um Stabilität, Leistung und Kompatibilität mit möglichst vielen PCs. Spieler sollen Ruckler, Bildfehler und Abstürze samt Hardware melden. Für Mac-Spieler gibt es den Test vorerst nicht. Laut Broadsword läuft das Projekt bis weit ins Jahr 2027, danach soll die Grafik schrittweise mindestens das alte Niveau erreichen.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/SWTOR-Star-Wars-The-Old-Republic-Spiel-17102/News/DirectX-12-doch-die-Grafik-wird-schlechter-1559693/"}, "weitere_links": [], "tags": ["SWTOR", "DirectX 12", "MMORPG", "Broadsword"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.580Z"}, "archiviert_am": "2026-11-19T18:25:35.308Z"}, {"id": "2026-11-12-apex-neural-rendering", "datum": "2026-11-12T11:11:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Upscaling"], "kategorie": "Grafik", "titel": "Apex Neural Rendering: Start-up verspricht herstellerunabhängige Alternative zu DLSS, FSR und XeSS", "schlagzeile": "Besser als DLSS? Apex bringt Frame Generation für alle drei GPU-Lager", "kurz": "Das Unternehmen Apex Compute hat Apex Neural Rendering (ANR) vorgestellt, mit Super Resolution, Ray Reconstruction und Frame Generation für GeForce, Radeon und Arc. Die Frame Generation gibt es ab sofort als kostenlose Beta auf GitHub. Die Versprechen sind groß, ComputerBase hält sie aber für kaum nachvollziehbar.", "zusammenfassung": "Apex Compute, bisher auf Edge-KI-Beschleuniger spezialisiert, will mit Apex Neural Rendering (ANR) gegen DLSS, FSR und XeSS antreten. ANR soll Super Resolution, Ray Reconstruction und Frame Generation herstellerunabhängig auf Nvidia, AMD und Intel bieten. Laut Hersteller soll es bis zu 2,4-mal schneller sein und eine bessere Bildqualität als DLSS liefern. Bereits verfügbar ist nur die Frame Generation als kostenlose Beta auf GitHub, eingebunden wird sie über OptiScaler, mit den Stufen 2×, 3× und 4×. Super Resolution und Ray Reconstruction sind laut Apex noch in Entwicklung. Die Frame Generation läuft laut ComputerBase ab GeForce GTX 16 und RTX 2000, ab Radeon RX 5000 inklusive Steam Deck und auf Intel Arc A, unter Windows 10, Windows 11 und Linux mit Proton. ComputerBase kritisiert Unstimmigkeiten in den Herstellerangaben, etwa angebliche Messwerte von FSR mit mehr als einem KI-Zwischenbild, und unklare Faktoren in den Vergleichsvideos. Unabhängige Tests gibt es noch nicht, die Leistungs- und Qualitätsversprechen sind daher unbestätigt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/grafikkarten/apex-neural-rendering-anr-soll-dlss-fsr-und-xess-in-allen-disziplinen-schlagen.100301/"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354727/apex-neural-rendering-beats-nvidia-dlss-in-both-image-quality-and-performance"}, {"name": "Wccftech", "url": "https://wccftech.com/apex-neural-rendering-challenges-nvidia-dlss-with-up-to-2-4x-faster-frame-generation-62-lower-vram-usage-and-broad-gpu-support/"}, {"name": "GamingOnLinux", "url": "https://www.gamingonlinux.com/2026/11/apex-compute-revealed-apex-neural-rendering-anr-their-cross-platform-answer-to-nvidia-dlss/"}], "tags": ["Upscaling", "Frame Generation", "DLSS", "FSR", "XeSS"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.653Z"}, "archiviert_am": "2026-11-19T18:25:35.308Z"}, {"id": "2026-11-12-samsung-hbm-onyang", "datum": "2026-11-12T10:15:00+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM", "Speicher"], "kategorie": "Speicher", "titel": "Speicherknappheit: Samsung baut neue HBM-Packaging-Linie und will sie ein Jahr früher fertigstellen", "schlagzeile": "RAM-Krise: Samsung zieht neue HBM-Fabrik um ein Jahr vor", "kurz": "Samsung hat in Onyang mit dem Bau einer neuen Linie für HBM-Packaging begonnen. Sie soll im Juni 2028 starten, ein Jahr früher als geplant. Grund ist die anhaltende Speicherknappheit.", "zusammenfassung": "Samsung hat laut ComputerBase auf seinem Onyang-Campus in Asan den Spatenstich für eine neue Produktionslinie gesetzt, die HBM-Speicher verpacken soll. Der Betrieb soll im Juni 2028 starten und damit ein Jahr früher als ursprünglich geplant. In Onyang investiert Samsung 46 Billionen Won, rund 31 Milliarden Euro, davon den Großteil in die Ausrüstung. Geplant sind etwa 31.000 Quadratmeter Reinraum auf drei Etagen und rund 700 neue Arbeitsplätze. Samsung hatte im Oktober erklärt, die HBM-Liefermengen für 2027 schon ausverhandelt zu haben und den Bedarf bei weitem nicht decken zu können. HBM steckt vor allem in KI-Beschleunigern, die Knappheit belastet aber den gesamten Speichermarkt und damit auch RAM-Preise für PC-Nutzer. Kurzfristig ändert die neue Linie an den Preisen nichts.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/arbeitsspeicher/speicherknappheit-samsung-will-neue-hbm-fabrik-ein-jahr-frueher-fertigstellen.100299/"}, "weitere_links": [], "tags": ["Samsung", "HBM", "RAM-Preise", "Speicherknappheit"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.935Z"}, "archiviert_am": "2026-11-19T18:25:35.309Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:02.862Z"}, "id": "2026-11-12-outlook-mails-blockiert", "datum": "2026-11-12T05:53:00+01:00", "label": "News", "bereich": "software", "themen": ["Outlook", "Microsoft"], "kategorie": "Software", "titel": "Outlook.com: Fehlerhafte Spam-Regel hat tagelang echte E-Mails abgewiesen – die Mails sind verloren", "schlagzeile": "Outlook hat tagelang Mails abgewiesen – und die kommen nicht zurück", "kurz": "Eine fehlerhafte Spam-Regel von Microsoft hat tagelang legitime E-Mails an Outlook.com-, Hotmail- und Live-Adressen abgewiesen. Microsoft hat das Update zurückgenommen, Absender und Empfänger müssen nichts ändern. Abgewiesene Mails sind aber nicht wiederherstellbar, man muss Absender um erneutes Senden bitten.", "zusammenfassung": "Wer zuletzt auffällig wenige E-Mails im Outlook.com-Postfach hatte, war womöglich betroffen. Laut Windows Latest wurden mindestens ab dem 5. November legitime Mails an Outlook.com-, Hotmail-, Live- und MSN-Adressen abgewiesen. Absender erhielten Fehlermeldungen, ihren Mails fehlten SPF-, DKIM- oder DMARC-Einträge, obwohl das teils nicht stimmte. Microsoft bestätigte gegenüber Windows Latest, dass ein Update der Spam-Regeln die Ursache war. Das Unternehmen hat es zurückgenommen, der Mailfluss läuft laut Windows Latest seit dem 9. November wieder. Weder Absender noch Empfänger müssen Einstellungen ändern. Das Problem: Die abgewiesenen Mails landeten nicht im Spam-Ordner, sondern kamen nie an. Microsoft kann sie deshalb nicht wiederherstellen. Wer wichtige Mails erwartet hat, sollte Absender bitten, sie erneut zu schicken. Admins finden den Vorfall im Microsoft-365-Admin-Center unter der Kennung EX1545193. Wie viele Nutzer betroffen waren, nennt Microsoft nicht.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/12/you-may-have-missed-emails-on-outlook-for-days-as-microsoft-confirms-its-spam-rule-wrongly-blocked-them-and-blamed-senders-settings/"}, "weitere_links": [], "tags": ["Outlook", "Microsoft", "E-Mail", "Spam"], "archiviert_am": "2026-11-19T07:36:34.697Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:02.974Z"}, "id": "2026-11-12-powershell-signatur-kb5132061", "datum": "2026-11-12T05:08:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "November-Update KB5132061: Strengere Prüfung lässt manche signierte PowerShell-Skripte scheitern", "schlagzeile": "Windows-Update bremst signierte PowerShell-Skripte aus – so geht der Fix", "kurz": "Mit dem November-Sicherheitsupdate prüft Windows die Textkodierung signierter PowerShell-Skripte strenger. Skripte mit fehlerhaftem UTF-8 gelten danach womöglich als nicht signiert und laufen in verwalteten Umgebungen nicht mehr wie gewohnt. Microsoft empfiehlt, sie als UTF-8 mit BOM zu speichern und neu zu signieren.", "zusammenfassung": "Microsoft hat mit dem Update KB5132061 vom 10. November die Prüfung von PowerShell-Signaturen verschärft. Bisher konnte Windows Skripte mit ungültigem UTF-8 noch verarbeiten, indem es fehlerhafte Zeichen ersetzte. Das passiert jetzt nicht mehr, betroffene Dateien werden abgelehnt. Laut Microsoft meldet Get-AuthenticodeSignature dann „NotSigned“ für ein eigentlich signiertes Skript. Set-AuthenticodeSignature kann mit einem Fehler abbrechen. Auf Geräten mit App Control for Business können betroffene Skripte nur noch im eingeschränkten Sprachmodus laufen. Betroffen sind vor allem Skripte mit fehlerhaftem UTF-8, UTF-8 ohne BOM auf Systemen mit anderer Codepage und Dateien in Kodierungen wie Shift-JIS. Microsoft empfiehlt, die Skripte zu prüfen, als gültiges UTF-8 mit BOM zu speichern und neu zu signieren. Ein Beispielskript namens Repair-SignedPowerShellUtf8.ps1 sucht betroffene Dateien und überschreibt keine Originale. Laut Neowin gilt die Änderung neben Windows 11 auch für Windows 10 Enterprise LTSC 2021 und Windows Server 2025. Private Nutzer ohne signierte Skripte merken davon in der Regel nichts.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/latest-windows-11-update-kb5132061-could-break-your-powershell-scripts/"}, "weitere_links": [{"name": "Microsoft Support (KB5132061)", "url": "https://support.microsoft.com/en-us/servicing/os/windows-11/2026/11/kb5132061-windows-11-24h2-25h2-26h2-security-update"}, {"name": "Microsoft Support (Anleitung zur Kodierung)", "url": "https://support.microsoft.com/en-us/servicing/os/windows/docs/2026/11/powershell-sip-canonical-repair"}], "tags": ["Windows 11", "PowerShell", "KB5132061", "Sicherheit"], "archiviert_am": "2026-11-19T07:36:34.698Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.109Z"}, "id": "2026-11-12-tomb-raider-catalyst-switch2", "datum": "2026-11-12T04:01:00+01:00", "label": "News", "bereich": "games", "themen": ["Tomb Raider", "Switch 2"], "kategorie": "Spiele", "titel": "Amazon nennt Tomb Raider: Catalyst auch für Nintendo Switch 2", "schlagzeile": "Tomb Raider: Catalyst kommt wohl auch für die Switch 2", "kurz": "Ein Beitrag auf Amazons offizieller News-Seite nennt die Switch 2 als Plattform für beide kommenden Tomb-Raider-Spiele. Für Legacy of Atlantis war das bekannt, für Catalyst bisher nicht. Amazon ist Publisher von Catalyst, eine Bestätigung von Crystal Dynamics oder Nintendo fehlt noch.", "zusammenfassung": "Laut Insider Gaming steht in einem am 9. November aktualisierten Beitrag von Amazon News, dass beide neuen Tomb-Raider-Spiele für PS5, Xbox Series X/S, Nintendo Switch 2 und Steam erscheinen. Für Tomb Raider: Legacy of Atlantis (2027) war die Switch-2-Version schon offiziell, das Spiel ist im eShop vorbestellbar. Neu ist die Angabe für Tomb Raider: Catalyst. Das Spiel wurde in diesem Jahr auf 2028 verschoben. Catalyst wird von Amazon Game Studios veröffentlicht, daher hat die Angabe Gewicht. Insider Gaming hält einen Fehler im Artikel aber für möglich, auch wenn er seit zwei Tagen unverändert online ist. Crystal Dynamics und Nintendo haben die Switch-2-Fassung noch nicht bestätigt. Technische Details oder einen Termin für die Switch-2-Version gibt es nicht.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/tomb-raider-catalyst-switch-2/"}, "weitere_links": [], "tags": ["Tomb Raider", "Catalyst", "Switch 2", "Amazon"], "archiviert_am": "2026-11-19T07:36:34.704Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.236Z"}, "id": "2026-11-12-steam-erfolge-linux-64bit", "datum": "2026-11-12T02:16:00+01:00", "label": "News", "bereich": "games", "themen": ["Steam", "Linux"], "kategorie": "Spiele-Stores", "titel": "Steam-Client-Update: Achievement Sets für alle und der Linux-Client läuft endlich als 64-Bit-Programm", "schlagzeile": "Steam-Update: Neue Erfolge-Sets und 64 Bit für Linux", "kurz": "Valve hat ein neues Steam-Update für alle Nutzer veröffentlicht. Spiele können Erfolge jetzt in Sets für Grundspiel und DLC gruppieren, ohne dass eine 100-Prozent-Wertung verloren geht. Unter Linux ist der Steam-Client nun ein 64-Bit-Programm und läuft in einem Steam-Runtime-Container.", "zusammenfassung": "Valve hat am 11. November ein Steam-Client-Update für den stabilen Kanal veröffentlicht. Wichtigste Neuerung für alle sind die Steam Achievement Sets. Entwickler können Erfolge damit nach Grundspiel und DLC gruppieren. Neue Erfolge oder DLC-Erfolge machen eine bereits vollständige Erfolgs-Sammlung so nicht mehr unvollständig. Saisonale oder nicht mehr erreichbare Erfolge lassen sich archivieren. Dazu kommt eine überarbeitete Erfolgs-Seite. Unter Linux ist der Steam-Client nun eine 64-Bit-Anwendung und läuft in einem Steam-Runtime-Container. Das soll laut Valve für gleiches Verhalten auf verschiedenen Distributionen sorgen, es ist dieselbe Technik, die auch Spiele nutzen. Laut TechPowerUp war Steam unter Linux bisher noch ein 32-Bit-Programm. Zusätzlich behebt das Update unter anderem einen Absturz beim Aufwachen aus dem Standby. Ob Entwickler die neuen Erfolgs-Sets auch nutzen, liegt bei ihnen.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/353772/linux-finally-gets-64-bit-steam-client-and-new-game-achievements-management"}, "weitere_links": [{"name": "Steam (Ankündigung Achievement Sets)", "url": "https://store.steampowered.com/news/posts/4149575031735702629"}, {"name": "9to5Linux", "url": "https://9to5linux.com/new-steam-client-update-introduces-linux-64-bit-support-steam-achievement-sets"}], "tags": ["Steam", "Valve", "Linux", "Achievements"], "archiviert_am": "2026-11-19T07:36:34.704Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.349Z"}, "id": "2026-11-12-witcher3-ki-stimme-geralt", "datum": "2026-11-12T01:02:00+01:00", "label": "News", "bereich": "games", "themen": ["Witcher"], "kategorie": "Spiele", "titel": "The Witcher 3: CD Projekt passt die polnische Stimme von Geralt im neuen Add-on per KI an – mit Zustimmung des Sprechers", "schlagzeile": "Nach Schlaganfall: KI lässt Geralts polnische Stimme wieder jung klingen", "kurz": "Im kommenden Witcher-3-Add-on Songs of the Past wird die polnische Stimme von Geralt per KI nachbearbeitet. Sprecher Jacek Rozenek nimmt alle Zeilen selbst auf, seine Stimme hat sich nach einem Schlaganfall 2019 aber hörbar verändert. Das KI-Unternehmen Respeecher gleicht sie mit seiner Zustimmung an den Klang von früher an.", "zusammenfassung": "CD Projekt Red hat bestätigt, für die polnische Fassung der neuen Witcher-3-Erweiterung Songs of the Past KI einzusetzen. Das berichtete zuerst Game File, PC Gamer, VGC und IGN haben es aufgegriffen. Jacek Rozenek spricht Geralt seit jeher auf Polnisch, erlitt 2019 aber einen Schlaganfall und konnte zeitweise nicht sprechen. Nach langem Training kehrte er zurück, seine Stimme klingt heute jedoch tiefer und rauer. Weil die Erweiterung mitten in der Handlung von The Witcher 3 spielt, hätte der Unterschied auffallen können. Rozenek nimmt deshalb weiter alle Zeilen selbst auf, Respeecher passt sie danach an seinen Klang von vor rund zwölf Jahren an. Trainiert wurde das Modell mit seinen früheren Aufnahmen für das Spiel. Rozenek unterstützt das ausdrücklich und sagt, die Stimme solle so nah wie möglich an seiner von damals sein. Lokalisierungsproduzent Mikołaj Szwed nennt es einen Sonderfall wegen der Erkrankung und sieht darin eine ethische Nutzung mit Einwilligung. Für die englische Stimme von Doug Cockle ist laut CD Projekt nichts dergleichen geplant. CD Projekt arbeitete schon bei Cyberpunk 2077: Phantom Liberty mit Respeecher, damals mit Zustimmung der Familie eines verstorbenen Sprechers. Ein Termin für Songs of the Past steht in den Berichten nicht.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/the-witcher/cd-projekt-used-ai-to-modify-the-voice-of-geralts-polish-actor-after-a-stroke-left-it-significantly-changed-this-was-a-special-case/"}, "weitere_links": [{"name": "VGC", "url": "https://www.videogameschronicle.com/news/the-witcher-3-expansion-uses-ai-to-adjust-geralts-polish-voiceover-because-the-actor-suffered-a-stroke/"}, {"name": "IGN", "url": "https://www.ign.com/articles/cd-projekt-red-used-ai-to-alter-geralts-voice-due-to-polish-actors-health-issues"}], "tags": ["The Witcher 3", "CD Projekt Red", "KI", "Synchronisation"], "archiviert_am": "2026-11-19T07:36:34.705Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.467Z"}, "id": "2026-11-12-helldivers2-kosmetik-mods", "datum": "2026-11-12T00:29:00+01:00", "label": "News", "bereich": "games", "themen": ["Helldivers 2"], "kategorie": "Spiele", "titel": "Helldivers 2: Nach Anti-Cheat-Wechsel und Review-Welle sollen kosmetische Mods mit dem nächsten Hotfix wieder laufen", "schlagzeile": "Helldivers 2: Arrowhead will harmlose Mods wieder erlauben", "kurz": "Seit dem Wechsel auf Easy Anti-Cheat funktionieren in Helldivers 2 viele Mods nicht mehr, auf Steam folgten über 10.000 negative Reviews. Arrowhead kündigt an, dass einige rein kosmetische Mods mit dem nächsten Hotfix wieder laufen sollen. Mods, die das Gameplay verändern, bleiben verboten.", "zusammenfassung": "Arrowhead hat bei Helldivers 2 das Anti-Cheat-System von GameGuard auf Easy Anti-Cheat umgestellt. Ziel war laut Studio, Mods zu stoppen, die unfaire Vorteile bringen oder anderen schaden. Dabei hörten aber auch harmlose kosmetische Mods auf zu funktionieren. Die Reaktion fiel heftig aus: Laut PC Gamer kamen über 10.000 neue negative Steam-Reviews dazu, die jüngsten Bewertungen stehen auf „größtenteils negativ“. Im neuen Entwickler-Blog räumt Arrowhead ein, dass PC-Spieler Fan-Mods verloren haben. Nach Anpassungen sollen einige kosmetische Mods mit dem nächsten Hotfix wieder funktionieren. Mods, die das Gameplay verändern, bleiben verboten, weil sie technisch nicht von Cheats zu unterscheiden seien. Offiziell unterstützt werden Mods weiterhin nicht. Arrowhead entschuldigt sich außerdem für eine ungenaue Roadmap und verpasste Patch-Termine. Für Anfang Dezember sind unter anderem Jetpacks beim Tragen zweihändiger Gegenstände geplant. Ein Datum für den Hotfix nennt das Studio nicht.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/third-person-shooter/after-cracking-down-on-cheat-mods-in-helldivers-2-and-taking-another-steam-review-beating-arrowhead-plans-hotfix-that-should-allow-harmless-cosmetics/"}, "weitere_links": [], "tags": ["Helldivers 2", "Arrowhead", "Mods", "Anti-Cheat"], "archiviert_am": "2026-11-19T07:36:34.705Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.583Z"}, "id": "2026-11-12-marvel-1943-fast-fertig", "datum": "2026-11-12T00:27:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Marvel 1943"], "kategorie": "Spiele", "titel": "Bericht: Marvel 1943: Rise of Hydra soll fast fertig sein, aber deutlich kleiner als geplant", "schlagzeile": "Leak: Ist Marvel 1943 fast fertig – aber stark zusammengestrichen?", "kurz": "Nach Gerüchten über eine Einstellung berichtet Kotaku, Marvel 1943: Rise of Hydra sei nahezu fertig. Das Spiel soll aber deutlich weniger Inhalt und spielerische Tiefe bieten als geplant. Skydance hat dazu nichts Offizielles gesagt.", "zusammenfassung": "Um Marvel 1943: Rise of Hydra, das Captain-America- und Black-Panther-Spiel von Amy Hennig, gab es zuletzt Gerüchte über eine bevorstehende Einstellung. Laut Kotaku und Bloomberg-Reporter Jason Schreier hat die Führung von Skydance den Mitarbeitern per Slack mitgeteilt, dass das nicht stimmt. Kotaku berichtet zudem, das Spiel sei „close to done“, also fast fertig. Die Entwicklung soll aber schwierig gewesen sein und das Budget deutlich überschritten haben. Deshalb seien Umfang und Spieldauer stark gekürzt worden. Laut den Quellen von Kotaku ist das Spiel „light on gameplay“, vieles laufe über eine einzige Taste. Ursprünglich soll Marvel 1943 als Netflix-Spiel begonnen haben. Angekündigt wurde es 2024, seitdem wurde es mehrfach verschoben. Einen Termin gibt es nicht. Alle Angaben stammen aus anonymen Quellen, Skydance hat sie nicht bestätigt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/marvel-1943-rise-of-hydra-is-reportedly-close-to-done-though-at-the-cost-of-cutting-back-on-content-and-length"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Bericht von Kotaku mit anonymen Quellen, Teile von Jason Schreier (Bloomberg) gestützt; über IGN (Bewertung hoch) aufgegriffen; von Skydance nicht bestätigt."}, "ursprungsquelle": "Kotaku (via IGN)", "tags": ["Marvel 1943", "Skydance", "Amy Hennig"], "archiviert_am": "2026-11-19T07:36:34.706Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.692Z"}, "id": "2026-11-12-nvidia-board-huang-abloesung", "datum": "2026-11-12T00:14:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Unternehmen", "titel": "Berichte: Nvidia-Verwaltungsrat berät über Absetzung von CEO Jensen Huang und sucht bereits Nachfolger", "schlagzeile": "Nvidia vor dem Chefwechsel? Verwaltungsrat berät über Huangs Absetzung", "kurz": "Laut Wall Street Journal bereitet Nvidias Verwaltungsrat die Absetzung von Firmengründer und CEO Jensen Huang vor. Auslöser ist ein Bericht der New York Times über eine zweite außereheliche Beziehung, diesmal zu einer ihm direkt unterstellten Managerin. Bloomberg zufolge sucht eine externe Firma bereits nach Nachfolgern. Bis heute mittag hat Nvidia weiterhin keine Entscheidung bekanntgegeben; die Meldungen beruhen auf anonymen Quellen.", "zusammenfassung": "Die Krise um Nvidia-Chef Jensen Huang spitzt sich zu. Nach Berichten des Wall Street Journal wollte der Verwaltungsrat am Mittwochabend (US-Zeit) über Huangs Zukunft beraten, eine Absetzung stehe im Raum. Auslöser ist ein neuer Bericht der New York Times: Huang soll neben der bereits eingeräumten Affäre auch eine Beziehung zu einer Vizepräsidentin gehabt haben, die direkt an ihn berichtet. Die Zeitung beruft sich auf fünf frühere Beschäftigte, ein angebliches Video eines Vorfalls im März hat sie nach eigenen Angaben nicht selbst gesehen. Weder Nvidia noch die Betroffenen haben den Bericht bestätigt. Laut Bloomberg arbeitet der Verwaltungsrat bereits mit einer externen Firma an der Suche nach einem Nachfolger, auch ein Interims-CEO werde erwogen. Hintergrund ist die seit Sonntag laufende Untersuchung zu Huangs Affäre mit einer Managerin des Nvidia-Kunden Megaspeed, die von US-Behörden als mutmaßliche chinesische Agentin eingestuft worden sein soll; China weist das zurück. Huang führt Nvidia seit der Gründung 1993, einen benannten Nachfolger gibt es laut PCGH nicht. Laut PCGH reicht für eine Abberufung die einfache Mehrheit der Direktoren. Die Aktie verlor nach den Berichten nachbörslich rund acht Prozent und fiel auf ein 52-Wochen-Tief. Am kommenden Dienstag legt Nvidia Quartalszahlen vor, am Mittwoch darauf ist ein vertrauliches Briefing im US-Kongress geplant. Konkrete Auswirkungen auf GeForce-Karten, Preise oder Treiber sind bisher nicht bekannt. Wichtig: Alles beruht auf Medienberichten mit anonymen Quellen von Wall Street Journal, New York Times und Bloomberg; bis heute mittag hat Nvidia keine Entscheidung bekanntgegeben, die Lage kann sich ändern.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/nvidia-krise-verwaltungsrat-beraet-ueber-rauswurf-von-jensen-huang.100297/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/Nvidia-Jensen-Huang-Affaere-Abloesung-CEO-Nachfolger-1559660/"}, {"name": "heise online", "url": "https://www.heise.de/news/Jensen-Huang-nach-weiterer-Affaere-mit-Mitarbeiterin-wohl-vor-dem-Aus-bei-Nvidia-11521625.html"}, {"name": "Golem.de", "url": "https://www.golem.de/news/zweite-affaere-nvidia-erwaegt-offenbar-jensen-huangs-absetzung-2611-215113.html"}, {"name": "IGN", "url": "https://www.ign.com/articles/nvidia-board-is-preparing-to-potentially-oust-ceo-jensen-huang"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/software/ai/nvidia-ceo-jensen-huang-allegedly-had-a-second-affair-with-another-nvidia-exec/"}], "tags": ["Nvidia", "Jensen Huang", "Unternehmen", "Aktie"], "archiviert_am": "2026-11-19T07:36:34.706Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.780Z"}, "id": "2026-11-12-golden-joystick-2026", "datum": "2026-11-11T22:31:00+01:00", "label": "News", "bereich": "games", "themen": ["Awards"], "kategorie": "Spiele", "titel": "Golden Joystick Awards 2026: Resident Evil Requiem ist Spiel des Jahres, Crimson Desert gewinnt am PC", "schlagzeile": "Golden Joysticks: Resident Evil Requiem holt den Spiel-des-Jahres-Titel", "kurz": "Bei den 44. Golden Joystick Awards hat Resident Evil Requiem den Hauptpreis als Ultimate Game of the Year gewonnen. Bestes PC-Spiel wurde Crimson Desert. Der Multiplayer-Hit Meccha Chameleon räumte vier Preise ab, The Witcher 4 ist das meisterwartete Spiel.", "zusammenfassung": "Die Golden Joystick Awards gelten als ältestes Publikumsvoting der Spielebranche und fanden 2026 zum 44. Mal statt. Den Hauptpreis als Ultimate Game of the Year holte Resident Evil Requiem von Capcom. Das Horrorspiel gewann außerdem als bestes Konsolenspiel, für den besten Trailer und für die beste Hauptdarstellerin, Angela Sant'Albano als Grace Ashcroft. Capcom wurde laut TheGameVerse zudem Studio des Jahres. Bestes PC-Spiel wurde Crimson Desert, obwohl es auch auf Konsolen erscheint. Das Versteckspiel Meccha Chameleon gewann vier Preise: bestes Multiplayer-Spiel, bestes selbst veröffentlichtes Indie-Spiel, Streamers' Choice und Developers' Choice. The Witcher 3: Wild Hunt Remastered wurde bestes Remaster, The Witcher 4 meisterwartetes Spiel. Als beste Gaming-Hardware wählten die Fans den Steam Controller. Weitere Preise gingen an Onimusha: Way of the Sword (Audio), Control: Resonant (Grafikdesign), Doom: The Dark Ages – Revelations (Erweiterung) und Subnautica 2 (Early Access). Veranstalter der Awards ist der Verlag von PC Gamer.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/crimson-desert-wins-pc-game-of-the-year-at-the-2026-golden-joystick-awards/"}, "weitere_links": [{"name": "TheGameVerse auf X (Gewinnerliste)", "url": "https://x.com/TheGameVerse/status/2120750515277709426"}], "tags": ["Golden Joystick Awards", "Resident Evil Requiem", "Crimson Desert", "Awards"], "archiviert_am": "2026-11-19T07:36:34.707Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.876Z"}, "id": "2026-11-12-gta6-clip-realistisch", "datum": "2026-11-11T21:49:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6: Rockstar teilt Ingame-Clip, den viele für ein echtes Handyvideo aus Miami halten", "schlagzeile": "Echt oder GTA 6? Neuer Clip von Rockstar narrt das Netz", "kurz": "Ein rund 15 Sekunden langer GTA-6-Clip aus Ego-Perspektive sorgt für Diskussionen, weil viele ihn für ein echtes Video halten. Er bildet ein reales Handyvideo der GTA-Autos aus der Marketing-Aktion in Miami nach. Rockstar teilte den Clip in seiner Instagram-Story, was laut IGN auf echtes Spielmaterial hindeutet.", "zusammenfassung": "Eine Woche vor dem Start von GTA 6 sorgt ein kurzer Clip für Staunen. Ursprünglich tauchte er beim Instagram-Konto „Only in Dade“ auf, das skurrile Szenen aus Miami-Dade sammelt. Zu sehen ist eine Fahrt über den Ocean Drive, vorbei an einer Reihe auffälliger Autos, dazu eine zweite Perspektive vom Gehweg. Der Clip bildet laut IGN, Polygon und Insider Gaming ein echtes Video nach, das im Oktober bei Rockstars Marketing-Aktion mit nachgebauten GTA-Autos in Miami entstand. Viele Zuschauer hielten das Material zunächst für reale Aufnahmen oder für KI. Rockstar teilte den Clip in seiner Instagram-Story und markierte ihn mit „Gefällt mir“, was IGN als starkes Zeichen für echtes Spielmaterial wertet. Ausdrücklich bestätigt hat Rockstar es nach Polygon-Angaben aber nicht. Der Look könnte laut Spekulationen von Fans zeigen, wie Aufnahmen mit der Handykamera im Spiel aussehen. Insider Gaming betont, dass der Clip nichts über einen möglichen Ego-Modus aussagt. GTA 6 erscheint am 19. November für PS5 und Xbox Series X/S und läuft laut Rockstar auf Konsolen mit 30 fps. Das Preloading läuft bereits.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/new-gta-6-surprise-gameplay-seemingly-released-in-yet-another-viral-marketing-stunt"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/rockstar-games-unreal-gta-6-clip-social-media-first-person/"}, {"name": "Polygon", "url": "https://www.polygon.com/gta-6-new-gameplay-onlyindade-ai-real-fake-rockstar-instagram/"}, {"name": "GamePro (News-Übersicht)", "url": "https://www.gamepro.de/news/"}], "tags": ["GTA 6", "Rockstar", "Grafik", "Marketing"], "archiviert_am": "2026-11-19T07:36:34.707Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.986Z"}, "id": "2026-11-12-black-forest-games-unabhaengig", "datum": "2026-11-11T21:37:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spielebranche", "titel": "Black Forest Games kauft sich von Embracer frei und gründet die Studiogruppe Third Signal", "schlagzeile": "Deutsches Destroy-All-Humans-Studio kauft sich von Embracer frei", "kurz": "Das deutsche Studio Black Forest Games hat sich per Management-Buy-out von THQ Nordic und Embracer gelöst. Es gründet zugleich Third Signal, eine Gruppe unabhängiger Studios. Mit THQ Nordic arbeitet das Team weiter zusammen.", "zusammenfassung": "Black Forest Games ist nach neun Jahren unter dem Dach von THQ Nordic und Embracer wieder eigenständig. Das gelang laut Eurogamer und PC Gamer über einen Management-Buy-out. Das Studio entwickelte unter anderem Giana Sisters: Twisted Dreams und die Remakes der ersten beiden Destroy-All-Humans-Spiele. Gegründet wurde es von früheren Mitarbeitern von Spellbound Entertainment, bekannt für Desperados und Arcania: Gothic 4. Zusammen mit der Unabhängigkeit startet Third Signal, eine Gruppe unabhängiger Studios, die künftig auch anderen Indie-Teams helfen soll. Third-Signal-Chef Andreas Tobler sagt sinngemäß, viele der besten Spiele des letzten Jahrzehnts stammten von Teams mit 50 statt 500 Leuten. Laut Pressemitteilung arbeiten THQ Nordic und Black Forest Games weiter bei der Entwicklung zusammen. Die Rechte an Destroy All Humans hat das Studio offenbar nicht übernommen. Geschäftsführer Adrian Goersch kündigt ein neues Projekt an, Details nennt er nicht. Das Studio war 2024 von Embracers Entlassungen betroffen und verlor damals rund 50 Stellen.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/destroy-all-humans-independent-thq-embracer"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/giana-sisters-developer-black-forest-games-buys-itself-out-of-embracer-some-of-the-best-games-of-the-last-decade-came-from-teams-of-fifty-not-five-hundred/"}], "tags": ["Black Forest Games", "Embracer", "THQ Nordic", "Third Signal"], "archiviert_am": "2026-11-19T07:36:34.707Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.101Z"}, "id": "2026-11-12-nintendo-dmca-github", "datum": "2026-11-11T21:14:00+01:00", "label": "News", "bereich": "games", "themen": ["Nintendo"], "kategorie": "Konsolen", "titel": "Nintendo lässt per DMCA 144 GitHub-Repositorys mit Switch-Modchip-Firmware und zwei Emulatoren entfernen", "schlagzeile": "Nintendo räumt GitHub auf: Switch-Emulatoren und Modchip-Firmware weg", "kurz": "Nintendo hat vier DMCA-Beschwerden an GitHub geschickt, die sich gegen die Switch-Emulatoren Yuzu und Citron Neo sowie gegen Modchip-Firmware richten. GitHub hat 144 Repositorys mit der Firmware entfernt. Laut TorrentFreak ist sie an anderer Stelle auf der Plattform aber weiterhin zu finden.", "zusammenfassung": "Nintendo geht erneut gegen Werkzeuge zum Umgehen des Switch-Kopierschutzes vor. Laut IGN gingen vier DMCA-Beschwerden bei GitHub ein, die das Unternehmen öffentlich dokumentiert hat. Im Visier stehen die Emulatoren Yuzu und Citron Neo, vor allem aber Firmware für Modchips wie Picofly. Solche Chips werden auf die Switch-Hauptplatine gelötet und umgehen den Kopierschutz. Von der Firmware hat GitHub 144 Repositorys entfernt und durch einen DMCA-Hinweis ersetzt. Nintendo argumentiert in der Beschwerde vom 6. November, die technischen Schutzmaßnahmen sollten das Spielen von Raubkopien und auf fremden Geräten verhindern. Laut TorrentFreak ist die Firmware an anderen Stellen auf GitHub aber weiterhin verfügbar. Schon 2024 hatte Nintendo rund 8.500 Kopien von Yuzu entfernen lassen. IGN bringt die neue Welle mit Berichten in Verbindung, wonach Emulatoren kurz zuvor das neue Ocarina-of-Time-Remake am PC lauffähig gemacht haben; ein direkter Zusammenhang ist nicht belegt. Ob Nintendo weitere Schritte plant, ist offen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/nintendo-takes-down-switch-emulators-and-mod-chip-firmware-in-massive-github-dmca-sweep"}, "weitere_links": [], "tags": ["Nintendo", "Switch", "Emulation", "DMCA", "GitHub"], "archiviert_am": "2026-11-19T07:36:34.707Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.209Z"}, "id": "2026-11-12-id-veteranen-hidden-horses", "datum": "2026-11-11T21:09:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spielebranche", "titel": "Rund 20 frühere id-Software-Entwickler gründen das Studio Hidden Horses und planen einen Arena-Shooter", "schlagzeile": "Nach Xbox-Entlassungen: Ex-id-Entwickler gründen eigenes Shooter-Studio", "kurz": "Rund 20 ehemalige Entwickler von id Software haben das Studio Hidden Horses gegründet, das den Beschäftigten selbst gehört. Ihr erstes Projekt ist der Einzelspieler-Arena-Shooter Danger Pay. Finanziert werden soll er unter anderem über Kickstarter.", "zusammenfassung": "Bei den Xbox-Entlassungen im Juli 2026 verlor id Software laut Berichten 136 Entwickler. Rund 20 von ihnen haben jetzt Hidden Horses gegründet, ein Studio im Besitz der Beschäftigten. Laut PC Gamer bringen die Gründer zusammen über 250 Jahre Erfahrung mit. Das Studio soll demokratisch geführt werden und langfristige Stabilität über schnelles Wachstum und fragwürdige Monetarisierung stellen. Mitgründer Dustin Land sagt, man wolle das Team zusammenhalten und klassische Shooter machen. Das erste Spiel heißt Danger Pay, ein Einzelspieler-Arena-Shooter rund um eine brutale TV-Spielshow. Als Vorbilder nennt das Studio den Film The Running Man von 1987 und das Arcade-Spiel Smash TV. Für die Finanzierung ist eine Kickstarter-Kampagne geplant. Plattformen, Termin und Kickstarter-Start sind noch nicht bekannt.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/former-id-software-developers-form-their-own-employee-owned-shooter-studio-in-the-wake-of-microsofts-mass-layoffs/"}, "weitere_links": [], "tags": ["id Software", "Hidden Horses", "Danger Pay", "Shooter"], "archiviert_am": "2026-11-19T07:36:34.708Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.315Z"}, "id": "2026-11-12-tes6-sentinel-pause", "datum": "2026-11-11T20:36:00+01:00", "label": "News", "bereich": "games", "themen": ["Elder Scrolls"], "kategorie": "Spiele", "titel": "Bethesda: Zum Skyrim-Jubiläum keine Neuigkeiten zu The Elder Scrolls 6: Sentinel – und auch „für einige Zeit“ nicht", "schlagzeile": "15 Jahre Skyrim, aber kein Elder Scrolls 6: Bethesda bremst die Fans", "kurz": "Zum 15. Geburtstag von Skyrim hatten Fans auf Neuigkeiten zu The Elder Scrolls 6: Sentinel gehofft. Bethesda Game Studios stellte auf Reddit klar, dass es keine große Ankündigung gibt. Neues zu Sentinel werde es „für einige Zeit“ nicht geben.", "zusammenfassung": "Am 11. November wurde The Elder Scrolls V: Skyrim 15 Jahre alt. Im Subreddit zu The Elder Scrolls 6 spekulierten Fans auf eine Überraschung zum Jubiläum, angeheizt durch einen Podcast-Teaser zu einer „großen Ankündigung“. Der Podcaster stellte später klar, dass sie nichts mit Bethesda zu tun hat. Dann meldete sich auch das offizielle Konto von Bethesda Game Studios auf Reddit. Man werde keine große Ankündigung machen und „für einige Zeit“ nichts Neues zu Sentinel zeigen, schrieb das Studio. Den Titel Sentinel hatte Bethesda erst Anfang November offiziell gemacht. Angekündigt wurde The Elder Scrolls 6 bereits 2018. Zum Jubiläum gibt es Skyrim auf allen Plattformen günstiger. The Elder Scrolls Online macht das Greymoor-Kapitel kostenlos zum Teil des Grundspiels, eine Skyrim-Aktion läuft dort bis 2. Dezember. Wann es neue Infos zu Sentinel gibt, ist offen.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/dont-expect-elder-scrolls-6-sentinel-for-some-time-bethesda"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/games/the-elder-scrolls/bethesda-shoots-down-elder-scrolls-6-sentinel-announcement-rumor-on-skyrims-15th-anniversary/"}], "tags": ["The Elder Scrolls 6", "Sentinel", "Skyrim", "Bethesda"], "archiviert_am": "2026-11-19T07:36:34.708Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.406Z"}, "id": "2026-11-11-xbox-cloud-ohne-game-pass", "datum": "2026-11-11T19:00:15+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Xbox Cloud Gaming ohne Game Pass: Spielzeit kaufen oder kostenlos mit Werbung streamen", "schlagzeile": "Xbox Cloud Gaming öffnet sich: Stunden kaufen oder gratis mit Werbung", "kurz": "Seit 11. November können Spieler in unterstützten Ländern Xbox-Cloud-Spielzeit auch ohne Game-Pass-Abo kaufen. Zusätzlich bewirbt Xbox kostenloses Streaming mit Werbung, mit Zeitlimit pro Sitzung. Gestreamt werden nur Spiele, die man besitzt, oder ausgewählte Free-to-Play-Titel.", "zusammenfassung": "Microsoft baut Xbox Cloud Gaming um. Laut Xbox Wire können Spieler in unterstützten Märkten seit dem 11. November Cloud-Spielzeit im Xbox Store kaufen, ohne Game Pass zu abonnieren. In der Insider-Testphase kosteten die werbefreien Pakete 3,99 Dollar für 10, 7,99 Dollar für 25 und 11,99 Dollar für 50 Stunden; das waren ausdrücklich Einführungspreise, Euro-Preise sind in den Quellen nicht genannt. Gekaufte Stunden verfallen nicht und bieten laut Xbox kürzere Wartezeiten und bessere Streamqualität. Auf der offiziellen Cloud-Gaming-Seite und auf X bewirbt Xbox zudem kostenloses Streaming mit Werbung, wo verfügbar, mit Zeitlimits pro Sitzung. Im Insider-Test lag das Limit laut The Verge bei einer Stunde. Gestreamt werden können eigene Spiele, ausgewählte Free-to-Play-Titel und Game-Pass-Spiele. Für Game-Pass-Abonnenten gibt es seit November Monatskontingente: 15 Stunden bei Ultimate, 10 bei Premium und 5 bei Essential. Wer sie verbraucht, kann Stunden dazukaufen oder auf die Werbe-Variante ausweichen. Pünktlich dazu startet GTA 6 am 19. November per Cloud auch auf der Xbox One. Welche Länder zum Start dabei sind, ist offen.", "quelle": {"name": "Xbox", "url": "https://x.com/XBOX/status/2120577357769564501"}, "weitere_links": [{"name": "Xbox Wire (GTA VI per Cloud, Spielzeit ab 11.11.)", "url": "https://news.xbox.com/en-us/2026/11/10/grand-theft-auto-6-comes-to-xbox-cloud-gaming-november-19/"}, {"name": "Xbox Cloud Gaming (offizielle Seite)", "url": "https://www.xbox.com/en-US/cloud-gaming"}, {"name": "Xbox Wire (Preise im Insider-Test)", "url": "https://news.xbox.com/en-us/2026/10/21/cloud-playtime-now-available-to-test-with-xbox-insiders/"}, {"name": "Xbox Wire (Monatskontingente)", "url": "https://news.xbox.com/en-us/2026/09/03/xbox-cloud-gaming-changes/"}, {"name": "The Verge", "url": "https://www.theverge.com/news/1015321/xbox-cloud-gaming-pay-as-you-go-cloud-hours-pricing"}], "tags": ["Xbox", "Cloud Gaming", "Game Pass", "Streaming"], "archiviert_am": "2026-11-18T18:26:48.878Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.493Z"}, "id": "2026-11-11-dark-souls-server-zurueck", "datum": "2026-11-11T18:05:00+01:00", "label": "News", "bereich": "games", "themen": ["Online"], "kategorie": "Spiele", "titel": "Dark Souls 2 und 3: Online-Funktionen nach fast zwei Wochen Ausfall wieder verfügbar", "schlagzeile": "Dark Souls 2 und 3 sind wieder online – Ursache bleibt geheim", "kurz": "Nach knapp zwei Wochen Pause laufen die Online-Funktionen von Dark Souls 2 und 3 wieder auf allen Plattformen. Invasionen und Nachrichten funktionieren laut PC Gamer wieder. Was genau das Serverproblem war, hat FromSoftware nicht verraten.", "zusammenfassung": "Die Server von Dark Souls 2 und Dark Souls 3 sind wieder in Betrieb. Knapp zwei Wochen zuvor waren die Mehrspieler-Funktionen beider Spiele wegen eines nicht näher erklärten Serverproblems auf allen Plattformen abgeschaltet worden. Auf der offiziellen Dark-Souls-Seite heißt es nun knapp, die Untersuchung sei abgeschlossen, ein Fix eingespielt und die Online-Funktionen seien wiederhergestellt. Damit funktionieren laut PC Gamer Invasionen und Nachrichten wieder wie gewohnt. Die Ursache nennt FromSoftware weiterhin nicht. Zum Vergleich: 2022 waren die PC-Server aller Dark-Souls-Spiele fast ein Jahr lang offline, damals wegen einer Sicherheitslücke, über die Schadcode ausgeführt werden konnte. Ob diesmal ebenfalls ein Sicherheitsproblem dahintersteckte, ist nicht bekannt. Während der Pause halfen Fan-Mods wie Seamless Co-op, die unabhängig von den offiziellen Servern laufen. Wer die klassischen Invasionen spielen will, kann das jetzt wieder.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/dark-souls/dark-souls-2-and-3-multiplayer-is-back-we-still-dont-know-what-went-wrong-but-at-least-it-didnt-take-almost-a-year-to-fix-it/"}, "weitere_links": [], "tags": ["Dark Souls", "FromSoftware", "Server", "Multiplayer"], "archiviert_am": "2026-11-18T17:57:07.731Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.581Z"}, "id": "2026-11-11-kb5132061-installationsfehler", "datum": "2026-11-11T16:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11: Microsoft bestätigt Installationsfehler bei KB5132061 und verteilt eine automatische Reparatur", "schlagzeile": "Microsoft bestätigt KB5132061-Fehler – Fix kommt per Windows Update", "kurz": "Microsoft hat die Installationsprobleme beim November-Sicherheitsupdate KB5132061 inzwischen offiziell bestätigt. Auf betroffenen Windows-11-PCs bricht die Installation ab oder wird wiederholt versucht, typische Fehlercodes sind 0x800f0993, 0x800f0989 und 0x80070306. Laut Microsoft läuft eine Reparatur automatisch über Windows Update und soll betroffene Geräte innerhalb von 24 bis 48 Stunden nach dem Start am Mittwoch um 19 Uhr Wiener Zeit erreichen; danach wird das Sicherheitsupdate selbst nachinstalliert. Nutzer müssen dafür nichts tun, außer online zu bleiben und Updates über die Einstellungen zu beziehen.", "zusammenfassung": "Das November-Sicherheitsupdate KB5132061 lässt sich auf einem Teil der Windows-11-PCs nicht installieren, die Installation bricht teilweise erst bei 99 Prozent ab, und wiederholte Versuche helfen oft nicht. Gemeldet werden die Fehlercodes 0x800f0993, 0x800f0989 und 0x80070306, vereinzelt auch 0x800f0922. Microsoft hat das Problem am Mittwoch als bekanntes Problem in den englischen Versionshinweisen zu KB5132061 dokumentiert. Laut den Angaben des Konzerns wird eine Reparatur automatisch auf betroffenen Geräten ausgeführt, die mit dem Internet verbunden sind und Updates über die Einstellungen beziehen; manuelle Schritte sind dafür nicht nötig. Alle betroffenen Geräte sollen innerhalb von 24 bis 48 Stunden nach dem Start am Mittwoch um 19 Uhr Wiener Zeit (10 Uhr Pazifikzeit) den Fix erhalten und das Sicherheitsupdate anschließend selbst herunterladen und installieren. Eine von BleepingComputer zitierte Microsoft-Service-Meldung schränkt ein, betroffen sei nur ein Teil der Geräte mit dem optionalen Oktober-Vorschauupdate KB5127936; Geräte ohne dieses Vorschauupdate seien nicht betroffen. Was genau die Ursache ist, nennt Microsoft nicht. Zuvor hatten unter anderem Windows Latest und das Portal DrWindows über die Fehler berichtet, viele Systeme waren aber nie betroffen. Frühere Hinweise auf die Windows-Sandbox oder auf DISM und sfc bleiben damit zweitrangig, weil der Konzern jetzt zum Abwarten auf die automatische Reparatur rät. Wer nach Ablauf der 48 Stunden immer noch nicht installieren kann, soll laut Microsoft die Windows-Hilfe nutzen oder den Support kontaktieren. Es bleibt ein Sicherheitsupdate, deshalb sollte man es nicht dauerhaft aussetzen.", "quelle": {"name": "Microsoft Support", "url": "https://support.microsoft.com/en-us/servicing/os/windows-11/2026/11/kb5132061-windows-11-24h2-25h2-26h2-security-update"}, "weitere_links": [{"name": "Dr. Windows", "url": "https://www.drwindows.de/news/installationsfehler-0x800f0993-beim-windows-11-november-update-problem-laut-microsoft-geloest"}, {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-confirms-kb5132061-installation-issues-0x80070306-0x800f0989-0x800f0993-errors/"}, {"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-explains-how-windows-11-kb5132061-install-fail-bug-is-being-fixed/"}, {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/11/microsoft-investigates-windows-11-kb5132061-issues-0x800f0993-0x80070306-and-0x800f0989-installation-errors/"}], "tags": ["Windows 11", "KB5132061", "Patchday", "Update-Fehler"], "archiviert_am": "2026-11-18T17:57:07.732Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.676Z"}, "id": "2026-11-11-harada-xbox-series-s", "datum": "2026-11-11T15:09:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Konsolen", "titel": "Ex-Tekken-Chef Katsuhiro Harada: Konsolen wie die Xbox Series S sollten nicht erscheinen", "schlagzeile": "Tekken-Legende Harada über Series S: „Extraarbeit für ein schwächeres Kind“", "kurz": "Katsuhiro Harada hat auf einer Entwicklerkonferenz in Südkorea die Xbox Series S kritisiert, während ein Xbox-Vertreter im Saal saß. Das Problem sei vor allem, dass sie der Series X so ähnlich, aber spürbar schwächer sei. Ein CD-Projekt-Entwickler hielt dagegen: Die Optimierung helfe allen Plattformen.", "zusammenfassung": "Katsuhiro Harada, lange Chef der Tekken-Reihe und inzwischen Leiter des neuen Studios VS Studio, hat sich auf der Console Game Developers Conference 2026 in Südkorea deutlich über die Xbox Series S geäußert. Laut Inven Global, zitiert von Eurogamer, sagte er vor einem anwesenden ranghohen Xbox-Vertreter, er wünsche sich, dass Hardware wie die Series S nicht veröffentlicht werde. Das größte Problem sei nicht nur der knappe Speicher, sondern dass die Konsole der Series X sehr ähnlich, aber unglücklich schwächer sei. Nach der besten Fassung fühle es sich an, als müsse man Extraarbeit für ein etwas schwächeres Kind leisten. Bei der Switch 2 könne man dagegen gedanklich auf ein eigenes Gerät für Nintendo-Fans umschalten. Weil es etwa in den USA mehr Series-S- als Series-X-Nutzer gebe, könne man nicht sparen, und Beschwerden über schlechtere Texturen landeten dann bei den Entwicklern. Paweł Sasko von CD Projekt Red hielt dagegen: Die Optimierung für schwächere Hardware lasse Spiele auf allen Plattformen deutlich besser laufen, und der niedrige Preis vergrößere den Markt. Shift-Up-Technikchef DongKi Lee sagte, er freue sich auf die nächste Xbox mit dem Codenamen Helix. Es handelt sich um eine Meinungsäußerung auf einem Podium, nicht um eine offizielle Position von Microsoft oder eines Studios.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/katsuhiro-harada-xbox-series-s-wish-it-wouldnt-release"}, "weitere_links": [{"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/katsuhiro-harada-says-he-wishes-xbox-series-s-didnt-exist-because-its-like-doing-extra-work-for-a-slightly-weaker-child/"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/ex-tekken-director-savages-xbox-series-s-in-front-of-senior-xbox-staff-feels-like-having-to-do-extra-work-for-a-slightly-weaker-child/"}], "tags": ["Xbox Series S", "Tekken", "Katsuhiro Harada", "Entwickler"], "archiviert_am": "2026-11-18T17:57:07.734Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.769Z"}, "id": "2026-11-11-rtx5080-24gb-gestrichen", "datum": "2026-11-11T14:09:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["GPU"], "kategorie": "Grafikkarten", "titel": "Berichte: Nvidia soll die RTX 5080 mit 24 GB gestrichen haben – 16-GB-Modell bleibt", "schlagzeile": "Leak: Nvidia soll die RTX 5080 mit 24 GB gestrichen haben", "kurz": "Laut dem chinesischen Branchenkanal Board Channels hat Nvidia seinen Boardpartnern den für Jänner 2027 geplanten Start einer RTX 5080 mit 24 GB abgesagt. Grund sollen die teuren 3-GB-GDDR7-Chips sein. Die RTX 5080 mit 16 GB soll weiter produziert werden. Nvidia hat dazu nichts bestätigt.", "zusammenfassung": "Eine RTX 5080 mit 24 GB Grafikspeicher wird es nach neuen Berichten vorerst nicht geben. TechPowerUp beruft sich auf den chinesischen Branchenkanal Board Channels, wonach Nvidia die Boardpartner offiziell über das Aus für den geplanten Start im Jänner 2027 informiert haben soll. Als Grund werden die Kosten genannt: 3-GB-GDDR7-Chips sollen laut dem von PC Gamer zitierten Beitrag etwa dreimal so viel kosten wie die bisher verbauten 2-GB-Chips. Mit dem teureren Speicher hätte die Karte zu einem Preis erscheinen müssen, der sich kaum verkaufen ließe. Die bekannte RTX 5080 mit 16 GB soll deshalb weiter gebaut werden. Laut früheren Gerüchten hätte das 24-GB-Modell die gleiche Zahl an Recheneinheiten gehabt, aber mehr Speicher, mehr Bandbreite und etwas höhere Taktraten. PC Gamer weist darauf hin, dass es zuvor sogar hieß, die 24-GB-Version könnte die RTX 5090 und die 16-GB-Variante ersetzen; Nvidia-Manager Jeff Fisher hatte aber betont, dass die Produktion der RTX 5090 nicht eingestellt sei. Ein Super-Refresh ist laut TechPowerUp derzeit nicht in Sicht, die nächste große Stufe wäre die RTX-60-Serie. Wichtig: Schon das 24-GB-Modell selbst war nie offiziell angekündigt, es geht also um das Gerücht über das Ende eines Gerüchts. Nvidia hat sich nicht geäußert.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354686/nvidia-geforce-rtx-5080-24-gb-reportedly-cancelled-16-gb-model-remains"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/apparently-now-we-wont-see-a-24-gb-rtx-5080-which-is-probably-actually-good-for-our-wallets/"}, {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Geforce-RTX-5080-Grafikkarte-281030/News/Nvidia-streicht-24-GiB-Modell-1559572/"}, {"name": "Wccftech", "url": "https://wccftech.com/nvidia-reportedly-cancelled-rtx-5080-24-gb-as-3-gb-gddr7-is-way-too-expensive/"}], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Board Channels ist eine bekannte, aber nicht immer treffsichere Lieferketten-Quelle; von TechPowerUp, PC Gamer, PCGH und Wccftech aufgegriffen, von Nvidia unbestätigt."}, "ursprungsquelle": "Board Channels (via VideoCardz, Gazlog, harukaze5719)", "tags": ["RTX 5080", "Nvidia", "GDDR7", "Grafikspeicher"], "archiviert_am": "2026-11-18T17:57:07.734Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.866Z"}, "id": "2026-11-11-gta6-de-cix-rekord", "datum": "2026-11-11T13:49:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Vorab-Download von GTA 6: Internetknoten DE-CIX misst neuen Datenrekord", "schlagzeile": "GTA-6-Download sprengt Rekord: 22,3 Terabit pro Sekunde in Frankfurt", "kurz": "Am ersten Abend des Vorab-Downloads von GTA 6 hat der Internetknoten DE-CIX in Frankfurt einen neuen Spitzenwert von 22,30 Terabit pro Sekunde gemessen. Auch weltweit meldet der Betreiber einen Rekord. Spielbar ist GTA 6 ab Mitternacht zum 19. November.", "zusammenfassung": "Der Start des Vorab-Downloads von Grand Theft Auto VI hat messbare Spuren im Netz hinterlassen. Wie der Betreiber des DE-CIX Golem auf Anfrage mitteilte, erreichte der Knoten in Frankfurt am 10. November um 20:20 Uhr einen neuen Spitzenwert von 22,30 Terabit pro Sekunde. Das sind 19,06 Prozent mehr als beim bisherigen Höchstwert seit Jänner 2026. Über alle DE-CIX-Standorte weltweit wurden 33,01 Terabit pro Sekunde gemessen, ebenfalls ein Rekord. DE-CIX-Technikchef Thomas King erklärte, große Spielestarts gehörten zu den Ereignissen, die den Verkehr sehr schnell stark steigen lassen. Der DE-CIX Frankfurt gilt nach Datendurchsatz als größter Internetknoten Europas. Der Vorab-Download für PS5 und Xbox Series X|S startete in der Nacht auf den 10. November, die Datei ist rund 210 bis 212 GB groß. Auch ein deutscher Internetanbieter meldete laut PC Games ein Vielfaches des üblichen Gaming-Datenverkehrs. Spielbar ist GTA 6 ab dem 19. November um Mitternacht. Ob der Starttag selbst noch einmal neue Rekorde bringt, bleibt abzuwarten.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/downloadstart-de-cix-verzeichnet-wegen-gta-vi-neue-datenrekorde-2611-215089.html"}, "weitere_links": [{"name": "PC Games", "url": "https://www.pcgames.de/GTA-6-Spiel-55239/News/Deutschland-Internet-1-und-1-Vodafone-Datenverkehr-zehnfach-1559532/"}], "tags": ["GTA 6", "DE-CIX", "Download", "Internet"], "archiviert_am": "2026-11-18T17:57:07.734Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.960Z"}, "id": "2026-11-11-mh-wilds-ascendance-beta", "datum": "2026-11-11T12:16:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Monster Hunter"], "kategorie": "Spiele", "titel": "Steam-Änderungen deuten auf Beta für die Monster-Hunter-Wilds-Erweiterung Ascendance hin", "schlagzeile": "Leak: Bekommt Monster Hunter Wilds: Ascendance bald eine Beta?", "kurz": "Capcom hat die alte Beta-App von Monster Hunter Wilds auf Steam still in „Ascendance Beta test“ umbenannt, wie SteamDB zeigt. Das spricht für einen baldigen Test der Erweiterung. Capcom hat noch nichts angekündigt, ein Termin ist unbekannt.", "zusammenfassung": "Die erste große Erweiterung von Monster Hunter Wilds heißt Ascendance und soll 2027 erscheinen. Laut Eurogamer und PC Gamer hat Capcom nun auf Steam die alte Beta-App des Hauptspiels umbenannt. Sie heißt laut dem SteamDB-Änderungsprotokoll jetzt Monster Hunter Wilds: Ascendance Beta test und hat ein neues Titelbild bekommen. Das deutet auf einen bevorstehenden Beta-Test hin. Weil die App dieselbe ID wie die frühere Wilds-Beta hat, könnte sie bei früheren Testern wieder in der Bibliothek auftauchen; eine eigene Anmeldung wäre dann eventuell nicht nötig. Wann eine Beta starten könnte, ist völlig offen, Eurogamer tippt vorsichtig auf Anfang 2027. Capcom hatte Ascendance zuletzt in der State of Play im September und auf der Tokyo Game Show gezeigt, inklusive des zurückkehrenden Älteren Drachen Teostra. Die Erweiterung soll anspruchsvoller werden, nachdem viele Spieler das Hauptspiel zum Start zu leicht fanden. Es handelt sich um Hinweise aus Steam-Daten, nicht um eine offizielle Ankündigung.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/monster-hunter-wilds-ascendance-beta-steam-backend"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/games/action/capcom-quietly-updates-the-monster-hunter-wilds-beta-listing-on-steam-indicating-a-possible-expansion-playtest/"}], "zuverlaessigkeit": {"stufe": "mittel-hoch", "begruendung": "Beruht auf öffentlich sichtbaren Steam-Änderungen (SteamDB), die Capcom selbst vorgenommen hat; eine Beta selbst ist aber nicht angekündigt."}, "ursprungsquelle": "SteamDB-Änderungsprotokoll (via PC Gamer)", "tags": ["Monster Hunter Wilds", "Ascendance", "Capcom", "Beta", "Steam"], "archiviert_am": "2026-11-18T17:57:07.734Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:05.058Z"}, "id": "2026-11-11-radeon-ssd-fix-tool", "datum": "2026-11-11T11:06:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Treiber"], "kategorie": "Grafikkarten", "titel": "Inoffizielles Open-Source-Tool stoppt das Dauerschreiben von atieclxx.exe auf die SSD", "schlagzeile": "Radeon-Treiber quält die SSD: Gratis-Tool stoppt das Dauerschreiben", "kurz": "Ein Community-Entwickler hat auf GitHub ein kostenloses Tool gegen den Radeon-Fehler veröffentlicht, bei dem atieclxx.exe sich jede Sekunde neu auf die SSD kopiert. Es prüft, ob der PC betroffen ist, schätzt den Verschleiß und blockiert das Schreiben, ohne den Dienst abzuschalten. Es ist ein inoffizieller Workaround, nicht von AMD.", "zusammenfassung": "Auf manchen PCs mit Radeon-Treiber oder AMD-Chipsatztreiber kopiert sich die Datei atieclxx.exe, die zum Dienst AMD External Events Utility gehört, jede Sekunde selbst. Das erzeugt ständige Schreiblast auf dem Systemlaufwerk, und so kommen auch ohne Nutzung schnell Hunderte Gigabyte zusammen, was SSDs unnötig altern lässt. Ein Community-Mitglied namens Necandi hat dafür nun das Tool Radeon-atieclxx-SSD-Fix auf GitHub veröffentlicht, wie ComputerBase und Wccftech berichten. Es prüft zuerst, ob das System betroffen ist, und schätzt den bisherigen Verschleiß der SSD. Diese Schätzung ist grob: Sie nimmt an, dass der Fehler seit dem Einbau der AMD-Karte besteht, und rechnet ohne Laufzeitangabe der SSD mit acht Stunden Betrieb pro Tag. Statt den Dienst abzuschalten, verbietet das Tool nur dem Systemkonto, die Kopie zu überschreiben. Dadurch schlägt der Kopierversuch fehl, und FreeSync, Frame Pacing und Hotkeys sollen weiter funktionieren. Bisherige Workarounds wie das Beenden des Dienstes oder das Abschalten von Resizable BAR konnten genau dort Probleme machen. Wer kein Tool will, kann die Rechte laut ComputerBase auch per icacls-Befehl selbst entziehen und später wieder freigeben. Der Entwickler betont, dass er nichts mit AMD zu tun hat und die Nutzung auf eigene Verantwortung erfolgt. AMD hat einen offiziellen Fix mit dem Treiber 26.11.1 angekündigt, der noch aussteht.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/grafikkarten/radeon-atieclxx-ssd-fix-tool-stoppt-das-dauerschreiben-des-radeon-treibers.100286/"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/amd-radeon-ssd-write-bug-gets-a-fix-from-necanditool/"}], "tags": ["AMD", "Radeon", "SSD", "Treiber", "atieclxx"], "archiviert_am": "2026-11-18T17:57:07.735Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:05.176Z"}, "id": "2026-11-11-zen6-epyc-tests", "datum": "2026-11-11T10:58:00+01:00", "label": "News", "bereich": "hardware", "themen": ["CPU"], "kategorie": "Prozessoren", "titel": "AMD Epyc 9006 Venice im Handel: Erste Tests zeigen große Sprünge für Zen 6", "schlagzeile": "Erste Zen-6-Tests: AMDs 256-Kerner ist 58 % schneller als der Vorgänger", "kurz": "AMD verkauft die Server-Prozessoren Epyc 9006 Venice mit Zen 6 jetzt offiziell. In den ersten unabhängigen Tests von Phoronix war das Topmodell Epyc 9996 im Mittel 1,58-mal so schnell wie das bisherige Zen-5c-Flaggschiff. Für Gamer ist das ein erster Blick auf die Architektur künftiger Ryzen-Chips.", "zusammenfassung": "AMD hat den Verkaufsstart der sechsten Epyc-Generation alias Venice bekanntgegeben, die bereits im Juli vorgestellt wurde. Den Anfang machen neun Modelle für den Sockel SP7, laut Golem folgen Anfang 2027 weitere 22 für SP8. Phoronix durfte die beiden Spitzenmodelle testen. Der Epyc 9996 hat 256 Zen-6c-Kerne, bis zu 4,1 GHz und 600 Watt TDP und kostet laut AMD-Liste 14.904 US-Dollar. Im Doppelsockel-System lag er über alle Benchmarks gemittelt beim 1,58-Fachen des Vorgängers Epyc 9965 mit 192 Kernen. Bei HPC-Anwendungen war er etwa doppelt so schnell wie Intels Xeon 6980P und lieferte trotz höherer Leistungsaufnahme die beste Leistung pro Watt. Laut Golem profitieren die kompakten Kerne von größeren Chiplets mit 32 statt 12 Kernen. Der zweite getestete Chip, der Epyc 9686F, hat 96 Zen-6-Kerne mit bis zu 5,3 GHz. Für Gamer sind das Server-Chips, aber sie zeigen erstmals unabhängig, was die Zen-6-Architektur leistet, die später auch in Ryzen-Prozessoren erwartet wird. Wie viel davon in Spielen ankommt, lässt sich aus Server-Benchmarks nicht ableiten. Phoronix weist außerdem darauf hin, dass die volle Leistung schnellen MRDIMM-Speicher braucht, der in der aktuellen RAM-Krise sehr teuer sein dürfte.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/venice-amds-epyc-9006-setzen-sich-an-die-spitze-der-server-cpus-2611-215075.html"}, "weitere_links": [{"name": "Phoronix (Epyc 9996 Test)", "url": "https://www.phoronix.com/review/amd-epyc-9996"}, {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/AMD-Zen-Architektur-261795/News/Neue-Architektur-Vergleich-1559571/"}, {"name": "AMD auf X", "url": "https://x.com/AMD/status/2120532173623054816"}], "tags": ["AMD", "Zen 6", "Epyc", "Venice", "Server"], "archiviert_am": "2026-11-18T17:57:07.735Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:05.281Z"}, "id": "2026-11-11-zelda-oot-5-2-mio", "datum": "2026-11-11T10:56:00+01:00", "label": "News", "bereich": "games", "themen": ["Nintendo"], "kategorie": "Spiele", "titel": "Zelda: Ocarina of Time Remake verkauft sich in vier Tagen mehr als 5,2 Millionen Mal", "schlagzeile": "Zelda-Remake bricht Switch-2-Rekord: 5,2 Millionen in nur vier Tagen", "kurz": "Nintendo meldet mehr als 5,2 Millionen verkaufte Exemplare des Ocarina-of-Time-Remakes in den ersten vier Tagen. Das ist der schnellste Verkaufsstart eines Nintendo-Spiels auf der Switch 2. Laut Nintendo zählen echte Verkäufe, nicht nur Auslieferungen an den Handel.", "zusammenfassung": "Das Remake von The Legend of Zelda: Ocarina of Time ist ein großer Erfolg für Nintendo. Laut einer Pressemitteilung des Herstellers wurden in den ersten vier Tagen nach dem Start am 5. November weltweit mehr als 5,2 Millionen Exemplare verkauft. Damit ist es der erfolgreichste Verkaufsstart eines von Nintendo veröffentlichten Switch-2-Spiels, laut Golem weltweit und in Europa. Nintendo spricht dabei laut Golem von tatsächlich verkauften Einheiten und nicht nur von Auslieferungen an den Handel. Eine Aufteilung nach Regionen oder nach digital und physisch gibt es nicht. Der Rekord bezieht sich ausdrücklich auf Nintendo-eigene Spiele, wie Eurogamer betont. Das Remake kommt auch bei der Kritik sehr gut an: Golem nennt einen Metacritic-Schnitt von 96 Punkten. Neu sind unter anderem Grafik, Soundtrack, Sprachausgabe und überarbeitete Kämpfe. Bemerkenswert ist der Erfolg auch, weil das Spiel nur zwei Wochen vor GTA 6 erschienen ist. Das Remake ist Teil der Feiern zum 40. Geburtstag der Zelda-Reihe.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/zelda-ocarina-of-time-switch-2-sales-nintendo"}, "weitere_links": [{"name": "Golem.de", "url": "https://www.golem.de/news/the-legend-of-zelda-zelda-ocarina-of-time-legt-rekordstart-auf-switch-2-hin-2611-215084.html"}, {"name": "IGN Deutschland", "url": "https://de.ign.com/the-legend-of-zelda-ocarina-of-time-remake/157167/the-legend-of-zelda-ocarina-of-time-ist-ein-riesenerfolg-fur-nintendo-und-hat-gerade-einen-verkaufsr"}], "tags": ["Zelda", "Ocarina of Time", "Switch 2", "Nintendo", "Verkaufszahlen"], "archiviert_am": "2026-11-18T17:57:07.736Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.500Z"}, "id": "2026-11-11-ps5-100-millionen", "datum": "2026-11-11T08:28:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Konsolen", "titel": "Sony bestätigt: PlayStation 5 hat sich mehr als 100 Millionen Mal verkauft", "schlagzeile": "PS5 knackt die 100 Millionen – nur noch knapp hinter der ersten PlayStation", "kurz": "Sony hat bestätigt, dass die PS5 mit Stand 10. November mehr als 100 Millionen Mal an den Handel ausgeliefert wurde. Damit liegt sie vor PS3 und PSP und knapp hinter der ersten PlayStation mit 102,4 Millionen. Zuletzt liefen die Verkäufe allerdings deutlich langsamer als im Vorjahr.", "zusammenfassung": "Die PlayStation 5 hat eine runde Marke erreicht: Laut Sonys offizieller Verkaufsübersicht wurden bis zum 10. November 2026 mehr als 100 Millionen Konsolen ausgeliefert. Gezählt werden Auslieferungen an den Handel (Sell-in), nicht Verkäufe an Endkunden. Damit hat die PS5 die PS3 (87,4 Millionen) und die PSP (76,4 Millionen) hinter sich gelassen. Die erste PlayStation liegt mit 102,4 Millionen nur noch knapp vorn, die PS4 mit 117 Millionen und die PS2 mit mehr als 160 Millionen deutlich. Das Tempo hat zuletzt nachgelassen: Laut Insider Gaming wurden im ersten Quartal des Geschäftsjahres 1,6 Millionen statt 2,5 Millionen Geräte ausgeliefert, im zweiten 2,6 statt 4 Millionen. Das stärkste Jahr war das Geschäftsjahr 2023 mit 20,8 Millionen Konsolen. Sony nennt außerdem 127 Millionen monatlich aktive PlayStation-Nutzer zum 30. September. Bei der Software stehen im laufenden Geschäftsjahr nach zwei Quartalen 154,3 Millionen verkaufte Einheiten für PS4 und PS5. Wie stark GTA 6 am 19. November die Konsolenverkäufe antreibt, zeigen erst die Zahlen für das dritte Quartal.", "quelle": {"name": "Sony Interactive Entertainment (Business Data & Sales)", "url": "https://sonyinteractive.com/en/our-company/business-data-sales/"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/playstation-5-officially-sold-more-than-100-million-units/"}], "tags": ["PS5", "Sony", "Verkaufszahlen"], "archiviert_am": "2026-11-18T17:57:07.736Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.203Z"}, "id": "2026-11-11-nvidia-aktie-china-chips", "datum": "2026-11-11T07:55:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Branche", "titel": "Nvidia-Aktie auf tiefstem Stand seit März: Bericht nennt über 240.000 KI-Systeme, die über ein Firmengeflecht nach China gelangt sein sollen", "schlagzeile": "Nvidia-Aktie fällt weiter: Chips für 7,5 Mrd. $ sollen nach China gegangen sein", "kurz": "Nach zwei Verlusttagen schloss die Nvidia-Aktie am Dienstag bei 168,89 US-Dollar, dem tiefsten Stand seit Ende März. Microsoft zog beim Börsenwert zeitweise vorbei. Laut einem Bericht von The Information soll die Frau, mit der Jensen Huang eine Affäre zugab, Nvidia-Systeme im Wert von mindestens 7,5 Milliarden Dollar nach China gebracht haben.", "zusammenfassung": "Der Skandal um Nvidia-Chef Jensen Huang belastet den Konzern an der Börse weiter. Nach einem Minus von mehr als 4 Prozent am Montag fiel die Aktie am Dienstag um weitere 5,5 Prozent und schloss bei 168,89 US-Dollar, so tief wie seit dem 30. März nicht mehr. Der Börsenwert liegt damit knapp über 4 Billionen Dollar; Anfang Oktober waren es noch mehr als 5,5 Billionen. Microsoft lag am Dienstag zeitweise vor Nvidia, Apple schon vor Bekanntwerden der Vorwürfe. Auslöser ist ein neuer Bericht von The Information, der sich auf zwei Personen aus dem Umfeld von Alice Huang beruft, mit der der Nvidia-Chef eine Affäre eingeräumt hat. Sie soll über ein Firmengeflecht Lieferungen von mehr als 240.000 A100-, H100- und H200-Systemen im Wert von mindestens 7,5 Milliarden Dollar nach China ermöglicht haben. Für A100 und H100 gelten seit Oktober 2022 US-Exportbeschränkungen. Eine Rolle spielen demnach die chinesische Rechenzentrumsfirma Century Litong und die Singapurer Firma Megaspeed, die seit Oktober 2023 zu Nvidias bevorzugten Cloud-Partnern zählt. US-Behörden sollen fordern, Megaspeed auf eine schwarze Liste zu setzen. China weist den Spionagevorwurf zurück. Nvidia hat eine interne Untersuchung gestartet, die laut einem von CNBC zitierten Analysten vier bis sechs Wochen dauern könnte. Derselbe Analyst schätzt die Wahrscheinlichkeit, dass Huang seinen Posten verliert, auf etwa 15 Prozent. Die Zahlen zu den Chip-Lieferungen stammen aus anonymen Quellen und sind nicht offiziell bestätigt.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Skandal-bei-Nvidia-Aktienkurs-faellt-auf-den-tiefsten-Stand-seit-Maerz-11520096.html"}, "weitere_links": [{"name": "heise online (Bericht zu den China-Lieferungen)", "url": "https://www.heise.de/news/Bericht-Jensen-Huangs-Affaere-brachte-Nvidia-Chips-im-Milliardenwert-nach-China-11520058.html"}], "tags": ["NVIDIA", "Jensen Huang", "Aktie", "China", "Exportkontrollen"], "archiviert_am": "2026-11-18T17:57:07.737Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.763Z"}, "id": "2026-11-11-fortis-games-schliessung", "datum": "2026-11-11T02:09:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spiele", "titel": "Mobile-Studio Fortis Games schließt, rund 440 Jobs betroffen, Geldgeber Las Vegas Sands stellt Finanzierung ein", "schlagzeile": "Fortis Games macht dicht – rund 440 Jobs weg, Casino-Konzern zieht Geld ab", "kurz": "Das 2022 gegründete Mobile-Studio Fortis Games hat geschlossen, betroffen sind rund 440 Stellen. Laut einem früheren Mitarbeiter hat Geldgeber Las Vegas Sands die Finanzierung beendet und alle Verträge weltweit gekündigt. Die beiden Spiele des Studios waren noch in einer frühen Testphase.", "zusammenfassung": "Die nächste große Schließung in der Spielebranche: Fortis Games ist Geschichte, rund 440 Arbeitsplätze sind betroffen. CEO Steven Chiang bestätigte das Aus am 10. November gegenüber GamesBeat. Man sei enttäuscht, die eigenen Ziele nach mehr als fünf Jahren nicht erreicht zu haben, und wolle sich nun darauf konzentrieren, dem Team bei der Jobsuche zu helfen. Ein ehemaliger Produzent schrieb auf LinkedIn, Mutterkonzern Las Vegas Sands habe entschieden, die Finanzierung zu beenden und alle Verträge weltweit zu kündigen. Das Studio aus San Francisco wurde 2022 von Chiang gegründet, der zuvor bei Electronic Arts und Zynga war. Fortis arbeitete an den Mobile-Spielen Twilight Towers und Bloom & Breakfast, die sich in einem frühen Soft Launch befanden; laut dem Produzenten mit soliden Kennzahlen. Ein früherer Kommunikationschef schrieb dagegen, der gemeinschaftsorientierte Ansatz habe bei Spielern nicht genug Anklang gefunden. Was mit den beiden Spielen passiert, ist nicht bekannt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/fortis-games-closes-with-over-400-jobs-impacted"}, "weitere_links": [], "tags": ["Fortis Games", "Entlassungen", "Mobile Games"], "archiviert_am": "2026-11-18T17:57:07.737Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.944Z"}, "id": "2026-11-11-windows11-speicherintegritaet", "datum": "2026-11-11T00:50:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Betriebssystem", "titel": "Windows 11 schaltet die Speicherintegrität (HVCI) jetzt auf mehr PCs automatisch ein, ein Schutz, der Spiele bremsen kann", "schlagzeile": "Windows 11 schaltet Speicherintegrität ein – was das für Gamer heißt", "kurz": "Mit dem November-Update aktiviert Windows 11 die Speicherintegrität (HVCI) auf mehr bestehenden PCs automatisch. Der Schutz blockiert manipulierte Treiber, kann aber laut Microsoft selbst Leistung in Spielen kosten. Wer sie bewusst abgeschaltet hat, bleibt verschont, ausschalten lässt sie sich weiterhin.", "zusammenfassung": "Microsoft dreht an einer Sicherheitsschraube, die Gamer betrifft. Seit dem optionalen Oktober-Update und nun mit dem Patchday-Update KB5132061 kann Windows 11 die Speicherintegrität, auch HVCI genannt, bei Updates automatisch einschalten. Bisher war sie meist nur auf neuen PCs und bei Neuinstallationen aktiv. Laut Windows Latest gilt die Änderung für Windows 11 25H2 und 26H2. Die Speicherintegrität läuft in einem durch den Windows-Hypervisor abgeschotteten Bereich und prüft dort, ob Treiber und Kernel-Code vertrauenswürdig sind; so kann selbst ein gekaperter Kernel keinen ungeprüften Code ausführen. Manche PCs bekommen dafür auch die virtualisierungsbasierte Sicherheit (VBS) eingeschaltet. Vor dem Aktivieren prüft Windows Hardware, Treiberkompatibilität und Leistung, und die Verteilung erfolgt schrittweise. Wer die Funktion zuvor selbst ausgeschaltet hat, bei dem schaltet Windows sie nicht wieder ein; Firmenrichtlinien haben Vorrang. Der Haken für Spieler: Microsoft selbst hatte vor einigen Jahren in einem Support-Artikel empfohlen, die Speicherintegrität für bessere Spieleleistung abzuschalten. Ausschalten lässt sie sich unter Windows-Sicherheit, Gerätesicherheit, Details zur Kernisolierung. Ob man das tun sollte, ist eine Abwägung, denn der Schutz richtet sich gegen Schadsoftware, die sich über Treiber in den Kern von Windows einschleust.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/11/windows-11-is-now-force-enabling-memory-integrity-a-feature-microsoft-admitted-can-hurt-gaming-performance-and-heres-how-to-turn-it-off/"}, "weitere_links": [], "tags": ["Windows 11", "Speicherintegrität", "HVCI", "VBS", "Gaming-Leistung"], "archiviert_am": "2026-11-18T17:57:07.737Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.585Z"}, "id": "2026-11-10-fairgames-eingestellt", "datum": "2026-11-10T21:52:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Spiele", "titel": "Sony stellt den Live-Service-Shooter Fairgames nach enttäuschendem Playtest ein, Haven Studios bleibt ohne Entlassungen", "schlagzeile": "Sony stoppt Fairgames – der nächste Live-Service-Shooter ist Geschichte", "kurz": "PlayStation hat die Entwicklung des Heist-Shooters Fairgames von Haven Studios eingestellt. Laut einer internen Mail, über die Bloomberg berichtet, blieben Spielerfeedback und Bindung in einem Playtest hinter den Zielen zurück. Entlassungen soll es nicht geben, das Studio unterstützt künftig andere Sony-Teams.", "zusammenfassung": "Fairgames ist Geschichte. Sony hat die Entwicklung des Live-Service-Shooters drei Jahre nach der Ankündigung 2023 beendet, wie zuerst Bloomberg berichtete. In einer internen Mail der PlayStation-Manager Sean Decker und John Doyle heißt es, ein aktueller Playtest habe zwar technisch und organisatorisch überzeugt, Feedback und Spielerbindung seien aber gemischt gewesen und hinter den Zielen zurückgeblieben. Zusammen mit dem schwierigen Markt für PvP-Shooter habe man sich gegen eine Fortsetzung entschieden. Entwickler Haven Studios wird laut den Berichten nicht geschlossen, Entlassungen sind nicht geplant; das Team soll stattdessen andere Sony-Studios unterstützen. Haven wurde 2021 von Jade Raymond gegründet, die das Studio inzwischen verlassen hat, und 2022 von Sony übernommen. Fairgames soll seit der Enthüllung mehrfach umgebaut worden sein, interne Tests sollen schon 2025 schlecht angekommen sein. Echtes Gameplay gab es offiziell nie zu sehen, nur Render-Szenen aus dem Ankündigungstrailer. Sonys Live-Service-Strategie hatte 2022 mindestens zehn solcher Spiele bis 2026 vorgesehen. Neben Erfolgen wie Helldivers 2 stehen inzwischen viele gestrichene Projekte und das Debakel um Concord.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/playstation-reportedly-cancels-fairgames-after-recent-playtests/"}, "weitere_links": [{"name": "Polygon", "url": "https://www.polygon.com/sony-cancels-fairgames-live-service-shooter-ps5/"}, {"name": "IGN", "url": "https://www.ign.com/articles/playstation-cancels-live-service-heist-shooter-fairgames"}], "tags": ["Fairgames", "PlayStation", "Haven Studios", "Live-Service"], "archiviert_am": "2026-11-18T17:57:07.738Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.317Z"}, "id": "2026-11-10-nvidia-tsmc-bestellungen", "datum": "2026-11-10T21:21:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Branche", "titel": "Bericht aus Taiwan: Nvidia könnte Chip-Bestellungen bei TSMC kürzen, AMD und ASIC-Entwickler würden profitieren", "schlagzeile": "Leak: Kürzt Nvidia seine Chip-Bestellungen bei TSMC?", "kurz": "Die taiwanische Commercial Times berichtet unter Berufung auf ungenannte Lieferketten-Quellen, Nvidia könnte weniger Chips bei TSMC bestellen. Genannt werden der Druck durch den Skandal um Jensen Huang und strengere Exportprüfungen. Produkt, Fertigungsverfahren, Umfang und Zeitraum nennt der Bericht nicht. Nvidia und TSMC haben sich nicht geäußert.", "zusammenfassung": "Nvidia könnte seine Bestellungen beim Auftragsfertiger TSMC zurückfahren. Das berichtet die taiwanische Zeitung Commercial Times, die sich auf ungenannte Quellen aus der Lieferkette beruft; TechPowerUp hat den Bericht aufgegriffen. Um welche Produkte, welches Fertigungsverfahren, welche Mengen und welchen Zeitraum es gehen soll, steht nicht darin. Als Gründe nennt der Bericht Druck von innen und außen: intern den Skandal um Jensen Huang und die Untersuchung des Nvidia-Boards, extern strengere Exportprüfungen. Zudem sollen H200-Chips in Hongkong auf Lager liegen. Auch der Verdacht, dass einige für H200 zugelassene Firmen Briefkastenfirmen sein könnten, wird erwähnt, aber ausdrücklich als Verdacht und nicht als Ergebnis. Sollte Nvidia Kapazität abgeben, erwartet die Zeitung, dass AMD und Entwickler eigener KI-Chips wie MediaTek, Alchip und GUC sie übernehmen. Betroffen wären bei Kürzungen vor allem Zulieferer wie TSMC und ASE. Für Spieler hieße das nicht automatisch günstigere Grafikkarten, denn der Speicher, der derzeit knapp ist, kommt nicht von TSMC. Der Bericht stützt sich auf eine einzige Quelle; Nvidia und TSMC haben ihn nicht kommentiert. Bis zu einer Bestätigung ist er als Gerücht zu werten.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354666/nvidia-may-cut-tsmc-chip-orders-amid-mounting-pressure-report-claims"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "niedrig bis mittel", "begruendung": "Einzelner Bericht der Commercial Times mit anonymen Lieferketten-Quellen, ohne Angaben zu Produkt, Menge oder Zeitraum; von Nvidia und TSMC unkommentiert."}, "ursprungsquelle": "Commercial Times (Taiwan), via TechPowerUp", "tags": ["NVIDIA", "TSMC", "AMD", "Lieferkette"], "archiviert_am": "2026-11-18T17:57:07.738Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.671Z"}, "id": "2026-11-10-gta6-xbox-fsr4-dateien", "datum": "2026-11-10T20:15:00+01:00", "label": "Leak", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Dataminer finden AMD-FSR-Bibliotheken im Xbox-Paket von GTA 6, ob FSR 4.1.2 genutzt wird, ist offen", "schlagzeile": "Leak: Nutzt GTA 6 auf der Xbox schon AMDs KI-Upscaling FSR 4?", "kurz": "Im Xbox-Preload von GTA 6 stecken zwei AMD-Dateien, deren Namen zur FSR-4.1.2-Integration für Xbox Series X|S passen. Das ist ein Hinweis, aber kein Beweis: Die Spieldateien sind verschlüsselt, und dieselbe Schnittstelle kann auch auf das ältere FSR 3.1 zurückfallen. Rockstar hat sich dazu nicht geäußert.", "zusammenfassung": "Kurz nach dem Start des Xbox-Preloads von GTA 6 haben Dataminer im Installationspaket zwei AMD-Bibliotheken entdeckt: amd_fidelityfx_loader_xbox.dll und amd_fidelityfx_upscaler_xbox.dll. Gefunden hat sie der Dataminer Tex2, andere Nutzer verglichen die Namen mit der Dokumentation zu FSR 4.1.2 für Xbox Series X|S. Zuerst berichtete VideoCardz, PC Games Hardware hat den Fund eingeordnet. AMD und Microsoft hatten FSR 4.1.2 am 4. November für die Xbox freigegeben; es ist der erste KI-basierte Upscaler für die Konsolen und kommt mit zwei INT8-Modellen, Full und Lite. Die Dateinamen belegen aber nicht, dass GTA 6 tatsächlich FSR 4.1.2 verwendet. Dasselbe AMD-SDK enthält auch das klassische FSR 3.1.6, und die Schnittstelle kann darauf ausweichen. Da die Spieldateien verschlüsselt sind, lässt sich der Inhalt der Bibliotheken noch nicht prüfen. Rockstar hat für die Konsolen bisher nur 30 fps auf allen Modellen und PSSR auf der PS5 Pro bestätigt, zum Upscaling auf der Xbox gibt es keine offizielle Angabe. Spätestens zum Start am 19. November dürften Analysen zeigen, welches Verfahren zum Einsatz kommt.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/GTA-6-Spiel-55239/News/FSR-4-Xbox-Series-Dataminer-AMD-Dateien-1559502/"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Dateifund in echten Spieldateien, von PCGH und VideoCardz berichtet; die Namen passen zu FSR 4.1.2, belegen dessen Nutzung aber nicht (Fallback auf FSR 3.1 möglich, Dateien verschlüsselt). Von Rockstar unbestätigt."}, "ursprungsquelle": "Dataminer Tex2 (X), zuerst berichtet von VideoCardz", "tags": ["GTA 6", "Xbox Series X", "FSR 4", "AMD", "Upscaling"], "archiviert_am": "2026-11-18T17:57:07.738Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.860Z"}, "id": "2026-11-10-patchday-november-1235", "datum": "2026-11-10T20:07:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Sicherheit", "titel": "Microsoft-Patchday November 2026: 1.235 Lücken geschlossen, darunter eine aktiv ausgenutzte Outlook-Zero-Day", "schlagzeile": "Patchday-Rekord: 1.235 Lücken – Outlook-Lücke wird schon ausgenutzt", "kurz": "Microsoft hat am November-Patchday 1.235 Sicherheitslücken geschlossen, 66 davon kritisch. Eine Spoofing-Lücke in Outlook wird bereits ausgenutzt, um NTLM-Kontodaten abzugreifen. Windows 11 bekommt KB5132061 und KB5131087, Windows 10 im ESU-Programm KB5131096.", "zusammenfassung": "Microsofts Patchday im November fällt erneut riesig aus: Laut BleepingComputer schließen die Updates 1.235 Sicherheitslücken, weitere 108 wurden schon früher im Monat behoben und sind nicht mitgezählt. Im Oktober waren es sogar 1.411; Microsoft setzt zunehmend KI ein, um Schwachstellen zu finden. 66 Lücken gelten als kritisch, 48 davon erlauben das Ausführen von Schadcode aus der Ferne. Rund 639 betreffen Windows und Windows-Komponenten. Am dringendsten ist eine Spoofing-Lücke in Microsoft Outlook, die bereits angegriffen wird. Laut Microsoft reicht es, wenn ein Opfer eine präparierte Nachrichtendatei öffnet: Outlook verbindet sich dann ohne die übliche Warnung mit einem Server der Angreifer und kann dabei Anmeldedaten in Form von NTLM-Hashes preisgeben. Windows 11 erhält die kumulativen Updates KB5132061 und KB5131087, Windows 10 22H2 im Programm für erweiterte Sicherheitsupdates KB5131096. Bei einigen Nutzern scheitert die Installation von KB5132061 laut Neowin mit dem Fehler 0x800f0993. Wer Windows oder Office nutzt, sollte die Updates trotzdem zeitnah einspielen, vor allem wegen der Outlook-Lücke.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-november-2026-patch-tuesday-fixes-1-235-flaws-outlook-zero-day/"}, "weitere_links": [{"name": "Dr. Windows", "url": "https://www.drwindows.de/news/patchday-november-2026-microsoft-schliesst-sicherheitsluecken-und-behebt-fehler-in-windows"}, {"name": "Neowin (Installationsfehler)", "url": "https://www.neowin.net/news/windows-11-kb5132061-update-download--install-fails-with-0x800f0993-error/"}], "tags": ["Windows 11", "Windows 10", "Patchday", "Outlook", "Zero-Day"], "archiviert_am": "2026-11-18T17:57:07.738Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-11T08:24:29.412Z"}, "id": "2026-11-10-fritzbox-5690-pro-speicher", "datum": "2026-11-10T19:45:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Netzwerk"], "kategorie": "Netzwerk", "titel": "Fritz!Box 5690 Pro: Neuere Geräte haben laut Support-Daten nur halb so viel RAM und Flash, bei gleicher Artikelnummer", "schlagzeile": "Fritz!Box 5690 Pro: Neuere Geräte mit halbem Speicher – gleiche Artikelnummer", "kurz": "Neuere Exemplare der Fritz!Box 5690 Pro haben offenbar nur 1 GB RAM und 2 GB Flash statt 2 und 4 GB. Artikelnummer und Hardwareversion sind gleich, erkennbar ist der Unterschied nur an der Hardware-Subrevision. Fritz spricht von branchenüblichen Anpassungen ohne Einfluss auf die Leistung.", "zusammenfassung": "Wer heute eine Fritz!Box 5690 Pro kauft, bekommt nicht unbedingt dieselbe Hardware wie Käufer zum Marktstart. Aufgefallen ist das einem Nutzer mit zwei Geräten: Das neuere zeigte bei gleicher Fritz!OS-Version eine deutlich höhere RAM-Auslastung. Laut den Support-Daten hat ein Gerät vom Juli 2024 2 GB RAM und 4 GB Flash, eines vom Juni 2026 nur 1 GB RAM und 2 GB Flash. Für das System nutzbar sind demnach 742 statt 1.754 MB RAM, der interne Speicher etwa für Fritz!NAS schrumpft von rund 1,7 GB auf 680 MB. Unterscheiden lassen sich die Varianten nur über die Hardware-Subrevision, die von 3 auf 5 gestiegen ist; Artikelnummer und Hardwareversion sind gleich, äußerlich sehen die Router identisch aus. Wann genau umgestellt wurde, ist unklar, zeitweise scheinen beide Varianten parallel ausgeliefert worden zu sein. Fritz erklärte gegenüber Router-FAQ.de, interne Bauteile wie Speicherbausteine würden im Produktlebenszyklus gelegentlich angepasst; das sei branchenüblich und ändere nichts an Spezifikation und Leistung. Die konkrete Halbierung bestätigte das Unternehmen nicht ausdrücklich. Vergleichstests beider Varianten gibt es noch nicht, ebenso offen ist, ob sich das auf künftige Updates auswirkt. Pikant ist es trotzdem, weil Fritz zum Start im Juni 2024 die hohe Speicherkapazität ausdrücklich beworben hatte.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/internet/fritz-box-5690-pro-router-mit-halbiertem-speicher-bei-gleicher-artikelnummer.100274/"}, "weitere_links": [], "tags": ["Fritz!Box", "Router", "RAM", "Speicherkrise"], "archiviert_am": "2026-11-18T17:57:07.738Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.855Z"}, "id": "2026-11-10-auto-sr-xbox-ally-ryzen", "datum": "2026-11-10T19:00:00+01:00", "label": "News", "bereich": "software", "themen": ["DirectX", "Windows", "PC-Gaming"], "kategorie": "Windows / Gaming", "titel": "Microsoft Auto SR verlässt die Vorschau auf ROG Xbox Ally X und X20 und kommt auf Copilot+ PCs mit AMD Ryzen, neuer Modus bis 120 fps", "schlagzeile": "Windows-Upscaling Auto SR: jetzt mobil, mit HDR und bis zu 120 fps", "kurz": "Microsofts KI-Upscaling Auto SR ist auf den Handhelds ROG Xbox Ally X und X20 offiziell gestartet. Neu sind ein Leistungsmodus mit bis zu 120 fps, der Handheld-Betrieb ohne Dock und die Kombination mit Auto HDR. Auto SR läuft jetzt auch auf ausgewählten Copilot+ PCs mit AMD Ryzen.", "zusammenfassung": "Microsoft hat im DirectX-Blog den offiziellen Start von Automatic Super Resolution (Auto SR) auf den Handhelds ROG Xbox Ally X und ROG Xbox Ally X20 angekündigt. Auto SR lässt Spiele intern mit niedrigerer Auflösung laufen und skaliert sie per KI auf der NPU hoch, ohne dass das Spiel das unterstützen muss. Bisher war die Funktion nur als Vorschau und nur im Dock-Betrieb nutzbar. Jetzt funktioniert sie auch auf dem eingebauten Bildschirm und im Akkubetrieb. Spiele mit 1080p werden ebenfalls unterstützt, am Monitor kann Auto SR dann bis 1440p hochskalieren. Ein neuer Leistungsmodus hebt die Grenze von bisher etwa 60 bis 75 auf bis zu 120 fps; in Microsofts Beispiel mit Rocket League stieg der Schnitt von 70 auf 115 fps. Außerdem lassen sich Auto SR und Auto HDR erstmals gleichzeitig nutzen. Handheld-Betrieb, 1080p und die neuen AMD-Ryzen-Copilot+-PCs sind ab sofort verfügbar. Leistungsmodus und Auto-HDR-Unterstützung kommen schrittweise mit Windows-Updates. Nötig sind aktuelle Windows-11-Updates, eine aktuelle Game Bar und das Auto-Super-Resolution-Paket aus dem Microsoft Store.", "quelle": {"name": "Microsoft DirectX Developer Blog", "url": "https://devblogs.microsoft.com/directx/autosr-performance-mode/"}, "weitere_links": [], "tags": ["Auto SR", "DirectX", "Upscaling", "ROG Xbox Ally", "Copilot+"], "archiviert_am": "2026-11-18T17:57:07.739Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.935Z"}, "id": "2026-11-10-gpu-taskman-vram", "datum": "2026-11-10T19:00:00+01:00", "label": "News", "bereich": "software", "themen": ["GPU", "Tools"], "kategorie": "Software", "titel": "GPU Taskman: Open-Source-Werkzeug zeigt genau, welche Programme wie viel Grafikspeicher belegen", "schlagzeile": "Wer frisst deinen VRAM? Kostenloses Tool zeigt es pro Programm", "kurz": "Der Microsoft- und GitHub-Entwickler Scott Hanselman hat das Open-Source-Werkzeug GPU Taskman veröffentlicht. Es zeigt pro Programm, wie viel Grafikspeicher belegt ist, dazu Auslastung, Temperatur und Takt der GPU. Das Tool ist noch experimentell.", "zusammenfassung": "Scott Hanselman, Vice President bei Microsoft und GitHub, hat mit GPU Taskman ein kostenloses Werkzeug für die Kommandozeile entwickelt. Es soll genauer als der Windows-Task-Manager zeigen, wohin der Grafikspeicher geht. Angezeigt werden VRAM-Belegung, von der GPU genutzter Systemspeicher und die einzelnen Prozesse, dazu Auslastung, Temperatur, Leistungsaufnahme, Takt und PCIe-Werte. Das Tool unterscheidet etwa zwischen Desktop, Browsern, Spielen und KI-Anwendungen. Bei lokalen KI-Modellen in llama.cpp, Ollama oder LM Studio kann es den Speicher für Modellgewichte und KV-Cache getrennt schätzen. Für Spieler kann es helfen, VRAM-Engpässe zu finden, die Ruckler verursachen. Hanselman warnt aber, dass genutzter System-RAM nicht automatisch einen VRAM-Überlauf bedeutet, und einzelne Texturen erkennt das Tool nicht. GPU Taskman unterstützt NVIDIA- und AMD-Karten unter Windows 10 und 11, dazu Linux, WSL und Apple-Silicon-Macs; Version 0.3.5 bringt Intel-GPUs unter Linux. Es steht unter MIT-Lizenz auf GitHub, für Windows gibt es eine portable Version. Die Software ist noch experimentell, einige Werte sind Schätzungen.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/microsoft-vp-creates-open-source-gpu-task-manager-that-shows-exactly-whats-using-your-vram/"}, "weitere_links": [], "tags": ["GPU Taskman", "VRAM", "Open Source", "Tool"], "archiviert_am": "2026-11-18T17:57:07.739Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.503Z"}, "id": "2026-11-10-ps-plus-pc-app-ende", "datum": "2026-11-10T18:05:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Spiele-Dienste", "titel": "Sony stellt die PlayStation-Plus-App für PC am 10. Dezember ein, Death Stranding 2 kommt in den Extra-Katalog", "schlagzeile": "Aus für PS-Plus-Streaming am PC – nur 0,4 % haben es genutzt", "kurz": "Sony stellt die PlayStation-Plus-App für Windows zum 10.12.2026 ein und beendet damit das Streamen von PS-Plus-Spielen auf den PC. Laut Sony nutzten weniger als 0,4 Prozent der Premium-Mitglieder die App. Im selben Beitrag kündigt Sony die neuen Extra- und Premium-Spiele an, angeführt von Death Stranding 2.", "zusammenfassung": "Ganz am Ende seines Beitrags zu den neuen PS-Plus-Spielen im November hat Sony das Aus der PC-App angekündigt. Ab dem 10. Dezember ist die PlayStation-Plus-App für PC nicht mehr verfügbar, und damit auch das Cloud-Streaming von PS-Plus-Premium-Spielen auf Windows-Rechner. Als Grund nennt Sony die geringe Nutzung: Weniger als 0,4 Prozent der berechtigten Premium-Mitglieder hätten die App verwendet. Mitgliedschaften und Vorteile auf PS5 und PS4 seien davon nicht betroffen, betroffene Nutzer will Sony direkt informieren. Damit fällt ein Weg weg, PlayStation-Spiele ohne Konsole am PC zu spielen. Neu im Extra- und Premium-Katalog sind im November unter anderem Death Stranding 2: On the Beach, Atomfall und Dragon Quest III HD-2D Remake. Hell Let Loose folgt am 11. November, Like a Dragon: Pirate Yakuza in Hawaii, Trepang2, MotoGP 26 und Cricket 26 am 24. November. Nur für Premium kommen Soul Reaver 2 und Freedom Wars Remastered dazu.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/playstation-announces-end-of-pc-streaming-in-december/"}, "weitere_links": [{"name": "Eurogamer", "url": "https://www.eurogamer.net/ps-plus-games-november-2026-pc-app"}, {"name": "PlayStation auf X", "url": "https://x.com/PlayStation/status/2120192361494126725"}], "tags": ["PlayStation Plus", "PC", "Cloud-Streaming", "Death Stranding 2"], "archiviert_am": "2026-11-18T17:57:07.739Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:31.904Z"}, "id": "2026-11-10-amd-zen6-ipc-epyc", "datum": "2026-11-10T18:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["CPU", "AMD"], "kategorie": "Prozessoren", "titel": "AMD legt Zen-6-Architektur offen: 27 Prozent mehr IPC, Epyc 9006 „Venice“ mit bis zu 256 Kernen startet", "schlagzeile": "Zen 6 ist da: AMD verspricht 27 % mehr IPC – zuerst für Server-Epyc", "kurz": "AMD hat die Technik hinter Zen 6 enthüllt und nennt 27 Prozent mehr IPC gegenüber Zen 5. Die ersten Zen-6-Chips sind die Server-Prozessoren Epyc 9006 „Venice“ mit bis zu 256 Kernen und bis zu 5,3 GHz. Der IPC-Wert stammt aus einem ungewöhnlichen Vergleich von AMD. Zu Ryzen-Desktop-CPUs mit Zen 6 hat AMD noch nichts gesagt.", "zusammenfassung": "Mit dem Ende der Sperrfrist hat AMD am Abend viele Details zur Zen-6-Architektur veröffentlicht. Laut AMD steigt die IPC, also die Leistung pro Takt, im Schnitt um 27 Prozent gegenüber Zen 5, mit rund 20 Prozent in normalen Anwendungen und rund 31 Prozent bei KI-Lasten. ComputerBase und heise weisen aber darauf hin, dass AMD dafür 16 Zen-6c-Kerne in einem einzigen Chiplet mit 16 Zen-5-Kernen auf zwei Chiplets verglichen hat, was kein klassischer IPC-Vergleich ist. Technisch wird der Kern breiter: Der Op-Cache wächst auf 6.750 Einträge und liefert 18 statt 12 Micro-Ops pro Takt, Registerfile und Reorder-Buffer wachsen auf 352 und 640 Einträge. AVX-512 bleibt, SMT ebenfalls. Die normalen Zen-6-Kerne sitzen zu zwölft in einem Chiplet mit 48 MB L3-Cache, die kompakten Zen-6c-Kerne zu 32 in einem Chiplet mit 128 MB L3, gefertigt in TSMCs 2-nm-Prozess. Erste Produkte sind die Server-CPUs Epyc 9006 „Venice“ mit bis zu 256 Kernen, 16 DDR5-Speicherkanälen, PCIe 6.0 und bis zu 600 Watt. Die Hochtakt-Modelle erreichen bis zu 5,3 GHz. AMD liefert nach eigenen Angaben bereits aus, erste Systeme sollen noch dieses Jahr kommen. In ersten Remote-Messungen von heise brauchte ein einzelner Zen-5-Kern in Blender rund 22 Prozent länger als ein Zen-6-Kern, der allerdings auch höher taktet. 2027 folgen eine kleinere Plattform sowie Venice-X mit 3D-V-Cache und Verano mit LPDDR5X-Speicher. Auf der Roadmap stehen danach Zen 7 „Florence“ für 2028 und Zen 8 „Ravenna“. Zu Ryzen-Prozessoren für Desktop und Notebook mit Zen 6 und deren Termin hat AMD auf dem Event nichts gesagt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/artikel/prozessoren/amd-zen-6-details.100131/"}, "weitere_links": [{"name": "heise online", "url": "https://www.heise.de/news/AMD-Zen-6-soll-agentische-KI-befluegeln-Erste-Leistungswerte-11518546.html"}, {"name": "AMD auf X", "url": "https://x.com/AMD/status/2120200385520369828"}], "tags": ["Zen 6", "Epyc 9006", "Venice", "IPC", "AMD"], "archiviert_am": "2026-11-18T17:57:07.739Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:31.989Z"}, "id": "2026-11-10-amd-mext-flash-statt-ram", "datum": "2026-11-10T18:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM", "AMD"], "kategorie": "Speicher", "titel": "AMD MEXT: Software lagert selten genutzten Arbeitsspeicher auf Flash aus, um teuren DRAM zu sparen", "schlagzeile": "RAM-Krise: AMD will mit Flash-Speicher bis zu 75 % DRAM einsparen", "kurz": "AMD hat MEXT vorgestellt, eine Software, die selten genutzte Speicherseiten von DRAM auf Flash-SSDs auslagert. So sollen Server mit deutlich weniger teurem Arbeitsspeicher fast gleich schnell laufen. Das Angebot gilt vorerst nur für Epyc-Server. Alle Leistungswerte stammen von AMD.", "zusammenfassung": "AMD reagiert mit MEXT auf die anhaltende Speicherknappheit. Laut AMD macht DRAM je nach Konfiguration 75 bis 90 Prozent der Kosten eines Servers aus, während ein großer Teil des Speichers ungenutzt oder überdimensioniert ist. MEXT erkennt „kalte“ Speicherseiten und verschiebt sie auf Flash-Speicher, also NVMe-SSDs. KI-Modelle sollen vorhersagen, welche Daten bald wieder gebraucht werden, und diese rechtzeitig in den DRAM zurückholen. Die Software besteht laut Wccftech aus einem Linux-Treiber, einer KI-Engine, die auf einem einzelnen Epyc-Kern läuft, und einem Monitoring-Werkzeug. Nach AMDs Angaben lässt sich der DRAM-Bedarf so um 20 bis 75 Prozent senken, bei ähnlicher Leistung. Im Chipdesign-Beispiel soll ein Server mit halbem DRAM noch 95 Prozent der Leistung erreichen. Diese Werte sind Herstellerangaben, unabhängige Tests fehlen noch. Laut Phoronix ist der Linux-Treiber nicht quelloffen. MEXT ist vorerst nur für Epyc-Server mit NVMe-Laufwerken gedacht, später soll es eine Lizenz geben. AMD deutete an, dass so etwas auch für normale PCs interessant werden könnte, konkrete Pläne dafür gibt es aber nicht.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/amd-mext-memory-solution-flash-repaces-dram-same-performance/"}, "weitere_links": [{"name": "ComputerBase", "url": "https://www.computerbase.de/artikel/prozessoren/amd-zen-6-details.100131/"}, {"name": "Phoronix", "url": "https://www.phoronix.com/news/AMD-MEXT"}], "tags": ["MEXT", "DRAM", "RAM-Krise", "Epyc", "Flash"], "archiviert_am": "2026-11-18T17:57:07.739Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.415Z"}, "id": "2026-11-10-gta6-vorbestell-rekord-xbox-cloud", "datum": "2026-11-10T16:45:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6", "Xbox"], "kategorie": "Spiele", "titel": "GTA 6 ist laut Sony und Microsoft das meistvorbestellte Spiel ihrer Stores, Xbox One bekommt es per Cloud, Xbox schließt 10-Jahres-Partnerschaft mit Take-Two", "schlagzeile": "GTA 6 bricht Vorbestell-Rekorde – und kommt per Cloud sogar auf die Xbox One", "kurz": "Sony und Microsoft melden, dass GTA 6 das meistvorbestellte Spiel in der Geschichte des PlayStation Store und des Microsoft Store ist. Über Xbox Cloud Gaming läuft es zum Start auch auf der alten Xbox One. Xbox-Chefin Asha Sharma spricht von einer neuen 10-Jahres-Partnerschaft mit Take-Two. Konkrete Verkaufszahlen nennt niemand.", "zusammenfassung": "Im PlayStation.Blog schreibt Sony, GTA 6 sei das meistvorbestellte Spiel in der Geschichte des PlayStation Store. Microsoft meldet im Xbox Wire dasselbe für den Microsoft Store. Zahlen nennen beide nicht; von Take-Two hieß es zuletzt nur, die Vorbestellungen lägen weit über den Erwartungen. Sony und Microsoft raten wegen des erwarteten Ansturms, das Spiel möglichst früh vorzuladen. Auf PlayStation startet GTA 6 am 19. November jeweils um Mitternacht Ortszeit, beginnend in Neuseeland. Xbox Cloud Gaming bietet das Spiel ab 19. November um 1 Uhr US-Ostküstenzeit, also 7 Uhr in Österreich, auf Xbox One und Xbox Series X|S an, mit den Grafikeinstellungen der Series S. Streaming auf PC oder Smartphone ist nicht vorgesehen. Xbox-Chefin Asha Sharma nannte das auf X den „ersten Schritt“ einer neuen 10-jährigen strategischen Partnerschaft mit Take-Two, Details dazu gab es nicht. Laut Xbox Wire sollen in den kommenden Monaten weitere Rockstar-Spiele wie GTA V und Red Dead Redemption 2 in Xbox Cloud Gaming kommen. Ab 11. November kann man in unterstützten Ländern außerdem Cloud-Spielzeit ohne Game-Pass-Abo kaufen.", "quelle": {"name": "Xbox Wire", "url": "https://news.xbox.com/en-us/2026/11/10/grand-theft-auto-6-comes-to-xbox-cloud-gaming-november-19/"}, "weitere_links": [{"name": "PlayStation.Blog", "url": "https://blog.playstation.com/2026/11/10/pre-load-grand-theft-auto-vi-on-ps5-starting-today/"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120181266318590366"}, {"name": "IGN", "url": "https://www.ign.com/articles/sony-confirms-gta-6-is-now-the-most-preordered-game-in-playstation-store-history-issues-official-preload-warning"}], "tags": ["GTA 6", "Xbox Cloud Gaming", "Xbox One", "PlayStation Store", "Take-Two"], "archiviert_am": "2026-11-18T17:57:07.739Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.673Z"}, "id": "2026-11-10-eu-dfa-lootboxen-entwurf", "datum": "2026-11-10T15:46:00+01:00", "label": "Leak", "bereich": "games", "themen": ["EU", "Lootboxen"], "kategorie": "Spielebranche", "titel": "Geleakter Entwurf des EU Digital Fairness Act: Lootboxen für Minderjährige standardmäßig aus, Pay-to-Win für Kinder verboten", "schlagzeile": "Leak: Will die EU Lootboxen für Kinder standardmäßig abschalten?", "kurz": "Ein mutmaßlicher Entwurf des EU-Gesetzes Digital Fairness Act ist vorab aufgetaucht. Er sieht vor, dass Lootboxen für Minderjährige standardmäßig ausgeschaltet sind und alle Spieler sie abschalten können. Die offizielle Vorstellung ist für den 11. November geplant, Gesetz ist das noch lange nicht.", "zusammenfassung": "Die französische Fachpublikation Contexte hat einen mutmaßlichen Entwurf des Digital Fairness Act veröffentlicht, Eurogamer berichtet darüber. Die EU-Kommission will den Vorschlag laut Eurogamer am 11. November offiziell vorstellen. Der Entwurf zielt auf unfaire Praktiken im Digitalen, darunter Monetarisierung in Spielen. Lootboxen, also Belohnungen mit Zufallsinhalt, sollen alle Spieler abschalten können; für Minderjährige sollen sie standardmäßig aus sein. Für Kinder sollen Pay-to-Progress- und Pay-to-Win-Mechaniken nicht angeboten werden, wenn ein Produkt sich an sie richtet oder der Anbieter weiß, dass Minderjährige es nutzen. Bei virtuellen Währungen soll der echte Preis von Käufen transparent werden, dazu Gewinnwahrscheinlichkeiten bei Lootboxen. Außerdem sieht der Text eine Pflicht zur Altersfreigabe für Spiele vor. Neben Spielen geht es um Influencer-Werbung, versteckte Preise und schwer kündbare Abos. Wichtig: Es handelt sich um einen geleakten Entwurf, der sich bis zur Vorstellung noch ändern kann. Danach folgen Verhandlungen; laut Eurogamer könnte das Gesetz Ende 2027 beschlossen und bis 2030 breit angewendet werden.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/digital-fairness-act-eu-europe-loot-boxes-regulation"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "mittel-hoch", "begruendung": "Dokument von der französischen Fachpublikation Contexte veröffentlicht und von Eurogamer (hoch) berichtet; Echtheit nicht offiziell bestätigt, offizielle Vorstellung am 11.11. angekündigt."}, "ursprungsquelle": "Contexte (via Video Games Industry Memo)", "tags": ["Digital Fairness Act", "EU", "Lootboxen", "Pay-to-Win", "Jugendschutz"], "archiviert_am": "2026-11-18T17:57:07.740Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.157Z"}, "id": "2026-11-10-asrock-vbios-tool-1-0-6", "datum": "2026-11-10T15:24:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Radeon"], "kategorie": "Grafikkarten", "titel": "ASRock veröffentlicht VBIOS-Flash-Tool 1.0.6 für RX 7900 XT/XTX, nachdem Version 1.0.5 Karten unbrauchbar gemacht hatte", "schlagzeile": "Nach gebrickten RX 7900 XTX: ASRock bringt neues BIOS-Tool – ohne Erklärung", "kurz": "ASRock hat das Flash-Werkzeug ASRVBFlash 1.0.6 für Radeon RX 7900 XT und XTX veröffentlicht. Die Vorversion 1.0.5 hatte laut Nutzerberichten Karten nach dem Update lahmgelegt. Was sich geändert hat und was die Ursache war, sagt ASRock nicht.", "zusammenfassung": "Anfang November häuften sich Berichte, dass Radeon RX 7900 XT und XTX von ASRock nach einem offiziellen VBIOS-Update nicht mehr starteten. Betroffen war das Flash-Werkzeug ASRVBFlash 1.0.5: Nach dem Neustart bootete das System nicht mehr. ASRock zog die Version danach offenbar von den Download-Seiten zurück. Jetzt ist still und leise Version 1.0.6 erschienen, die laut TechPowerUp das Bricking verhindern und das Firmware-Update für mehr Sicherheit korrekt aufspielen soll. Ein Änderungsprotokoll oder eine Erklärung der Ursache gibt es nicht, kritisiert auch PCGH. Unklar bleibt, wie ASRock mit bereits defekten Karten umgeht. Ein Kunde in Japan bekam laut TechPowerUp die Auskunft, dass ein durch das offizielle Update zerstörtes Modell unter die Garantie fällt. Einem Kunden in Europa wurde dagegen gesagt, dass das Abnehmen des Kühlers zum Neu-Flashen des BIOS-Chips die Garantie kostet. Betroffene sollten daher den RMA-Weg gehen statt selbst zu basteln. Wer noch nicht aktualisiert hat, kann auch erst Erfahrungen anderer Nutzer mit 1.0.6 abwarten.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354643/asrock-updates-vbios-flashing-utility-following-radeon-rx-7900-xt-xtx-bricking-reports"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Radeon-RX-7900-XTX-Grafikkarte-279267/News/Asrock-neues-vBios-Update-Ausfaelle-1559494/"}, {"name": "Wccftech", "url": "https://wccftech.com/asrock-rolls-out-new-rx-7900-xtx-vbios-after-previous-update-bricked-gpus/"}], "tags": ["ASRock", "RX 7900 XTX", "RX 7900 XT", "VBIOS", "Firmware"], "archiviert_am": "2026-11-18T17:57:07.740Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.329Z"}, "id": "2026-11-10-gta6-30fps-ps5-pro", "datum": "2026-11-10T15:14:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Rockstar bestätigt: GTA 6 zielt auf allen Konsolen auf 30 fps, PS5 Pro bekommt PSSR und exklusive Raytracing-Schatten", "schlagzeile": "GTA 6 läuft mit 30 fps – auch auf der PS5 Pro, aber mit Raytracing-Schatten", "kurz": "Rockstar hat bestätigt, dass GTA 6 auf allen Konsolen 30 Bilder pro Sekunde anpeilt, auch auf der PS5 Pro. Die Pro bekommt dafür schärfere Bilder per PSSR und exklusive Raytracing-Schatten. Der Preload läuft seit heute, Start ist am 19. November.", "zusammenfassung": "Zum Start des Preloads hat Rockstar Games erstmals offiziell die Technik von GTA 6 auf Konsolen erklärt. Das Spiel sei von Grund auf für die aktuelle Konsolengeneration entwickelt und ziele auf 30 Bilder pro Sekunde, während es beide Plattformen „an ihre absoluten Grenzen“ bringe. Das gilt laut Rockstar für PS5, PS5 Pro, Xbox Series X und Series S. Einen 60-fps-Modus erwähnt Rockstar nicht. Die PS5 Pro bekommt ein schärferes Bild über Sonys KI-Upscaling PSSR und Raytracing-Schatten, die es nur dort gibt. Auf der PS5 nutzt GTA 6 die Haptik, die adaptiven Trigger und den Lautsprecher des DualSense, dazu Tempest-3D-Audio; Rockstar und Sony sagen, das Spiel spiele sich am besten auf PS5. Remote Play wird auf PlayStation und Xbox unterstützt. Über Xbox Cloud Gaming lässt sich das Spiel auf Xbox-Konsolen streamen, mit den Grafikeinstellungen der Series S, aber nicht auf PC. Eine PC-Version hat Rockstar weiter nicht angekündigt. Der Download braucht je nach Konsole bis zu 212 GB. Zusätzlich gibt es einen neuen Preload-Trailer mit knapp 30 Sekunden neuen Szenen.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/rockstar-confirms-gta-6-targets-30-fps-with-ps5-pro-exclusive-ray-tracing/"}, "weitere_links": [{"name": "PlayStation.Blog", "url": "https://blog.playstation.com/2026/11/10/pre-load-grand-theft-auto-vi-on-ps5-starting-today/"}, {"name": "Eurogamer", "url": "https://www.eurogamer.net/gta-6-xbox-cloud-streaming-pc-xbox-one"}, {"name": "Rockstar Games auf X", "url": "https://x.com/RockstarGames/status/2120154484244381738"}], "tags": ["GTA 6", "Rockstar", "PS5 Pro", "PSSR", "30 fps"], "archiviert_am": "2026-11-18T17:57:07.740Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.586Z"}, "id": "2026-11-10-steam-deck-framerate-daten", "datum": "2026-11-10T14:53:00+01:00", "label": "News", "bereich": "games", "themen": ["Steam", "Steam Deck"], "kategorie": "Spiele-Stores", "titel": "Steam zeigt auf Shop-Seiten jetzt durchschnittliche Framerates von Spielern auf dem Steam Deck", "schlagzeile": "Steam zeigt jetzt echte Fps-Werte – wie gut läuft ein Spiel auf dem Deck?", "kurz": "Valve zeigt in Steam jetzt bei vielen Spielen die durchschnittliche Framerate auf dem Steam Deck an. Die Werte stammen von Spielern, die der Datenübermittlung zugestimmt haben. Später sollen weitere Geräte dazukommen.", "zusammenfassung": "Valve hat Steam um eine neue Leistungsanzeige erweitert. Im Bereich zur Steam-Deck-Kompatibilität einer Shop-Seite steht nach einem Klick auf „Mehr erfahren“ jetzt die durchschnittliche Framerate auf dem Steam Deck. Ein Histogramm zeigt zusätzlich, wie oft welche Framerate gemessen wurde, damit sieht man auch Schwankungen. Die Daten kommen von Spielern, die der Übermittlung von Framerate-Daten zugestimmt haben. Angezeigt wird der Wert bei Spielen, die Valve auf Deck-Kompatibilität geprüft hat, also mit den Einstufungen Verifiziert, Spielbar oder Nicht unterstützt. Valve begründet das damit, dass die bisherige Einstufung auf festen Testkriterien beruht und nicht jedem Anspruch an flüssiges Spielen entspricht. Ein „Nicht unterstütztes“ Spiel kann für manche trotzdem gut spielbar sein, ein verifiziertes Spiel dagegen niedrige Fps haben. Laut Valve soll die Funktion künftig auf weitere Geräte ausgeweitet werden. Ob dazu auch normale Desktop-PCs mit ihren vielen Hardware-Kombinationen gehören, ist offen.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/steam-deck-framerate-average-data-store-widget"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/handheld-gaming-pcs/steam-now-lets-you-see-exactly-what-frame-rate-you-should-get-in-games-using-a-steam-deck/"}, {"name": "GamingOnLinux", "url": "https://www.gamingonlinux.com/2026/11/valve-now-provide-steam-deck-framerate-data-to-the-public-for-each-game/"}], "tags": ["Steam", "Steam Deck", "Valve", "Framerate"], "archiviert_am": "2026-11-18T17:57:07.740Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.078Z"}, "id": "2026-11-10-msi-rtx50-preise-china", "datum": "2026-11-10T14:19:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["GPU", "Preise"], "kategorie": "Grafikkarten", "titel": "Bericht aus China: MSI soll Händlerpreise für RTX-50-Karten im November stark anheben, RTX 5080 um bis zu 8.000 Yuan", "schlagzeile": "Leak: MSI soll RTX 5080 in China um bis zu 8.000 Yuan verteuern", "kurz": "Laut dem chinesischen Branchenkanal ChannelGate hebt MSI im November die Händlerpreise aller RTX-50-Karten an. Bei der RTX 5080 soll das Plus 1.300 bis 8.000 Yuan betragen, umgerechnet rund 190 bis 1.200 US-Dollar. Es geht um Distributorpreise in China, nicht um offizielle Endkundenpreise. MSI hat das nicht bestätigt.", "zusammenfassung": "Der chinesische Branchenkanal ChannelGate (Board Channels) berichtet über neue Preislisten von MSI für den November. Demnach steigen die Distributorpreise aller RTX-50-Modelle in China gegenüber Oktober. Für die RTX-5080-Serie werden 1.300 bis 8.000 Yuan mehr genannt, für die RTX 5070 Ti 800 bis 4.000 Yuan und für die RTX 5070 500 bis 1.000 Yuan. Die RTX 5060 Ti soll je nach Speicher 200 bis 400 Yuan zulegen, die RTX 5060 200 bis 500 Yuan und selbst die RTX 3050 100 Yuan. Wccftech rechnet den Höchstwert bei der RTX 5080 auf rund 1.200 US-Dollar um. Wichtig: Der Höchstwert gilt nur für einzelne Modelle, und es handelt sich um Preise für Händler in China, nicht um eine weltweite neue UVP. Ob und wie stark sich das in Europa auswirkt, ist offen. Die Meldung reiht sich in frühere ChannelGate-Berichte über Preiserhöhungen anderer Boardpartner ein. Grund sollen vor allem die stark gestiegenen Speicherpreise sein. MSI selbst hat sich nicht geäußert, daher bleibt es ein unbestätigter Bericht.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/msi-planned-rtx-5080-price-hike-of-up-to-1200/"}, "weitere_links": [{"name": "IT之家 (ChannelGate)", "url": "https://www.ithome.com/1/024/745.htm"}, {"name": "TechRadar", "url": "https://www.techradar.com/computing/gpu/nvidia-rtx-5080-to-cost-usd3-000-and-the-rtx-5070-ti-at-usd2-000-rumored-gpu-price-hikes-could-be-the-finishing-blow-for-high-end-pc-gaming-in-the-ram-crisis"}], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "ChannelGate (Board Channels) ist eine bekannte, aber nicht immer treffsichere Lieferketten-Quelle; von IT之家 und Wccftech übernommen, von MSI unbestätigt."}, "ursprungsquelle": "ChannelGate / Board Channels (WeChat), via harukaze5719", "tags": ["MSI", "RTX 5080", "RTX 5070 Ti", "Preise", "China"], "archiviert_am": "2026-11-18T17:57:07.741Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.759Z"}, "id": "2026-11-10-arc-raiders-17-mio", "datum": "2026-11-10T13:28:00+01:00", "label": "News", "bereich": "games", "themen": ["Arc Raiders"], "kategorie": "Spielebranche", "titel": "Nexon: Arc Raiders hat nach einem Jahr über 17 Millionen Mal verkauft, Umsatz soll im vierten Quartal sinken", "schlagzeile": "Arc Raiders knackt 17 Millionen – doch der Verkauf wird langsamer", "kurz": "Der Extraction-Shooter Arc Raiders hat laut Publisher Nexon zum ersten Geburtstag mehr als 17 Millionen Exemplare verkauft. Im dritten Quartal kam aber nur noch eine Million dazu. Nexon erwartet für das vierte Quartal weniger Umsatz als zum Start vor einem Jahr.", "zusammenfassung": "Nexon hat in seinem Quartalsbericht neue Zahlen zu Arc Raiders von Embark Studios genannt. Der Extraction-Shooter ist Ende Oktober 2025 erschienen und hat inzwischen mehr als 17 Millionen Exemplare verkauft. Im dritten Quartal 2026 kam laut Nexon aber nur noch rund eine Million dazu, der Verkauf hat sich also deutlich verlangsamt. Für das vierte Quartal erwartet Nexon weniger Umsatz mit dem Spiel als im Vorjahresquartal, als der erfolgreiche Start in die Bilanz fiel. Im Vergleich zum Vorquartal soll der Umsatz etwa gleich bleiben. Der Umsatz lag laut Nexon im Rahmen der Prognose, das Update Frozen Trail habe frühere Spieler zurückgeholt und neue gewonnen. Arc Raiders bleibt einer der wichtigsten Titel von Nexon und war der Hauptgrund für das Umsatzplus in den ersten neun Monaten des Jahres. Offen ist, ob ein eigener PvE-Modus dauerhaft kommt; in China gibt es ihn bereits.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/arc-raiders-17-million-sales-nexon-decline"}, "weitere_links": [], "tags": ["Arc Raiders", "Nexon", "Embark Studios", "Verkaufszahlen"], "archiviert_am": "2026-11-18T17:57:07.741Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T18:28:32.235Z"}, "id": "2026-11-10-nvidia-fbi-sammelklagen", "datum": "2026-11-10T09:48:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "Spionageverdacht im Umfeld von NVIDIA-Chef Huang: Laut Trump prüft das FBI den Fall, Anwaltskanzleien werben für Anlegerklagen", "schlagzeile": "Spionage-Affäre um NVIDIA: FBI prüft den Fall, Anleger-Klagen drohen", "kurz": "Im Fall der mutmaßlichen chinesischen Spionin im Umfeld von NVIDIA-Chef Jensen Huang prüft laut US-Präsident Trump nun das FBI. Ob sich Ermittlungen auch gegen Huang richten, ist unklar. Mehrere US-Kanzleien suchen Anleger für mögliche Sammelklagen gegen NVIDIA.", "zusammenfassung": "Die Affäre um NVIDIA-Chef Jensen Huang und die mutmaßliche chinesische Spionin Alice Huang zieht weitere Kreise. Laut Spiegel und Reuters sagte US-Präsident Donald Trump, dass das FBI sich den Fall ansehe. Unklar ist, ob die Prüfung auch Jensen Huang selbst betrifft; die beiden sind trotz gleichen Nachnamens nicht verwandt. Trump nahm Huang in Schutz und sagte sinngemäß, er glaube ihm, dass er nichts von einer Spionagetätigkeit gewusst habe. Huang hatte die Beziehung zuvor eingeräumt und sich öffentlich entschuldigt, NVIDIAs Board hat eine Untersuchung mit externen Fachleuten gestartet. Laut PC Gamer werben mehrere US-Anwaltskanzleien, darunter Rosen Law Firm, um Anleger für mögliche Klagen wegen irreführender Aussagen. In San José wurde laut Guardian bereits eine Klage eingereicht, die NVIDIA und Huang vorwirft, ein mögliches Sicherheitsrisiko verschwiegen zu haben. Der Arbeitgeber von Alice Huang, Megaspeed, steht im Verdacht, NVIDIA-Chips unerlaubt nach China gebracht zu haben; NVIDIA und Megaspeed hatten das früher zurückgewiesen. Am 18. November soll Huang laut PC Gamer hinter verschlossenen Türen vor Kongressausschüssen aussagen. Alle Vorwürfe sind bisher nicht gerichtlich geklärt.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/jensen-huang-fbi-ermittelt-zum-spionageverdacht-bei-nvidia-2611-215024.html"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/law-firms-lining-up-for-a-chance-to-bop-nvidias-nose-on-behalf-of-its-own-shareholders-president-trump-says-fbi-are-sniffing-around-the-case/"}], "tags": ["NVIDIA", "Jensen Huang", "FBI", "Megaspeed", "Klage"], "archiviert_am": "2026-11-18T17:57:07.741Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:26.034Z"}, "id": "2026-11-10-chrome-zero-day", "datum": "2026-11-10T08:25:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit"], "kategorie": "Sicherheitslücke", "titel": "Chrome 157 schließt neun Lücken, darunter die aktiv ausgenutzte CVE-2026-125350", "schlagzeile": "Chrome-Lücke wird schon angegriffen – jetzt auf Version 157 updaten", "kurz": "Google hat ein Chrome-Update mit neun Sicherheits-Fixes veröffentlicht. Eine Lücke im XML-Teil des Browsers wird bereits aktiv ausgenutzt. Sichere Versionen sind 157.0.8103.50/.51 für Windows und Mac und 157.0.8103.50 für Linux.", "zusammenfassung": "Google hat für Chrome ein Sicherheitsupdate veröffentlicht, das neun Lücken schließt, berichtet Golem. Mindestens eine davon wird laut Google bereits aktiv ausgenutzt: CVE-2026-125350. Dabei handelt es sich um einen Use-after-free-Fehler in der Komponente, die XML-Daten verarbeitet; der Schweregrad gilt als hoch, einen CVSS-Wert nennt Google noch nicht. Wie und gegen wen die Lücke ausgenutzt wird, sagt Google nicht. Auch ob Nutzer dafür etwas anklicken müssen, ist unklar. Sechs der übrigen acht Lücken gelten als hoch, zwei als mittel; betroffen sind unter anderem die JavaScript-Engine V8, WebGL sowie Schnittstellen zur GPU und zum Dateisystem. Technische Details hält Google wie üblich zurück, bis die meisten Nutzer aktualisiert haben. Sichere Versionen sind 157.0.8103.50/.51 für Windows und macOS und 157.0.8103.50 für Linux. Andere Chromium-Browser wie Edge, Vivaldi oder Brave dürften ebenfalls betroffen sein und in den nächsten Tagen Updates bekommen. Tipp: Unter Hilfe › Über Google Chrome startet die Update-Prüfung, danach den Browser neu starten.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/dringend-patchen-attackierte-chrome-luecke-gefaehrdet-unzaehlige-nutzer-2611-215019.html"}, "weitere_links": [], "tags": ["Chrome", "Google", "Zero-Day", "CVE-2026-125350", "Sicherheitslücke"], "archiviert_am": "2026-11-18T17:57:07.741Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:25.811Z"}, "id": "2026-11-10-switch-eshop-geschenke", "datum": "2026-11-10T03:00:00+01:00", "label": "News", "bereich": "games", "themen": ["Nintendo"], "kategorie": "Konsolen-Update", "titel": "Switch-Systemupdate 23.5.0 bereitet Geschenkfunktion im Nintendo eShop für Familiengruppen vor", "schlagzeile": "Switch und Switch 2: Spiele verschenken klappt bald – aber nur in der Familie", "kurz": "Mit Systemupdate 23.5.0 bereitet Nintendo das Verschenken von eShop-Spielen vor. Aktiv wird die Funktion mit einem eShop-Update Mitte November. Geschenke gehen nur an Mitglieder der eigenen Familiengruppe.", "zusammenfassung": "Nintendo hat für Switch 2 und die erste Switch das Systemupdate 23.5.0 veröffentlicht. Es bereitet eine neue Funktion vor: Digitale Spiele, DLC und Upgrade-Pakete aus dem eShop lassen sich bald an andere verschenken. Die Einschränkung: Empfänger müssen Mitglied der eigenen Familiengruppe im Nintendo Account sein, die bis zu acht Mitglieder hat. Laut Nintendo können betreute Kinderkonten keine Geschenke senden, einige Produkte sind ausgenommen und die Zahl der Geschenkkäufe pro Zeitraum ist begrenzt; genaue Grenzen nennt Nintendo nicht. Beim Kauf setzt man auf der Produktseite den Haken „Als Geschenk kaufen“, wählt Empfänger und dessen Konsole und bezahlt wie gewohnt. Das Geschenk landet sofort im HOME-Menü des Empfängers. Freigeschaltet wird die Funktion erst mit einem eShop-Update: Die Patch Notes nennen den 17. November, Nintendo of America schreibt vom 16. November, vermutlich wegen der Zeitzone. Auf der Switch 2 lassen sich mit 23.5.0 außerdem Bedienungshilfen schon bei der Ersteinrichtung einstellen. Wer Spiele an Freunde außerhalb der Familiengruppe verschenken will, muss weiterhin zu eShop-Guthabenkarten greifen.", "quelle": {"name": "Nintendo", "url": "https://www.nintendo.com/us/whatsnew/coming-soon-gift-digital-games-to-family-group-members/"}, "weitere_links": [{"name": "VGChartz (Patch Notes)", "url": "https://www.vgchartz.com/article/469606/switch-2-and-switch-update-to-add-eshop-gifting-for-family-group-members/"}, {"name": "Nintendo of America auf X (Hinweis)", "url": "https://x.com/NintendoAmerica/status/2119973318572847152"}], "tags": ["Nintendo", "Switch 2", "Switch", "eShop", "Systemupdate"], "archiviert_am": "2026-11-18T17:57:07.741Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:26.118Z"}, "id": "2026-11-10-mesa-26-3", "datum": "2026-11-10T01:19:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Treiber"], "kategorie": "Treiber", "titel": "Mesa 26.3 erschienen: AMD Anti-Lag für RADV, Nova-Lake-Grafik standardmäßig aktiv, Vulkan Video für NVK", "schlagzeile": "Linux-Grafiktreiber Mesa 26.3: Anti-Lag für Radeon und mehr Vulkan", "kurz": "Die freie Grafiktreiber-Sammlung Mesa 26.3 ist da. Radeon-Nutzer bekommen über RADV die Vulkan-Erweiterung für AMD Anti-Lag, Intel-Nova-Lake-Grafik ist nicht mehr experimentell. Dazu kommen Vulkan Video für den NVIDIA-Treiber NVK und viele Vulkan-Verbesserungen.", "zusammenfassung": "Mesa 26.3 ist erschienen, das vierte große Release des Jahres der freien OpenGL- und Vulkan-Treiber für Linux, berichten Phoronix und 9to5Linux. Für Gamer mit Radeon-Karte ist die wichtigste Neuerung VK_AMD_anti_lag im Vulkan-Treiber RADV, die Vulkan-Schnittstelle für AMDs Anti-Lag zur Senkung der Eingabelatenz. RADV bringt außerdem Verbesserungen für frühe GCN-GPUs und Unterstützung für GFX1171. Bei Intel ist die Grafik von Nova Lake jetzt standardmäßig aktiv und nicht mehr experimentell, der neue Shader-Compiler Jay ist eingeschaltet. Intel aktiviert zudem Pufferkomprimierung, die laut Phoronix die Spieleleistung mit DXVK verbessern soll, also bei Windows-Spielen über Proton. Der freie NVIDIA-Treiber NVK bekommt Vulkan Video für Videobeschleunigung. Dazu kommen viele neue Vulkan-Erweiterungen für Arm-Mali-, PowerVR- und weitere Treiber. Mesa 26.3 steht auf FreeDesktop.org bereit; in den meisten Distributionen kommt es mit den nächsten Paket-Updates. Wie viel Anti-Lag in einzelnen Spielen bringt, hängt davon ab, ob das Spiel bzw. die Übersetzungsschicht es nutzt; Messwerte liegen noch nicht vor.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Mesa-26.3-Released"}, "weitere_links": [{"name": "9to5Linux", "url": "https://9to5linux.com/mesa-26-3-open-source-graphics-stack-officially-released-heres-whats-new"}], "tags": ["Mesa", "Linux", "RADV", "Vulkan", "AMD", "Intel", "NVK"], "archiviert_am": "2026-11-18T17:57:07.741Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:25.722Z"}, "id": "2026-11-10-take-two-ki-decompiling", "datum": "2026-11-10T00:18:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Branche", "titel": "Take-Two verstärkt technische und rechtliche Abwehr gegen KI-gestütztes Reverse Engineering von GTA 6", "schlagzeile": "Inoffizieller GTA-6-PC-Port per KI? Take-Two rüstet technisch und juristisch auf", "kurz": "Take-Two-Chef Strauss Zelnick nimmt KI-gestütztes Decompiling ernst und will technische Schutzmaßnahmen und rechtliche Schritte verstärken. Hintergrund ist die Sorge, GTA 6 könnte inoffiziell auf dem PC auftauchen. Zu einer offiziellen PC-Version oder einer Disc sagt Take-Two nichts, das komme von Rockstar.", "zusammenfassung": "Vor dem Start von GTA 6 am 19. November wächst die Sorge, KI-Werkzeuge könnten Konsolenspiele schneller dekompilieren und als inoffizielle PC-Ports verbreiten. IGN hat Take-Two-CEO Strauss Zelnick dazu im Interview und in der Investoren-Fragerunde befragt. Zelnick sagt, die Branche sei wegen Dateigrößen, Komplexität und Server-Anbindung lange weitgehend von Piraterie verschont geblieben, das werde aber schwieriger. Take-Two konzentriere sich deshalb darauf, die technischen Abwehrmaßnahmen und die rechtlichen Aktivitäten zu verstärken. Er erwartet, dass Piraterie das Geschäft „mehr oder weniger“ treffen werde, hält das aber für beherrschbar und sieht es nicht als finanzielle Bedrohung. Laut IGN hängt ein Teil der Sorge an der PS5-Sicherheit: Die Homebrew-Szene arbeitet an Jailbreaks für neuere Firmware, und GTA 6 soll eine aktuelle Firmware voraussetzen. Wann GTA 6 offiziell auf den PC kommt, ließ Zelnick offen. Laut Insider Gaming (mit Bezug auf Variety) verwies er darauf, dass solche Informationen immer vom Label kommen, also von Rockstar; das gilt auch für eine mögliche Disc-Version. Zum Start erscheint GTA 6 nur für PS5 und Xbox Series X|S. Ein früherer Rockstar-North-Techniker spekulierte zuletzt, Rockstar könnte einen PC-Port deshalb vorziehen, das ist aber nicht bestätigt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/take-two-enhancing-technical-defenses-and-legal-activities-to-combat-gta-6-ai-reverse-engineering-threat"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/gta-6-disc-and-pc-version-update-come-rockstar-take-two/"}], "tags": ["GTA 6", "Take-Two", "KI", "Piraterie", "PC-Version", "PS5"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:26.202Z"}, "id": "2026-11-10-sega-newsletter-leak", "datum": "2026-11-09T23:09:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit"], "kategorie": "Datenleck", "titel": "SEGA: Angriff auf Newsletter-Dienstleister ARARA legt rund 2,2 Millionen E-Mail-Adressen offen", "schlagzeile": "SEGA-Datenleck: 2,2 Millionen E-Mail-Adressen bei Dienstleister erbeutet", "kurz": "Bei einem Angriff auf den japanischen Newsletter-Dienstleister ARARA sind rund 2,2 Millionen E-Mail-Adressen von SEGA-Kunden abgeflossen. Namen, Passwörter und Zahlungsdaten sind laut SEGA nicht betroffen, ebenso wenig SEGA-Accounts. Kunden sollten sich vor gefälschten SEGA-Mails hüten.", "zusammenfassung": "SEGA hat am 9. November ein Datenleck bei seinem Newsletter-Dienstleister ARARA bestätigt. Betroffen sind 2.196.044 E-Mail-Adressen; bei 92.273 davon flossen zusätzlich Angaben zum Versand ab, was genau, wird noch untersucht. Laut SEGA geht es um elf Newsletter von SEGA und SEGA Fave, die zwischen Juli und Oktober 2026 verschickt wurden, etwa zu Arcade-Spielen wie CHUNITHM und maimai, zur Tokyo Game Show und zu Lotterie-Aktionen. Namen, Geburtsdaten, Adressen, Telefonnummern, Kreditkartendaten und Passwörter sind laut SEGA nicht betroffen. Auch E-Mail-Adressen aus dem SEGA Account laufen über ein anderes System und sind nicht Teil des Lecks. Ein Missbrauch der Daten ist bisher nicht bestätigt. ARARA selbst hatte Anfang November den Einbruch gemeldet; laut BleepingComputer und Infosecurity Magazine sind dort insgesamt rund 77 Millionen E-Mail-Adressen von etwa 380 Firmenkunden betroffen, offenbar über eine Schwachstelle in Webservern. SEGA hat den Versand über ARARA ausgesetzt und will Betroffene einzeln informieren. Wer SEGA-Newsletter bezogen hat, sollte bei Mails mit SEGA-Bezug besonders auf Phishing achten.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/sega-newsletter-data-breach-exposes-22-million-email-addresses/"}, "weitere_links": [{"name": "SEGA (Mitteilung, Japanisch)", "url": "https://www.sega.co.jp/release/261109_1.html"}, {"name": "Infosecurity Magazine", "url": "https://www.infosecurity-magazine.com/news/email-sega-customers-vendor-breach/"}], "tags": ["SEGA", "ARARA", "Datenleck", "Phishing"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:25.617Z"}, "id": "2026-11-10-take-two-gta6-vorbestellungen", "datum": "2026-11-09T22:42:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Geschäftszahlen", "titel": "Take-Two: GTA-6-Vorbestellungen weit über Erwartung, bis zu 3,5 Mrd. Dollar im Launch-Quartal erwartet", "schlagzeile": "GTA 6: Vorbestellungen „weit über den Erwartungen“ – Take-Two rechnet mit Rekord", "kurz": "Zehn Tage vor dem Start von GTA 6 meldet Take-Two Vorbestellungen auf „beispiellosem“ Niveau. Für das laufende Quartal erwartet der Konzern 3,35 bis 3,5 Milliarden Dollar Net Bookings. Konkrete Vorbestellzahlen nennt Take-Two weiterhin nicht.", "zusammenfassung": "Take-Two hat am 9. November seine Zahlen für das zweite Quartal des Geschäftsjahres 2027 vorgelegt, und GTA 6 stand im Mittelpunkt. Laut CEO Strauss Zelnick liegen die Vorbestellungen „weit über den Erwartungen“ und erreichen weiterhin „beispiellose“ Werte, berichten Insider Gaming, Eurogamer und PC Gamer. Für das laufende dritte Quartal, in das der Start am 19. November fällt, erwartet Take-Two Net Bookings von 3,35 bis 3,5 Milliarden Dollar. Laut PC Gamer liegt das sogar leicht unter der Analystenschätzung von 3,51 Milliarden Dollar (LSEG, via Reuters). Für das gesamte Geschäftsjahr 2027 rechnet der Konzern mit 8 bis 8,2 Milliarden Dollar. Konkrete Vorbestellzahlen nennt Take-Two weiterhin nicht, weil die Rohzahlen ohne Vergleichswerte irreführend sein könnten. Das abgelaufene Quartal lief schwächer: Die Net Bookings lagen mit 1,6 Milliarden Dollar unter den Erwartungen und 18 Prozent unter dem Vorjahr. Ein Grund ist NBA 2K27, das zwar gut startete, aber unter der Prognose blieb; Zelnick sieht die Vorfreude auf GTA 6 als Mitursache. Nebenbei nannte Take-Two neue Verkaufszahlen: GTA 5 steht bei rund 235 Millionen Exemplaren, Red Dead Redemption 2 nähert sich 90 Millionen. Die Serie GTA kommt insgesamt auf fast 480 Millionen verkaufte Einheiten.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/gta-6-presales-far-in-excess-take-two-expectations/"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/games/grand-theft-auto/take-two-expects-to-make-as-much-as-usd3-5-billion-during-the-gta-6-launch-period/"}, {"name": "Eurogamer", "url": "https://www.eurogamer.net/gta-6-preorders-tracking-take-two-earnings-call"}, {"name": "Insider Gaming (GTA 5)", "url": "https://insider-gaming.com/gta-5-sales-reach-235-million-copies-since-launch/"}, {"name": "Insider Gaming (RDR2)", "url": "https://insider-gaming.com/red-dead-redemption-2-90m-sold/"}], "tags": ["GTA 6", "Take-Two", "Rockstar", "Quartalszahlen", "NBA 2K27"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:25.907Z"}, "id": "2026-11-10-skydance-games-entlassungen", "datum": "2026-11-09T22:36:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Branche", "titel": "Skydance Games entlässt Mitarbeiter und fährt Projekte zurück – einen Monat nach der Fusion von Paramount und Warner Bros.", "schlagzeile": "Nach Mega-Fusion: Skydance Games entlässt Entwickler und stutzt Projekte", "kurz": "Skydance Games hat Stellen gestrichen und „einige Projekte zurückgefahren“. Das kommt einen Monat nach der Fusion von Paramount und Warner Bros. Discovery. Wie viele Leute betroffen sind, sagt das Unternehmen nicht.", "zusammenfassung": "Skydance Games hat Entlassungen bestätigt, berichten IGN und PC Gamer mit Bezug auf ein Statement gegenüber Variety. Man habe entschieden, einige Projekte zurückzufahren, deshalb seien Stellen betroffen; das sei kein Urteil über Talent oder Einsatz der Betroffenen. Zuerst hatten Mitarbeiter des erst im Juni gegründeten Paramount Games Studio gemeldet, dass sie gehen mussten. Zu Paramount Games gehören unter anderem Skydance Interactive und Skydance New Media. Angekündigt waren dort zuletzt Spiele wie Teenage Mutant Ninja Turtles: The Last Ronin sowie Umsetzungen von Yellowstone, Tulsa King und Lioness. Welche Projekte gekürzt werden, ist nicht bekannt. Wie viele Stellen wegfallen, nennt Skydance nicht; laut Insider Gaming sind es mindestens 30 Entwickler, vermutlich mehr. Die Kürzungen kommen rund einen Monat, nachdem die Fusion von Paramount und Warner Bros. Discovery unter dem Skydance-Dach genehmigt wurde. Was das für die Spielesparte von Warner Bros. Games bedeutet, ist noch offen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/skydance-games-confirms-layoffs-following-warner-bros-paramount-merger"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/a-month-after-paramount-acquired-warner-bros-discovery-its-merged-game-division-is-laying-people-off/"}], "tags": ["Skydance Games", "Paramount", "Warner Bros.", "Entlassungen"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:25.440Z"}, "id": "2026-11-10-rdna5-gfx13-linux", "datum": "2026-11-09T20:11:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Linux"], "kategorie": "Grafikkarten", "titel": "AMD veröffentlicht Linux-Treiberpatches für GFX13, die Grafik-IP der nächsten Generation (vermutlich RDNA 5)", "schlagzeile": "RDNA 5 kommt näher: AMD schickt erste Linux-Treiber für GFX13", "kurz": "AMD hat über 12.600 Zeilen Linux-Kerneltreiber für GFX13 veröffentlicht, die nächste Radeon-Grafikgeneration. Sehr wahrscheinlich steckt RDNA 5 dahinter. Neue Details zu Leistung oder Funktionen verraten die Patches bisher nicht.", "zusammenfassung": "AMD-Entwickler Alex Deucher hat eine Patch-Reihe veröffentlicht, die den Linux-Kerneltreiber AMDGPU für GFX13 vorbereitet, berichten Phoronix und VideoCardz. GFX13 ist AMDs nächste Grafik-IP und steht sehr wahrscheinlich für RDNA 5, offiziell bestätigt hat AMD den Namen dafür nicht. Die acht Patches umfassen mehr als 12.600 Codezeilen, ohne die üblichen großen Header-Dateien. Sie enthalten auch Unterstützung für die konkreten Varianten GFX 13.0.1 und GFX 13.0.4. Laut Phoronix verraten die Patches bisher wenig über Fähigkeiten oder neue Funktionen von RDNA 5. Für den Compiler LLVM gab es schon seit Jahresbeginn GFX13-Patches, jetzt folgt der Kerneltreiber. Phoronix erwartet die Unterstützung im Linux-Kernel 7.5. Andere Bausteine, die wohl in RDNA-5-GPUs stecken, etwa Display Core Next 6, sind bereits im Kernel. Frühe Linux-Treiber erscheinen bei AMD oft Monate vor dem Marktstart; einen Termin für RDNA-5-Grafikkarten nennt AMD nicht.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/AMDGPU-Patches-GFX13"}, "weitere_links": [{"name": "VideoCardz", "url": "https://videocardz.com/newz/amd-rdna-5-gfx13-graphics-support-arrives-in-linux-driver-patches"}], "tags": ["AMD", "RDNA 5", "GFX13", "Linux", "Radeon"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-10T11:16:25.538Z"}, "id": "2026-11-10-nvidia-megaspeed-nyt", "datum": "2026-11-09T19:15:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "NYT-Bericht: NVIDIA soll bei US-Ermittlungen gegen mutmaßlichen KI-Chip-Schmuggler Megaspeed interveniert haben", "schlagzeile": "Bericht: NVIDIA soll Ermittlungen zu Chip-Schmuggel ausgebremst haben", "kurz": "Laut New York Times wandte sich NVIDIAs Chefjustiziar 2025 direkt an das US-Handelsministerium, das gegen die Firma Megaspeed wegen mutmaßlichen Chip-Schmuggels nach China ermittelte. Die Ermittlungen gerieten ins Stocken und gingen an das Justizministerium. Es handelt sich um einen Bericht, eine Stellungnahme von NVIDIA liegt uns nicht vor.", "zusammenfassung": "Nach dem Bericht über die Untersuchung des NVIDIA-Boards rund um CEO Jensen Huang kommt neuer Druck: Die New York Times berichtet laut Wccftech über die Rolle von NVIDIA bei Ermittlungen gegen die Firma Megaspeed. Das Rechenzentrumsunternehmen aus Singapur stand im Verdacht, als Tarnfirma eingeschmuggelte NVIDIA-KI-Beschleuniger an US-Exportkontrollen vorbei nach China gebracht zu haben. Geleitet wird Megaspeed von Alice Huang, die laut US-Geheimdiensten für Peking arbeitete; es ist dieselbe Frau, mit der Jensen Huang eine Affäre eingeräumt hat. Laut Bericht wandte sich NVIDIAs Chefjustiziar Tim Teter 2025 direkt an das Bureau of Industry and Security des Handelsministeriums. Er habe sich darauf berufen, dass der Trump-Kandidat Jeff Kessler ihm diesen direkten Kontakt erlaubt habe. Mehrere Beamte sollen das als schweren Verstoß gegen übliche Abläufe gesehen haben. Die Ermittlungen gerieten danach ins Stocken und wurden an das Justizministerium abgegeben. Dass Firmenanwälte mit Behörden sprechen, ist an sich üblich; strittig ist laut Bericht die Art des Kontakts. Laut Wccftech steht Huang am 18. November eine nicht öffentliche Anhörung im US-Kongress bevor. Die Vorwürfe stammen aus Medienberichten, eine Stellungnahme von NVIDIA dazu lag uns nicht vor.", "quelle": {"name": "Wccftech (mit Bezug auf The New York Times)", "url": "https://wccftech.com/nvidia-intervened-federal-investigation-megaspeed-ai-chip-smuggling-probe/"}, "weitere_links": [], "tags": ["NVIDIA", "Megaspeed", "Exportkontrollen", "China", "Jensen Huang"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.162Z"}, "id": "2026-11-09-dark-heresy-release", "datum": "2026-11-09T17:50:00+01:00", "label": "News", "bereich": "games", "themen": ["Warhammer 40k", "RPG"], "kategorie": "Release-Termin", "titel": "Warhammer 40,000: Dark Heresy von Owlcat erscheint am 28. Januar 2027 für PC, PS5 und Xbox Series", "schlagzeile": "Warhammer 40k: Dark Heresy hat einen Termin – Start am 28. Januar 2027", "kurz": "Owlcat Games hat den Release-Termin für Warhammer 40,000: Dark Heresy genannt. Das Taktik-Rollenspiel erscheint am 28.01.2027 für PC, PS5 und Xbox Series X/S, eine Switch-2-Version folgt später. Man spielt einen Inquisitor, der Ketzer jagt.", "zusammenfassung": "Owlcat Games hat per Pressemitteilung und Trailer den Release-Termin seines Taktik-Rollenspiels Warhammer 40,000: Dark Heresy bekanntgegeben, berichten Eurogamer und GameStar. Das Spiel erscheint am 28. Januar 2027 für PC, PlayStation 5 und Xbox Series X/S. Für die Switch 2 soll ein Termin „zu einem späteren Zeitpunkt“ folgen. Dark Heresy baut auf Warhammer 40,000: Rogue Trader auf, das Owlcat vor einigen Jahren veröffentlicht hat. Diesmal spielt man einen Inquisitor, der im 41. Jahrtausend Ketzer und dunkle Einflüsse aufspürt. Laut Eurogamer hat Owlcat viele der zugrunde liegenden Systeme überarbeitet. Bereits seit einiger Zeit läuft eine Beta mit dem kompletten ersten Akt, die Käufer der Founders Edition spielen können. Diese Beta wird am 7. Januar abgeschaltet, während Owlcat das Spiel für den Start vorbereitet. Eurogamer erinnert daran, dass Rogue Trader zwar für Setting und Kämpfe gelobt wurde, zum Start aber mit Bugs und schwacher Performance zu kämpfen hatte. Wie gut Dark Heresy zum Release läuft, muss sich also erst zeigen. Parallel arbeitet Owlcat an einem Rollenspiel zur Science-Fiction-Reihe The Expanse.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/warhammer-40k-dark-heresy-owlcat-crpg"}, "weitere_links": [{"name": "GameStar", "url": "https://www.gamestar.de/news/"}], "tags": ["Warhammer 40k", "Dark Heresy", "Owlcat", "Rollenspiel", "Release"], "archiviert_am": "2026-11-18T17:57:07.742Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:43.937Z"}, "id": "2026-11-09-ps-portal-speicher-japan", "datum": "2026-11-09T17:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["PlayStation", "Konsole"], "kategorie": "Konsole", "titel": "Sony bringt in Japan ein neues PlayStation-Portal-Modell mit internem Speicher für künftige Funktionen", "schlagzeile": "Neues PS Portal mit eigenem Speicher – Sony deutet mehr Funktionen an", "kurz": "Sony bringt in Japan am 10.12.2026 ein neues Modell des PlayStation Portal mit internem Speicher. Laut Sony Japan ist der Speicher für künftige Funktionen gedacht, Details folgen später. Der Preis bleibt bei 39.980 Yen, Vorbestellungen starten am 13.11.2026, und ob das Modell auch nach Europa kommt, ist offen.", "zusammenfassung": "Sony veröffentlicht in Japan ein überarbeitetes Modell des PlayStation Portal, berichtet IGN unter Berufung auf den offiziellen Blog von Sony Japan. Der wichtigste Unterschied zum bisherigen Gerät ist ein interner Speicher. Sony schreibt, man habe den Speicher mit Blick auf künftige Funktionen eingebaut und werde Details nennen, sobald diese feststehen. Welche Funktionen das sein sollen, sagt Sony noch nicht. Gleichzeitig ändert Sony in Japan den offiziellen Namen von „PlayStation Portal Remote Player“ zu „PlayStation Portal Player“. Sony betont im Blog außerdem, dass auch Spieler ohne PS5 mit dem Portal PS5-Spiele spielen können; das bezieht sich auf das Cloud-Streaming für PS-Plus-Premium-Mitglieder, das Sony im vergangenen Jahr eingeführt hat. IGN wertet Speicher und Namenswechsel als möglichen Schritt weg vom reinen Remote-Play-Zubehör hin zu einem eigenständigeren Handheld; das ist eine Einschätzung, keine Ankündigung von Sony. Das neue Modell erscheint in Japan am 10. Dezember, Vorbestellungen beginnen am 13. November, der Preis bleibt mit 39.980 Yen gleich. Es ist nur auf Japanisch eingestellt und braucht ein japanisches PSN-Konto. Ob und wann es in andere Regionen kommt, ist nicht bekannt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/sony-launches-new-ps-portal-model-in-japan-with-internal-storage-for-future-functionality-changes-official-name"}, "weitere_links": [], "tags": ["PlayStation Portal", "Sony", "Handheld", "PS5", "Japan"], "archiviert_am": "2026-11-18T17:57:07.743Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.319Z"}, "id": "2026-11-09-sshole-angriffe", "datum": "2026-11-09T17:04:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit"], "kategorie": "Sicherheitslücke", "titel": "OpenSSH-Lücke „SSHole“ (CVE-2026-123158) wird aktiv angegriffen, Angreifer erlangen Root auf Alpine-Systemen", "schlagzeile": "OpenSSH-Lücke „SSHole“ wird jetzt aktiv angegriffen – Alpine-Server updaten", "kurz": "Die OpenSSH-Lücke auf musl-Systemen wie Alpine Linux, über die wir am 05.11.2026 berichtet haben, wird inzwischen aktiv ausgenutzt. Mehrere Sicherheitsfirmen melden Angriffe, in einem Honeypot erlangten Angreifer Root-Zugriff. Die Lücke heißt jetzt „SSHole“ (CVE-2026-123158); Abhilfe schafft OpenSSH 10.6p2 mit anschließendem Neustart von sshd.", "zusammenfassung": "Die OpenSSH-Lücke, über die wir am 5. November berichtet haben, wird inzwischen aktiv angegriffen, berichten BleepingComputer, SecurityWeek und The Hacker News. Sie trägt jetzt den Spitznamen „SSHole“ und die Kennung CVE-2026-123158 (CVSS 8.1). Betroffen ist OpenSSH vor Version 10.6p2 auf Linux-Systemen mit der musl-C-Bibliothek ohne PAM, etwa die Standard-Konfiguration von Alpine Linux; der Entdecker nennt auch OpenWrt, Buildroot, Yocto und viele Docker-Images als prüfenswert. Mit einem sehr langen Passwort von 257 bis 1.024 Byte können sich Angreifer bei Konten anmelden, die eigentlich gar kein Passwort akzeptieren sollen. Laut BleepingComputer begannen Angriffsversuche am 5. November, als wenige Stunden nach dem Fix ein Proof-of-Concept auftauchte. Die Firma Previdian bestätigt erfolgreichen Root-Zugriff auf einem eigenen Honeypot mit echtem Alpine Linux und zählte bis 8. November 20 Versuche von 13 IP-Adressen aus neun Ländern. GreyNoise registrierte die erste erfolgreiche Ausnutzung in freier Wildbahn am 7. November und beobachtete 16 erfolgreiche Angriffsketten: Die Angreifer erkundeten System und Container, fragten Cloud-Metadaten ab, versuchten Passwort-Hashes und Root-SSH-Schlüssel zu lesen und eigene Schlüssel für dauerhaften Zugang einzutragen. Abhilfe schafft OpenSSH 10.6p2 oder das gepatchte Paket der Distribution; Alpine hat Pakete für alle Zweige ab 3.16 veröffentlicht. Wichtig: Nach dem Update muss sshd neu gestartet werden, sonst läuft die alte Version weiter; laut watchTowr nutzen bisher vor allem Botnetze und Krypto-Miner die Lücke. Als Sofortmaßnahme hilft PasswordAuthentication no. Admins sollten zudem Logs auf unerwartete „Accepted password for“-Einträge bei Konten ohne Passwort und auf fremde SSH-Schlüssel prüfen.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/hackers-exploit-sshole-openssh-flaw-to-breach-linux-systems/"}, "weitere_links": [{"name": "SecurityWeek", "url": "https://www.securityweek.com/hackers-exploiting-sshole-authentication-bypass-in-openssh/"}, {"name": "The Hacker News", "url": "https://thehackernews.com/2026/11/hackers-exploited-openssh-sshole-flaw.html"}, {"name": "Help Net Security", "url": "https://www.helpnetsecurity.com/2026/11/06/openssh-sshole-cve-2026-123158-exploitation/"}], "tags": ["OpenSSH", "SSHole", "CVE-2026-123158", "Alpine Linux", "musl", "Sicherheitslücke"], "archiviert_am": "2026-11-18T17:57:07.743Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.090Z"}, "id": "2026-11-09-gta6-festival-miami", "datum": "2026-11-09T15:00:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Event", "titel": "Rockstar kündigt „Grand Theft Auto VI: The Festival“ am 21. November in Miami mit Travis Scott, Cardi B und Justice an", "schlagzeile": "GTA 6 bekommt ein eigenes Musikfestival – mit Travis Scott und Cardi B", "kurz": "Rockstar feiert den Start von GTA 6 mit einem Musikfestival in Miami. „Grand Theft Auto VI: The Festival“ findet am 21.11.2026 im Mana Wynwood statt, unter anderem mit Travis Scott, Cardi B, Kodak Black und Justice. Tickets werden per Lotterie vergeben, das Spiel selbst erscheint am 19.11.2026.", "zusammenfassung": "Rockstar Games hat auf X ein Musikfestival zum Launch von GTA 6 angekündigt, berichten VGC und Eurogamer. „Grand Theft Auto VI: The Festival“ findet am 21. November im Mana Wynwood in Miami statt, zwei Tage nach dem Release des Spiels am 19. November. Laut Rockstar treten Künstler aus dem Spiel und vom offiziellen Soundtrack auf. Bestätigt sind laut VGC unter anderem Travis Scott, Don Toliver, Kodak Black, Sofaygo, Cardi B, Ca7riel und Paco Amoroso, Justice, Metro Boomin, Rauw & Friends, Suero und Tainy, dazu mehrere DJ-Doppel-Sets. Tickets laufen über den Anbieter DICE und werden per Lotterie verlost. Laut Rockstar muss man sich bis Dienstag, 10. November, 16 Uhr Ostküstenzeit (22 Uhr in Österreich) für die Vorverkaufs-Lotterie anmelden; die Chance auf Tickets gibt es dann am Mittwoch um 12 Uhr Ostküstenzeit (18 Uhr bei uns). Zum Spiel erscheinen zwei Soundtracks auf CD, Vinyl und bei Streamingdiensten: „GTA 6: The Album“ mit 34 neuen Songs am 19. November, unter anderem mit Travis Scott und Keith Richards, und am 11. Dezember „Grand Theft Auto VI: Original Score“ mit 30 Stücken des französischen Elektro-Duos Justice.", "quelle": {"name": "Video Games Chronicle (VGC)", "url": "https://www.videogameschronicle.com/news/rockstar-announces-grand-theft-auto-6-music-festival-taking-place-in-miami/"}, "weitere_links": [{"name": "Rockstar Games auf X", "url": "https://x.com/RockstarGames/status/2119792290600239401"}, {"name": "Rockstar Games auf X (Ticket-Lotterie)", "url": "https://x.com/RockstarGames/status/2119792500617494877"}, {"name": "Eurogamer", "url": "https://www.eurogamer.net/rockstar-gta-6-miami-music-festival"}], "tags": ["GTA 6", "Rockstar", "Festival", "Miami", "Soundtrack", "Travis Scott"], "archiviert_am": "2026-11-18T17:57:07.743Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.465Z"}, "id": "2026-11-09-amd-ssd-fix-26-11-1", "datum": "2026-11-09T14:20:00+01:00", "label": "News", "bereich": "software", "themen": ["Treiber", "AMD"], "kategorie": "Treiber", "titel": "AMD bestätigt SSD-Dauerschreiben durch Radeon-Treiber, Fix soll mit Adrenalin 26.11.1 kommen", "schlagzeile": "Radeon-Treiber frisst SSD-Lebensdauer: Fix soll mit 26.11.1 kommen", "kurz": "Nachtrag zu unserer Meldung vom 08.11.2026: Laut TechPowerUp und PC Gamer soll der Fehler, bei dem ein Radeon-Treiberdienst ständig auf die SSD schreibt, mit Adrenalin 26.11.1 behoben werden. Betroffen sind laut TechPowerUp die Versionen 26.10.1 und 26.10.2, ein Termin für den neuen Treiber steht noch nicht fest. Nutzer berichten von etwa 1 Prozent SSD-Gesundheit weniger pro Monat.", "zusammenfassung": "Zum Radeon-Treiberfehler mit ständigen SSD-Schreibzugriffen, über den wir am 8. November berichtet haben, gibt es eine Lösung in Sicht. Laut TechPowerUp hat AMD bestätigt, dass die Treiber Adrenalin 26.10.1 und 26.10.2 betroffen sind und der Fix mit Version 26.11.1 kommen soll. PC Gamer zitiert den AMD-Vertreter AMD_Vik auf Reddit, wonach das Problem in 26.11.1 „behoben sein sollte“; ein genaues Datum gibt es nicht, der Treiber wird laut PC Gamer im Laufe des Monats erwartet. Verursacher ist der Dienst atieclxx.exe aus AMDs External Events Utility, der etwa Monitore erkennt und Hotkeys der Radeon-Software verarbeitet und offenbar in einer Endlosschleife Daten schreibt. Gemeldet werden 0,3 bis 1,5 MB/s, ein Reddit-Nutzer nennt dauerhaft 5 MB/s. Ein Nutzer auf X maß 19,5 GB Schreibzugriffe in 12 Stunden und meint, der Fehler bestehe schon seit Adrenalin 26.7.1 aus dem Juni. Auf Reddit berichten Nutzer, dass ihre SSD-Gesundheit dadurch um etwa 1 Prozent pro Monat sinke; das sind Erfahrungsberichte, keine Messung von AMD. Nicht jedes System ist betroffen, PC Gamer konnte den Fehler selbst nicht nachstellen. Als Übergangslösung nennt TechPowerUp das Abschalten der AMD External Events Utility, was aber Anzeigeprobleme verursachen kann, oder das Deaktivieren von Resizable BAR, was Leistung kosten kann. TechPowerUp rät eher, auf den offiziellen Treiber zu warten.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354605/amd-confirms-excessive-ssd-writes-in-radeon-drivers-fix-coming-with-adrenalin-26-11-1"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/amd-users-are-reporting-a-misfiring-utility-is-eating-ssd-health-by-1-percent-a-month-amd-says-a-fix-is-on-the-way-for-its-gpu-drivers/"}, {"name": "ComputerBase", "url": "https://www.computerbase.de/news/grafikkarten/schnelle-ssd-alterung-radeon-treiber-schreibt-fortwaehrend-daten-auf-die-ssd.100237/"}], "tags": ["AMD", "Radeon", "Adrenalin", "Treiber", "SSD", "atieclxx.exe"], "archiviert_am": "2026-11-18T17:57:07.743Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.019Z"}, "id": "2026-11-09-amdlss5-2-radeon", "datum": "2026-11-09T13:32:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Mod"], "kategorie": "Grafik-Mod", "titel": "Mod AMDLSS5 2.0 bringt DLSS-5-artiges Neural Rendering mit eigener Engine auf Radeon-Karten", "schlagzeile": "Mod bringt DLSS-5-Neural-Rendering auf Radeon – jetzt deutlich schneller", "kurz": "Die inoffizielle Mod AMDLSS5 ist in Version 2.0 erschienen und soll DLSS-5-artiges Neural Rendering auf Radeon-Karten bringen. Laut Entwickler läuft sie jetzt auf einer eigenen Engine und deutlich schneller als andere Mods. Die Messwerte stammen nur vom Entwickler. Die Mod hat nichts mit AMD oder NVIDIA zu tun.", "zusammenfassung": "Wccftech berichtet über Version 2.0 der Community-Mod AMDLSS5 vom Entwickler Wehaveall. Sie soll DLSS-5-artiges Neural Rendering, also KI-Verbesserungen bei Licht und Materialien, auf AMD-Radeon-Karten bringen, indem sie sich in vorhandene DirectX-12-Upscaling-Pfade einklinkt. Neu ist eine eigene Engine, die die bisherige Abhängigkeit von einer anderen Mod ersetzt und weniger Overhead haben soll. In einem Reddit-Beitrag nennt der Entwickler PresentMon-Werte aus Resident Evil Requiem in 4K mit FSR auf einer RX 9070 XT: 101,2 Fps im Schnitt und 78,5 Fps bei den 1-%-Lows, gegenüber 91,3 und 66,0 mit Version 1.6.1 und 61,6 und 55,5 mit anderen Mods. Daraus ergeben sich die beworbenen 64 Prozent mehr Fps, allerdings nur im Vergleich zu anderen Mods, nicht zum Spiel ohne Mod oder zu NVIDIAs echtem DLSS 5. Es handelt sich um Angaben des Entwicklers aus einer einzigen Szene mit einer Karte, unabhängige Tests gibt es noch nicht. Neu unterstützt werden PRAGMATA, Nioh 3 und GTA V Enhanced, Letzteres nur im Offline-Story-Modus mit deaktiviertem BattlEye. Hauptziel sind RX 9070 und RX 9070 XT; die RX-9060-Serie soll theoretisch funktionieren, RX-7000-Karten haben eine experimentelle Alpha-Unterstützung, beides hat der Entwickler laut Wccftech nicht auf echter Hardware geprüft. Dazu kommen 39 Farbvorlagen, lokales Tone Mapping, verbesserte Umgebungsverdeckung und indirektes Licht sowie überarbeitete 2x-Frame-Generation in ausgewählten Spielen. Die Mod ist kostenlos auf GitHub, der Quellcode der neuen Engine ist aber noch nicht veröffentlicht.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/amdlss5-2-0-brings-faster-dlss-5-neural-rendering-to-radeon-gpus-claims-64-higher-fps/"}, "weitere_links": [], "tags": ["AMDLSS5", "DLSS 5", "Neural Rendering", "Radeon", "RX 9070 XT", "Mod"], "archiviert_am": "2026-11-18T17:57:07.743Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:43.846Z"}, "id": "2026-11-09-amazon-us-amd-vor-nvidia", "datum": "2026-11-09T12:56:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU"], "kategorie": "Markt", "titel": "Amazon US im Oktober: AMD verkauft mehr Grafikkarten als NVIDIA, RX 9070 XT ist Bestseller", "schlagzeile": "Amazon US: AMD verkauft im Oktober mehr Grafikkarten als NVIDIA", "kurz": "Laut Verkaufszahlen von Amazon US für Oktober 2026 hat AMD knapp mehr Grafikkarten verkauft als NVIDIA: rund 9.200 gegen 8.900 Stück. Meistverkaufte Karte war die Radeon RX 9070 XT mit etwa 3.300 Einheiten. NVIDIA machte wegen höherer Durchschnittspreise weiter mehr Umsatz. Die Zahlen stammen von einem Datensammler, nicht von den Herstellern.", "zusammenfassung": "Wccftech berichtet über Amazon-US-Verkaufszahlen für Oktober 2026, die der Datensammler TechEpiphany zusammengetragen hat. Demnach hat AMD dort im Oktober knapp die meisten Grafikkarten verkauft: rund 9.200 Stück gegenüber etwa 8.900 bei NVIDIA. Das ist laut Wccftech bemerkenswert, weil Amazon US sonst meist von NVIDIA dominiert wird, während AMD etwa in Deutschland häufiger vorne liegt. Beim Umsatz bleibt NVIDIA vorne, denn der durchschnittliche Verkaufspreis lag bei NVIDIA bei 1.313 Dollar und bei AMD bei 915 Dollar. Bestseller war die Radeon RX 9070 XT mit etwa 3.300 Einheiten; die RTX 5070 Ti kam nur auf rund ein Drittel davon. Auf Platz zwei landete die RTX 5060 Ti (8 und 16 GB zusammen) mit etwa 2.250 Stück, dahinter die RX 9060 XT mit rund 2.150. Die RTX 5070 blieb unter 2.000 Einheiten, die RTX 5090 kam wegen schlechter Verfügbarkeit nur auf etwa 150. Selbst die alte Arc A380 verkaufte sich mit rund 500 Stück häufiger. Intel kam laut den Daten auf etwa 6,22 Prozent Anteil, getragen von Arc B570, B580 und Arc-Pro-Karten. Wccftech sieht die stark gestiegenen Preise als Hauptgrund dafür, dass Käufer zu günstigeren Karten greifen. Wichtig: Die Zahlen bilden nur einen Shop in den USA ab und stammen nicht von AMD, NVIDIA oder Amazon selbst; sie sind daher nur ein Stimmungsbild und keine Marktanteile für den Gesamtmarkt.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/amd-leads-nvidia-in-gpu-sales-capturing-47-share-according-to-amazon-us-october-data/"}, "weitere_links": [], "tags": ["AMD", "NVIDIA", "Intel", "RX 9070 XT", "Amazon", "GPU-Verkäufe"], "archiviert_am": "2026-11-18T17:57:07.744Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.244Z"}, "id": "2026-11-09-bit-reactor-entlassungen", "datum": "2026-11-09T12:41:00+01:00", "label": "News", "bereich": "games", "themen": ["Star Wars", "Studio"], "kategorie": "Branche", "titel": "Star Wars Zero Company: Entwicklerstudio Bit Reactor entlässt Mitarbeiter trotz guter Kritiken und einer Million Verkäufen", "schlagzeile": "Star Wars Zero Company: Studio entlässt Leute – trotz Hit und 84 Metascore", "kurz": "Bit Reactor, das Studio hinter Star Wars Zero Company, hat Mitarbeiter entlassen. Das berichtet VGC nach LinkedIn-Posts betroffener Entwickler. Dabei war das Spiel gut bewertet und hat laut EA eine Million Exemplare verkauft. Wie viele Stellen betroffen sind, ist offen.", "zusammenfassung": "Bit Reactor, das Entwicklerstudio von Star Wars Zero Company, hat Mitarbeiter entlassen, berichtet VGC unter Berufung auf die Seite Bespin Bulletin. Mehrere Entwickler, darunter ein Senior Environment Artist, ein UI-Engineer, ein Producer und ein Senior QA Analyst, haben in den vergangenen Tagen auf LinkedIn geschrieben, dass sie betroffen sind. Wie viele Stellen insgesamt wegfallen, ist nicht bekannt. Laut Berichten hatte das Studio vor dem Release im August rund 80 Prozent seiner Belegschaft unbezahlt freigestellt, weil das Geld knapp wurde. Im Oktober sagte Studiochef Greg Foertsch, dass ein Teil der freigestellten Leute zurückkehrt; Berichten zufolge kam das Studio damit wieder auf mehr als die Hälfte der früheren Größe. Unklar ist, ob nun auch Rückkehrer betroffen sind oder nur Leute, die nach der Freistellung nicht zurückgeholt wurden. Mindestens ein Betroffener schreibt, er sei nach drei Monaten Freistellung entlassen worden. Bitter ist das, weil Star Wars Zero Company Ende August mit sehr guten Kritiken erschien und auf Metacritic bei 84 Punkten steht. Am 9. Oktober meldete der offizielle EA-Star-Wars-Account eine Million verkaufte Einheiten. Eine offizielle Stellungnahme von Bit Reactor zu den Entlassungen nennt VGC nicht.", "quelle": {"name": "Video Games Chronicle (VGC)", "url": "https://www.videogameschronicle.com/news/star-wars-zero-company-studio-bit-reactor-is-laying-off-staff-a-month-after-it-started-bringing-back-furloughed-devs/"}, "weitere_links": [{"name": "GameStar", "url": "https://www.gamestar.de/news/"}], "tags": ["Star Wars Zero Company", "Bit Reactor", "Entlassungen", "EA"], "archiviert_am": "2026-11-18T17:57:07.744Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T18:36:44.396Z"}, "id": "2026-11-09-notepadpp-7zip-luecken", "datum": "2026-11-09T11:18:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows", "Sicherheit"], "kategorie": "Sicherheitslücke", "titel": "Notepad++ 8.9.9 schließt sechs Sicherheitslücken, 7-Zip 26.06 behebt nicht näher genannte Schwachstellen", "schlagzeile": "Notepad++ und 7-Zip: Updates stopfen Sicherheitslücken – selbst updaten", "kurz": "Notepad++ 8.9.9 schließt sechs Sicherheitslücken, die schwerste als hoch eingestuft. Auch 7-Zip 26.06 behebt laut Entwickler Schwachstellen, nennt aber keine Details. 7-Zip hat keine Update-Funktion, man muss selbst aktualisieren. Unter Windows geht das bequem mit winget.", "zusammenfassung": "Zwei weit verbreitete Windows-Werkzeuge haben Sicherheitsupdates bekommen, berichtet heise online. Notepad++ 8.9.9 von Entwickler Don Ho schließt sechs Sicherheitslücken. Am schwersten wiegt ein Heap-Pufferüberlauf im SAML-Decoder des Plugins mimeTools: Präparierte SAML-Nachrichten könnten beim Dekodieren Speicher überschreiben und möglicherweise Schadcode ausführen. Das Advisory stuft das Risiko als hoch ein, nennt aber keinen CVSS-Wert. Die übrigen fünf Lücken gelten als mittel, einige davon eignen sich laut heise wohl zur Ausweitung von Rechten im System, etwa über das UAC-Speichern geschützter Dateien oder Fenster-Nachrichten. CVE-Nummern gibt es noch nicht. Daneben beschleunigt die Version die Suche in Dateien und aktualisiert die Editor-Komponente Scintilla auf 5.6.9. Notepad++ hat eine eigene Update-Prüfung; alternativ hilft winget update Notepad++.Notepad++. Das Archivprogramm 7-Zip ist am Wochenende in Version 26.06 erschienen. Entwickler Igor Pavlov schreibt nur, dass einige Fehler und Schwachstellen behoben wurden, ohne zu sagen, welche oder wie schwer. Zusätzlich hat er die Unterstützung für Dateien verbessert, die mit dem Linux-Werkzeug split aufgeteilt wurden. Weil 7-Zip keine Update-Prüfung hat, müssen Nutzer die neue Version selbst herunterladen oder unter Windows winget upgrade 7zip.7zip verwenden. heise empfiehlt, mit winget upgrade --all gleich alle verfügbaren Updates einzuspielen.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Notepad-Update-schliesst-Rechteausweitungsluecke-und-mehr-11517053.html"}, "weitere_links": [{"name": "heise online (7-Zip)", "url": "https://www.heise.de/news/7-Zip-Update-schliesst-nicht-genannte-Sicherheitsluecken-11516845.html"}], "tags": ["Notepad++", "7-Zip", "Sicherheitslücke", "Windows", "winget", "Update"], "archiviert_am": "2026-11-18T17:57:07.744Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T10:27:13.341Z"}, "id": "2026-11-09-sonicwall-sslvpn-angriffe", "datum": "2026-11-09T08:12:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit"], "kategorie": "Sicherheitslücke", "titel": "SonicWall: Lücke im SSLVPN wird angegriffen, Firmware-Updates stopfen sieben Schwachstellen", "schlagzeile": "SonicWall-Firewalls: VPN-Lücke wird angegriffen – sofort updaten", "kurz": "Angreifer nutzen offenbar eine Lücke im SSLVPN von SonicWall-Firewalls aus, mit der sich die SAML-Anmeldung und damit die Mehr-Faktor-Authentifizierung umgehen lässt. SonicWall und die US-Behörde CISA raten zum schnellen Update. Betroffen ist das SSLVPN nur, wenn SAML für die VPN-Anmeldung aktiv ist. Die neue Firmware schließt insgesamt sieben Lücken.", "zusammenfassung": "SonicWall hat am Freitag eine Sicherheitsmitteilung zu sieben Schwachstellen in SonicOS veröffentlicht, wie heise online berichtet. Bei einer davon geht der Hersteller davon aus, dass sie möglicherweise bereits für Angriffe genutzt wurde; auch die US-Sicherheitsbehörde CISA warnt. Es handelt sich um CVE-2026-19868 (CVSS 7.1, hoch): Wer gültige Zugangsdaten für eine andere Anmeldemethode hat, kann damit die SAML-Anmeldung umgehen, die etwa für Single Sign-on genutzt wird. Damit lässt sich offenbar auch die per SAML erzwungene Mehr-Faktor-Authentifizierung aushebeln. Anfällig ist das SSLVPN laut SonicWall nur, wenn SAML für SSLVPN-Logins aktiviert ist. Abhilfe schaffen SonicOS 7.3.4-7013 für Gen7-Firewalls und 8.2.3-8015 für Gen8-Geräte sowie jeweils neuere Versionen. Die Updates schließen sechs weitere Lücken, darunter zwei mit CVSS 8.8 zu Cross-Domain-Richtlinien und Sitzungsprüfung sowie einen Heap-Pufferüberlauf im SSL-VPN, der sich ohne Anmeldung auslösen lässt (CVSS 7.5). Dazu kommen zwei Pufferüberläufe in TACACS+ und schwaches Passwort-Hashing auf virtuellen Appliances, alle mit mittlerem Risiko. heise erinnert daran, dass SonicWall bereits Anfang Oktober eine kritische Lücke mit Höchstwertung in SMA1000-Appliances gemeldet hatte. Betroffen sind vor allem Firmen und Admins; wer zu Hause oder im Büro eine SonicWall-Firewall betreut, sollte die Firmware jetzt aktualisieren.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Angriffswarnung-Luecke-in-SonicWall-SSLVPN-wird-attackiert-11516825.html"}, "weitere_links": [], "tags": ["SonicWall", "SSLVPN", "Sicherheitslücke", "CISA", "Firewall", "MFA"], "archiviert_am": "2026-11-16T07:33:23.243Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T10:27:13.407Z"}, "id": "2026-11-08-windows11-app-updates", "datum": "2026-11-08T23:49:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11 testet zentrale Seite für Updates von Drittanbieter-Apps", "schlagzeile": "Schluss mit Update-Pop-ups? Windows 11 testet zentrale App-Updates", "kurz": "In einer Vorschauversion von Windows 11 26H2 ist eine neue Seite „App-Updates“ in den Einstellungen aufgetaucht. Sie soll Updates von Drittanbieter-Programmen wie Browsern oder Mediaplayern an einem Ort sammeln, statt dass jede App eigene Hinweise zeigt. Funktionieren wird das nur, wenn Entwickler ihre Apps registrieren. Im Test von Windows Latest war noch kein einziger Anbieter angemeldet.", "zusammenfassung": "Windows Latest hat in einer Vorschauversion von Windows 11 26H2 unter Einstellungen > Apps eine Seite namens „App-Updates“ entdeckt. Die Seite war schon im Dezember 2025 kurz zu sehen und ist nun wieder aufgetaucht, was laut Windows Latest auf einen baldigen Start hindeutet. Ziel ist, Updates von Programmen außerhalb des Microsoft Store an einem Ort zu bündeln, statt dass jede App wie früher der berüchtigte Java-Updater ihre eigenen Pop-ups zeigt. Grundlage ist die „Windows Update Orchestration Platform“, die Microsoft 2025 vorgestellt hat. Entwickler können ihre Apps dort als Anbieter registrieren und behalten dabei ihre eigenen Update-Server und Installer; Windows übernimmt nur die Koordination. Unterstützt werden sollen MSIX- und APPX-Pakete sowie klassische Win32-Programme. Für die Registrierung müssen Entwickler ein Skript oder Programm liefern, das nach Updates sucht; Windows führt diese Prüfung standardmäßig alle 22 Stunden aus. Die Installation soll Windows ähnlich wie Systemupdates planen und dabei Nutzung, Akku und Netzwerk berücksichtigen, damit man nicht mitten in der Arbeit unterbrochen wird. Auf dem Testrechner von Windows Latest meldete die Seite allerdings, dass kein App-Anbieter registriert sei, nicht einmal Microsoft selbst für Teams oder Outlook, und der Knopf zur Update-Suche war ausgegraut. Es handelt sich also um eine Funktion im Test, die man noch nicht nutzen kann. Ob sie wirklich etwas bringt, hängt davon ab, wie viele Entwickler mitmachen; zwingen will Microsoft niemanden. Einen Starttermin hat Microsoft nicht genannt.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/09/for-20-years-windows-apps-like-java-have-nagged-you-with-their-own-update-pop-ups-and-windows-11-now-wants-to-end-it/"}, "weitere_links": [], "tags": ["Windows 11", "26H2", "App-Updates", "Insider", "Windows Update"], "archiviert_am": "2026-11-16T07:33:23.244Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T10:27:13.030Z"}, "id": "2026-11-08-nvidia-board-untersuchung-huang", "datum": "2026-11-08T21:48:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "NVIDIA-Verwaltungsrat startet unabhängige Untersuchung zu CEO Jensen Huang", "schlagzeile": "NVIDIA-Board startet Untersuchung – Huang gesteht Affäre", "kurz": "Der Verwaltungsrat von NVIDIA hat eine unabhängige Untersuchung eingeleitet, nachdem Medien berichtet hatten, CEO Jensen Huang sei Ziel eines ausländischen Geheimdienstes gewesen. Huang räumte in einer von NVIDIA veröffentlichten Nachricht an die Belegschaft ein, seiner Frau untreu gewesen zu sein. Laut Verwaltungsrat gibt es bisher keinen Grund zur Annahme, dass nationale Sicherheit oder Firmengeheimnisse kompromittiert wurden. Huang bleibt CEO.", "zusammenfassung": "NVIDIA hat am Abend des 8.11.2026 zwei Erklärungen veröffentlicht. In der ersten kündigt der Verwaltungsrat eine unabhängige Untersuchung an: Ein Komitee unabhängiger Direktoren soll mit Unterstützung externer Anwälte prüfen, ob Gründer und CEO Jensen Huang Ziel einer Aktivität eines ausländischen Geheimdienstes war. Der Verwaltungsrat schreibt, er habe keinen Grund zur Annahme, dass die nationale Sicherheit oder NVIDIA-Geheimnisse kompromittiert wurden, wolle aber alle verfügbaren Informationen prüfen. Huang unterstütze die Prüfung und werde kooperieren; der Verwaltungsrat spricht ihm und dem Führungsteam sein Vertrauen aus. In der zweiten Erklärung, einer Nachricht an die Belegschaft, die zuerst Axios veröffentlicht hatte, entschuldigt sich Huang bei Familie und Mitarbeitern und räumt ein, seiner Frau untreu gewesen zu sein. Hintergrund sind Berichte der Financial Times und der New York Times aus den Tagen zuvor. Demnach soll ein auf US-Geheimdienstinformationen gestütztes Memo Huang eine Beziehung zu einer Frau namens Alice Huang zuschreiben, einer früheren Führungskraft des NVIDIA-Kunden Megaspeed; US-Dienste hielten sie laut diesen Berichten für eine Informantin des chinesischen Ministeriums für Staatssicherheit. Die beiden sind trotz gleichen Nachnamens laut den Berichten nicht verwandt. Weder das Memo noch seine Grundlagen sind öffentlich, und weder Huang noch der Verwaltungsrat gehen inhaltlich auf die Spionagevorwürfe ein; Huangs Nachricht nennt Alice Huang laut Axios nicht. Die Erklärung des Verwaltungsrats bestätigt die Vorwürfe also nicht. Laut NYT soll das Ziel gewesen sein, mehr über US-KI-Chips zu erfahren. NVIDIA-Sprecher John Rizzo sagte laut ComputerBase, die Vorgänge würden die Arbeit des Unternehmens nicht bremsen. Wann Ergebnisse der Untersuchung vorliegen, ist offen; der Verwaltungsrat will bei Bedarf weiter informieren.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/nvidia-ceo-jensen-huang-raeumt-untreue-ein-verwaltungsrat-startet-untersuchung.100232/"}, "weitere_links": [{"name": "heise online", "url": "https://www.heise.de/news/Jensen-Huang-gesteht-Affaere-ein-Nvidia-beginnt-Untersuchung-11516757.html"}, {"name": "IGN", "url": "https://www.ign.com/articles/nvidia-launches-investigation-into-ceo-jensen-huang-following-affair-with-alleged-chinese-spy"}], "tags": ["NVIDIA", "Jensen Huang", "Verwaltungsrat", "Untersuchung", "China"], "archiviert_am": "2026-11-16T07:33:23.244Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T10:27:13.272Z"}, "id": "2026-11-08-layden-ps5-300", "datum": "2026-11-08T21:11:00+01:00", "label": "News", "bereich": "games", "themen": ["PS6", "PS5"], "kategorie": "Konsolen", "titel": "Ex-PlayStation-Chef Shawn Layden: Sony braucht eine PS5 für 300 statt einer PS6 für 1.200 Dollar", "schlagzeile": "Ex-PlayStation-Chef: Keine PS6 für 1.200 $ – lieber PS5 für 300 $", "kurz": "Der frühere PlayStation-Chef Shawn Layden rät Sony, statt einer teuren PS6 lieber eine deutlich günstigere PS5 zu bauen. „Die Innovation muss nicht von einer PS6 für 1.200 Dollar kommen, sondern von einer PS5 für 300 Dollar“, sagte er im Podcast The Trophy Room. Die PS5 sei die erste Plattform, die mit der Zeit teurer geworden ist. Offizielle PS6-Pläne kommentiert das nicht.", "zusammenfassung": "Shawn Layden, früher Präsident und CEO von Sony Interactive Entertainment America, hat sich im Podcast The Trophy Room zur nächsten PlayStation geäußert, wie IGN berichtet. Seiner Ansicht nach bringt eine PS6, die vor allem auf mehr Raytracing und mehr Teraflops setzt, nicht genug echte Neuerung. „Ich glaube, wir haben genug Leistung in der Maschine“, sagte Layden. Die eigentliche Innovation wäre aus seiner Sicht nicht eine PS6 für 1.200 Dollar, sondern eine weitere PS5 für 300 Dollar. Er verwies darauf, dass die PS2 am Ende ihres Lebens für 99 Dollar zu haben war, während die PS5 die erste Plattform sei, die er mit steigenden Preisen erlebt habe. Sony solle die Konsole kleiner und günstiger machen; Chip und Betriebssystem seien gut genug für die Spiele, die man spielen wolle. IGN ordnet ein: Zum Start vor sechs Jahren kostete die PS5 in den USA 499 Dollar, die Digital Edition 399 Dollar. Direkt bei PlayStation kosten heute die Standardversion 649, die Digital Edition 599 und die PS5 Pro 899 Dollar. Sony begründet die Erhöhungen mit dem schwierigen wirtschaftlichen Umfeld. Zur PS6 gibt es wenig Offizielles: Sony sagte im Mai, man entscheide noch über den Zeitpunkt, und ein Bericht vom Februar sprach von einer möglichen Verschiebung auf 2028 oder 2029. Layden ist seit Jahren nicht mehr bei Sony; seine Aussagen sind eine persönliche Meinung und keine Information über Sonys Pläne. Ein konkreter PS6-Preis ist nicht bekannt, die 1.200 Dollar sind Laydens zugespitztes Beispiel.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/former-playstation-boss-says-sony-doesnt-need-a-ps6-for-1200-it-needs-a-ps5-for-300"}, "weitere_links": [], "tags": ["PlayStation", "PS5", "PS6", "Shawn Layden", "Konsolenpreise"], "archiviert_am": "2026-11-16T07:33:23.244Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-08T19:51:10.264Z"}, "id": "2026-11-08-amd-radeon-ssd-writes", "datum": "2026-11-08T17:27:00+01:00", "label": "News", "bereich": "software", "themen": ["AMD", "GPU"], "kategorie": "Grafiktreiber", "titel": "AMD bestätigt Radeon-Treiberfehler mit dauernden SSD-Schreibzugriffen", "schlagzeile": "Radeon-Treiber schreibt im Leerlauf dauernd auf die SSD", "kurz": "Einige Nutzer von AMD-Radeon-Karten berichten, dass der Grafiktreiber auch im Leerlauf dauerhaft auf die System-SSD schreibt. Verantwortlich gemacht wird der Prozess atieclxx, also das AMD External Events Client Module. AMD hat das Problem nach Angaben von Wccftech und Neowin anerkannt und arbeitet an einem Fix; in den Hinweisen zu Adrenalin 26.10.2 vom 30.10.2026 steht er noch nicht. Nicht jedes System scheint betroffen zu sein, und wie stark das die Lebensdauer einer SSD tatsächlich verkürzt, ist nicht belegt.", "zusammenfassung": "Wccftech und Neowin berichten am 8.11.2026 über einen Fehler in AMDs Radeon-Grafiktreibern, der zu ständigen Schreibzugriffen auf die Systemfestplatte führen kann, auch wenn der Rechner sonst nichts tut. Auslöser soll der Prozess atieclxx sein, das AMD External Events Client Module, das zur AMD External Events Utility gehört und unter anderem Monitorwechsel, Hotkeys und FreeSync verwaltet. Nutzerangaben liegen häufig zwischen etwa 0,3 und 1,5 Megabyte pro Sekunde, einzelne Berichte nennen rund 5 Megabyte pro Sekunde. Hochgerechnet wären das bei ununterbrochenen 5 MB/s theoretisch etwa 432 Gigabyte Host-Schreibungen am Tag; Wccftech betont, dass das eine Obergrenze unter Dauerlast ist und nicht automatisch der Menge entspricht, die wirklich ins NAND geschrieben wird. Ob und wie stark der Fehler die Lebensdauer einer SSD verkürzt, ist den Berichten zufolge nicht belegt. Das Problem sei nicht ganz neu und tauche unter Windows 10 und Windows 11 auf verschiedenen Radeon-Karten und Adrenalin-Versionen auf; manche Rechner mit dem aktuellen Treiber 26.10.2 zeigen nach Nutzerangaben gar keine ungewöhnliche Last. Ein AMD-Mitarbeiter namens AMD_Matt habe das Verhalten im Oktober als echtes Problem bestätigt, das untersucht werde. Ein weiterer Vertreter, AMD_Vik, habe später signalisiert, dass ein Fix wahrscheinlich bereits eingereicht sei, den Termin für die nächste Treiberversion aber verpasst haben könnte. Die am 30.10.2026 erschienene Adrenalin Edition 26.10.2 erwähnt den Fehler in den offiziellen Versionshinweisen nicht. Neowin ergänzt, AMD habe den Zusammenhang mit Microsofts PCIe-Filtertreiber und Resizable BAR genannt. Als Workaround nennen beide Seiten das vorübergehende Stoppen des Dienstes AMD External Events Utility über die Windows-Diensteverwaltung oder das Abschalten von Resizable BAR; beides kann FreeSync, Adrenalin-Hotkeys oder die Spieleleistung beeinträchtigen. Einige Nutzer berichten allerdings, FreeSync und ReBAR hätten nach dem Dienststopp weiter funktioniert. Wer prüfen will, ob der eigene Rechner betroffen ist, soll im Ressourcenmonitor unter dem Reiter „Datenträger“ nach dauerhafter Schreibaktivität von atieclxx suchen. Ein Treiber-Update mit dem Fix liegt den Berichten nach noch nicht vor.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/amd-acknowledges-radeon-driver-bug-causing-constant-ssd-writes-fix-in-the-works/"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/old-amd-windows-chipset-driver-bug-that-quietly-degrades-ssds-now-back-on-gpus/"}], "tags": ["AMD", "Radeon", "Adrenalin", "SSD", "Treiber", "atieclxx"], "archiviert_am": "2026-11-15T18:31:25.943Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-08T19:51:10.344Z"}, "id": "2026-11-08-gpu-preise-plus40", "datum": "2026-11-08T12:50:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Grafikkarten"], "kategorie": "GPU & Markt", "titel": "Grafikkartenpreise: Seit August im Schnitt fast 40 Prozent drauf", "schlagzeile": "Grafikkarten seit August im Schnitt fast 40 Prozent teurer", "kurz": "GameStar hat aktuelle Grafikkartenpreise verglichen: Seit August 2026 sind die erfassten Modelle im Schnitt fast 40 Prozent teurer geworden. Zwischen Januar und August lag die Änderung ohne die RTX 5090 noch bei rund drei Prozent. Die RTX 5090 selbst stieg der Auswertung zufolge von etwa 3.000 Euro im Januar über 4.350 Euro im August auf aktuell rund 7.500 Euro.", "zusammenfassung": "GameStar hat am 8.11.2026 einen neuen Blick auf die Straßenpreise aktueller Grafikkarten veröffentlicht. Im August hatte dieselbe Auswertung über 16 Modelle von AMD, NVIDIA und Intel ohne die RTX 5090 noch eine durchschnittliche Änderung von etwa drei Prozent gegenüber Januar 2026 ergeben. Seitdem zeige der Trend bei praktisch allen betrachteten Karten nur noch nach oben. Die RTX 5090 nimmt der Bericht bewusst aus dem Durchschnitt, weil sie als Top-Modell mit 32 Gigabyte Speicher eine Sonderrolle habe. Ihr Preis sei von rund 3.000 Euro im Januar über 4.350 Euro im August auf aktuell etwa 7.500 Euro gestiegen. Auch darunter bis zur RTX 5050 sehe es düster aus: Bleibt die Richtung so, liege die RTX 5080 bald bei über 2.000 Euro, und für die Einsteigerkarte RTX 5050 würden fast 400 Euro fällig. Über die erfassten Modelle hinweg kommt GameStar seit August auf einen durchschnittlichen Aufschlag von fast 40 Prozent. Als Ursache nennt der Text den anhaltenden KI-Boom. Hardware-Unternehmen wie AMD sprächen zudem klar aus, dass sie sich vor allem als Firmen für Rechenzentren und nicht fürs Gaming sähen. Alle dem Autor bekannten Prognosen zur Speicher- und Hardwarekrise gingen davon aus, dass die Lage noch Jahre anhalte und eher schlimmer als besser werde. Genaue Preisvorhersagen seien schwierig; der Autor erwartet aber weiter steigende Preise und eine schlechtere Verfügbarkeit. Die Prozentwerte stammen aus GameStars eigener Preisauswertung; einzelne Modellpreise außer 5090, 5080 und 5050 weist der Text nicht tabellarisch aus.", "quelle": {"name": "GameStar", "url": "https://www.gamestar.de/artikel/grafikkarten-der-anfang-vom-ende,3462641.html"}, "weitere_links": [], "tags": ["Grafikkarten", "Preise", "RTX 5090", "RTX 5080", "RTX 5050", "GameStar"], "archiviert_am": "2026-11-15T18:31:25.944Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T10:27:13.198Z"}, "id": "2026-11-08-12v2x6-kabel-rtx-pro-6000", "datum": "2026-11-08T12:47:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Netzteil"], "kategorie": "Grafikkarten", "titel": "Beschädigte 12V-2×6-Kabel an zwei RTX PRO 6000 trotz Premium-Netzteil entdeckt", "schlagzeile": "32.000-Dollar-PC: 12V-2×6-Kabel zerbröseln an zwei RTX PRO 6000", "kurz": "Ein Reddit-Nutzer mit zwei NVIDIA RTX PRO 6000 Blackwell hat an beiden 12V-2×6-Stromkabeln beschädigte Ummantelungen entdeckt, obwohl die Karten auf 500 Watt begrenzt waren. Die Schäden zeigten sich an GPU- und Netzteilseite, geschmolzen ist aber nichts. Das Netzteil ist ein Seasonic PRIME TX-1600 Noctua Edition. Die Ursache ist nicht gemessen; es handelt sich um einen Einzelfall.", "zusammenfassung": "VideoCardz berichtet über einen Reddit-Beitrag des Nutzers Doomslayer606, der in seiner Workstation zwei NVIDIA RTX PRO 6000 Blackwell in der 600-Watt-Workstation-Edition mit je 96 GB GDDR7 betreibt. Die Karten zusammen kosten laut VideoCardz über 32.000 Dollar. Versorgt werden sie von einem Seasonic PRIME TX-1600 Noctua Edition mit zwei nativen 16-Pin-Kabeln. Obwohl der Besitzer beide Karten auf 500 Watt begrenzt hatte, bemerkte er an beiden Kabeln, dass die Ummantelung zweier einzelner Adern steif, rissig und leicht abzuziehen war. Die Schäden traten sowohl an den Steckern der Grafikkarten als auch an der Netzteilseite auf, wo sie sogar stärker ausfielen, obwohl diese Stecker kaum bewegt wurden. Die eigentliche Isolierung der Adern blieb intakt, und weder an den Karten noch am Netzteil gab es sichtbare Schmelz- oder Verfärbungsspuren. Zuvor war dem Nutzer aufgefallen, dass gelegentlich eine GPU oder eine NVMe-SSD vom PCIe-Bus verschwand, weshalb er die Kabel mehrfach neu gesteckt hatte. Er vermutet örtliche Überhitzung durch ungleich verteilte Ströme, gemessen wurden Temperatur oder Strom aber nicht. Als Konsequenz hat er Ersatzkabel mit Temperaturschutz gekauft und überlegt, die Karten auf 450 Watt zu begrenzen; bei 300 Watt habe er in seinen Anwendungen 40 bis 50 Prozent Leistung verloren. Seasonic oder NVIDIA haben sich laut Bericht nicht geäußert. Es ist ein Einzelfall ohne Herstellerbestätigung, passt aber in die lange Reihe von Problemen rund um den 16-Pin-Stecker. VideoCardz rät, Stromstecker regelmäßig zu kontrollieren, ohne sie ständig ab- und anzustecken.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/user-spots-damaged-seasonic-noctua-power-cables-before-losing-two-16000-rtx-pro-6000-gpus"}, "weitere_links": [], "tags": ["12V-2x6", "16-Pin", "RTX PRO 6000", "Seasonic", "Netzteil", "Kabel"], "archiviert_am": "2026-11-15T18:31:25.945Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-09T10:27:13.114Z"}, "id": "2026-11-08-rtings-woled-edge-rot", "datum": "2026-11-08T11:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["OLED", "Monitor"], "kategorie": "Displays", "titel": "RTINGS-Langzeittest: 14 von 16 älteren WOLED-Fernsehern zeigen Pixelausfälle am Rand", "schlagzeile": "„Edge Rot“: 14 von 16 WOLED-TVs mit toten Pixeln am Rand", "kurz": "Im 18.000-Stunden-Langzeittest von RTINGS haben 14 von 16 Fernsehern mit WOLED-Panels von LG Display tote Pixel entlang der Bildränder entwickelt. RTINGS nennt das „Edge Rot“; mit Einbrennen hat es nichts zu tun. Die drei getesteten QD-OLED-TVs blieben verschont. Betroffen sind vor allem Modelle von 2020 bis 2022, neuere Panels ab 2024 sind nicht getestet.", "zusammenfassung": "Die Testseite RTINGS hat Ergebnisse aus ihrem beschleunigten Langzeittest veröffentlicht, in dem Fernseher rund 18.000 Stunden liefen. Von 16 Geräten mit WOLED-Panels von LG Display entwickelten 14 tote Pixel, kleine Pixelgruppen oder sichtbare Schäden entlang der Bildschirmränder, das sind 87,5 Prozent. RTINGS nennt das Phänomen „Edge Rot“. Anders als Einbrennen hängt es laut RTINGS nicht davon ab, ob statische Inhalte gezeigt werden, und lässt sich auch nicht durch abwechslungsreiches Material vermeiden. Bei den älteren WBC-Panels waren 9 von 10 Geräten betroffen, fünf davon stark; bei den neueren WBE-Panels 5 von 6, darunter Modelle von LG und Sony. Das 2023er-Modell LG G3 zeigte keine Randschäden. Die drei getesteten QD-OLED-Fernseher mit Panels von Samsung Display blieben ohne Edge Rot; RTINGS betont aber, dass drei Geräte zu wenige sind, um QD-OLED für immun zu erklären. Auch drei geprüfte OLED-Monitore, darunter ein WOLED-Modell, zeigten keine Randschäden. Zwei RTINGS-Mitarbeiter fanden das Problem zudem an ihren privat genutzten Geräten aus 2020 und 2021. Die genaue Ursache ist nicht geklärt; diskutiert werden Verunreinigungen in der Fertigung und Schwächen der Schutzschicht, die Feuchtigkeit vom Panel fernhalten soll. LG Electronics und LG Display bestätigten gegenüber RTINGS, dass das Phänomen bei einer kleinen Zahl von Produkten unter längerer Hitze, Feuchtigkeit oder anderen harten Bedingungen auftreten könne, unter normalen Bedingungen aber nicht zu erwarten sei. Die 87,5 Prozent sind ein Ergebnis aus einem kleinen Testfeld unter Dauerlast und keine Ausfallquote aller verkauften Geräte. Ob Panels ab 2024 betroffen sind, hat RTINGS noch nicht ermittelt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/rtings-discovers-edge-rot-affecting-87-5-of-tested-woled-tvs"}, "weitere_links": [{"name": "Hardware Busters", "url": "https://hwbusters.com/news/rtings-finds-edge-rot-on-14-of-16-woled-tvs-after-18000-hours-while-qd-oled-sets-stay-clean/"}], "tags": ["OLED", "WOLED", "QD-OLED", "RTINGS", "LG Display", "Edge Rot"], "archiviert_am": "2026-11-15T11:01:57.622Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-08T09:19:31.848Z"}, "id": "2026-11-07-warzone-switch2", "datum": "2026-11-07T20:48:00+01:00", "label": "News", "bereich": "games", "themen": ["Switch 2", "Warzone"], "kategorie": "Spiele", "titel": "Call of Duty: Warzone ist jetzt kostenlos auf der Nintendo Switch 2", "schlagzeile": "Warzone ist jetzt kostenlos auf der Nintendo Switch 2", "kurz": "Call of Duty: Warzone ist auf der Nintendo Switch 2 erschienen und im Nintendo eShop kostenlos erhältlich. Einen Kauf von Modern Warfare 4 braucht man dafür nicht, ein Activision-Konto schon. Der Start fiel mit Season 1 zusammen; gleichzeitig endete der Support für PlayStation 4 und Xbox One.", "zusammenfassung": "Laut Insider Gaming ist Call of Duty: Warzone auf der Nintendo Switch 2 verfügbar und im eShop als eigenständiges Free-to-Play-Spiel zu haben. Wer Modern Warfare 4 nicht besitzt, kann das Battle Royale trotzdem spielen. Ein Activision-Konto ist Voraussetzung. Der Start erfolgte zusammen mit Season 1; Activision schreibt dazu, man könne in Hajin, Zodiac und die übrigen Karten und Playlists einsteigen, während das kostenlose Spiel erstmals auf Nintendos Handheld ankomme. Nintendo Life hat das Angebot am 7.11.2026 nachgetragen und auf dem eigenen Gerät eine Dateigröße von 122 GB gemessen; eine offizielle Downloadgröße von Activision liegt uns nicht vor. Insider Gaming ordnet den Schritt als Rückkehr der Reihe auf Nintendo-Hardware ein: Modern Warfare 4 war demnach das erste Call-of-Duty-Spiel auf einer Nintendo-Konsole seit Ghosts auf der Wii U. Mit Season 1 hat Activision den Support für PlayStation 4 und Xbox One beendet; der Fortschritt soll sich über dasselbe verknüpfte Activision-Konto auf unterstützte Plattformen mitnehmen lassen. Auflösung, Bildrate und Crossplay-Details für die Switch-2-Fassung hat Activision in der uns vorliegenden Berichterstattung nicht beziffert. Der Start selbst lag am 6.11.2026, die von uns genutzte Meldung von Insider Gaming erschien am 7.11.2026.", "quelle": {"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/call-of-duty-warzone-switch-2-release/"}, "weitere_links": [{"name": "Nintendo Life (122 GB Messung)", "url": "https://www.nintendolife.com/news/2026/11/icymi-call-of-duty-warzone-is-now-available-for-switch-2"}], "tags": ["Warzone", "Switch 2", "Call of Duty", "Activision", "Modern Warfare 4"], "archiviert_am": "2026-11-15T07:25:39.427Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-08T09:19:31.917Z"}, "id": "2026-11-07-pulse-elevate-verschoben", "datum": "2026-11-07T20:36:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Konsolen", "titel": "Sony verschiebt Pulse-Elevate-Lautsprecher unbegrenzt wegen Produktionsproblem", "schlagzeile": "Sony verschiebt Pulse Elevate unbegrenzt – kurz vor dem Start", "kurz": "Sony hat den Verkaufsstart der kabellosen Pulse-Elevate-Lautsprecher unbegrenzt verschoben. Der 12. November als Termin entfällt, weil die Qualitätsprüfung ein Produktionsproblem gefunden hat. Einen neuen Termin nennt Sony nicht; was mit bereits aufgegebenen Vorbestellungen passiert, ist offen.", "zusammenfassung": "Sony hat am 6.11.2026 im PlayStation-Blog den Start der Pulse-Elevate-Lautsprecher unbegrenzt verschoben. Eurogamer und IGN haben die Mitteilung am 7.11.2026 aufgegriffen. Im Blog schreibt Sony, man habe bei der laufenden Qualitätsprüfung ein Produktionsproblem gefunden und sich deshalb entschieden, den Start zu verschieben; die zusätzliche Zeit solle sicherstellen, dass das Produkt die vorgesehene Erfahrung liefert. Einen neuen Termin und eine genaue Beschreibung des Problems nennt Sony nicht. Die Lautsprecher sollten am 12. November weltweit in den Handel kommen, also nur wenige Tage nach der Mitteilung. Die unverbindliche Preisempfehlung liegt laut der aktualisierten Blog-Seite bei 219,99 US-Dollar, 219,99 Euro und 199,99 Pfund. Pulse Elevate ist Sonys erstes kabelloses Lautsprecherpaar für Desktop-Spiele und sitzt neben dem Pulse-Elite-Headset und den Pulse-Explore-Ohrhörern. Sie verbinden sich über PlayStation Link mit der PS5, mit PCs, Macs und dem PlayStation Portal und können gleichzeitig per Bluetooth mit einem Smartphone gekoppelt werden. Im rechten Lautsprecher steckt ein Mikrofon mit von Sony so genannter KI-unterstützter Geräuschunterdrückung. Die Variante Midnight Black sollte überall erhältlich sein, die weiße Fassung nur in ausgewählten Ländern, darunter Deutschland, Österreich und Großbritannien. Vorbestellungen liefen seit September. Eurogamer schreibt, es sei unklar, was nun mit diesen Bestellungen geschieht.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/playstation-pulse-elevate-speakers-delayed-indefinitely-production-issue"}, "weitere_links": [{"name": "PlayStation Blog (offizielle Mitteilung)", "url": "https://blog.playstation.com/2025/09/24/introducing-pulse-elevate-sony-interactive-entertainments-first-wireless-speakers-for-desktop-gaming/"}, {"name": "IGN", "url": "https://www.ign.com/articles/sony-announces-indefinite-delay-for-playstations-pulse-elevate-wireless-speakers-days-before-launch"}], "tags": ["PlayStation", "Pulse Elevate", "Sony", "PS5"], "archiviert_am": "2026-11-15T07:25:39.427Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.350Z"}, "id": "2026-11-07-anno117-fsr3-rtx30", "datum": "2026-11-07T18:30:00+01:00", "label": "News", "bereich": "games", "themen": ["Anno 117", "GPU"], "kategorie": "Spiele", "titel": "Anno 117 Update 3.0: FSR 3 Frame Generation auf GeForce RTX 30 jetzt standardmäßig aktiv", "schlagzeile": "Anno 117 schaltet auf RTX-30-Karten jetzt AMDs Frame Generation ein", "kurz": "Mit Update 3.0 aktiviert Anno 117: Pax Romana bei GeForce-RTX-30-Karten in der automatischen Grafikeinstellung standardmäßig AMDs FSR 3 Frame Generation. Grund: NVIDIAs eigene DLSS Frame Generation läuft erst ab RTX 40. Mehr angezeigte Fps heißen aber nicht weniger Eingabeverzögerung.", "zusammenfassung": "Ubisoft Mainz hat am 5. November 2026 Update 3.0 für Anno 117: Pax Romana zusammen mit der Erweiterung „Dawn of the Delta“ veröffentlicht. Laut den offiziellen Patchnotes schaltet die automatische Grafikerkennung bei GeForce-Karten der RTX-30-Serie jetzt standardmäßig AMDs FSR 3 Frame Generation ein. PCGH hat das am 7. November aufgegriffen und erklärt den Hintergrund: NVIDIAs DLSS Frame Generation ist offiziell den Serien RTX 40 und RTX 50 vorbehalten, FSR 3 läuft dagegen herstellerübergreifend und braucht keine KI-Einheiten. Auf Systemen, denen das Spiel das Profil „Niedrig“ zuweist, wird Frame Generation dagegen nicht mehr automatisch aktiviert, um Schwankungen auf Rechnern nahe den Mindestanforderungen zu vermeiden. Konkrete Messwerte zum Fps-Plus nennt Ubisoft nicht. Frame Generation fügt Zwischenbilder ein: Die angezeigte Bildrate steigt, die Eingabeverzögerung sinkt dadurch aber nicht. Weitere Änderungen betreffen Ruckler beim Schwenken über große Städte, Leistungseinbrüche beim Hervorheben von Straßen und das Archiv im Questbuch. Laut Patchnotes behebt das Update außerdem zahlreiche Abstürze und Fehler. Wer die automatische Einstellung nicht nutzt oder Frame Generation nicht will, kann sie in den Grafikoptionen selbst steuern.", "quelle": {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Anno-117-Pax-Romana-Spiel-74719/News/Ubisoft-setzt-automatisch-auf-AMD-FSR-3-auf-Geforce-RTX-3000-1559251/"}, "weitere_links": [{"name": "Anno Union: Patchnotes Update 3.0", "url": "https://www.anno-union.com/updates/anno-117-pax-romana-patch-3-0/"}], "tags": ["Anno 117", "FSR 3", "Frame Generation", "GeForce RTX 30", "Ubisoft"], "archiviert_am": "2026-11-14T18:00:46.885Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.435Z"}, "id": "2026-11-07-assassins-creed-mars-rom", "datum": "2026-11-07T16:37:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Assassin's Creed"], "kategorie": "Games", "titel": "Bericht: Ubisoft arbeitet an Assassin's Creed „Mars“ im antiken Rom und Mobile-Ableger „Pocket“", "schlagzeile": "Leak: Geht Assassin's Creed zurück nach Rom?", "kurz": "Laut dem Content Creator J0nathan entwickelt Ubisoft ein Assassin's Creed mit dem Codenamen „Mars“, das im antiken Rom spielen soll, dazu einen Mobile-Titel „Pocket“ in Jerusalem. Insider Gaming kennt die Codenamen, konnte die Angaben aber nicht ausreichend prüfen. Ein Release wäre laut Bericht erst um 2029/2030 denkbar.", "zusammenfassung": "Insider Gaming berichtet am 7. November 2026 über Angaben des YouTubers J0nathan, der in der Vergangenheit öfter richtige Informationen zu Assassin's Creed hatte. Demnach arbeitet Ubisoft an einem Assassin's Creed mit dem Codenamen „Mars“, das im antiken Rom spielen soll. Zwei Quellen mit Zugang zu Ubisofts internen Systemen sollen das bestätigt haben; ein Bezug zur geplanten Assassin's-Creed-Serie gilt als möglich. Ein zweites Projekt mit dem Codenamen „Pocket“ soll ein Mobile-Spiel sein, das in Jerusalem spielt. Insider Gaming hat nach eigenen Angaben von den Codenamen ebenfalls gehört, konnte die Details aber nicht nach seinen Standards verifizieren. Die Reihe ist zuletzt in unruhigem Fahrwasser, unter anderem nach dem Abgang von Marc-Alexis Côté. Laut früheren Insider-Gaming-Quellen wurde das nächste große Spiel, Assassin's Creed Hexe, intern um ein weiteres Jahr verschoben, wohl auf 2028. Ein Rom-Spiel wäre dem Bericht zufolge daher nicht vor 2029/2030 zu erwarten. Ubisoft hat sich nicht geäußert. Alles ist unbestätigt; frühe Projekte können sich ändern oder eingestellt werden.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/assassins-creed-rome-game/"}, "weitere_links": [{"name": "TheGamer: Codename Mars", "url": "https://www.thegamer.com/assassins-creed-codename-mars-pocket-leak-reliable-insider-ancient-rome/"}], "tags": ["Assassin's Creed", "Ubisoft", "Rom", "Leak"], "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Ursprung ist der YouTuber J0nathan mit gemischter, aber oft zutreffender Bilanz bei Assassin's Creed. Insider Gaming kennt die Codenamen, konnte die Details aber nicht verifizieren. Keine Stellungnahme von Ubisoft."}, "archiviert_am": "2026-11-14T18:00:46.886Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.514Z"}, "id": "2026-11-07-microsoft-gpu-patent-ki", "datum": "2026-11-07T15:09:00+01:00", "label": "News", "bereich": "software", "themen": ["KI", "GPU"], "kategorie": "Software", "titel": "Microsoft-Patentanmeldung: Ungenutzte GPU-Leistung privater Geräte für KI-Training gegen Gutschriften", "schlagzeile": "Geld für deine GPU im Leerlauf? Microsoft-Patent beschreibt KI-Training", "kurz": "Eine am 5. November veröffentlichte Microsoft-Patentanmeldung beschreibt ein System, das KI-Training in kleine Teilaufgaben zerlegt und auf ungenutzte GPUs von Endgeräten verteilt. Nutzer müssten zustimmen und könnten Gutschriften erhalten. Ein Produkt hat Microsoft nicht angekündigt.", "zusammenfassung": "Insider Gaming berichtet über eine Microsoft-Patentanmeldung mit dem Titel „Opportunistic Micro-training on Edge Devices Using Spare GPU Utilization“ (US-20260349820-A1), veröffentlicht am 5. November 2026. Beschrieben wird ein System, das große KI-Trainingsaufgaben in unabhängig trainierbare Mini-Aufgaben zerlegt und an Geräte verteilt, deren GPU gerade wenig zu tun hat. Ob ein Gerät frei ist, soll anhand von GPU- und CPU-Last, Speicher, Temperatur und Stromverbrauch erkannt werden. Laut Text soll das System die Nutzung nicht stören, also Programme nicht verlangsamen, Akkus nicht leeren und Geräte nicht überhitzen. Teilnehmen sollen nur Nutzer, die zustimmen. Die geleistete Rechenarbeit soll erfasst und als Gutschrift auf dem Konto verbucht werden, einlösbar etwa für Software, Modellzugang oder Geld. Microsoft wäre dabei Vermittler zwischen Dritten, die Rechenleistung brauchen, und den Geräte-Besitzern. Offen bleiben Fragen zu Datenschutz, Berechtigungen und zum zusätzlichen Verschleiß der Grafikkarte. Wichtig: Eine Patentanmeldung ist kein Produktversprechen, viele Patente werden nie umgesetzt. Microsoft hat keinen solchen Dienst angekündigt.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/microsoft-ai-use-your-gpu/"}, "weitere_links": [], "tags": ["Microsoft", "Patent", "KI", "GPU"], "archiviert_am": "2026-11-14T18:00:46.887Z"}, {"id": "2026-11-07-hwinfo-rx7500-razor-lake", "datum": "2026-11-07T13:02:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["AMD", "GPU", "Intel"], "kategorie": "Grafikkarten", "titel": "HWiNFO-Beta erkennt unangekündigte Radeon RX 7500 und Intel Razor Lake-H/HX/S", "schlagzeile": "Leak: HWiNFO kennt RX 7500 und Razor Lake", "kurz": "Die HWiNFO-Beta 8.55 Build 6115 listet eine AMD Radeon RX 7500, die AMD noch nicht angekündigt hat. Denselben Build verbessert die Erkennung von Intel Razor Lake-H, -HX und -S sowie Nova Lake-E. Specs und Launch der RX 7500 bleiben unbekannt; Namenssupport in Tools ist keine Launch-Garantie.", "zusammenfassung": "TechPowerUp und VideoCardz berichten, dass die HWiNFO-Beta Version 8.55 Build 6115 erstmals „AMD Radeon RX 7500“ erkennt. AMD hat die Karte nicht offiziell vorgestellt; im Changelog steht nur der Name, ohne Spezifikationen oder Termin. TechPowerUp hält Navi 33 / RDNA 3 für den wahrscheinlichsten Chip-Kandidaten, weil die Architektur bereits RX 7400 und RX 7600 speist – ein Modell dazwischen wäre eng bemessen. Der Name RX 7500 bzw. RX 7500 XT tauchte laut Berichten schon in älteren Gerüchten um 2024 auf, ohne konkreten Launch. VideoCardz verweist zusätzlich auf frühere Prototyp-Hinweise zu Navi 33 XE mit 6 GB GDDR6 und Device-ID 749F; ob das finale Produkt so aussieht, ist unbestätigt. Derselbe HWiNFO-Build erweitert die Unterstützung für Intel Nova Lake-E und Razor Lake-H/HX/S. Razor Lake gilt als Nachfolger-Generation nach Nova Lake; retail-Chips sind weit entfernt, da Nova Lake-S erst um Q1 2027 erwartet wird. CPU-Z 3.02 hatte Razor Lake Anfang der Woche bereits ergänzt, HWiNFO hatte Razor Lake-AX schon im August vorläufig. AMD und Intel haben die Einträge nicht bestätigt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354555/unreleased-radeon-rx-7500-and-intel-razor-lake-h-hx-s-appear-in-latest-hwinfo-beta"}, "weitere_links": [{"name": "VideoCardz: HWiNFO RX 7500 und Razor Lake", "url": "https://videocardz.com/newz/hwinfo-adds-amd-radeon-rx-7500-support-improves-intel-razor-lake-h-hx-s-detection"}, {"name": "HWiNFO-Forum: Beta 8.55-6115", "url": "https://www.hwinfo.com/forum/threads/hwinfo-v8-55-6115-beta-released.11381/"}], "tags": ["HWiNFO", "Radeon RX 7500", "Razor Lake", "AMD", "Intel", "Leak"], "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Nur Namens- bzw. ID-Support in der HWiNFO-Beta 8.55-6115 sowie Berichte von TechPowerUp und VideoCardz. Keine offizielle Ankündigung von AMD oder Intel; Specs und Launch der RX 7500 unbekannt. Tool-Erkennung ist keine Launch-Garantie."}, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:09.645Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-14T18:00:46.887Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.585Z"}, "id": "2026-11-07-vulkan-1-4-368", "datum": "2026-11-07T11:53:00+01:00", "label": "News", "bereich": "software", "themen": ["Vulkan", "Grafik-API"], "kategorie": "Grafiktreiber", "titel": "Vulkan 1.4.368 mit neuen Erweiterungen von Valve und NVIDIA", "schlagzeile": "Vulkan 1.4.368: Valve und NVIDIA bringen neue Erweiterungen", "kurz": "Die Khronos Group hat Vulkan 1.4.368 veröffentlicht. Das Wochen-Update bringt zwei neue Erweiterungen: eine von Valves Mesa-Entwickler Mike Blumenkrantz für Vertex-Daten und eine NVIDIA-Erweiterung für interne Treiber-Handles. Für Spieler ändert sich sofort nichts, es ist ein Baustein für Treiber und Engines.", "zusammenfassung": "Vulkan 1.4.368 ist das neueste wöchentliche Update der Spezifikation der plattformübergreifenden Grafik- und Compute-Schnittstelle, wie Phoronix am 7. November 2026 berichtet. Inhaltlich ist es ein kleines Update: Sechs intern gemeldete Probleme der Spezifikation wurden behoben. Neu sind zwei Erweiterungen. VK_EXT_vertex_address_binding_unrestricted stammt von Mike Blumenkrantz aus Valves Linux-Grafikteam und bekanntem Mesa-Entwickler. Sie hilft, wenn Vertex-Daten für einen Draw-Aufruf in einen eigenen Puffer ausgelagert werden, um Speicher zu sparen, und schaltet dafür eine Adressprüfung ab. Die zweite, VK_NV_internal_handle, ist eine NVIDIA-eigene Erweiterung: Programme und Engines können damit interne Treiber-Handles für bestimmte Vulkan-Objekte abfragen und an andere NVIDIA-Schnittstellen weitergeben. Beide Erweiterungen müssen erst in Treibern und Software ankommen, bevor sie in Spielen etwas bewirken. Vulkan ist unter anderem die Basis von Proton auf Linux und Steam Deck, wo Valves Beiträge besonders wichtig sind. Alle Details stehen im Vulkan-Docs-Repository der Khronos Group auf GitHub.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Vulkan-1.4.368"}, "weitere_links": [{"name": "Khronos Vulkan-Docs auf GitHub", "url": "https://github.com/KhronosGroup/Vulkan-Docs"}], "tags": ["Vulkan", "Khronos", "Valve", "NVIDIA", "Grafik-API"], "archiviert_am": "2026-11-14T18:00:46.888Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.660Z"}, "id": "2026-11-07-razor-lake-lga1954-2028", "datum": "2026-11-07T10:40:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["Intel", "CPU"], "kategorie": "Prozessoren", "titel": "Bericht: Intel Razor Lake-S soll 2028 auf dem Nova-Lake-Sockel LGA 1954 erscheinen", "schlagzeile": "Leak: Razor Lake soll 2028 auf den Nova-Lake-Sockel passen", "kurz": "Laut dem Insider Jaykihn ist Intels Razor Lake-S derzeit für 2028 geplant und soll denselben Sockel LGA 1954 nutzen wie Nova Lake-S. Wer 2027 auf Nova Lake umsteigt, könnte damit eine weitere CPU-Generation ohne neues Mainboard nachrüsten. Intel hat nichts davon bestätigt.", "zusammenfassung": "Wccftech und HotHardware fassen am 7. November 2026 Angaben des Intel-Insiders Jaykihn zusammen: Razor Lake-S sei „derzeit als 2028-Produkt eingeplant“, offiziell gesagt habe Intel dazu nichts. Nova Lake-S, die nächste Desktop-Generation, wird für Anfang 2027 erwartet und bringt den neuen Sockel LGA 1954 mit. Razor Lake-S soll laut den Berichten auf demselben Sockel laufen, Intel hätte damit erstmals seit Längerem zwei Desktop-Generationen auf einer Plattform. Bereits im Juni hatte Jaykihn geschrieben, LGA 1954 werde auf Boards mit 64 MB BIOS-Flash sogar Prozessoren über Razor Lake hinaus unterstützen, darunter alle Z-Boards. Als P-Kern-Architektur von Razor Lake nennen die Berichte Griffin Cove, einen Nachfolger von Nova Lakes Coyote Cove; SMT soll es bei den Desktop-Chips nicht geben. Zudem sollen einige ursprünglich für Nova Lake geplante Varianten, etwa Nova Lake-AX, in die Razor-Lake-Familie gewandert sein. Ein Quartal für 2028 ist nicht bekannt, Wccftech spekuliert über Computex 2028 oder die zweite Jahreshälfte. Intel-Manager Robert Hallock hatte im März angedeutet, man höre auf die Kritik an häufigen Sockelwechseln, eine konkrete Zusage gibt es aber nicht. Erste Vorbereitungen sind sichtbar: CPU-Z 3.02 und eine HWiNFO-Beta kennen Razor Lake bereits. Alle Angaben zu Termin und Sockel sind unbestätigt und können sich ändern; Kaufentscheidungen sollte man darauf nicht stützen.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/intel-razor-lake-s-desktop-cpus-arrive-in-2028-on-lga-1954-socket/"}, "weitere_links": [{"name": "HotHardware: Razor Lake-S auf LGA 1954", "url": "https://hothardware.com/news/intel-razor-lake-s-desktop-cpus-tap-lga-1954-socket"}, {"name": "VideoCardz: LGA 1954 über Razor Lake hinaus (Juni)", "url": "https://videocardz.com/newz/intel-lga-1954-boards-with-64mb-to-support-cpus-beyond-razor-lake-2l-ilm-leak-confirmed"}], "tags": ["Intel", "Razor Lake", "Nova Lake", "LGA 1954", "Leak"], "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Angaben des Insiders Jaykihn (X), der bei Intel-Roadmaps oft richtig lag; aufgegriffen von Wccftech und HotHardware. Keine Bestätigung von Intel, Termin und Sockel können sich ändern."}, "archiviert_am": "2026-11-14T18:00:46.888Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.736Z"}, "id": "2026-11-07-cpuz-ram-rueckgang", "datum": "2026-11-07T10:40:00+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM"], "kategorie": "Speicher & Markt", "titel": "CPU-Z-Statistik: Anteil von 32- und 64-GB-PCs sinkt erstmals im Jahresvergleich", "schlagzeile": "Erstmals weniger RAM: CPU-Z sieht 16-GB-PCs wieder im Kommen", "kurz": "Laut CPU-Z-Validator-Statistik sinkt der Anteil von PCs mit 32 GB RAM im Jahresvergleich um 2,5 %, bei 64 GB sogar um 18 %. 16-GB- und 8-GB-Systeme legen dagegen zu, DDR4 gewinnt Anteile vor DDR5. Die Daten zeigen nur eingereichte Validierungen, keine Marktzahlen.", "zusammenfassung": "Doc TB, einer der Entwickler hinter CPU-Z, hat am 6. November 2026 neue Zahlen aus dem CPU-Z Validator veröffentlicht, VideoCardz hat sie am 7. November aufbereitet. Erstmals sinkt demnach die RAM-Ausstattung der erfassten PCs im Jahresvergleich. 32 GB bleiben mit 37,2 % die häufigste Konfiguration, verlieren aber 2,5 % an Anteil. Bei 64 GB beträgt der Rückgang 18 %, der Anteil liegt jetzt bei 7,3 %. 16-GB-Systeme legen um 12,9 % auf 33,0 % zu und liegen damit knapp hinter 32 GB. Auch 8 GB wachsen um 5,5 % auf 11,0 %, 24 GB um 19,7 % auf 2,3 %. Bei der Speichergeneration steigt DDR4 um 6,0 % auf 54,5 %, DDR5 fällt um 2,9 % auf 32,9 %. Eine Ursache nennen die Zahlen nicht; sie passen aber zu den stark gestiegenen RAM-Preisen der letzten Monate, über die der Ticker mehrfach berichtet hat. Wichtig: Die Statistik beruht nur auf Systemen, die Nutzer aktiv im Validator einreichen, und ist keine Marktstudie. Die Veränderungen sind relative Anteile und bedeuten nicht, dass Besitzer ihren RAM ausbauen.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/cpu-z-statistics-show-32gb-and-64gb-ram-configurations-declining-year-over-year"}, "weitere_links": [{"name": "Doc TB (CPU-Z) auf X, 06.11.2026", "url": "https://x.com/d0cTB/status/2118776662292906051"}], "tags": ["RAM", "CPU-Z", "DDR4", "DDR5", "Statistik"], "archiviert_am": "2026-11-14T18:00:46.888Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T20:50:55.797Z"}, "id": "2026-11-07-custom-engine-wald-rtx3080", "datum": "2026-11-07T09:45:00+01:00", "label": "News", "bereich": "software", "themen": ["Engine", "GPU"], "kategorie": "Tools & Mods", "titel": "Eigene Engine: Entwickler rendert dichten Wald mit rund 130 Fps auf einer RTX 3080 – ohne Hardware-Raytracing", "schlagzeile": "130 Fps auf der RTX 3080: Hobby-Engine rendert Wald ohne Raytracing", "kurz": "Der Entwickler und Modder Toni Macaroni zeigt eine selbst geschriebene Engine, die einen dichten Wald in 1440p mit durchschnittlich rund 130 Fps auf einer RTX 3080 darstellen soll. Sie setzt auf Nanite-ähnliche Geometrie, Voxel und Voxel-Beleuchtung statt Hardware-Raytracing. Die Werte stammen vom Entwickler selbst und sind eine reine Technik-Demo.", "zusammenfassung": "PCGH und Wccftech berichten über eine Technik-Demo des Entwicklers und Modders Toni Macaroni, deren YouTube-Video laut PCGH über 500.000 Aufrufe hat. Er arbeitet nach eigenen Angaben seit rund acht Monaten an der Engine, nachdem er lange die Open-Source-Engine Godot genutzt hatte. Die Szene zeigt eine Hügellandschaft mit dichtem Wald, rund eine Million Instanzen und vier Millionen Dreiecke. Auf einer GeForce RTX 3080 in 1440p sollen im Schnitt etwa 130 Fps erreicht werden, in Luftaufnahmen bis zu 200 und im dichten Unterholz rund 80 Fps. Technisch nutzt die Engine Clustered Levels of Detail mit Nanite-ähnlicher virtueller Geometrie, Voxel-Darstellungen für entfernte Vegetation und vereinfachte Proxys für sehr weit entfernte Objekte. Die Beleuchtung kombiniert Screen-Space-Techniken mit voxelbasierter Global Illumination und kommt ohne hardwarebeschleunigtes Raytracing aus, ähnlich dem Ansatz in Kingdom Come: Deliverance II. Die Engine ist bewusst spezialisiert: Sie soll vor allem viele Objekte mit hoher Polygonzahl gut darstellen, ein Wettersystem ist erst teilweise fertig. Die Fps-Werte sind Angaben des Entwicklers, die genauen Einstellungen und ein mögliches Upscaling sind nicht bekannt. Eine Demo ohne Spielfiguren, Physik und KI ist nicht mit einem fertigen Spiel vergleichbar, und eine öffentliche Version gibt es bisher nicht.", "quelle": {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Spiele-Entwicklung-Thema-35261/News/Custom-Engine-Wald-RTX-3080-130-Fps-1559175/"}, "weitere_links": [{"name": "Wccftech: Custom Forest Engine", "url": "https://wccftech.com/custom-forest-engine-delivers-stunning-visuals-at-130-fps-on-an-rtx-3080-at-1440p-without-hardware-ray-tracing/"}], "tags": ["Engine", "RTX 3080", "Voxel GI", "Tech-Demo"], "archiviert_am": "2026-11-14T18:00:46.889Z"}, {"id": "2026-11-07-windows-hello-pin-parallel", "datum": "2026-11-07T08:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Betriebssysteme", "titel": "Windows 11 Insider: PIN parallel zum Windows-Hello-Gesichts- oder Fingerabdruck-Scan", "schlagzeile": "Windows 11: PIN tippen während Windows Hello scannt", "kurz": "In der Windows-11-Insider-Experimental-Build 26340.9882 lässt sich die PIN tippen, während Windows Hello noch Gesicht oder Fingerabdruck prüft. Der Lockscreen zeigt „Look at the camera or enter your PIN“; wer zuerst funktioniert, gewinnt. Der Rollout ist experimentell, ein Retail-Termin fehlt.", "zusammenfassung": "Windows Latest testet Build 26340.9882 vom 6 November 2026 (Basis Windows 11 26H2, Experimental-Kanal): Auf dem Anmeldebildschirm erscheint das PIN-Feld parallel zur Windows-Hello-Prüfung. Statt auf Fehlschlag der Gesichtserkennung zu warten oder umständlich Anmeldeoptionen zu wählen, gilt laut Microsoft-Release-Notes „whichever method works first“. Nach einem Neustart bleibt PIN-First aus Sicherheitsgründen bestehen. Schlägt Face fehl, gibt es einen direkten „Retry face sign-in“-Hinweis. Bei Geräten mit IR-Kamera und Fingerabdrucksensor kann der Prompt Gesicht und Fingerabdruck nennen, mit PIN darunter. Neu sind Event-Log-IDs 4628 und 4629 unter Security für eingerichtete bzw. fehlgeschlagene Hello-Methoden; zusätzliche Operational-Events helfen der IT. Die Funktion erschien laut Test ohne ViVeTool. Experimental-Builds können Bugs enthalten; wann das Verhalten den stabilen Kanal erreicht, sagte Microsoft nicht.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/07/microsoft-is-fixing-one-of-windows-11s-most-frustrating-sign-in-problems-with-a-new-windows-hello-update/"}, "weitere_links": [], "tags": ["Windows 11", "Windows Hello", "PIN", "Insider"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:09.706Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-14T07:39:21.337Z"}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-08T09:19:31.755Z"}, "id": "2026-11-07-tsmc-3d-dram-nvidia", "datum": "2026-11-07T06:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Speicher"], "kategorie": "Speicher & Markt", "titel": "TSMC prüft Einstieg in 3D-DRAM – Anstoß soll von NVIDIA gekommen sein", "schlagzeile": "TSMC prüft 3D-DRAM: NVIDIA soll den Speichereinstieg angestoßen haben", "kurz": "Laut einem Bericht von The Information vom 6.11.2026 prüft der Auftragsfertiger TSMC den Einstieg in die Produktion von 3D-DRAM. Der Anstoß soll von NVIDIA gekommen sein, TSMCs größtem Kunden. Konkrete Fabriken, Investitionen oder ein Starttermin nennt der Bericht nicht. TSMC wollte Marktgerüchte gegenüber The Information nicht kommentieren und verwies auf seine Rolle als Logik-Foundry; NVIDIA antwortete demnach nicht.", "zusammenfassung": "The Information hat am 6.11.2026 unter Berufung auf zwei mit den Gesprächen vertraute Personen berichtet, TSMC prüfe einen Einstieg in die Fertigung von 3D-DRAM. Auslöser soll eine Anfrage von NVIDIA gewesen sein. igor'sLAB hat den Bericht am 7.11.2026 aufgegriffen und eingeordnet. Demnach hat TSMC damit begonnen, mögliche Produktionskonzepte für vertikal aufgebauten DRAM auszuarbeiten; als Optionen nennt der Bericht den Bau neuer Fertigungsanlagen oder die Übernahme eines vorhandenen Werks mit anschließender Umrüstung. Ein Produktionsbeginn, Investitionssummen oder geplante Kapazitäten wurden nicht genannt. Verantwortlich für die Initiative soll Hsu Kuo-chin sein, ein TSMC-Vizepräsident aus dem Bereich Advanced Packaging, der zuvor bei Micron in Taiwan tätig war. TSMC erklärte gegenüber The Information, grundsätzlich keine Marktgerüchte zu kommentieren, und verwies auf seine Ausrichtung als Auftragsfertiger für Logikchips. NVIDIA reagierte laut dem Bericht nicht auf eine Anfrage, und Reuters konnte die Angaben nicht unabhängig bestätigen. Technisch ist 3D-DRAM etwas anderes als das bereits etablierte High Bandwidth Memory: Bei HBM werden mehrere separat gefertigte DRAM-Chips gestapelt, bei 3D-DRAM sollen die Speicherzellenschichten selbst vertikal integriert werden, um die Dichte zu erhöhen. Ein erfolgreicher Einstieg würde TSMC in einen Markt bringen, den bislang vor allem Samsung, SK hynix und Micron beherrschen. Gleichzeitig ist aus dem Bericht kein kurzfristiger Start der Massenproduktion abzuleiten, weil Wärme, Prozessintegration und ausreichende Ausbeuten als offene Hürden gelten und eine Entwicklung Jahre dauern könnte. Vor dem Hintergrund knapper und teurer Speicher für PCs und Rechenzentren wäre ein zusätzlicher Hersteller folgenschwer, bislang stehen aber nur ein Medienbericht und mögliche Entwicklungsüberlegungen im Raum.", "quelle": {"name": "igor'sLAB", "url": "https://www.igorslab.de/tsmc-prueft-einstieg-in-3d-dram-nvidia-soll-entwicklung-neuartiger-speicherchips-angestossen-haben/"}, "weitere_links": [{"name": "The Verge (über The Information)", "url": "https://www.theverge.com/news/1029248/tsmc-is-apparently-considering-getting-into-the-ram-business-at-the-request-of-nvidia"}, {"name": "Seoul Economic Daily", "url": "https://en.sedaily.com/finance/2026/11/07/tsmc-weighs-3d-dram-push-at-nvidias-request"}, {"name": "Wccftech (Update)", "url": "https://wccftech.com/nvidia-custom-hbm-samsung-tsmc-3nm-base-die/"}], "tags": ["TSMC", "NVIDIA", "3D-DRAM", "Speicher", "HBM"], "archiviert_am": "2026-11-14T07:39:21.338Z"}, {"id": "2026-11-06-openai-gpt6-cyber-bugs", "datum": "2026-11-06T21:24:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit", "KI"], "kategorie": "Sicherheit", "titel": "OpenAI stellt GPT-6 Cyber vor: laut eigener Angabe 81 Firefox- und 948 Linux-LPE-Funde", "schlagzeile": "OpenAI GPT-6 Cyber findet 81 Firefox- und 948 Linux-Bugs", "kurz": "OpenAI hat GPT-6 Cyber vorgestellt, ein nicht öffentliches Security-Modell. Laut Unternehmensangaben fand es 81 zuvor unbekannte high-severity Firefox-Lücken und entwickelte Exploits für 948 Linux-Local-Privilege-Escalation-Fälle. Die Zahlen stammen von OpenAI und sind keine unabhängige Vollaudit-Bestätigung.", "zusammenfassung": "BleepingComputer, Phoronix und Golem berichten über OpenAIs Ankündigung von GPT-6 Cyber. Das Modell ist nicht öffentlich und derzeit auf freigeschaltete Kunden im Daybreak-Red-Programm beschränkt. OpenAI gibt an, 81 zuvor unbekannte high-severity Schwachstellen in Firefox entdeckt und Patches mitentwickelt zu haben; viele seien bei Mozilla bereits ausgerollt. Zur Linux-Kernel-Forschung nennt OpenAI 2308 potenzielle Funde, 1724 reproduzierte Schwachstellen und 948 Local-Privilege-Escalation-Exploits von unprivileged zu root. Im ExploitGym-Benchmark nennt das Unternehmen 48,5 Prozent Erfolgsrate gegenüber 32,1 Prozent beim Vorgänger GPT-5.6 Cyber. Im Preparedness Framework stuft OpenAI die Cyber-Fähigkeit als „Critical“ ein. Unabhängige Audit-Tiefe zu Umfang und Schwere der Funde ist begrenzt – die Zahlen sind Firmenangaben, kein Beleg dafür, dass „Linux generell unsicher“ wäre. OpenAI warnt vor einem begrenzten Zeitfenster, in dem Verteidiger Frontier-Modelle zum Härten nutzen sollten, bevor ähnliche Fähigkeiten breiter verfügbar sind.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/openais-new-gpt-6-cyber-ai-finds-81-firefox-flaws-948-linux-bugs/"}, "weitere_links": [{"name": "Phoronix: OpenAI 948 Linux LPE Bugs", "url": "https://www.phoronix.com/news/OpenAI-948-Linux-LPE-Bugs"}, {"name": "Golem: OpenAI will fast 1000 Root-Lücken gefunden haben", "url": "https://www.golem.de/news/mit-ki-agenten-openai-will-in-linux-system-fast-1-000-root-luecken-gefunden-haben-2611-214884.html"}], "tags": ["OpenAI", "GPT-6 Cyber", "Firefox", "Linux", "Sicherheit"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:09.777Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T21:54:41.797Z"}, {"id": "2026-11-06-zen6-tee-riscv", "datum": "2026-11-06T20:30:00+01:00", "label": "News", "bereich": "hardware", "themen": ["AMD", "CPU"], "kategorie": "Prozessoren", "titel": "AMD Zen 6: Firmware-Hinweis auf RISC-V-basiertes TEE statt ARM-PSP", "schlagzeile": "Zen 6: AMD wechselt TEE von ARM auf RISC-V", "kurz": "Ein linux-firmware-Commit für AMD PMF Trusted Application auf Zen-6-Client (Family 1Ah M80h) erwähnt ein RISC-V-basiertes TEE. Bisher lief der Secure Processor typischerweise auf ARM Cortex-A5 mit TrustZone. Ob RISC-V wirklich neu ab Zen 6 ist oder nur erstmals dokumentiert, bleibt offen.", "zusammenfassung": "Phoronix berichtet über einen linux-firmware-Commit, der PMF-TA-Firmware v4 für die Plattform 1AH_M80H ergänzt – das entspricht kommenden AMD-Ryzen-Zen-6-Client-CPUs. Im Commit-Text heißt es, die Trusted Application laufe nun auf einem RISC-V-basierten TEE, nutze ein größeres Shared-Memory-Layout und erweiterte Policy-Bedingungen inklusive bis zu 20 Custom-BIOS-Inputs. Das Platform Management Framework steuert unter anderem Power-, Thermal- und Systemverhalten. Traditionell basierte der AMD Platform Security Processor bzw. Secure Processor auf ARM Cortex-A5 mit TrustZone. Phoronix findet keine älteren öffentlichen Hinweise auf RISC-V-TEE in Ryzen/EPYC und lässt offen, ob das Feature neu für Zen 6 ist oder bei älteren SoCs nur nie erwähnt wurde. Ein finales Marketing-Label der Ryzen-Generation nennt der Commit nicht. Für Linux-Enablement und Security-Nerds ist der Architekturwechsel dennoch ein seltenes Zen-6-Detail vor dem Produktlaunch.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/AMD-Zen-6-TEE-RISC-V-Based"}, "weitere_links": [], "tags": ["AMD", "Zen 6", "RISC-V", "TEE", "Firmware"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:09.838Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T21:54:41.797Z"}, {"id": "2026-11-06-epic-linux-launcher-distros", "datum": "2026-11-06T20:22:00+01:00", "label": "News", "bereich": "games", "themen": ["Linux", "PC"], "kategorie": "Spiele", "titel": "Epic Games Launcher Preview: breite Linux-Distro-Unterstützung und AppImage-Rückkehr geplant", "schlagzeile": "Epic: neuer Launcher soll viele Linux-Distros unterstützen", "kurz": "Epic bestätigt gegenüber GamingOnLinux, dass der neue Launcher in der Preview möglichst viele Linux-Distributionen unterstützen soll – explizit unter anderem Fedora, SteamOS, Cachy und Omarchy. Packaging wechselt noch; AppImage soll noch in diesem Monat zurückkommen. Preview heißt nicht fertige Distro-Matrix.", "zusammenfassung": "GamingOnLinux hat Jake Jones (Communications Director, Epic Games) zum Linux-Support des neuen Epic Games Launchers befragt. Laut Statement plant Epic, „so viele Linux-Distributionen wie möglich“ zu unterstützen, darunter Fedora, SteamOS, Cachy, Omarchy und weitere. Die Preview startete mit AppImage, wechselte später auf ein .deb für Debian/Ubuntu; die FAQ nannte Fedora als baldig. Epic testet und bewertet Packaging-Formate und will AppImage noch in diesem Monat wiederherstellen. Bis die Matrix feststeht, können Formate kommen und gehen. Flatpak/Flathub bleibt in der Meldung offen. Der Launcher-Status ist Preview, kein finaler Store-Rollout für jede Distro. Fortnite oder Easy Anti-Cheat v2 sind ein separates Thema und werden hier nicht als „Fortnite kommt auf Linux“ verkauft. Zusammen mit dem bereits bekannten GOG-Galaxy-Linux-Zeitfenster 2027 bleibt der Wettbewerb der Store-Clients auf Linux spannend.", "quelle": {"name": "GamingOnLinux", "url": "https://www.gamingonlinux.com/2026/11/epic-games-comments-on-planned-linux-distribution-support/"}, "weitere_links": [], "tags": ["Epic Games", "Linux", "Launcher", "SteamOS"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:09.906Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T21:54:41.798Z"}, {"id": "2026-11-06-mindfactory-cyberangriff", "datum": "2026-11-06T18:22:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit"], "kategorie": "Sicherheit", "titel": "Mindfactory meldet Cyberangriff: Kundenpasswörter zurückgesetzt, Behörde informiert", "schlagzeile": "Mindfactory: Hackerangriff – Passwörter zurückgesetzt", "kurz": "Der Hardware-Shop Mindfactory hat am 6 November 2026 einen Cyberangriff gemeldet und Kunden sowie die Datenschutzbehörde informiert. Möglicherweise betroffen: Adresse, E-Mail, Telefon und verschlüsselte Passwörter; Bankdaten liegen laut Shop nicht im Shopsystem. Alle Shop-Passwörter wurden zurückgesetzt; Phishing-Vorsicht ist geboten.", "zusammenfassung": "heise online und Golem berichten, dass Mindfactory Opfer eines Cyberangriffs geworden ist und Kunden per Mitteilung informiert. Das Unternehmen hat Strafanzeige erstattet und die zuständige Datenschutzbehörde eingeschaltet. Nach aktuellem Stand kann Mindfactory nicht ausschließen, dass Angreifer auf Anschrift, E-Mail, Telefon sowie verschlüsselt gespeicherte Passwörter zugriffen. Klartext-Passwörter und Bank- bzw. Kreditkartendaten seien laut Unternehmen nicht betroffen, weil Zahlungsdaten bei Dienstleistern liegen. Alle Kundenpasswörter für den Shop wurden vorsorglich zurückgesetzt; beim nächsten Login ist ein neues Passwort nötig, künftig mit modernem Hash-Verfahren. Geschäftsführer Marcel Kirchner spricht von forensischer Untersuchung, keiner Erpressung und einer geschlossenen Lücke. Kunden sollen bei unerwarteten Mails, SMS oder Anrufen vorsichtig sein, weil Kontaktdaten für Betrug missbraucht werden könnten. Transparenzhinweis: Mindfactory gehört seit Mitte 2025 zur heise group; heise online ist Teil derselben Unternehmensgruppe. Umfang und genauer Angriffszeitpunkt waren zum Meldungszeitpunkt noch in Klärung.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Mindfactory-informiert-Kunden-ueber-Cyberangriff-11515963.html"}, "weitere_links": [{"name": "Golem: Hacker attackieren Mindfactory", "url": "https://www.golem.de/news/onlinehaendler-hacker-attackieren-mindfactory-2611-214956.html"}, {"name": "GameStar: Cyberangriff bei Mindfactory", "url": "https://www.gamestar.de/artikel/cyberangriff-bei-mindfactory-grosser-deutscher-haendler-meldet-vorfall-mit-hoechster-prioritaet,3462625.html"}], "tags": ["Mindfactory", "Cyberangriff", "Sicherheit", "Datenschutz"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:09.963Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.364Z"}, {"id": "2026-11-06-nier-366gb-update", "datum": "2026-11-06T18:09:00+01:00", "label": "News", "bereich": "games", "themen": ["PC"], "kategorie": "Spiele", "titel": "NieR: Automata-Update verlangt versehentlich 366 GB Speicher – Fix angekündigt", "schlagzeile": "NieR: Automata-Update frisst 366 GB – Studio entschuldigt sich", "kurz": "Ein Steam-Update für NieR: Automata vom 6. November 2026 (JST) verlangt laut Entwickler deutlich mehr Speicher als vorgesehen – Insider Gaming nennt 366 GB bei rund 50 GB Basisspiel. Es sollte Sprachen ergänzen; ein Fix und eine DLC-Abwahl-Workaround sind kommuniziert.", "zusammenfassung": "Insider Gaming berichtet über ein fehlerhaftes Steam-Update für NieR: Automata: Nach dem Update vom 6. November 2026 (japanische Zeit) sei die Installation deutlich größer als beabsichtigt – genannt werden 366 GB Speicherbedarf, während das Basisspiel rund 50 GB braucht. Laut Update-Notes sollten vereinfachtes und traditionelles Chinesisch sowie Koreanisch ergänzt werden. Das NieR-Series-Konto auf X entschuldigte sich und kündigte eine Korrektur an. Als Workaround können Spieler unter Eigenschaften → DLC die DLC-Einträge abwählen und so vorerst mit dem Basisspiel weiterspielen. Ein neues Story-DLC gibt es seit 2024 nicht; das Spiel hatte im Februar 2026 die Marke von über 10 Millionen verkauften bzw. ausgelieferten Exemplaren überschritten. Die exakte Ursache der aufgeblähten Downloadgröße ist in der kurzen Mitteilung nicht erklärt.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/nier-automata-devs-address-366-gb-update/"}, "weitere_links": [], "tags": ["NieR Automata", "Steam", "Update"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.408Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.366Z"}, {"id": "2026-11-06-qnap-plex2shell", "datum": "2026-11-06T18:04:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit"], "kategorie": "Sicherheit", "titel": "QNAP warnt: Angreifer kompromittieren NAS über Plex2Shell-Lücken in Plex Media Server", "schlagzeile": "QNAP: Hacker knacken NAS über Plex2Shell – Plex sofort updaten", "kurz": "QNAP meldet Kompromittierungen von NAS-Geräten über die Plex2Shell-Schwachstellenkette im Plex Media Server. Nutzer sollen Plex im App Center auf mindestens 1.43.3.10861 aktualisieren; bei Verdacht droht eine Neuinstallation. QTS selbst sei nicht betroffen.", "zusammenfassung": "BleepingComputer berichtet über eine QNAP-Sicherheitswarnung: Mehrere Nutzer hätten gemeldet, dass Plex Media Server auf ihren NAS-Geräten über die Plex2Shell-Lücken kompromittiert worden sei. Plex2Shell umfasst vier Schwachstellen (CVE-2026-96652, CVE-2026-96654, CVE-2026-96655, CVE-2026-96656), die Zach Main am 27. Juli gemeldet hatte; nach Veröffentlichung technischer Details am 16. Oktober begann die Ausnutzung. CISA nahm die CVEs am 20. Oktober 2026 in den Known-Exploited-Katalog auf und setzte eine kurze Frist für Behörden. QNAP betont, die Lücken lägen nur in Plex Media Server, nicht in QTS/QuTS hero. Empfohlen wird das Update auf Plex 1.43.3.10861 aus dem QNAP App Center. Wer einen verwundbaren, öffentlich erreichbaren Plex-Server betreibt, solle das Gerät als potenziell kompromittiert behandeln: Update entfernt bereits installierte Payloads nicht. QNAP rät zu Neuinstallation von QTS/QuTS hero, Credential-Reset und – wenn Remote-Zugriff nötig – VPN statt Portfreigabe 32400.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/qnap-says-hackers-breaching-nas-devices-in-plex2shell-attacks/"}, "weitere_links": [], "tags": ["QNAP", "Plex", "Sicherheit", "NAS"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.473Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.366Z"}, {"id": "2026-11-06-ratchet-ranger-rumble", "datum": "2026-11-06T18:02:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Spiele", "titel": "Ratchet & Clank: Ranger Rumble wird eingestellt – Server-Ende Mai 2027", "schlagzeile": "Ratchet & Clank: Ranger Rumble stirbt – Server-Aus am 1. Mai 2027", "kurz": "Das mobile Ratchet-&-Clank-Spin-off Ranger Rumble wird gestoppt: finales Update heute, Entfernung aus den Stores am 21 November 2026, Server-Abschaltung am 1 Mai 2027. Das Spiel war noch in der Soft-Launch-Phase vor dem geplanten Global-Release.", "zusammenfassung": "IGN berichtet über die Einstellung von Ratchet & Clank: Ranger Rumble. Laut Entwickler-Statement rollt am 6. November 2026 das letzte geplante Update aus; die App verschwindet am 21. November 2026 aus den Stores. Wer das Spiel bereits hat, kann bis zum 1. Mai 2027 spielen, dann gehen die Server endgültig offline. In-App-Käufe wurden entfernt; Erstattungen verweisen auf Apple bzw. Google. Das Arena-Shooter-Spin-off stammte von Oh BiBi in Zusammenarbeit mit Insomniac Games und PlayStation Studios und steckte laut IGN noch im Soft Launch vor dem weltweiten Start. Noch im Juli hatte der PlayStation-Blog von einem bevorstehenden Global Launch nach erfolgreicher Testphase gesprochen. VGC spricht ebenfalls von einer Absage des Free-to-play-Mobile-Shooters.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/ratchet-clank-ranger-rumble-shutting-down"}, "weitere_links": [{"name": "VGC: Sony’s Ratchet & Clank mobile shooter cancelled", "url": "https://www.videogameschronicle.com/news/sonys-free-to-play-mobile-ratchet-clank-multiplayer-shooter-has-been-cancelled/"}], "tags": ["Ratchet & Clank", "PlayStation", "Mobile"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.344Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.367Z"}, {"id": "2026-11-06-poe2-1-0-exilecon", "datum": "2026-11-06T17:00:00+01:00", "label": "News", "bereich": "games", "themen": ["PC", "ARPG"], "kategorie": "Spiele", "titel": "Path of Exile 2 Vollrelease am 11 Dezember 2026: Shadow, Duelist und League Conquerors of Wraeclast", "schlagzeile": "Path of Exile 2 1.0: Shadow, Duelist, Start 11.12.", "kurz": "Grinding Gear Games hat auf der ExileCon den Vollrelease von Path of Exile 2 für den 11 Dezember 2026 angekündigt. Neu dabei sind die Klassen Shadow und Duelist sowie die fertigen Campaign-Acts fünf und sechs. Dazu kommt die League „Conquerors of Wraeclast“ mit Base- und Army-Building.", "zusammenfassung": "PC Gamer fasst die ExileCon-Keynote zu Path of Exile 2 Version 1.0 zusammen: Der Vollrelease nach rund zwei Jahren Early Access ist für den 11 Dezember 2026 datiert. Zwei neue Klassen starten mit: der Dolch- und Fallen-fokussierte Shadow mit Stealth sowie der schwertlastige Duelist. Shadow kann laut Studio als Assassin ascendieren oder die neue Ascendancy Infiltrator wählen; eine dritte Ascendancy ist später vorgesehen. Stealth verhindert, dass Monster den Charakter aus der Distanz sehen, setzt sich bei Kill zurück und interagiert mit Fallen, die aus dem Versteck erst beim Enthüllen auslösen. Die Campaign erhält Acts fünf und sechs inklusive Rückkehr nach Oriath und Einführung in die League-Mechanik. „Conquerors of Wraeclast“ bringt Base-Building, Armeen, Commanders und später fraktionsgebundene Atlas-Schlachten. Das Endgame strafft den Atlas-Skilltree stark, überarbeitet Gems und Passive Tree inklusive Jewel-Slots und ergänzt viele neue Bases sowie Uniques. Exakte Launch-Uhrzeit und weitere Ascendancy-Details können nach der laufenden ExileCon noch nachziehen.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/rpg/heres-whats-in-path-of-exile-2s-huge-1-0-release-coming-in-december/"}, "weitere_links": [{"name": "PC Gamer: Shadow-Klasse für PoE2 1.0", "url": "https://www.pcgamer.com/games/rpg/path-of-exile-2-announces-a-second-new-class-the-shadow-for-its-december-1-0-release/"}], "tags": ["Path of Exile 2", "ExileCon", "ARPG", "Grinding Gear Games"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:10.022Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.367Z"}, {"id": "2026-11-06-nvidia-11mio-diebstahl", "datum": "2026-11-06T16:32:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA", "GPU"], "kategorie": "Markt & Wirtschaft", "titel": "NVIDIA-Hardware im Wert von 11,4 Mio. Dollar bei Transport von Oakland nach Texas gestohlen", "schlagzeile": "11,4 Mio. $ NVIDIA-Hardware: Sechs Paletten verschwinden unterwegs", "kurz": "Die Polizei in Oakland untersucht den Diebstahl von sechs Paletten NVIDIA-Hardware im Wert von 11,4 Millionen US-Dollar. Ein Lkw mit Lebensmittel-Transport-Logo holte die Ladung am 29. August ab und verschwand; die Spur endete im San Bernardino County. Es gibt noch keine Festnahmen.", "zusammenfassung": "Laut VideoCardz und dem lokalen Sender ABC7 News ermittelt die Polizei von Oakland (Kalifornien) wegen eines Großdiebstahls von NVIDIA-Hardware. Sechs Paletten im deklarierten Wert von 11,4 Millionen US-Dollar sollten von Oakland nach Fort Worth in Texas. Am 29. August 2026 holte ein Lkw mit dem Logo einer Lebensmittel-Spedition die Ladung ab – danach verschwanden Fahrzeug und Fahrer. Ermittler verfolgten mehrere längere Zwischenstopps und verloren die Spur im San Bernardino County. Die Anzeige bei der Polizei erfolgte erst am 13. September. Welche genauen Produkte in den Paletten lagen (KI-Beschleuniger, komplette Systeme oder Consumer-GPUs), ist nicht öffentlich bestätigt; der Durchschnittswert liegt bei rund 1,9 Millionen Dollar pro Palette. UC-Berkeley-Professor Olaf Groth sagte ABC7, solche Chips seien im Ausland deutlich teurer und ein Sicherheitsrisiko. Parallel berichtete VideoCardz über frühere NVIDIA-bezogene Diebstähle in der Bay Area (über 7,5 Mio. Dollar 2025) und einen Fall in Brasilien mit gestohlenen ZOTAC RTX 5090. Bislang gibt es keine Festnahmen und keine Bestätigung, dass die Ware gefunden wurde.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/nvidia-shipment-worth-11-4-million-stolen-in-california-six-pallets-disappear-during-transport"}, "weitere_links": [{"name": "ABC7 News: $11.4M Nvidia cargo stolen from Oakland", "url": "https://abc7news.com/post/114-million-shipment-nvidia-cargo-stolen-oakland-calif/20018822/"}, {"name": "Wccftech: NVIDIA GPUs Worth $11.4 Million Stolen", "url": "https://wccftech.com/nvidia-cargo-heist-11-million-dollars-hardware-stolen-oakland-texas/"}], "tags": ["NVIDIA", "Diebstahl", "Oakland", "GPU"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:09.873Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.369Z"}, {"id": "2026-11-06-micron-fab-stop", "datum": "2026-11-06T15:30:00+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM"], "kategorie": "Speicher", "titel": "Micron pausiert laut Berichten den Bau einer RAM-Fabrik in Taiwan wegen Gewerkschaftsstreit", "schlagzeile": "Micron stoppt RAM-Fab-Bau in Taiwan – Streit mit Gewerkschaften", "kurz": "PCGH berichtet unter Berufung auf Bloomberg, Micron habe die Bauarbeiten an einer Halbleiter-Fab in Taoyuan gestoppt und die Ausbaupläne auf Eis gelegt. Hintergrund sei ein Konflikt mit taiwanesischen Gewerkschaften um Gewinnbeteiligung. Ein kompletter Ausstieg ist nicht bestätigt.", "zusammenfassung": "Laut PC Games Hardware und Bloomberg-Quellen vor Ort hat Micron die Bauarbeiten an einer geplanten Halbleiter-Fabrik in Taoyuan (Taiwan) gestoppt und will die Ausbaupläne pausieren. PCGH ordnet das Investitionsvolumen mit rund 4 Milliarden Euro ein. Der Schritt falle in einen länger andauernden Konflikt mit Gewerkschaften, die eine Beteiligung der Mitarbeiter an den gestiegenen Gewinnen fordern. In Taichung habe es vor zwei Wochen einen Kompromiss gegeben, dessen Akzeptanz unter den Arbeitern strittig sei; in Taoyuan liefen die Verhandlungen noch, inklusive eines symbolischen Streiks – dem ersten in Taiwans Halbleiterindustrie. Die Taoyuan Labour Union weist die Verantwortung von sich und betont, man wolle den Unternehmensgewinn nicht gefährden. Ob der Baustopp dauerhaft ist oder Druckmittel in den Verhandlungen, ist offen. Für PC-Käufer ist die Meldung relevant, weil zusätzliche RAM-Kapazität als Ausweg aus der Speicherknappheit gilt – und genau diese Kapazität hier stockt.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/RAM-Hardware-154108/News/Micron-stoppt-Fab-Ausbau-in-Taiwan-1559210/"}, "weitere_links": [], "tags": ["Micron", "RAM", "Taiwan", "Speicher"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.093Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.372Z"}, {"id": "2026-11-06-switch2-verkauf-minus37", "datum": "2026-11-06T15:00:00+01:00", "label": "News", "bereich": "games", "themen": ["Nintendo", "Switch 2"], "kategorie": "Konsolen", "titel": "Switch 2: Nintendo meldet 37,4 Prozent weniger Hardware-Verkäufe im Halbjahresvergleich", "schlagzeile": "Switch 2: 37 % weniger Verkäufe als im Rekord-Vorjahr – Software legt zu", "kurz": "Laut Nintendo-Geschäftszahlen und GameStar gingen die Switch-2-Sell-in-Zahlen von April bis September 2026 um 37,4 Prozent auf 6,49 Millionen zurück (Vorjahr 10,36 Mio.). Software legte um 18,8 Prozent zu; die Jahresprognose von 16,5 Millionen Geräten bleibt.", "zusammenfassung": "GameStar fasst Nintendos Halbjahreszahlen zusammen: Von April bis September 2026 verkaufte Nintendo 6,49 Millionen Switch-2-Konsolen an den Handel – 37,4 Prozent weniger als die 10,36 Millionen im Vorjahreszeitraum. Im ersten Quartal waren es 3,82 Millionen, von Juli bis September 2,67 Millionen. Der Vorjahresvergleich ist durch den Launch am 5. Juni 2025 und die aufgestaute Nachfrage verzerrt. Seit September ist die Switch 2 teurer (Europa offiziell 499,99 Euro). Nintendo nennt Speicherpreise, Wechselkurse und Ölpreise als Gründe für die Preisanpassung. Die Jahresprognose von 16,5 Millionen Geräten bis März 2027 bleibt laut GameStar und VGC unverändert. Switch-2-Software legte im Halbjahr um 18,8 Prozent auf 24,49 Millionen Einheiten zu; der Nettogewinn stieg um elf Prozent. VGC betont zudem, dass die Switch 2 kumuliert weiterhin klar vor Original-Switch und PS5 (launch-aligned) liegt. Es handelt sich um Sell-in, nicht zwingend um Endkunden-Verkäufe.", "quelle": {"name": "GameStar", "url": "https://www.gamestar.de/artikel/nintendo-switch-2-verkaufszahlen-rueckgang-preiserhoehung,3462594.html"}, "weitere_links": [{"name": "Nintendo IR: Financial Results Explanatory Material", "url": "https://www.nintendo.co.jp/ir/pdf/2026/261105_3e.pdf"}, {"name": "VGC: Switch 2 sales down 37%, still beating original", "url": "https://www.videogameschronicle.com/news/nintendo-switch-2-sales-have-dropped-37-but-its-still-comfortably-beating-the-original-console/"}], "tags": ["Nintendo", "Switch 2", "Verkäufe"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.282Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.373Z"}, {"id": "2026-11-06-rtx5070ti-doppel-msrp", "datum": "2026-11-06T13:38:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "NVIDIA"], "kategorie": "Grafikkarten", "titel": "GeForce RTX 5070 Ti erreicht in US-Shops fast das Doppelte der UVP", "schlagzeile": "RTX 5070 Ti knackt 1.340 Dollar – fast doppelte UVP in US-Shops", "kurz": "Nach RTX 5090 und 5080 zieht auch die RTX 5070 Ti stark an: Das günstigste erfasste Online-Angebot in den USA liegt bei 1.339,99 Dollar, teurere Modelle bei 1.499,99 Dollar. Die UVP beim Start lag bei 749 Dollar. NVIDIA hatte eine Abkündigung zuvor dementiert.", "zusammenfassung": "VideoCardz meldet, dass die GeForce RTX 5070 Ti in großen US-Online-Shops inzwischen deutlich über der UVP gehandelt wird. Die Karte startete im Februar 2025 mit 749 Dollar UVP; das günstigste erfasste Angebot liegt am 6. November 2026 bei 1.339,99 Dollar (etwa 79 Prozent über UVP). Einzelne Modelle bei B&H und Best Buy liegen bei rund 1.400 bis 1.499,99 Dollar – also nahe bzw. am doppelten Startpreis. Innerhalb von acht Tagen stieg der günstigste Track-Preis um 160 Dollar (von 1.179,99 am 29. Oktober). Genannte Beispiele: GIGABYTE AERO OC bei Newegg für 1.339,99 Dollar, ASUS PRIME OC und TUF GAMING OC bei B&H für 1.399,99 bzw. 1.499,99 Dollar. Im Januar 2026 hatte NVIDIA Abkündigungsgerüchte zur 5070 Ti dementiert; ASUS verwies damals auf Speicherknappheit. Die Karte ist weiterhin verfügbar, ein Produktionsstopp ist damit nicht belegt – aber die Preisspirale nach RTX 5090 und 5080 setzt sich bei der 5070 Ti fort.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/after-rtx-5090-and-rtx-5080-the-not-discontinued-geforce-rtx-5070-ti-now-reaches-twice-its-msrp"}, "weitere_links": [], "tags": ["RTX 5070 Ti", "NVIDIA", "Preise"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:09.960Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.374Z"}, {"id": "2026-11-06-asus-xg-core-9060xt", "datum": "2026-11-06T12:16:00+01:00", "label": "News", "bereich": "hardware", "themen": ["AMD", "GPU"], "kategorie": "Grafikkarten", "titel": "ASUS XG Core: externe Radeon RX 9060 XT LP 16 GB per USB4 für Laptops und Handhelds", "schlagzeile": "ASUS XG Core: externe RX 9060 XT LP 16 GB per USB4", "kurz": "ASUS stellt die XG Core vor: eine kompakte externe Grafiklösung mit Radeon RX 9060 XT LP 16 GB GDDR6 und USB4-Anschluss für kompatible Laptops, Mini-PCs und Handhelds wie ROG Ally X. Ein Preis wurde offiziell nicht genannt; ein schwedischer Shop listet laut TechPowerUp rund 1.207 Euro inkl. MwSt.", "zusammenfassung": "In einer Pressemitteilung, die TechPowerUp veröffentlicht, kündigt ASUS die XG Core an: eine externe Grafikeinheit mit AMD Radeon RX 9060 XT LP (RDNA 4) und 16 GB GDDR6. Die Box misst etwa 144 × 117 × 39 mm und verbindet sich per USB4 mit kompatiblen Hosts – laut ASUS auch Thunderbolt-3-Systeme sowie Handhelds wie ROG Ally X und ROG Xbox Ally X. HDMI und DisplayPort sind eingebaut; Tuning läuft über GPU Tweak III. ASUS bewirbt Gaming, Kreativarbeit und lokale KI-Workloads (etwa ComfyUI, LM Studio, Ollama). Ein offizieller Listenpreis fehlt in der Mitteilung; in den TechPowerUp-Kommentaren wird ein schwedischer Shop mit etwa 1.346 US-Dollar bzw. 1.207 Euro inkl. 25 Prozent MwSt. genannt – das ist kein bestätigter UVP. Ob und wann die Box in DE/AT erhältlich ist, bleibt offen.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354534/asus-announces-the-xg-core-radeon-rx-9060-xt-lp-16gb-gddr6"}, "weitere_links": [], "tags": ["ASUS", "RX 9060 XT", "eGPU", "USB4"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.164Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.374Z"}, {"id": "2026-11-06-medusa-point-6-8-kerne", "datum": "2026-11-06T11:32:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["AMD", "CPU"], "kategorie": "Prozessoren", "titel": "Weitere Zen-6-Medusa-Point-Samples: 6 und 8 Kerne in Lenovo-Geekbench-Einträgen", "schlagzeile": "Leak: Medusa Point 2/3 mit 6 und 8 Kernen taucht bei Lenovo auf", "kurz": "Nach dem 10-Kern-Sample sollen zwei weitere AMD-Zen-6-Medusa-Point-Engineering-Samples in Geekbench 7 aufgetaucht sein: 8 Kerne (2+6) und 6 Kerne (1+5), beide als Medusa Point 2/3 auf Lenovo-Systemen. Unbestätigt, Taktraten und Scores schwanken stark.", "zusammenfassung": "VideoCardz berichtet über zwei weitere Geekbench-7-Einträge zu AMD Zen 6 Medusa Point, diesmal mit 6 und 8 Kernen und dem Label Medusa Point 2/3. Beide Samples wurden auf Lenovo-Systemen getestet. Das 8-Kern-Sample (100-000002152-50_Y) hat 16 Threads in Clustern 2+6 und 8 MB L3; das 6-Kern-Sample (100-000001658-50_Y) 12 Threads in 1+5 und 4 MB L3. Beide teilen die CPU-ID Family 26 Model 224 Stepping 0 und unterscheiden sich damit vom 10-Kern-Medusa-Point-1-Sample. Geekbench-7-Werte: 8C späterer Lauf 2.889 / 15.099 (max. gemeldet 5,28 GHz), früherer Lauf deutlich schwächer; 6C 1.732 / 8.340 bei nur ~2,04 GHz. VideoCardz betont, dass Taktablesungen und Scores bei Engineering Samples stark schwanken und nicht final sind. Ein Debüt der Zen-6-Mobilchips wird rund um die CES 2027 erwartet. AMD hat die Samples nicht bestätigt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/amd-zen-6-medusa-point-2-3-spotted-with-6-and-8-cores-in-lenovos-geekbench-leak"}, "weitere_links": [], "tags": ["AMD", "Zen 6", "Medusa Point", "Leak"], "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Geekbench-7-Einträge von Engineering Samples auf Lenovo-Systemen, berichtet von VideoCardz. Taktraten und Scores schwanken stark zwischen Läufen. Kein finales Produkt, AMD hat nichts bestätigt."}, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.030Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.376Z"}, {"id": "2026-11-06-windows11-27h2", "datum": "2026-11-06T10:45:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Betriebssysteme", "titel": "Windows 11 27H2 soll erstmals seit drei Jahren den technischen Unterbau erneuern", "schlagzeile": "Windows 11 27H2: echtes Plattform-Update statt nur UI-Jahre", "kurz": "Dr. Windows berichtet mit Bezug auf The Verge: Version 27H2 soll 2027 den Kernel- und Treiber-Unterbau von Windows 11 erneuern – erstmals seit 24H2/25H2/26H2, die technisch gleich waren. Ein Windows 12 ist laut den Berichten für 2027 nicht geplant.", "zusammenfassung": "Laut Dr. Windows (Bezug: The Verge) steht Windows 11 im Jahr 2027 mit Version 27H2 ein Plattform-Update bevor. Seit 24H2 seien 25H2 und 26H2 beim technischen Unterbau (Kernel, Treibermodell und Basiselemente) identisch gewesen; neue Funktionen betrafen vor allem UI und austauschbare Komponenten. 27H2 soll diesen Unterbau erstmals seit drei Jahren ändern. Das kann Kompatibilitätsprüfungen nötig machen – besonders bei systemnaher Software wie Sicherheitsprodukten. Ob bestimmte Features künstlich an 27H2 gebunden werden, ist offen. Die Berichte betonen zugleich, dass damit kein Windows 12 für 2027 angekündigt wird; es bleibe bei Windows 11. Die Meldung bestätigt im Wesentlichen Pläne, die Microsoft schon früher skizziert hatte. The Verge selbst steckt hinter einer Paywall; die Kernaussage ist über Dr. Windows und Golem („kein Windows 12“) nachvollziehbar.", "quelle": {"name": "Dr. Windows", "url": "https://www.drwindows.de/news/windows-11-die-version-27h2-erneuert-den-technischen-unterbau"}, "weitere_links": [{"name": "Golem.de: Im nächsten Jahr kommt wohl kein Windows 12", "url": "https://www.golem.de/news/microsoft-im-naechsten-jahr-kommt-wohl-kein-windows-12-2611-214920.html"}], "tags": ["Windows 11", "27H2", "Microsoft"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.599Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.378Z"}, {"id": "2026-11-06-msi-claw-fsr41", "datum": "2026-11-06T10:34:00+01:00", "label": "News", "bereich": "hardware", "themen": ["AMD", "Handheld"], "kategorie": "Handhelds", "titel": "MSI will FSR 4.1 für den Claw A8 im Dezember per Hersteller-Treiber bringen", "schlagzeile": "MSI Claw A8: FSR 4.1 soll im Dezember per Hersteller-Treiber kommen", "kurz": "MSI bestätigt, dass der Claw A8 (Ryzen Z2 Extreme / Radeon 890M) AMD FSR Upscaling 4.1 per eigenem Grafiktreiber bekommen soll – Zieltermin Dezember 2026, abhängig von der Validierung. Ein aktueller Treiber behebt Render-Bugs, enthält FSR 4.1 aber noch nicht.", "zusammenfassung": "VideoCardz berichtet mit Bezug auf MSI: Der Handheld Claw A8 soll AMD FSR Upscaling 4.1 über einen Hersteller-Grafiktreiber erhalten. Als Ziel nennt MSI Dezember 2026, sofern die Validierung klappt. Der Claw A8 nutzt AMDs Ryzen Z2 Extreme mit Radeon 890M. AMD hatte FSR 4.1 für Ryzen Z2 Extreme und andere Handheld-APUs am 20. Oktober freigegeben; Standard-Adrenalin-Treiber unterstützen Handhelds offiziell nicht, deshalb müssen Hersteller wie MSI, ASUS oder Lenovo eigene Treiber ausliefern. Parallel ist bereits Treiber 32.0.32016.5 für den Claw A8 BZ2EM verfügbar: Er behebt falsche Schatten, Lichtfehler, FSR-Artefakte, Partikelprobleme und schwarze Quadrate – enthält aber noch kein FSR 4.1. Damit bestätigt MSI eine offizielle FSR-4.1-Umsetzung statt inoffizieller Mod-Treiber.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/msi-confirms-amd-fsr-4-1-upgrade-for-claw-a8-targets-december-release"}, "weitere_links": [], "tags": ["MSI", "Claw A8", "FSR 4.1", "Handheld"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T01:52:10.226Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T18:09:21.380Z"}, {"id": "2026-11-06-nvidia-dlss-override-19", "datum": "2026-11-06T08:30:00+01:00", "label": "News", "bereich": "software", "themen": ["NVIDIA", "DLSS"], "kategorie": "Software", "titel": "NVIDIA App: DLSS Override für 19 weitere Spiele, darunter Witcher 3 und PUBG", "schlagzeile": "NVIDIA App: DLSS Override für 19 weitere Spiele freigeschaltet", "kurz": "Ein Update der NVIDIA App ergänzt DLSS-Override-Profile für 19 weitere Titel. Darunter sind ältere Spiele wie The Witcher 3 und PUBG sowie kommende bzw. angekündigte Releases. Override erlaubt das Erzwingen neuerer DLSS-Modelle und -Modi, wo der Treiber es unterstützt.", "zusammenfassung": "TechPowerUp meldet das NVIDIA-App-Update 11.0.9.585 mit DLSS-Override-Unterstützung für 19 weitere Spiele sowie Optimal-Settings-Profilen für sechs Titel. Auf der Override-Liste stehen unter anderem Honeycomb: The World Beyond, WARDOGS, PUBG: Battlegrounds, Aniimo, 007 First Light, Active Matter, Enlisted, Dragon's Dogma 2, The Witcher 3: Wild Hunt, AION 2, Halloween: The Game, HOT WHEELS Infinite Rush, Silent Hill: Townfall, Control Resonant, Ace Combat 8: Wings of Theve, Dynasty Warriors 3 Complete Edition Remastered, Star Wars: Galactic Racer, Gears of War: E-Day und Clive Barker's Hellraiser: Revival. Optimal Settings kommen unter anderem für AION 2, Aniimo, Control Resonant, EA Sports FC 27, Gears of War: E-Day und Star Wars: Galactic Racer. Einige Titel waren laut TechPowerUp bereits in früheren Builds gelistet; NVIDIA erklärt die Doppelungen nicht und nennt auch nicht pro Spiel, welche Override-Optionen greifen. DLSS Override liegt unter Grafik-Programmeinstellungen und erlaubt neuere DLSS-Modelle oder Modi wie DLAA, wenn ein Spiel sie selbst nicht anbietet. Das Changelog erwähnt sonst nur allgemeine Stabilitäts- und Sicherheitsfixes.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354528/nvidia-app-update-adds-dlss-override-support-to-19-more-games"}, "weitere_links": [{"name": "VideoCardz: 19 DLSS-Override-Profile", "url": "https://videocardz.com/newz/nvidia-adds-19-dlss-override-profiles-including-several-upcoming-pc-games"}], "tags": ["NVIDIA", "DLSS", "NVIDIA App", "Treiber"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.904Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T07:49:12.921Z"}, {"id": "2026-11-06-unity-buyout-gespraeche", "datum": "2026-11-06T08:00:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Unity"], "kategorie": "Games", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Reuters-Bericht über vorläufige Gespräche, aufgegriffen von PC Gamer, Insider Gaming und IGN. Kein abgeschlossener Deal; Unity prüft Optionen mit einer Bank. Zahlen und Ausgang offen."}, "ursprungsquelle": "Reuters", "titel": "Berichte: Silver Lake und saudischer PIF sollen vorläufig über Unity-Übernahme gesprochen haben", "schlagzeile": "Leak: Silver Lake und PIF sollen über Unity-Kauf sprechen", "kurz": "Laut einem Reuters-Bericht haben Silver Lake und der saudische Public Investment Fund nach dem EA-Deal vorläufige Gespräche über eine Übernahme von Unity geführt. In Zweitberichten kursieren Bewertungsgrößen um etwa 25 Milliarden US-Dollar. Ein Abschluss ist nicht sicher; die Aktien reagierten auf die Gerüchte.", "zusammenfassung": "Mehrere Medien berichten unter Berufung auf Reuters, dass Silver Lake und der saudische Public Investment Fund vorläufige Gespräche über eine mögliche Übernahme von Unity geführt haben. Dieselben Akteure waren kürzlich am großen EA-Deal beteiligt; Silver Lake hält Berichten zufolge bereits einen Minderheitsanteil an Unity. Insider Gaming nennt eine Bewertung in der Größenordnung von etwa 25 Milliarden US-Dollar und schreibt, Unity prüfe Optionen mit einer Bank. Es handelt sich ausdrücklich um frühe Gespräche; ein Deal ist nicht garantiert. Allein die Gerüchte hätten den Aktienkurs spürbar anziehen lassen, in einem Bericht ist von nahezu 15 Prozent die Rede. Unity ist vor allem für die gleichnamige Engine bekannt und steckt hinter zahlreichen großen Spielen. Die Lage bleibt unbestätigt, bis Unity oder die Investoren offiziell Stellung nehmen. Zuverlässigkeit: mittel wegen Reuters als Ursprung, aber vorläufigem Charakter.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/saudi-arabia-owns-ea-and-according-to-a-reuters-report-unity-is-next/"}, "weitere_links": [{"name": "Insider Gaming: Silver Lake und PIF sollen Unity wollen", "url": "https://insider-gaming.com/saudi-silver-lake-pif-unity-acquisition-buyout/"}, {"name": "IGN: Silver Lake und PIF sollen Unity anstreben", "url": "https://www.ign.com/articles/after-buying-ea-silver-lake-and-pif-are-reportedly-now-seeking-to-acquire-gaming-software-provider-unity"}], "tags": ["Unity", "Silver Lake", "PIF", "Übernahme", "Leak"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.844Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T07:49:12.922Z"}, {"id": "2026-11-06-amd-pc-markt-2027", "datum": "2026-11-06T07:30:00+01:00", "label": "News", "bereich": "hardware", "themen": ["AMD", "RAM"], "kategorie": "Markt & Wirtschaft", "titel": "AMD plant 2027 mit zweistelligem Rückgang der PC-Auslieferungen wegen hoher Speicherpreise", "schlagzeile": "AMD: PC-Markt soll 2027 zweistellig schrumpfen – RAM-Preise belasten", "kurz": "Lisa Su sagte im Earnings Call, AMD plane für 2027 mit einem zweistelligen Rückgang der PC-Stückzahlen weltweit. Grund seien höhere Speicher- und Komponentenpreise, die die Nachfrage belasten. Es handelt sich um eine Planungsannahme für den Gesamtmarkt, nicht um bereits gemessene Zahlen.", "zusammenfassung": "Im Earnings Call zum dritten Quartal 2026 erklärte AMD-Chefin Lisa Su, der Konzern plane für 2027 mit einem Rückgang der PC-Markt-Stückzahlen um einen zweistelligen Prozentsatz. Als Ursache nennt sie höhere Speicher- und Komponentenkosten, die Desktop-PCs und Notebooks verteuern und die Nachfrage belasten. AMD will Sell-in an Sell-through angleichen, um Lagerbestände bei Kunden und im Handel gesund zu halten. Trotz der erwarteten Marktschwäche will AMD laut Su über die Ryzen-Roadmap und ein wachsendes Commercial-Geschäft besser abschneiden als der Gesamtmarkt. Parallel erwartet AMD, dass der Data-Center-Bereich 2027 mehr als 80 Prozent des Konzernumsatzes ausmacht. Im Client-Geschäft stieg der Umsatz im dritten Quartal um 7 Prozent auf 2,9 Milliarden US-Dollar; Gaming fiel um 40 Prozent auf 773 Millionen, vor allem wegen schwächerer Semi-Custom-Verkäufe im Konsolenzyklus. PCGH betont, dass es sich um eine Planungsannahme handelt und nicht um eine schon gemessene Marktentwicklung. VideoCardz greift dieselbe Earnings-Call-Aussage auf. RAM-Preise sind in Google Trends DE aktuell kaum gesucht, die Meldung bleibt trotzdem relevant für Hardware-Käufer.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/AMD-PC-Markt-2027-Prognose-RAM-Preise-Lisa-Su-1559144/"}, "weitere_links": [{"name": "VideoCardz: AMD erwartet zweistelligen PC-Markt-Rückgang 2027", "url": "https://videocardz.com/newz/amd-prepares-for-even-weaker-pc-market-in-2027-expects-double-digit-decline-in-shipments"}], "tags": ["AMD", "Lisa Su", "PC-Markt", "RAM", "Data Center"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.598Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T07:49:12.923Z"}, {"id": "2026-11-06-rx9070xt-clustered-geometry", "datum": "2026-11-06T07:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["DirectX", "GPU", "PC-Gaming"], "kategorie": "GPU", "titel": "Microsoft Agility SDK: größtes DirectX-Raytracing-Update seit 2018 – Clustered Geometry und PTLAS", "schlagzeile": "DirectX: größtes Raytracing-Update seit 2018 – Clustered Geometry", "kurz": "Microsoft hat mit dem Agility SDK 1.722 Preview das umfangreichste DirectX-Raytracing-Update seit 2018 veröffentlicht. Clustered Geometry und Partitioned TLAS sollen den Aufbau von Raytracing-Strukturen massiv beschleunigen und den Speicherbedarf senken. In unabhängigen Demo-Messungen von PCGH steigt eine RX 9070 XT von 1,7 auf 91 Fps; Spiele müssen die Technik erst einbauen.", "zusammenfassung": "Microsoft bezeichnet die neuen DirectX-Raytracing-Funktionen im Agility SDK 1.722 Preview als umfangreichste Erweiterung seit der Einführung von DXR im Jahr 2018. Kernpunkte sind Clustered Geometry (CLAS), Partitioned Top-Level Acceleration Structures (PTLAS) und indirekte Acceleration-Structure-Builds. Clustered Geometry zerlegt Geometrie in wiederverwendbare Cluster mit bis zu 256 Dreiecken; das soll den Aufbau von Raytracing-Strukturen in detailreichen, dynamischen Szenen stark beschleunigen und präzisere Reflexionen sowie Schatten ohne teure Proxy-Geometrie ermöglichen. PTLAS soll erlauben, nur veränderte Szenenbereiche zu aktualisieren. Laut ComputerBase und Microsoft stieg in einem Beispiel auf einer Radeon RX 9070 die Bildrate von 1,2 auf 79 Fps, der Struktur-Speicherbedarf sank von rund 7519 auf 774 MB; Scratch-Speicher stieg dagegen stark. PC Games Hardware hat die Demo D3D12RaytracingClusteredGeometry zusätzlich unabhängig gemessen: Eine RX 9070 XT ging bei 1600×920 von 1,7 auf 91 Fps (etwa Faktor 54), der BVH-Speicher von 7518 auf 771 MiB; eine RTX 5080 von 1,4 auf 310 Fps. Ohne Clustered Geometry lag die Radeon leicht vorn, mit dem Feature war die RTX 5080 deutlich schneller. Die Preview läuft auf GeForce RTX, Radeon RX 9000 sowie Intel Arc B-Serie und unterstützten Core-Ultra-iGPUs; neue Hardware-Features sind nicht nötig, Treiberunterstützung schon. Bestehende Spiele profitieren nicht automatisch: Studios müssen die APIs einbauen. Advanced Shader Delivery und weitere Agility-SDK-1.620-Funktionen gehören zum gleichen Release-Paket, sind aber kein Teil der Raytracing-Demo-Zahlen.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/gaming/directx-12-microsoft-bringt-groesstes-raytracing-update-seit-2018.100099/"}, "weitere_links": [{"name": "Microsoft DirectX Blog: Agility SDK 1.620 / 1.722 Preview", "url": "https://devblogs.microsoft.com/directx/agilitysdk-1-620-retail-and-1-722-preview/"}, {"name": "Microsoft: Clustered Geometry und PTLAS Preview", "url": "https://devblogs.microsoft.com/directx/clas-ptlas-preview/"}, {"name": "PCGH: RX 9070 XT / RTX 5080 in Clustered-Geometry-Demo", "url": "https://www.pcgameshardware.de/Radeon-RX-9070-XT-Grafikkarte-281023/News/DirectX-Raytracing-Clustered-Geometry-RTX-5080-Benchmark-1559145/"}], "tags": ["Radeon", "RX 9070 XT", "DirectX", "Raytracing", "RTX 5080"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.389Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-13T07:49:12.923Z"}, {"id": "2026-11-05-asrock-rx7900-vbios", "datum": "2026-11-05T20:07:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "AMD"], "kategorie": "GPU", "titel": "ASRock-VBIOS für RX 7900 XT/XTX: Besitzer melden bricked GPUs nach offiziellem Update", "schlagzeile": "ASRock-VBIOS brickt RX 7900 XT/XTX – Downloads offenbar zurückgezogen", "kurz": "Nach dem offiziellen ASRock-VBIOS von Ende Oktober melden Besitzer von Radeon RX 7900 XT und XTX Phantom Gaming sowie Taichi, dass ihre Karten nicht mehr starten. Das Update sollte AMD-SN-6023 absichern und lief über ASRVBFlash 1.0.5. HTTP-Downloads sind laut Berichten inzwischen 404; einige Karten ließen sich nur mit externem EEPROM-Programmer retten.", "zusammenfassung": "ASRock hatte Ende Oktober neue VBIOS-Dateien für zehn Radeon-RX-7000-Karten veröffentlicht, darunter als Teil der AMD-Sicherheitsmaßnahme AMD-SN-6023. Mehrere Besitzer berichten nun, dass nach dem Flash mit ASRVBFlash 1.0.5 das System mit installierter GPU keinen POST mehr schafft. Betroffen genannt werden RX 7900 XT Phantom Gaming sowie RX 7900 XTX Phantom Gaming und Taichi inklusive White-Edition. Das Problem tritt Berichten zufolge auf unterschiedlichen Mainboards auf, etwa von ASRock und MSI. VideoCardz dokumentiert den Ablauf: das Tool prüft Kompatibilität, Windows startet neu, danach bootet der Rechner mit der Karte nicht mehr. Mindestens zwei Nutzer haben ihre RX 7900 XTX Phantom Gaming mit externen EEPROM-Programmern wiederhergestellt, darunter ein T48 mit Testclip. Die Oktober-Downloads sollen über HTTP inzwischen mit 404 antworten, während FTP-Links teilweise noch funktionieren. Ein Nutzer in Japan erhielt laut Reddit von ASRock Support die Zusage, der Schaden falle unter die Garantie; eine öffentliche Firmenaussage oder ein offizielles Recovery-Verfahren gibt es laut VideoCardz und Guru3D noch nicht. Bis ASRock klarstellt und eine korrigierte Firmware liefert, sollten Besitzer der genannten Modelle die Oktober-Firmware nicht installieren. Quelle ist VideoCardz, ergänzend Guru3D.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/asrock-radeon-rx-7900-xt-xtx-owners-report-bricked-gpus-after-official-vbios-update"}, "weitere_links": [{"name": "Guru3D: ASRock RX-7000-VBIOS und Brick-Berichte", "url": "https://www.guru3d.com/story/asrock-radeon-rx-7000-vbios-update-draws-reports-of-bricked-cards/"}], "tags": ["ASRock", "Radeon", "RX 7900", "VBIOS", "AMD"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.535Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T19:17:36.303Z"}, {"id": "2026-11-05-gog-galaxy-linux-2027", "datum": "2026-11-05T19:28:00+01:00", "label": "News", "bereich": "games", "themen": ["Linux", "GOG"], "kategorie": "Games", "titel": "GOG Galaxy kommt 2027 neu – mit voller Linux-Unterstützung", "schlagzeile": "GOG Galaxy 2027: neuer Client mit voller Linux-Unterstützung", "kurz": "Beim ersten GOG Showcase hat GOG bestätigt, dass 2027 ein neuer Galaxy-Client mit voller Linux-Unterstützung erscheint. Parallel wird der Client für Windows und Mac überarbeitet. Galaxy bleibt optional; Offline-Installer bleiben erhalten.", "zusammenfassung": "GamingOnLinux berichtet vom ersten GOG Showcase: 2027 soll ein komplett neuer GOG-Galaxy-Client für alle Plattformen erscheinen, erstmals mit voller Linux-Unterstützung. GOG hatte gegenüber GamingOnLinux schon im Juli an dem Vorhaben gearbeitet; nun ist der Zeitrahmen öffentlich. Laut GOG-Statement soll der Client auf Windows und Mac einfacher und schneller werden und die Bibliothek übersichtlicher darstellen. Die Kernzusage bleibt: Galaxy ist optional, Spiele lassen sich weiter über Offline-Installer herunterladen und behalten. Interessenten können sich auf der GOG-Anniversary-Seite für die Beta vormerken, sobald sie startet. Zusätzlich arbeitet GOG an GOG Social, einer modernisierten Community-Funktion mit Threads, Medien und spielebezogenen Tags. Weitere Feature-Details zum Linux-Client nennt der Bericht nicht; spekuliert wird hier nicht.", "quelle": {"name": "GamingOnLinux", "url": "https://www.gamingonlinux.com/2026/11/a-new-gog-galaxy-is-coming-in-2027-with-full-linux-support/"}, "weitere_links": [], "tags": ["GOG", "Galaxy", "Linux", "Launcher"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.787Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T19:17:36.304Z"}, {"id": "2026-11-05-medusa-point-gb7", "datum": "2026-11-05T18:34:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["AMD", "CPU"], "kategorie": "CPU", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Geekbench-7-Eintrag eines Engineering Samples (100-000001713-32_Y) auf Lenovo-Plattform, berichtet von VideoCardz und TechPowerUp via HXL. Taktraten wirken unplausibel (rund 2,0 GHz). Kein finales Produkt, AMD hat nichts bestätigt."}, "ursprungsquelle": "Geekbench via HXL", "titel": "AMD Zen-6 Medusa Point taucht in Geekbench 7 auf: 10 Kerne, Single-Core über 9950X3D-Schnitt", "schlagzeile": "Leak: Medusa Point in Geekbench 7 – 10C ES schlägt 9950X3D in SC?", "kurz": "Ein unbestätigtes Geekbench-7-Ergebnis zeigt ein AMD-Medusa-Point-Engineering-Sample mit 10 Kernen und 20 Threads. Der Single-Core-Wert liegt bei 3100 Punkten und damit knapp über dem Schnitt des Ryzen 9 9950X3D. Die gemeldeten Taktraten um 2,0 GHz wirken für ein finales Produkt unplausibel.", "zusammenfassung": "VideoCardz und TechPowerUp berichten über einen Geekbench-7-Eintrag des Engineering Samples 100-000001713-32_Y auf einer Lenovo-Plattform. Genannt werden 10 Kerne und 20 Threads in zwei Clustern mit 4 plus 6 Kernen sowie 16 MB L3-Cache. Der Single-Core-Score liegt bei 3100 Punkten und damit laut VideoCardz etwa 1,6 Prozent über dem Durchschnitt des Ryzen 9 9950X3D mit 3051 Punkten. Multi-Core kommt auf 18313 Punkte. Base- und Maximalfrequenz werden mit rund 2,0 GHz bzw. 1996 MHz angegeben; das wirkt für Serientaktraten unglaubwürdig und gilt als typisches ES- bzw. Fehlablesungs-Artefakt. TechPowerUp beschreibt die Cluster als mögliche Zen-6- und Zen-6c-Mischung und nennt AVX-512-Unterstützung im Listing. Es handelt sich nicht um ein finales Produkt; Spezifikationen, Taktraten und Erscheinungsdatum sind offen. Frühere Geekbench-6-Werte desselben Produkts sind wegen anderer Workloads nicht direkt vergleichbar. Zuverlässigkeit: mittel, weil nur ein öffentliches Benchmark-Listing über Leaker-Kanäle vorliegt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/amd-zen-6-medusa-point-appears-in-first-geekbench-7-leak-beats-ryzen-9-9950x3d-in-single-core-test"}, "weitere_links": [{"name": "TechPowerUp: Medusa Point 10C/20T in Geekbench", "url": "https://www.techpowerup.com/354504/amd-medusa-point-with-10-core-20-thread-cpu-configuration-surfaces"}], "tags": ["AMD", "Zen 6", "Medusa Point", "Geekbench", "Leak"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.472Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.932Z"}, {"id": "2026-11-05-switch2-keine-preiserhoehung", "datum": "2026-11-05T18:30:00+01:00", "label": "News", "bereich": "games", "themen": ["Nintendo", "Switch 2"], "kategorie": "Games", "titel": "Nintendo schließt weitere Switch-2-Preiserhöhung aus – trotz schwächerer Konsolenverkäufe", "schlagzeile": "Nintendo: Keine weitere Preiserhöhung für die Switch 2 geplant", "kurz": "Nintendo-Präsident Shuntaro Furukawa schließt weitere Preiserhöhungen für die Switch 2 aus. Das Unternehmen sieht sich bei Speicherchips ausreichend versorgt. Gleichzeitig berichten Medien von sinkenden Konsolenverkäufen und Gewinnrückgang im jüngsten Quartal.", "zusammenfassung": "Bei der Vorstellung der aktuellen Geschäftszahlen erklärte Nintendo-Präsident Shuntaro Furukawa laut PC Games, Eurogamer, VGC und IGN, dass keine weitere Preiserhöhung für die Switch 2 geplant sei. Nintendo habe sich ausreichend Speicherkapazitäten gesichert und sehe derzeit keinen Grund für eine erneute Anpassung. Zuvor hatte Nintendo die Switch-2-Preise bereits angehoben, unter anderem um 50 US-Dollar bzw. 30 Euro in mehreren Regionen. IGN zitiert Bloomberg mit einem operativen Gewinnrückgang von 16 Prozent auf 73,9 Milliarden Yen im Quartal bis Ende September und nennt 2,67 Millionen verkaufte Switch-2-Einheiten in diesem Zeitraum. VGC spricht von einem etwa 37-prozentigen Rückgang der Switch-2-Verkäufe im gleichen Berichtskontext, während Nintendo betont, die Switch 2 verkaufe sich weiterhin besser als der Vorgänger im Vergleichszeitraum. Bis Ende September seien insgesamt rund 26 Millionen Switch-2-Konsolen verkauft worden. Die Prognosen für das laufende Geschäftsjahr behält Nintendo laut PC Games bei. Speicherknappheit bleibt branchenweit ein Thema; Nintendo positioniert sich hier anders als jüngste PS5- und Xbox-Preiserhöhungen.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/Nintendo-Switch-2-Konsolen-280469/News/Preiserhoehung-Geschaeftsbericht-Shuntaro-Furukawa-1559115/"}, "weitere_links": [{"name": "IGN: Nintendo schließt weitere Switch-2-Preiserhöhungen aus", "url": "https://www.ign.com/articles/nintendo-rules-out-further-switch-2-price-rises-as-console-sales-and-profit-fall"}, {"name": "Eurogamer: No plans for more Switch 2 price hikes", "url": "https://www.eurogamer.net/nintendo-switch-2-no-plans-for-more-price-hikes"}, {"name": "VGC: Nintendo not considering Switch 2 price hike", "url": "https://www.videogameschronicle.com/news/nintendo-says-it-is-not-considering-a-switch-2-price-hike/"}], "tags": ["Nintendo", "Switch 2", "Preis", "Furukawa"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.728Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.933Z"}, {"id": "2026-11-05-dlss5-hogwarts-legacy", "datum": "2026-11-05T18:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA", "DLSS", "GPU"], "kategorie": "GPU", "titel": "Hogwarts Legacy erhält DLSS 5 mit 3D-Guided Neural Rendering auf GeForce RTX 50", "schlagzeile": "DLSS 5 Neural Rendering jetzt in Hogwarts Legacy", "kurz": "Seit dem 5 November 2026 unterstützt Hogwarts Legacy auf dem PC NVIDIA DLSS 5 mit 3D-Guided Neural Rendering. Das Feature braucht eine GeForce RTX 50 und einen aktuellen Game-Ready-Treiber; in den Display-Einstellungen gibt es den Schalter „Neural Rendering“. Marketing-FPS-Zahlen sind kein Alltagsversprechen.", "zusammenfassung": "NVIDIA und Portkey Games melden, dass Hogwarts Legacy auf dem PC DLSS 5 mit 3D-Guided Neural Rendering erhalten hat. Die Technik soll Beleuchtung und Materialdetails KI-gestützt anreichern und dabei Geometrie sowie Texturen der Engine als Grundlage behalten; Entwickler können das Ergebnis über Artist-Controls steuern. Voraussetzung laut Support-Artikel: eine GeForce RTX 50 Serie sowie GeForce Game Ready Driver 616.64 oder neuer. Aktivierung unter Display-Einstellungen: Upscale Type auf NVIDIA DLSS, dann Neural Rendering einschalten; Shortcut Shift+Alt+B. Unterstützte Stores: Steam, Epic Games Store und Windows Store. Laut NVIDIA-Blog vom 5 November 2026 folgt War Thunder mit DLSS 5 Mitte November, Where Winds Meet am 23 November. Das Feature ist an RTX 50 bzw. passende Cloud-/Spark-Pfade gebunden und ersetzt kein klassisches Upscaling allein. FPS-Marketing aus Demos übernehmen wir nicht als Praxisversprechen.", "quelle": {"name": "NVIDIA GeForce", "url": "https://www.nvidia.com/en-us/geforce/news/hogwarts-legacy-war-thunder-dlss-5-3d-guided-neural-rendering/"}, "weitere_links": [{"name": "Portkey Games: DLSS 5 in Hogwarts Legacy aktivieren", "url": "https://portkeygamessupport.wbgames.com/hc/en-us/articles/56349775286419-Enabling-NVIDIA-DLSS-5-Neural-Rendering-in-Hogwarts-Legacy-PC-Steam-EGS-or-Windows-PC"}, {"name": "NVIDIA Blog: GFN Thursday Hogwarts DLSS 5", "url": "https://blogs.nvidia.com/blog/geforce-now-thursday-hogwarts-legacy-dlss-5/"}], "tags": ["NVIDIA", "DLSS 5", "Hogwarts Legacy", "RTX 50", "Neural Rendering"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-07T07:51:10.079Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.935Z"}, {"id": "2026-11-05-xbox-pc-app-60", "datum": "2026-11-05T18:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Xbox", "Windows"], "kategorie": "Software", "titel": "Xbox-PC-App: Microsoft verspricht bis zu 60 Prozent schnelleren Start für Insiders", "schlagzeile": "Xbox-PC-App startet bis zu 60 % schneller – zuerst für Insider", "kurz": "Xbox-Insider können ab dem 05.11.2026 eine überarbeitete Xbox-PC-App testen. Microsoft spricht von einem bis zu 60 Prozent schnelleren Start sowie spürbar flotteren Seiten und Fenstern. Parallel rollt ein aufgefrischtes Web- und Cloud-Gaming-Erlebnis an weitere Spieler aus.", "zusammenfassung": "Jason Beaumont, VP Xbox Experiences, hat am 05.11.2026 auf Xbox Wire eine schnellere und übersichtlichere Xbox-Erfahrung für PC, Web und Cloud angekündigt. Xbox-Insider sollen die aktualisierte Xbox-PC-App ab sofort nutzen können. Laut Microsoft-Tests startet die App bis zu 60 Prozent schneller; Seiten wie Home, Store und Game Pass laden bis zu 50 Prozent schneller, In-App-Fenster öffnen sich bis zu 65 Prozent schneller. Die Werte hängen laut Hinweis von Gerät, Netz, Konfiguration und Nutzung ab. Die Bibliothek bekommt einfachere Navigation, neue Filter und bessere Sortierung. Freunde und Social-Funktionen rücken in die Hauptnavigation. Die Suche deckt Spiele inklusive installierter Titel und Add-ons sowie Personen ab. Optisch gibt es überarbeitete Spielkarten, Home, Einstellungen und Animationen. Das bereits zuvor für Insider gezeigte Web-Erlebnis für Xbox Cloud Gaming soll in den kommenden Wochen automatisch an mehr Spieler gehen; wer früher testen will, kann play.xbox.com aufrufen. Dort gibt es einen Library-Tab für Cloud-Spiele (gekauft und Game Pass), einen Desktop-Modus für größere Bildschirme sowie Dunkel-/Hellmodus und fünf High-Contrast-Themes. Ein ähnlicher Refresh beginnt auch bei Cloud-Apps auf unterstützten TVs und VR-Headsets. Wer noch kein Insider ist, kann über den Xbox Insider Hub für Series X|S, Xbox One oder Windows beitreten. The Verge, Neowin und IGN greifen die Ankündigung auf.", "quelle": {"name": "Xbox Wire", "url": "https://news.xbox.com/en-us/2026/11/05/a-faster-simpler-xbox-experience-is-coming-to-pc-web-and-cloud/"}, "weitere_links": [{"name": "The Verge: Redesign der Xbox-PC-App", "url": "https://www.theverge.com/news/1027353/microsoft-new-xbox-pc-app-redesign"}, {"name": "IGN: Xbox-PC-App laut Microsoft 60 % schneller", "url": "https://www.ign.com/articles/microsoft-updates-xbox-pc-app-says-its-60-faster"}, {"name": "Neowin: Redesign und schnellere Starts", "url": "https://www.neowin.net/news/microsoft-unveils-redesigned-xbox-pc-app-already-60-faster-when-launching/"}], "tags": ["Xbox", "Windows", "Game Pass", "Cloud Gaming", "Microsoft"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T19:32:48.366Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.936Z"}, {"id": "2026-11-05-nova-lake-h-foto", "datum": "2026-11-05T16:37:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["CPU", "Intel"], "kategorie": "CPU", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Foto von Leaker momomo_us (@momomo_us / 188号); Jaykihn antwortete auf Nachfrage mit „Yes“ zur 4+8+4-Konfiguration. VideoCardz konnte den Ursprung des zugeschnittenen Bildes nicht nachverfolgen. Intel hat nichts bestätigt; Taktfrequenzen unbekannt."}, "ursprungsquelle": "momomo_us (@momomo_us) auf X", "titel": "Leak: Foto soll unreleasedes Intel-Nova-Lake-H-Package mit Multi-Tile-Design zeigen", "schlagzeile": "Leak: Zeigt dieses Foto schon Intels Nova Lake-H mit 16 Kernen?", "kurz": "Ein von momomo_us geteiltes Foto soll ein noch unveröffentlichtes Intel-Prozessorpackage mit mehreren sichtbaren Silicon-Tiles zeigen. Jaykihn bestätigte auf Nachfrage eine Nova-Lake-H-Konfiguration mit 4+8+4 Kernen. Intel hat nichts bestätigt; der Bildursprung bleibt unklar.", "zusammenfassung": "Der Hardware-Leaker momomo_us (188号) hat am 05.11.2026 auf X ein zugeschnittenes Foto geteilt, das laut VideoCardz ein noch unveröffentlichtes Intel-Prozessorpackage mit mehreren sichtbaren Silicon-Tiles zeigen soll. VideoCardz konnte den industriellen oder Embedded-Mainboard-Ursprung des Bildes nicht nachverfolgen; sichtbar ist nur das Package. Auf die Frage, ob es sich um Nova Lake-H mit 4+8+4-Konfiguration handelt, antwortete der Leaker Jaykihn mit „Yes“. In einem Update nannte momomo_us laut VideoCardz 16 CPU-Kerne, 4 Xe-GPU-Kerne und 18 MB Cache. Diese Kernzahl passt zur kolportierten Core Ultra 9 4970H mit 4+8+4, also 16 CPU-Kernen. In der VideoCardz-Tabelle steht für die gerüchtete 4970H allerdings 12 Xe3P-Grafikkerne – das weicht von momomos Angabe „4 Xe“ ab; welche GPU-Angabe zutrifft, ist offen. Ob das abgebildete Exemplar speziell die 4970H ist, bleibt unklar; Taktraten nennt VideoCardz nicht. Zum Vergleich nutzen mehrere Panther-Lake-H-Modelle ebenfalls 4+8+4. TechPowerUp und Wccftech greifen den Leak auf. Intel hat die Angaben nicht bestätigt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/intel-core-ultra-4000-nova-lake-h-processor-has-been-pictured-featuring-16-core-design"}, "weitere_links": [{"name": "TechPowerUp: Nova Lake-H SoC aufgetaucht", "url": "https://www.techpowerup.com/354506/intel-core-ultra-4000-series-nova-lake-h-soc-surfaces"}, {"name": "Wccftech: Nova Lake-H mit Six-Tile-Setup", "url": "https://wccftech.com/intel-nova-lake-h-smiles-for-the-camera-reveals-a-six-tile-setup/"}], "tags": ["Intel", "Nova Lake", "Core Ultra 4000", "CPU", "Leak"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T19:32:48.237Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.937Z"}, {"id": "2026-11-05-gta6-39-screenshots", "datum": "2026-11-05T16:34:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Games", "titel": "Rockstar veröffentlicht rund 39 neue offizielle GTA-6-Screenshots – zwei Wochen bis zum US-Start", "schlagzeile": "GTA 6: Rockstar zeigt 39 neue Screenshots – zwei Wochen bis Launch", "kurz": "Rockstar Games hat rund 39 neue offizielle Screenshots zu Grand Theft Auto VI veröffentlicht. Anlass ist der Countdown: in den USA stehen noch etwa zwei Wochen bis zum Start am 19.11.2026. Die Bilder zeigen unter anderem Szenen aus Vice City bzw. Leonida sowie Jason und Lucia.", "zusammenfassung": "Rockstar Games hat offiziell eine größere Ladung neuer Screenshots zu Grand Theft Auto VI freigegeben. IGN und weitere Medien sprechen von 39 neuen Bildern zum Markieren der letzten zwei Wochen vor dem US-Launch. Der US-Starttermin 19.11.2026 wird in der Berichterstattung als Bezugspunkt genannt. Laut IGN, IGN Deutschland und PC Gamer sind unter den Motiven Vice-City- bzw. Leonida-Szenen, die Protagonisten Jason und Lucia, Crime- und Nightlife-Momente sowie Details wie Tänzer, Kampfhunde und sehr detailreiche Hautporen. Die Screenshots stammen von Rockstar bzw. der offiziellen Website und dem Rockstar-X-Kanal; es handelt sich um bestätigte Marketing-Bilder, nicht um Leaks. Inhalte über das hinaus, was die Quellen beschreiben, werden hier nicht spekuliert. Google Trends DE zeigt GTA 6 mit Wert 60 als höchsten der verglichenen Begriffe der letzten sieben Tage; AT liegt bei 41.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/rockstar-games-releases-39-new-gta-6-screenshots-to-celebrate-two-weeks-from-launch"}, "weitere_links": [{"name": "IGN Deutschland: 39 neue GTA-6-Screenshots", "url": "https://de.ign.com/grand-theft-auto-vi/157022/rockstar-games-veroffentlicht-39-neue-screenshots-zu-gta-6-um-die-letzten-zwei-wochen-bis-zum-start"}, {"name": "PC Gamer: Launch-Screenshots mit Tänzern, Kampfhunden und Poren", "url": "https://www.pcgamer.com/games/grand-theft-auto/rockstar-drops-a-pile-of-new-gta-6-launch-screenshots-featuring-dancers-combat-dogs-and-so-many-pores/"}, {"name": "Rockstar Games (offizielle Seite)", "url": "https://www.rockstargames.com/"}], "tags": ["GTA 6", "Rockstar", "Screenshots", "Launch"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.663Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.937Z"}, {"id": "2026-11-05-discord-native-windows", "datum": "2026-11-05T16:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows", "Discord"], "kategorie": "Software", "titel": "Discord baut Windows-Client in Rust neu: Early Build mit rund 290 MB RAM statt Electron-Gigabytes", "schlagzeile": "Discord verlässt Electron: Rust-Client soll RAM-Hunger beenden", "kurz": "Discord will den Windows-Desktop-Client von Electron auf eine native Rust-App mit GPUI umstellen. Ein früher Build namens Discord Phoenix zeigt laut CTO-Screenshot etwa 290 MB RAM. Die bisherige Electron-App kann Berichten zufolge bis in den Bereich von 4 GB laufen.", "zusammenfassung": "Discord-CTO Stanislav Vishnevskiy hat angekündigt, dass Discord Electron zugunsten einer in Rust geschriebenen Desktop-App mit GPUI aufgibt. ComputerBase und Windows Latest greifen die Ankündigung auf. Ein früher Windows-11-Screenshot listet Discord Phoenix mit 290,2 MB RAM. Windows Latest erinnert daran, dass Discord selbst getestet hat, den Client neu zu starten, wenn der Speicherverbrauch 4 GB überschreitet, und dass normaler Betrieb oft unter 1 GB liege, Idle aber leicht 1 bis 2 GB erreichen könne. Rust nutzt Discord bereits für Infrastruktur, Voice und Teile des aktuellen Clients; nun soll der ganze Client folgen. Wann Tests oder der öffentliche Rollout starten, ist offen. Der Schritt passt zu Microsofts Effizienz-Agenda für Windows 11, weniger speicherhungrige Apps auf schwächeren PCs laufen zu lassen. Es bleibt abzuwarten, ob Feature-Parität und Stabilität der Electron-Version standhalten.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/apps/effizienz-fuer-windows-11-discord-will-mit-nativer-app-den-ram-verbrauch-senken.100189/"}, "weitere_links": [{"name": "Windows Latest: Electron raus, Rust-Build mit ~290 MB", "url": "https://www.windowslatest.com/2026/11/05/discord-is-killing-its-electron-app-that-can-eat-4gb-of-ram-on-windows-11-and-the-rust-rebuild-uses-just-290mb/"}], "tags": ["Discord", "Windows", "Rust", "Electron", "RAM"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-06T08:41:21.960Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.938Z"}, {"id": "2026-11-05-fsr-412-xbox", "datum": "2026-11-05T16:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["FSR", "Xbox", "AMD"], "kategorie": "GPU", "titel": "AMD FSR Upscaling 4.1.2 steht Xbox-Series-X|S-Entwicklern im Oktober-2026-GDK bereit", "schlagzeile": "FSR 4.1.2 kommt auf die Xbox – erstmals mit KI-Upscaling", "kurz": "Mit dem Microsoft GDK vom Oktober 2026 können Entwickler AMD FSR Upscaling 4.1.2 auf Xbox Series X und S nutzen. Erstmals steht damit ML-basiertes AMD-FSR-Upscaling auf den Konsolen bereit. Bestehende Spiele bekommen es nicht automatisch; Studios müssen integrieren.", "zusammenfassung": "AMD hat auf GPUOpen mitgeteilt, dass FSR Upscaling 4.1.2 über das Microsoft Game Development Kit vom Oktober 2026 für Xbox Series X|S verfügbar ist. Alexander Blake-Davies schreibt, dass damit erstmals ML-basiertes AMD-FSR-Upscaling auf den Xbox-Konsolen ankommt; zuvor gab es dort nur analytisches FSR. Für Series X und Series S gibt es zwei INT8-Modelle: Full und ein neues Lite. Lite ist laut AMD weniger als halb so groß und entlastet die GPU stärker. Beide laufen auf Series X und Series S. Der Upscaler-Speicherbedarf hängt von Render- und Ausgabeauflösung ab, nicht vom Modell – die Wahl ist also ein Performance-, kein Speicher-Trade-off. Die API entspricht dem FSR-SDK unter Windows; Qualitätsmodi sind Native AA, Quality, Balanced, Performance und Ultra Performance. Über FSR SDK 2.4 und einen ASUS-Preview-Treiber gilt die Technik auch für ROG-Xbox-Ally-Handhelds (Ally X und X20 zuerst). Es geht um Entwicklerzugang: Studios müssen integrieren, automatische Updates für bestehende Spiele gibt es nicht, konkrete Titel hat AMD nicht genannt. VideoCardz, PC Gamer und TechPowerUp berichten darüber.", "quelle": {"name": "AMD GPUOpen", "url": "https://gpuopen.com/learn/amd-fsr-upscaling-412-xbox/"}, "weitere_links": [{"name": "VideoCardz: FSR 4.1.2 mit ML auf Series X|S", "url": "https://videocardz.com/newz/amd-fsr-4-1-2-brings-machine-learning-upscaling-to-xbox-series-x-and-s-consoles"}, {"name": "PC Gamer: FSR 4.1.2 auf Xbox und Handhelds", "url": "https://www.pcgamer.com/hardware/fsr-4-1-2-now-on-xbox-and-xbox-handhelds-just-in-time-for-a-certain-big-gta-6-shaped-game/"}, {"name": "TechPowerUp: FSR Upscaling 4.1.2 für Xbox", "url": "https://www.techpowerup.com/354493/amd-brings-fsr-upscaling-4-1-2-to-xbox-consoles"}], "tags": ["AMD", "FSR", "Xbox", "Series X", "Upscaling"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T19:32:48.173Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.938Z"}, {"id": "2026-11-05-geforce-8800-gtx-demo", "datum": "2026-11-05T15:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA", "GPU", "GeForce"], "kategorie": "GPU", "titel": "Kostenlose Steam-Demo „GeForce 8800 GTX – 20 Years of a Legend“ feiert 20 Jahre CUDA-GPU", "schlagzeile": "Nvidia lässt dich die 8800 GTX auspacken – braucht aber eine RTX 4070", "kurz": "Seit dem 05.11.2026 gibt es auf Steam die kostenlose Demo „GeForce 8800 GTX – 20 Years of a Legend“. Sie lässt die 2006er-Karte auspacken und in einen zeitgenössischen PC einbauen – gerendert mit Path Tracing und DLSS 4.5. Mindestens gefordert ist eine RTX 4070.", "zusammenfassung": "Zum rund 20-jährigen Jubiläum der GeForce 8800 GTX (Marktstart am 08.11.2006) ist am 05.11.2026 die kostenlose Steam-Demo „GeForce 8800 GTX – 20 Years of a Legend“ erschienen. Erstellt hat sie Unreal-Engine-Künstler Dylan Browne mit Unterstützung von NVIDIA. Die semi-interaktive Demo lässt die Karte auspacken, in einen PC der Epoche einbauen und einen Gaming-Raum von 2006 mit Easter Eggs erkunden. Technisch setzt sie Path Tracing, DLSS 4.5 mit Ray Reconstruction und Dynamic Multi Frame Generation sowie RTX Mega Geometry ein. Die Steam-Systemanforderungen nennen als Minimum eine RTX 4070, 32 GB RAM, 30 GB Speicherplatz und Treiber 621.12 oder neuer; empfohlen wird eine RTX 5080. Die 8800 GTX galt als erste CUDA-fähige GPU. Eine Version für GeForce NOW Ultimate soll laut Berichten von eTeknix und The Verge bald folgen. VideoCardz und Wccftech greifen die Aktion ebenfalls auf.", "quelle": {"name": "Steam", "url": "https://store.steampowered.com/app/4910040/GeForce_8800_GTX_20_Years_of_a_Legend/"}, "weitere_links": [{"name": "eTeknix: 20th-Anniversary-Steam-Demo", "url": "https://www.eteknix.com/geforce-8800-gtx-20th-anniversary-steam-demo/"}, {"name": "The Verge: 8800-GTX-Unboxing-Demo", "url": "https://www.theverge.com/news/1027400/nvidia-geforce-8800-gtx-unboxing-steam-demo"}, {"name": "VideoCardz: Unboxing-Spiel braucht RTX 4070", "url": "https://videocardz.com/newz/nvidia-promotes-a-game-about-unboxing-a-2006-gpu-but-it-requires-rtx-4070"}, {"name": "Wccftech: GeForce 8800 GTX wird 20", "url": "https://wccftech.com/nvidia-geforce-8800-gtx-turns-20/"}], "tags": ["NVIDIA", "GeForce", "8800 GTX", "DLSS", "Steam"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T19:32:48.308Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.939Z"}, {"id": "2026-11-05-openssh-musl-bypass", "datum": "2026-11-05T14:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit"], "kategorie": "Software", "titel": "OpenSSH und musl: Lange Passwörter können passwortlose Konten knacken – Fix in 10.6p2", "schlagzeile": "OpenSSH-Lücke: Lange Passwörter knacken gesperrte Logins (musl)", "kurz": "Auf manchen Linux-Systemen mit musl und ohne PAM können Angreifer Konten ohne Passwort-Hash mit einem sehr langen Passwort knacken. OpenSSH 10.6p2 und aktualisierte Alpine-Pakete schließen die Lücke; sshd muss danach neu gestartet werden. Bis dahin hilft PasswordAuthentication no.", "zusammenfassung": "OpenSSH und Alpine Linux warnen vor einer schweren, aber nischenhaften Lücke bei OpenSSH ohne PAM auf musl-basierten Systemen. Betroffen ist laut Alpine und heise vor allem das Alpine-Paket openssh-server (ohne PAM) bzw. openssh-server-pam mit UsePAM no. Erreicht ein Angreifer den SSH-Port und ist PasswordAuthentication aktiv, kann er sich anmelden, ohne ein Passwort zu kennen – wenn mindestens ein Konto im Shadow-Feld „*“ hat (typisch für Key-only) und zugleich mindestens ein lokales Konto einen $5$- oder $6$-Hash besitzt. Der Angriff sendet ein sehr langes Passwort von 257 bis 1024 Byte: musl-crypt() liefert bei Keys über 256 Byte „*“ als Fehlerwert, was dem gespeicherten „*“ entspricht und die Prüfung bestehen lässt. Ein CVE war zum Zeitpunkt der Advisories noch nicht vergeben. Der Fix steckt in OpenSSH 10.6p2; Alpine hat aktualisierte Pakete veröffentlicht. Nach dem Upgrade muss sshd neu gestartet werden. Workaround: PasswordAuthentication no setzen und sshd neu starten. OpenSSH-Entwickler Damien Miller rät, Passwort-Logins sofort zu deaktivieren. Laut heise geht das Projekt davon aus, dass der Bug eher nicht in OpenSSH selbst entsteht, 10.6p2 ihn aber entschärft. Gemeldet hat die Sache Özgün Kültekin von Wakefield; BleepingComputer und Alpine beschreiben die Bedingungen ausführlich.", "quelle": {"name": "Alpine Linux", "url": "https://alpinelinux.org/posts/2026-11-05-openssh-password-authentication-bypass/"}, "weitere_links": [{"name": "heise: OpenSSH und Alpine warnen vor Lücke", "url": "https://www.heise.de/en/news/OpenSSH-and-Alpine-Linux-warn-of-severe-but-niche-bug-11513360.html"}, {"name": "BleepingComputer: Flaw bei passwortgesperrten Konten", "url": "https://www.bleepingcomputer.com/news/security/openssh-flaw-lets-attackers-log-into-password-disabled-linux-accounts/"}], "tags": ["OpenSSH", "Linux", "Alpine", "musl", "Sicherheit"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T19:32:48.419Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T18:18:52.940Z"}, {"id": "2026-11-04-gta6-vorbestellungen-750-mio", "datum": "2026-11-04T23:42:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Games", "titel": "GTA 6: Sensor Tower schätzt über 750 Millionen US-Dollar Umsatz aus Vorbestellungen", "schlagzeile": "Analysten: GTA 6 spielt schon vor dem Start über 750 Mio. Dollar ein", "kurz": "Laut einer Schätzung des Analysehauses Sensor Tower wurde GTA 6 bis zum 03.11.2026 rund 7,7 Millionen Mal vorbestellt. Das entspricht etwa 751 Millionen US-Dollar Umsatz auf PS5 und Xbox. Offizielle Zahlen von Rockstar oder Take-Two gibt es dazu nicht.", "zusammenfassung": "Das Analysehaus Sensor Tower hat laut IGN die Vorbestellungen von Grand Theft Auto VI ausgewertet. Demnach waren bis zum 03.11.2026 geschätzt 7,71 Millionen Exemplare vorbestellt, was rund 751 Millionen US-Dollar Umsatz entspricht. Der Großteil entfällt auf die PlayStation 5: Sensor Tower sieht dort etwa 74 Prozent der Vorbestellungen und rund 559 Millionen US-Dollar, auf der Xbox etwa 26 Prozent und rund 192 Millionen US-Dollar. Die Ultimate Edition kostet 100 US-Dollar, die Standard-Version 80 US-Dollar. Take-Two-Chef Strauss Zelnick sieht in den Vorbestellungen laut IGN vor allem die treuesten Fans. Zum Vergleich: GTA 5 setzte 2013 laut IGN in den ersten 24 Stunden 800 Millionen US-Dollar um und knackte nach drei Tagen die Milliarde. Ob GTA 6 diesen Rekord bricht, zeigt sich erst nach dem Start. Wichtig ist: Es handelt sich um eine Schätzung eines Marktforschers, nicht um Zahlen von Rockstar oder Take-Two. GTA 6 erscheint am 19.11.2026 für PS5 und Xbox Series X|S, eine PC-Version ist weiterhin nicht angekündigt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/gta-6-rakes-in-over-750-million-in-pre-orders-two-weeks-ahead-of-release-date"}, "weitere_links": [], "tags": ["GTA 6", "Rockstar Games", "Take-Two", "Vorbestellungen", "Sensor Tower"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T11:07:22.393Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T07:50:29.964Z"}, {"id": "2026-11-04-windows-paint-luecke", "datum": "2026-11-04T20:36:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows & Sicherheit", "titel": "Windows 11: Sicherheitslücke in Paint (CVE-2026-83844) – gepatchte Version kommt bei vielen nicht an", "schlagzeile": "Lücke in Windows-Paint: Der Fix ist da, nur bei vielen kommt er nicht an", "kurz": "In der Paint-App von Windows 11 steckt eine Sicherheitslücke, über die Angreifer aus der Ferne Code ausführen könnten. Microsoft hat schon am 13.10.2026 einen Fix über den Microsoft Store verteilt. Viele Nutzer und Admins bekommen die gepatchte Version laut Berichten aber gar nicht angeboten.", "zusammenfassung": "Microsoft führt die Schwachstelle in Paint unter der Kennung CVE-2026-83844 und bewertet sie mit 8,1 von 10 Punkten. Microsoft selbst stuft sie als „Wichtig“ ein, also eine Stufe unter „Kritisch“. Es handelt sich um einen Lesezugriff außerhalb des erlaubten Speicherbereichs, der im schlimmsten Fall das Ausführen von Schadcode über das Netzwerk ermöglicht, ohne dass der Nutzer etwas anklicken muss. Laut Microsoft ist ein Angriff aber schwierig umzusetzen, und Angriffe in freier Wildbahn sind bisher nicht bekannt. Weil Paint über den Microsoft Store aktualisiert wird, schützt das normale Windows-Update allein nicht vor der Lücke. Laut Windows Latest gilt Paint ab Version 11.2609.401.0 als sicher, diese Version tauchte im Store aber selbst bei aktivierten automatischen Updates nicht auf. Auch Admins berichten auf Reddit und im Microsoft-Forum, dass sie die genannte Version nicht bekommen. Laut Neowin nannte Microsofts Sicherheitsseite zunächst eine andere Versionsnummer, möglicherweise ein Tippfehler. Ebenfalls denkbar ist laut Neowin eine gestaffelte Verteilung. Die installierte Version lässt sich in der PowerShell mit dem Befehl „Get-AppxPackage Microsoft.Paint“ prüfen. Wer Paint nicht braucht, kann die App vorerst auch deinstallieren.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-paint-cve-2026-83844-lets-hackers-hack-windows-11-pcs-over-internet/"}, "weitere_links": [{"name": "Windows Latest: Paint-Lücke und fehlendes Update", "url": "https://www.windowslatest.com/2026/11/05/windows-11s-paint-has-a-no-click-hacking-bug-and-even-with-auto-updates-on-you-may-not-have-the-fix/"}, {"name": "Microsoft Security Update Guide: CVE-2026-83844", "url": "https://msrc.microsoft.com/update-guide/vulnerability/CVE-2026-83844"}], "tags": ["Windows 11", "Paint", "Sicherheitslücke", "CVE-2026-83844", "Microsoft Store"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T11:07:22.457Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-12T07:50:30.016Z"}, {"id": "2026-11-04-nova-lake-90-grad-limit", "datum": "2026-11-04T19:13:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["CPU"], "kategorie": "CPU", "zuverlaessigkeit": {"stufe": "mittel-hoch", "hinweis": "Unbestätigt: Einzige Quelle ist der Intel-Leaker Jaykihn auf X, der die Angabe selbst als vorläufig („Preliminary“) bezeichnet. VideoCardz und TechPowerUp geben den Beitrag wieder. Intel hat nichts bestätigt, finale Taktraten sind nicht bekannt."}, "ursprungsquelle": "Jaykihn (@jaykihn0) auf X", "titel": "Leak: Intel Core Ultra 4000 „Nova Lake-S“ soll oberhalb von 90 °C maximal 5,1 GHz takten", "schlagzeile": "Leak: Intels Nova Lake soll ab 90 °C nur noch 5,1 GHz schaffen", "kurz": "Laut dem Leaker Jaykihn sollen alle Desktop-Prozessoren der Reihe Nova Lake-S ihren Takt oberhalb von 90 °C auf höchstens 5,1 GHz begrenzen. Die Grenze soll sich nicht anheben lassen. Die Angabe ist vorläufig und von Intel nicht bestätigt.", "zusammenfassung": "Der Intel-Leaker Jaykihn hat am 04.11.2026 auf X geschrieben, dass Intels kommende Desktop-Prozessoren Core Ultra 4000 „Nova Lake-S“ eine feste Temperaturgrenze bekommen sollen. Oberhalb von 90 °C soll der maximale Kerntakt demnach bei allen Modellen auf 5,1 GHz begrenzt werden. Das soll unabhängig von der üblichen Notbremse bei 100 °C (TjMax) greifen, ab der die CPU ohnehin drosselt. Laut Jaykihn lässt sich auch die neue 90-Grad-Grenze nicht nach oben verschieben. Er bezeichnet die Information ausdrücklich als vorläufig. Modelle, die ohnehin nicht über 5,1 GHz takten, wären von der Grenze nicht betroffen. Bei schnelleren Modellen könnte ein Teil des Boosts wegfallen, wenn die Kühlung nicht ausreicht. TechPowerUp erinnert daran, dass der aktuelle Core Ultra 9 285K bis zu 5,7 GHz erreicht und dessen TjMax mit 105 °C höher liegt. Zudem soll das Topmodell mit 28 Kernen laut früheren Berichten kurzzeitig bis zu 296 W ziehen, was einen starken Kühler nötig machen dürfte. Nova Lake-S wird laut TechPowerUp im ersten Quartal 2027 erwartet. Intel hat die Angaben nicht bestätigt, es bleibt also ein Leak.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/intel-core-ultra-4000-desktop-nova-lake-s-cpus-will-reportedly-limit-frequency-to-5-1-ghz-above-90c"}, "weitere_links": [{"name": "Jaykihn auf X (Ursprungsbeitrag)", "url": "https://x.com/jaykihn0/status/2118040739946852809"}, {"name": "TechPowerUp: Nova Lake-S drosselt über 90 °C auf 5,1 GHz", "url": "https://www.techpowerup.com/354475/intel-nova-lake-s-cpus-reportedly-drop-to-5-1-ghz-max-above-90-c"}], "tags": ["Intel", "Nova Lake", "Core Ultra 4000", "CPU", "Gerücht"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T11:07:22.518Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-11T18:17:07.867Z"}, {"id": "2026-11-04-god-of-war-laufey-verschoben", "datum": "2026-11-04T18:06:00+01:00", "label": "News", "bereich": "games", "themen": ["God of War"], "kategorie": "Games", "titel": "God of War Laufey verschoben: Neuer Termin ist der 20.05.2027", "schlagzeile": "God of War Laufey verschoben: Fans müssen drei Monate länger warten", "kurz": "Sony Santa Monica hat God of War Laufey offiziell verschoben. Statt am 16.02.2027 erscheint das Spiel nun am 20.05.2027. Das Studio will die zusätzliche Zeit für den letzten Feinschliff nutzen.", "zusammenfassung": "Das PlayStation-Studio Santa Monica hat am 04.11.2026 auf X bekanntgegeben, dass God of War Laufey später erscheint. Geplant war bisher der 16.02.2027, neuer Termin ist der 20.05.2027. Das Studio begründet die Verschiebung damit, dass es dem Spiel den letzten Feinschliff geben und es voll ausreizen will. Seit der Enthüllung im Juni sei man dankbar für die große Vorfreude der Fans, heißt es in dem Statement. Laufey ist der erste Hauptteil der Reihe, in dem nicht Kratos die Hauptrolle spielt. Spieler übernehmen stattdessen Faye, die Frau von Kratos und Mutter von Atreus, die vor den Ereignissen von God of War aus dem Jahr 2018 gestorben ist. Laut der offiziellen Beschreibung erwacht sie nach ihrem Tod in einer Art Jenseits der Götter, dem „Everywhen“. Eurogamer weist darauf hin, dass das Spiel damit einem vollen Februar mit vielen großen Veröffentlichungen ausweicht. Weitere Neuigkeiten will das Studio bald zeigen.", "quelle": {"name": "Video Games Chronicle (VGC)", "url": "https://www.videogameschronicle.com/news/god-of-war-laufey-has-officially-been-delayed/"}, "weitere_links": [{"name": "Eurogamer: God of War Laufey auf Mai 2027 verschoben", "url": "https://www.eurogamer.net/god-of-war-laufey-delayed-may-three-months"}, {"name": "Neowin: Sony verschiebt God of War Laufey", "url": "https://www.neowin.net/news/sony-delays-ps5-exclusive-god-of-war-laufey-out-of-february/"}], "tags": ["God of War Laufey", "Santa Monica Studio", "PlayStation", "PS5", "Verschiebung"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T11:07:22.572Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-11T18:17:07.868Z"}, {"id": "2026-11-04-amd-rekord-gaming-einbruch", "datum": "2026-11-04T11:12:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Markt"], "kategorie": "Markt & Wirtschaft", "titel": "AMD: Rekordumsatz von 13,4 Mrd. US-Dollar, Gaming-Umsatz minus 40 Prozent – im vierten Quartal wohl erstmals mehr Umsatz als Intel", "schlagzeile": "AMD verdient so viel wie nie – doch im Gaming bricht der Umsatz um 40 % ein", "kurz": "AMD hat im dritten Quartal 2026 mit 13,4 Milliarden US-Dollar so viel umgesetzt wie noch nie, vor allem dank Rechenzentren. Der Gaming-Umsatz fiel dagegen um 40 Prozent, weil teurer Arbeitsspeicher Grafikkarten, Konsolen und PCs ausbremst. Laut eigener Prognose dürfte AMD im vierten Quartal erstmals mehr umsetzen als Intel.", "zusammenfassung": "AMD hat im dritten Quartal 2026 einen Rekordumsatz von 13,4 Milliarden US-Dollar gemeldet. Laut ComputerBase stammten davon 8,5 Milliarden US-Dollar aus dem Geschäft mit Rechenzentren, das laut TechPowerUp um 97 Prozent zum Vorjahr gewachsen ist. Ganz anders sieht es im Gaming aus: Dieser Bereich brach im Vergleich zum Vorjahresquartal um 40 Prozent auf 773 Millionen US-Dollar ein. Als Grund nennt AMD die Engpässe und Preissteigerungen beim Arbeitsspeicher, die Grafikkarten, Konsolen mit AMD-Chips und ganze PCs teurer machen. Für das vierte Quartal erwartet AMD rund 17 Milliarden US-Dollar Umsatz, plus oder minus drei Prozent. Intel rechnet für denselben Zeitraum nur mit 15 bis 16 Milliarden US-Dollar. Selbst das untere Ende von AMDs Prognose liegt damit über dem oberen Ende von Intel, AMD würde also laut TechPowerUp erstmals mehr Umsatz machen als Intel. Das gilt nur für den Umsatz, nicht für den Gewinn. Gleichzeitig rechnet AMD-Chefin Lisa Su für 2027 mit einem zweistelligen Rückgang bei den PC-Verkäufen. Für PC-Spieler heißt das: Der Fokus von AMD verschiebt sich weiter Richtung Rechenzentrum und KI.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/amd-erzielt-rekordquartal-datacenter-waechst-stark-gaming-umsatz-bricht-ein.100170/"}, "weitere_links": [{"name": "TechPowerUp: AMD vor erstem Quartal mit mehr Umsatz als Intel", "url": "https://www.techpowerup.com/354470/amd-guidance-points-to-its-first-quarter-ever-with-more-revenue-than-intel"}, {"name": "PC Games Hardware: AMD-Quartalszahlen", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/AMD-Quartalszahlen-KI-Server-Gaming-Umsatzzahlen-1558944/"}], "tags": ["AMD", "Intel", "Quartalszahlen", "Gaming", "Arbeitsspeicher"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-05T11:07:22.625Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-11T18:17:07.869Z"}, {"id": "2026-11-03-arc-b580-eol", "datum": "2026-11-03T20:12:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["Grafikkarten"], "kategorie": "GPU", "zuverlaessigkeit": {"stufe": "niedrig-mittel", "hinweis": "Unbestätigt: Einzige Quelle ist ein Beitrag des Leakers Haze2K1 auf X, der selbst nur von „might“ (könnte) spricht. TechPowerUp und Wccftech geben den Beitrag wieder, eine unabhängige zweite Quelle gibt es nicht. Intel hat sich nicht geäußert."}, "ursprungsquelle": "Haze2K1 auf X", "titel": "Leak: Intel könnte die Arc B580 einstellen und auf teurere Arc-Pro-Karten setzen", "schlagzeile": "Leak: Steht Intels Spar-Grafikkarte Arc B580 vor dem Aus?", "kurz": "Laut dem Leaker Haze2K1 könnte Intel die Grafikkarte Arc B580 auslaufen lassen. Grund sollen die besser verdienenden Arc-Pro-Karten mit demselben Grafikchip sein. Das ist ein unbestätigtes Gerücht, Intel hat sich nicht dazu geäußert.", "zusammenfassung": "Der Leaker Haze2K1 hat am 02.11.2026 auf X geschrieben, dass die Intel Arc B580 möglicherweise eingestellt wird. Intel wolle sich demnach stärker auf Profi- und Workstation-Karten wie die Arc Pro B50 konzentrieren, die sich für KI-Anwendungen gut verkaufen sollen. TechPowerUp und Wccftech haben den Beitrag aufgegriffen. Die Arc B580 kam im Dezember 2024 für 249 US-Dollar als günstige Gaming-Karte mit 12 GB Grafikspeicher auf den Markt. Die Arc Pro B60 nutzt laut TechPowerUp denselben Grafikchip, hat aber 24 GB Speicher und kostet rund 500 US-Dollar, was mehr Gewinn pro Chip bringen dürfte. Laut TechPowerUp ist die B580 bei vielen Händlern bereits ausverkauft oder nur über dem ursprünglichen Preis zu haben. Haze2K1 formuliert selbst vorsichtig und spricht nur davon, dass die Karte auslaufen könnte. Ob die kleinere Arc B570 ebenfalls betroffen wäre, geht aus dem Gerücht nicht hervor. Intel hat das Gerücht nicht kommentiert, es ist also unbestätigt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354440/intel-might-discontinue-the-arc-b580-to-prioritize-higher-margin-arc-pro-cards"}, "weitere_links": [{"name": "Haze2K1 auf X (Ursprungsbeitrag)", "url": "https://x.com/Haze2K1/status/2117241776688037938"}, {"name": "Wccftech: Intel might discontinue Arc B580", "url": "https://wccftech.com/intel-might-discontinue-arc-b580-to-focus-on-higher-margin-ai-centric-products-such-as-arc-pro-b50/"}], "tags": ["Intel Arc B580", "Intel", "Arc Pro", "Grafikkarten", "Gerücht"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-04T11:08:43.383Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-11T07:51:26.376Z"}, {"id": "2026-11-03-windows11-8gb-ram", "datum": "2026-11-03T18:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11 läuft auf PCs mit 8 GB RAM spürbar besser – Microsoft nennt Details und Bedingungen", "schlagzeile": "Windows 11 auf 8-GB-PCs: Bis zu 40 % schnelleres Multitasking versprochen", "kurz": "Microsoft hat Windows 11 für PCs mit nur 8 GB Arbeitsspeicher optimiert. Laut Microsoft reagiert das System bis zu 20 Prozent schneller, Multitasking soll im Labortest bis zu 40 Prozent schneller sein. Nötig sind Windows 11 26H2 ab Build 26300.9818 und aktuelle Apps.", "zusammenfassung": "Microsoft hat am 03.11.2026 im Windows Experience Blog erklärt, wie Windows 11 auf PCs mit 8 GB RAM besser laufen soll. Laut Windows-Chef Pavan Davuluri reagieren Start, Suche, Kontextmenü, Einstellungen, Snipping Tool und Explorer auf solchen Geräten bis zu 20 Prozent schneller, gemessen über Telemetriedaten. Die bis zu 40 Prozent schnellere Multitasking-Zeit stammt aus einem einzigen Labortest auf einem HP-Notebook mit Snapdragon X Plus, Microsoft selbst nennt das keinen allgemeinen Benchmark. Durch besser abgestimmte Speicherkomprimierung kann Windows bis zu 2 GB mehr aktive Daten im RAM halten, statt sie auf die langsamere SSD auszulagern. Dadurch sollen offene Apps und Browser-Tabs seltener neu laden müssen. Zusammen mit Edge und den Microsoft-365-Apps sinkt der zusätzliche Speicherbedarf im Multitasking um bis zu 900 MB, allein Word, Excel, PowerPoint und Outlook sparen rund 360 MB. Die Widgets werden auf 8-GB-PCs erst geladen, wenn man das Widget-Panel öffnet, das spart etwa 200 MB. Voraussetzung ist Windows 11 26H2 ab Build 26300.9818, das zunächst über das optionale Update vom 28.10.2026 kommt und laut Windows Latest am Patchday 10.11.2026 für alle erscheint. Edge, Microsoft 365 und Teams sollten ebenfalls aktuell sein, weil ein Teil der Verbesserungen über App-Updates kommt. Für 3D-Modellierung, anspruchsvollen Videoschnitt oder große Datenmengen empfiehlt Microsoft weiterhin 16 GB oder mehr.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/03/microsoft-admits-windows-11-was-moving-your-open-apps-to-slower-storage-on-8gb-ram-pcs-which-is-why-they-reload-and-now-it-keeps-up-to-2gb-more-in-memory/"}, "weitere_links": [{"name": "Windows Experience Blog (Microsoft): Raising the bar for 8 GB Windows 11 PCs", "url": "https://blogs.windows.com/windowsexperience/2026/11/03/raising-the-bar-for-8-gb-windows-11-pcs-whats-improved-and-how-to-get-it/"}, {"name": "TechPowerUp: Bis zu 40 % schnelleres Multitasking auf 8-GB-PCs", "url": "https://www.techpowerup.com/354441/windows-11-optimizations-bring-up-to-40-faster-multitasking-to-8-gb-pcs"}], "tags": ["Windows 11", "26H2", "Arbeitsspeicher", "8 GB RAM", "Microsoft Edge"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-04T11:08:43.224Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-10T18:18:09.701Z"}, {"id": "2026-11-03-rtx50-preise-china", "datum": "2026-11-03T16:30:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["Grafikkarten"], "kategorie": "GPU & Markt", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Unbestätigt: Alle Berichte stützen sich auf die chinesische Branchenplattform Channelgate (Umfeld Board Channels). NVIDIA, Colorful und Galax haben nichts offiziell bestätigt. Die Preise gelten für China und lassen sich nicht 1:1 auf Europa übertragen."}, "ursprungsquelle": "Channelgate (Board Channels), China", "titel": "Leak: Boardpartner erhöhen in China die Preise der GeForce RTX 50 – bis zu 3.300 Yuan mehr", "schlagzeile": "Leak: RTX-50-Karten sollen schon wieder teurer werden – bis zu 3.300 Yuan", "kurz": "Laut der chinesischen Branchenplattform Channelgate erhöhen NVIDIA-Boardpartner in China erneut die Preise der GeForce RTX 50. Genannt werden Aufschläge von rund 100 bis 3.300 Yuan je nach Modell. Bestätigt ist das nicht, und die Zahlen gelten nur für China.", "zusammenfassung": "Die chinesische Branchenplattform Channelgate berichtet, dass Grafikkarten-Hersteller in China die Preise der GeForce RTX 50 im November erneut anheben. Laut PC Games Hardware soll Colorful die neuen Preise bereits umgesetzt haben, Galax soll noch diese Woche folgen. Laut TechPowerUp reichen die gemeldeten Aufschläge von etwa 100 bis 150 Yuan bei der RTX 5060 Ti mit 8 GB bis zu 2.200 bis 3.300 Yuan bei der China-Variante RTX 5090 D V2. Für die RTX 5080 nennt der Bericht 2.500 bis 2.800 Yuan, für die RTX 5070 Ti rund 1.000 Yuan und für die RTX 5070 etwa 600 bis 900 Yuan mehr. Umgerechnet wären das grob 15 bis knapp 500 US-Dollar. Als Gründe nennt der Bericht knappen Grafikspeicher und teurere Rohstoffe wie Kupfer. Im Handel könnten die höheren Preise laut TechPowerUp ein bis zwei Wochen später ankommen. Weil RTX-50-Karten in China knapp werden, sollen Händler laut PCGH verstärkt auf ältere Modelle wie die RTX 3060 und auf Radeon-Karten ausweichen. NVIDIA und die genannten Boardpartner haben die Erhöhungen nicht offiziell bestätigt. Ob und wie stark sich das auf die Preise in Europa auswirkt, ist offen.", "quelle": {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Boardpartner-erhoehen-Preise-in-China-1558760/"}, "weitere_links": [{"name": "TechPowerUp: RTX 50 vor Preiserhöhung um bis zu 500 US-Dollar", "url": "https://www.techpowerup.com/354427/nvidia-geforce-rtx-50-series-scheduled-for-up-to-usd-500-price-hike-this-week"}], "tags": ["GeForce RTX 50", "NVIDIA", "Grafikkartenpreise", "China", "Colorful", "Galax"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-04T11:08:43.333Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-10T18:18:09.704Z"}, {"id": "2026-11-03-elder-scrolls-6-sentinel", "datum": "2026-11-03T16:08:00+01:00", "label": "News", "bereich": "games", "themen": ["The Elder Scrolls 6"], "kategorie": "Games", "titel": "The Elder Scrolls 6 heißt offiziell „Sentinel“ – Bethesda enthüllt Titel und Logo", "schlagzeile": "Nach 8 Jahren Funkstille: The Elder Scrolls 6 hat endlich einen Namen", "kurz": "Bethesda hat zum 40-jährigen Firmenjubiläum den vollen Titel des nächsten Elder-Scrolls-Rollenspiels verraten: The Elder Scrolls VI: Sentinel. Sentinel ist eine Stadt in der Region Hammerfell. Einen Release-Termin gibt es weiterhin nicht.", "zusammenfassung": "Bethesda hat am 03.11.2026 in einem Video zum 40. Jubiläum des Studios offiziell bestätigt, dass The Elder Scrolls VI den Untertitel „Sentinel“ trägt. Im Video sind Titel und Logo zu sehen, außerdem kommt Todd Howard zu Wort. Sentinel ist eine Hafenstadt in der Provinz Hammerfell im Nordwesten Tamriels. Ein Zitat im Video ist laut IGN auf eine Zeit nach den Ereignissen von Skyrim datiert. Angekündigt wurde das Spiel bereits auf der E3 2018, seither gab es kaum offizielle Informationen. Ein Bericht hatte den Namen schon in der Vorwoche vorhergesagt, nun ist er bestätigt. Einen Erscheinungstermin oder Gameplay hat Bethesda nicht gezeigt. Als Plattformen gelten laut IGN Xbox und PC, ob das Spiel auch für PlayStation erscheint, ist offen. Eurogamer spekuliert, dass es bei den Game Awards im Dezember mehr zu sehen geben könnte, das ist aber nicht bestätigt.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/the-elder-scrolls-6-sentinel-revealed-bethesda-xbox"}, "weitere_links": [{"name": "IGN Deutschland: The Elder Scrolls 6 heißt Sentinel", "url": "https://de.ign.com/the-elder-scrolls-vi/156962/the-elder-scrolls-6-name-und-logo-von-sentinel-wurden-offiziell-enthullt-sowie-ein-erster-hinweis-au"}, {"name": "PC Gamer: The Elder Scrolls 6: Sentinel ist offiziell", "url": "https://www.pcgamer.com/games/the-elder-scrolls/the-elder-scrolls-6-sentinel-is-finally-made-official/"}], "tags": ["The Elder Scrolls 6", "Sentinel", "Bethesda", "Xbox", "Rollenspiel"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-04T11:08:43.168Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-10T18:18:09.704Z"}, {"id": "2026-11-03-gta6-preload-212gb", "datum": "2026-11-03T15:55:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Games", "titel": "GTA 6: Rockstar bestätigt Preload ab 10.11.2026 und bis zu 212 GB Download", "schlagzeile": "GTA 6 frisst bis zu 212 GB – und der Preload startet früher als gedacht", "kurz": "Rockstar Games hat offiziell bestätigt, dass der Vorab-Download von GTA 6 auf PS5 und Xbox Series X|S am 10.11.2026 beginnt. Der Download ist je nach Konsole bis zu 212 GB groß. Erscheinen soll das Spiel weiterhin am 19.11.2026.", "zusammenfassung": "Rockstar Games hat am Nachmittag des 03.11.2026 die Details zum Vorab-Download von Grand Theft Auto VI veröffentlicht. Auf der PS5 startet der Preload am 10.11.2026 um Mitternacht Ortszeit, auf Xbox Series X|S am selben Tag um 0 Uhr GMT, also um 1 Uhr in Österreich und Deutschland. Laut Rockstar ist der Download je nach Gerät bis zu 212 GB groß, auch der PlayStation Blog rät, mindestens 212 GB Speicher freizumachen. Damit bestätigt sich im Kern ein Leak von Ende Oktober, nach dem das Spiel auf der PS5 rund 210 GB belegen sollte. Ursprünglich war der Preload laut den Berichten erst ab dem 12.11.2026 angekündigt, digital geht es nun also zwei Tage früher los. Am 12.11.2026 sollen die Boxed-Versionen in den Handel kommen, die laut den Berichten nur einen Download-Code enthalten. Der Release bleibt beim 19.11.2026 für PS5 und Xbox Series X|S. Zum Start will Rockstar zusätzlich ein Cover-Poster und eine Karte von Leonida zum Ausdrucken auf seiner Website anbieten. Ob die Xbox Series S mit weniger Speicherplatz auskommt, geht aus den Angaben nicht eindeutig hervor.", "quelle": {"name": "Rockstar Games (Newswire + @RockstarGames)", "url": "https://x.com/RockstarGames/status/2117631870967984130"}, "weitere_links": [{"name": "PlayStation Blog: Pre-Download startet am 10. November", "url": "https://blog.playstation.com/2026/11/03/grand-theft-auto-vi-pre-download-begins-november-10/"}, {"name": "IGN Deutschland: Preload-Zeiten und Installationsgröße bestätigt", "url": "https://de.ign.com/grand-theft-auto-vi/156961/preload-zeiten-und-installationsgrosse-von-gta-6-bestatigt"}, {"name": "VGC: Rockstar nennt Preload-Termin und Dateigröße", "url": "https://www.videogameschronicle.com/news/rockstar-details-grand-theft-auto-6-pre-load-date-and-time-and-file-size/"}], "tags": ["GTA 6", "Rockstar Games", "PS5", "Xbox Series X|S", "Preload"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-04T11:08:43.111Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-10T18:18:09.705Z"}, {"id": "2026-11-03-fedora-45", "datum": "2026-11-03T09:42:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux"], "kategorie": "Linux", "titel": "Fedora Linux 45 ist erschienen – mit GNOME 51, KDE Plasma 6.8 und Linux-Kernel 7.2", "schlagzeile": "Fedora 45 ist da: Neuer Desktop, neuer Installer und Builds zum Nachprüfen", "kurz": "Das Fedora-Projekt hat Fedora Linux 45 veröffentlicht. Die Workstation-Edition setzt auf GNOME 51, die KDE-Edition auf Plasma 6.8, darunter arbeitet der Linux-Kernel 7.2. Neu sind unter anderem Stratis im Installer und reproduzierbare Paket-Builds.", "zusammenfassung": "Am 03.11.2026 ist Fedora Linux 45 erschienen, rund sechs Monate nach Fedora 44 und laut Phoronix nach zwei Verschiebungen. Die Workstation-Edition bringt GNOME 51 mit, die KDE-Plasma-Desktop-Edition die Version Plasma 6.8. Als Kernel kommt Linux 7.2 zum Einsatz. Eine der größten Neuerungen ist laut dem offiziellen Fedora Magazine die Unterstützung für das Speichersystem Stratis direkt im Anaconda-Installer. Die virtuelle Textkonsole übernimmt standardmäßig KMSCON, außerdem setzt Fedora laut 9to5Linux auf vollständig reproduzierbare Paket-Builds. Die Signaturprüfung für RPM-Pakete ist standardmäßig aktiv und ptrace ist standardmäßig eingeschränkt, was die Sicherheit erhöhen soll. Die Atomic-Varianten wie Silverblue und Kinoite installieren jetzt über den neuen WebUI-Installer. Für Entwickler sind unter anderem GCC 16.2, LLVM 23, Python 3.15, Go 1.27 und Podman 6 dabei. Die alten VPN-Plugins NetworkManager-vpnc und NetworkManager-fortisslvpn fallen weg, wer sie nutzt, sollte seine Verbindungen vor dem Upgrade umstellen. Bestehende Fedora-44-Installationen lassen sich per DNF system-upgrade aktualisieren.", "quelle": {"name": "9to5Linux", "url": "https://9to5linux.com/fedora-linux-45-is-now-available-for-download-with-gnome-51-and-kde-plasma-6-8"}, "weitere_links": [{"name": "Fedora Magazine (offiziell): Announcing Fedora Linux 45", "url": "https://fedoramagazine.org/announcing-fedora-linux-45/"}, {"name": "Phoronix: Fedora 45 Released", "url": "https://www.phoronix.com/news/Fedora-45-Released"}], "tags": ["Fedora 45", "Linux", "GNOME 51", "KDE Plasma 6.8", "Linux 7.2"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-04T11:08:43.278Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-10T11:16:32.912Z"}, {"id": "2026-11-02-zelda-oot-remake-puppenlook", "datum": "2026-11-02T23:51:00+01:00", "label": "News", "bereich": "games", "themen": ["Zelda"], "kategorie": "Games", "titel": "Zelda: Ocarina of Time für Switch 2: Nintendo erklärt den umstrittenen Puppen-Look des Remakes", "schlagzeile": "Zelda-Remake sieht aus wie ein Puppenspiel – Nintendo erklärt, warum", "kurz": "Das Remake von The Legend of Zelda: Ocarina of Time erscheint am 5. November für Nintendo Switch 2. Der Grafikstil mit puppenhaften Figuren spaltet die Fans. In einem Interview erklären die Entwickler, dass sie bewusst ein „Puppenspiel-Gefühl“ wollten statt reinen Fotorealismus.", "zusammenfassung": "Nintendo hat sich laut Polygon zum umstrittenen Grafikstil des Remakes von The Legend of Zelda: Ocarina of Time geäußert. Link, Zelda und andere Figuren wirken darin eher wie Puppen als wie fotorealistische Menschen, was unter langjährigen Fans für Diskussionen sorgt. Art Director Aya Shida sagt in einem Entwicklerinterview, das Ziel sei nicht gewesen, einfach alles realistisch aussehen zu lassen. Hyrule sollte als dichte Welt wirken, die wirklich existieren könnte, während die bunten, schrulligen Figuren wie im Original einen Kontrast dazu bilden. Leitbegriffe für das Team waren laut Shida ein „Puppenspiel-Gefühl“ und die „analoge Anmutung von Filmen mit praktischen Effekten“. Serienproduzent Eiji Aonuma erklärt, das Team empfinde beim Blick auf das Nintendo-64-Original Nostalgie, und dieser Ausdruck habe zu dem analogen Puppen-Look geführt. Das Remake erscheint laut Video Games Chronicle am Donnerstag, 5. November 2026, für Nintendo Switch 2. Entwickelt wird es von Nintendos eigener Abteilung Nintendo EPD, die auch Breath of the Wild und Tears of the Kingdom gemacht hat. Ob der Stil am Ende überzeugt, zeigt sich erst mit den Tests nach dem Start.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/zelda-ocarina-of-time-art-style-link-zelda-puppets/"}, "weitere_links": [{"name": "Video Games Chronicle: Zelda: Ocarina of Time UK midnight launch", "url": "https://www.videogameschronicle.com/news/nintendo-announces-zelda-ocarina-of-time-uk-midnight-launch-with-free-n64-boxes-up-for-grabs/"}], "tags": ["Zelda", "Ocarina of Time", "Nintendo Switch 2", "Remake"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-03T06:30:37.346Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-10T07:46:04.912Z"}, {"id": "2026-11-02-rtx5080-preis-heise", "datum": "2026-11-02T18:52:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU"], "kategorie": "GPU & Markt", "titel": "RTX 5080 kaum noch unter 2.000 Euro, Bericht: 24-GB-Version könnte sich verzögern", "schlagzeile": "RTX 5080 knackt die 2.000 Euro: Über 30 % teurer in nur zwei Wochen", "kurz": "Die GeForce RTX 5080 ist laut heise online derzeit kaum noch unter 2.000 Euro zu bekommen, ihr Preis ist in zwei Wochen um mehr als 30 Prozent gestiegen. Als Grund nennt heise die Gerüchte um ein Aus der RTX 5090, die inzwischen bei rund 8.000 Euro liegt. Die erwartete 24-GB-Version der RTX 5080 könnte sich laut einem unbestätigten Bericht von BenchLife verzögern.", "zusammenfassung": "Nach der RTX 5090 wird laut heise online auch die RTX 5080 deutlich teurer: Die zweitschnellste Gaming-Grafikkarte von NVIDIA ist derzeit kaum noch unter 2.000 Euro erhältlich. Das sind mehr als 30 Prozent mehr als noch vor zwei Wochen. Mitte Oktober kamen Gerüchte auf, NVIDIA könnte die RTX 5090 vom Markt nehmen, was laut heise die Nachfrage nach der 5080 angeheizt hat. Die RTX 5090 selbst kostet inzwischen rund 8.000 Euro, die letzte UVP von NVIDIA lag bei 2.099 Euro. NVIDIA hat das Aus der 5090 dementiert, allerdings nur mit der Formulierung, die Karte werde „weiterhin ausgeliefert“. Ob sie weiter hergestellt wird, geht daraus laut heise nicht hervor. Im Oktober hieß es außerdem, eine RTX 5080 mit 24 statt 16 GB GDDR7 solle im Januar 2027 vorgestellt werden. Laut der taiwanischen Seite BenchLife haben die Kartenhersteller die nötigen Designunterlagen von NVIDIA aber noch nicht erhalten, obwohl sie für Oktober geplant gewesen sein sollen. Das ist ein unbestätigter Bericht, NVIDIA hat sich dazu nicht geäußert. Zudem soll der Bestand an GB203-Chips in China bereits verkauft sein und nur noch ein bis zwei Monate reichen. Als Ursache der Knappheit nennt heise den KI-Boom: Dieselben Chips und der knappe GDDR7-Speicher stecken auch in teuren Workstation-Karten mit höherer Marge. Wer eine High-End-Karte sucht, muss sich also vorerst auf weiter hohe Preise einstellen.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Auch-Preis-fuer-RTX-5080-steigt-stark-Nachfolger-verzoegert-11508541.html"}, "weitere_links": [{"name": "Wccftech: RTX 5080 24 GB may miss January 2027 launch", "url": "https://wccftech.com/nvidia-geforce-rtx-5080-24-gb-may-miss-january-2027-launch-as-board-partners-still-await-design-kits/"}], "tags": ["NVIDIA", "RTX 5080", "RTX 5090", "GPU-Preise"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-03T06:30:37.169Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-09T18:18:56.052Z"}, {"id": "2026-11-02-windows11-smart-app-control-fix", "datum": "2026-11-02T14:57:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Microsoft behebt Fehler: Smart App Control ließ sich nach dem Oktober-Update nicht mehr einschalten", "schlagzeile": "Windows 11: Schutzfunktion nach Oktober-Update ausgegraut – jetzt gibt's den Fix", "kurz": "Nach dem Oktober-Sicherheitsupdate KB5127648 ließ sich die Windows-11-Schutzfunktion Smart App Control auf manchen PCs nicht mehr einschalten. Microsoft hat den Fehler mit den Updates ab dem 28. Oktober 2026 behoben, darunter das optionale Vorschau-Update KB5127936. Wo Smart App Control schon aktiv war, blieb der Schutz die ganze Zeit bestehen.", "zusammenfassung": "Microsoft hat laut BleepingComputer einen bekannten Fehler in Windows 11 behoben, der nach dem Sicherheitsupdate KB5127648 vom Oktober 2026 auftrat. Auf betroffenen Geräten mit Windows 11 24H2 und neuer war die Option für Smart App Control in der Windows-Sicherheit ausgegraut und ließ sich nicht einschalten. Smart App Control blockiert zusammen mit SmartScreen und Microsoft Defender potenziell schädliche Apps. Betroffen waren nur PCs, auf denen die Funktion zuvor ausgeschaltet war. Wo sie bereits aktiv war, blieben die Geräte laut Microsoft geschützt. Der Fehler ist mit den Windows-Updates vom 28. Oktober 2026 und später behoben, darunter das optionale Vorschau-Update KB5127936. Microsoft empfiehlt, das jeweils neueste Update zu installieren. Für Firmen-PCs, die nicht auf den nächsten Patchday warten wollen, nennt Microsoft eine Übergangslösung über zwei Registry-Einträge oder spezielle Gruppenrichtlinien, jeweils mit Neustart. Laut BleepingComputer behebt KB5127936 außerdem Probleme mit Remote Desktop bei aktiviertem „Administratorschutz“ und VPN-Fehler nach den Updates vom September 2026. Privatnutzer müssen nichts tun, außer das Update zu installieren.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-fixes-smart-app-control-broken-by-october-windows-update/"}, "weitere_links": [], "tags": ["Windows 11", "Smart App Control", "KB5127648", "KB5127936"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-03T06:30:37.288Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-09T18:18:56.053Z"}, {"id": "2026-11-02-raspberry-pi5-16gb-preis", "datum": "2026-11-02T13:55:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Raspberry Pi"], "kategorie": "Speicher & Markt", "titel": "Raspberry Pi 5 mit 16 GB RAM wird zum vierten Mal teurer: 385 statt 305 US-Dollar", "schlagzeile": "Raspberry Pi 5 mit 16 GB kostet jetzt 385 Dollar – dreimal so viel wie zum Start", "kurz": "Raspberry Pi hebt den Listenpreis des Raspberry Pi 5 mit 16 GB RAM von 305 auf 385 US-Dollar an. Es ist die vierte Erhöhung seit Dezember 2025, zum Start lag der Preis bei 120 US-Dollar. Grund sind die steigenden RAM-Preise, der Raspberry Pi 500+ wird diesmal aber nicht teurer.", "zusammenfassung": "Der Raspberry Pi 5 mit 16 GB LPDDR4-RAM wird laut heise online erneut teurer. Der Listenpreis steigt um 80 auf 385 US-Dollar. Es ist bereits die vierte Erhöhung nach Dezember 2025, Februar 2026 und April 2026. Zum Start kostete diese Version laut heise 120 US-Dollar beziehungsweise rund 135 Euro. Als Grund nennt der Hersteller die ständig steigenden RAM-Preise. Raspberry-Pi-Chef Eben Upton erklärt, dass es für den 16-GB-Speicherbaustein keinen alternativen Zulieferer gibt. Derselbe Baustein steckt auch im Compute Module 5 und im Raspberry Pi 500+. Die 16-GB-Version des Compute Module 5 wird um 40 US-Dollar teurer, der Raspberry Pi 500+ dagegen diesmal nicht. Laut heise werden auch einige andere Raspberry-Pi-Modelle noch teurer. Wegen der Engpässe hat der Hersteller für mehrere Produkte zusätzliche Bestückungsoptionen eingeführt, um auch Speicherchips anderer Hersteller verwenden zu können. Golem.de berichtet, dass ein Pi 5 inzwischen fast 350 Euro kostet. Wie stark die Preise im Handel steigen, hängt vom Händler ab.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Der-teuerste-Raspi-wird-noch-teurer-16-Gigabyte-Version-kostet-385-US-Dollar-11507912.html"}, "weitere_links": [{"name": "Golem.de: Pi 5 und Compute Module – Raspberry Pi kostet mittlerweile fast 350 Euro", "url": "https://www.golem.de/news/pi-5-und-compute-module-raspberry-pi-kostet-mittlerweile-fast-350-euro-2611-214770.html"}], "tags": ["Raspberry Pi", "RAM-Preise", "Einplatinencomputer"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-03T06:30:37.229Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-09T18:18:56.053Z"}, {"id": "2026-11-02-rtx5090-pro5500-igorslab", "datum": "2026-11-02T05:30:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU"], "kategorie": "GPU", "titel": "RTX 5090 gegen RTX PRO 5500: igor'sLAB prüft, ob NVIDIAs Profikarte der Gaming-GPU die Chips wegnimmt", "schlagzeile": "Über 8.000 Euro für eine RTX 5090: Nimmt NVIDIAs Profikarte ihr die Chips weg?", "kurz": "Eine sofort lieferbare RTX 5090 kostete laut igor'sLAB am 1.11.2026 bei einem deutschen Händler 8.059 Euro, die UVP der Founders Edition liegt bei 2.099 Euro. Die Analyse prüft, ob NVIDIA passende GB202-Chips lieber in die kommende Profikarte RTX PRO 5500 steckt, die gleich viele Recheneinheiten hat. Das Ergebnis: wirtschaftlich plausibel, aber öffentlich nicht belegt.", "zusammenfassung": "igor'sLAB hat untersucht, warum die GeForce RTX 5090 zu ihrem ursprünglichen Preis kaum noch zu bekommen ist. In einer Händler-Stichprobe vom 1.11.2026 kostete eine sofort lieferbare INNO3D RTX 5090 iCHILL X3 bei ALTERNATE 8.059 Euro, eine ZOTAC Solid OC White bei Caseking 8.499 Euro. Die deutsche UVP der Founders Edition liegt bei 2.099 Euro, die Founders Edition ist dort aber als nicht verfügbar gelistet. Im Mittelpunkt steht die kommende RTX PRO 5500 Blackwell Workstation Edition: Sie nutzt laut Partnerangaben ebenfalls den großen GB202-Chip mit 170 aktiven Streaming-Multiprozessoren und 21.760 CUDA-Kernen, hat aber 84 GB GDDR7 mit ECC statt 32 GB. Reuters berichtete am 20.10.2026 unter Berufung auf anonyme Quellen von mehr als drei Millionen bestellten PRO-5500-Karten aus China zu rund 11.400 Dollar pro Stück. Damit hätte NVIDIA einen Anreiz, geeignete Chips eher in die teure Profikarte zu stecken als in die Gaming-Karte. igor'sLAB betont aber, dass das öffentlich nicht nachgewiesen ist: Es gibt weder Daten zur Chip-Ausbeute noch zur Verteilung der Chips auf die beiden Produkte. Zudem war die Versorgung mit Gaming-Karten schon vor den gemeldeten PRO-5500-Bestellungen knapp, und reguläre Lieferungen der Profikarte sollen erst im ersten Quartal 2027 beginnen. Als weiteren Engpass nennt die Analyse den GDDR7-Speicher, der laut TrendForce zunehmend für KI- und Serveranwendungen eingeplant wird. Die Rechenbeispiele zu Kosten und Margen im Artikel beruhen ausdrücklich auf frei gewählten Annahmen und sind keine echten NVIDIA-Zahlen. Das Fazit von igor'sLAB: Die Profikarte ist ein ernstzunehmender Konkurrent um Chips und Speicher, eine messbare Verdrängung der RTX 5090 ist aber nicht belegt.", "quelle": {"name": "igor'sLAB", "url": "https://www.igorslab.de/geforce-rtx-5090-wenn-selbst-der-teilaktivierte-chip-fuer-spieler-zu-wertvoll-wird-analyse/"}, "weitere_links": [], "tags": ["NVIDIA", "RTX 5090", "RTX PRO 5500", "GPU-Preise"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-02T06:19:23.739Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-09T07:49:02.896Z"}, {"id": "2026-11-01-linux-7-4-rc1", "datum": "2026-11-01T22:51:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux"], "kategorie": "Linux", "titel": "Linux 7.4-rc1 veröffentlicht: Größtes Merge-Window der Kernel-Geschichte, viel davon durch KI angestoßen", "schlagzeile": "Linux 7.4: Rekord-Update dank KI-Flut – und Torvalds findet das gut", "kurz": "Linus Torvalds hat die erste Testversion von Linux 7.4 veröffentlicht. Das Merge-Window war mit fast 20.000 Commits das größte der Kernel-Geschichte, ein großer Teil davon wurde durch KI-Werkzeuge angestoßen. Neu sind unter anderem Vorbereitungen für AMDs Zen-6-Prozessoren und HDMI 2.1 als Standard im AMDGPU-Treiber.", "zusammenfassung": "Linus Torvalds hat am Sonntagabend Linux 7.4-rc1 veröffentlicht und damit das Merge-Window planmäßig abgeschlossen. Laut Torvalds war es mit fast 20.000 Commits statt der üblichen rund 15.000 außergewöhnlich groß, laut Phoronix das größte der Kernel-Geschichte. Als Hauptgrund nennt Torvalds die Flut an KI-angestoßenen Änderungen. Er sieht das positiv: Es sei ihm deutlich lieber, wenn diese Arbeit im Merge-Window landet statt als Welle von Korrekturen in der Testphase. Ein weiterer Grund könnte laut Torvalds sein, dass Linux 7.4 als nächste Long-Term-Support-Version erwartet wird. Ein Drittel des Patches besteht nach seinen Worten allein aus AMD-GPU-Registerdefinitionen. Zu den Neuerungen zählen laut Phoronix die Unterstützung für kommende Ryzen-Prozessoren mit Zen 6, HDMI 2.1 als Standard im AMDGPU-Treiber und die Funktion AMD PerfOpt für bessere KI-Leistung auf Radeon-iGPUs. Dazu kommen Intel-IPU8-Unterstützung für kommende Nova-Lake-Laptops, mehr Unterstützung für Snapdragon-X2-Laptops, erste Grundlagen für Apples M4 (noch nicht alltagstauglich) und schnellere Kernel-Builds. Bis zur finalen Version folgen nun mehrere Testversionen. Läuft alles nach Plan, erscheint Linux 7.4 laut Phoronix am 20.12.2026. Normale Nutzer warten am besten, bis ihre Distribution den neuen Kernel ausliefert.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Linux-7.4-rc1"}, "weitere_links": [{"name": "LWN.net: Kernel prepatch 7.4-rc1", "url": "https://lwn.net/Articles/1104654/"}], "tags": ["Linux", "Kernel", "Linux 7.4", "AMD"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-02T06:19:23.831Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-09T07:49:02.897Z"}, {"id": "2026-11-01-gta6-210gb-download", "datum": "2026-11-01T20:31:00+01:00", "label": "Leak", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Games", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Stammt vom Daten-Account @PlaystationSize (wertet Store-Daten aus); Insider Gaming gibt an, die Zahl bestätigen zu können. Nicht offiziell von Rockstar oder Take-Two bestätigt; die Größe kann sich bis zum Start und durch einen Day-One-Patch ändern."}, "ursprungsquelle": "PlayStation Game Size (@PlaystationSize) auf X, 27.10.2026", "titel": "GTA 6: Download-Größe von 210 GB für die PS5 aufgetaucht", "schlagzeile": "Leak: Braucht GTA 6 satte 210 GB auf der PS5?", "kurz": "Laut dem Daten-Account PlayStation Game Size soll der PS5-Download von GTA 6 rund 210 GB groß sein, Insider Gaming will das bestätigen können. Offiziell hat Rockstar keine Größe genannt, die Zahl ist also unbestätigt. Fest steht: Digitale Vorbesteller dürfen ab dem 12.11.2026 vorladen, das Spiel erscheint am 19.11.2026.", "zusammenfassung": "Der auf Store-Daten spezialisierte X-Account PlayStation Game Size (@PlaystationSize) hat am 27.10.2026 eine Download-Größe von 210 GB für die Standard-Edition von Grand Theft Auto VI auf der PlayStation genannt. Insider Gaming berichtete am 1.11.2026 darüber und schreibt, die Angabe bestätigen zu können. Damit wäre GTA 6 laut Insider Gaming eines der größten Spiele überhaupt. Offiziell bestätigt haben Rockstar Games oder Take-Two die Größe bislang nicht, die Zahl gilt deshalb als unbestätigt. Auch Insider Gaming weist darauf hin, dass sich die Größe bis zum Start noch ändern kann und ein Day-One-Patch zusätzlichen Speicherplatz kosten könnte. Für die Xbox-Version nennt die Quelle keine Zahl. Offiziell bestätigt sind dagegen die Termine: Wer digital vorbestellt, kann laut Rockstar ab dem 12.11.2026 vorladen, das Spiel erscheint am 19.11.2026 für PlayStation 5 und Xbox Series X|S. Auch die Box-Version enthält laut Rockstar nur einen Download-Code und ist ebenfalls ab dem 12.11.2026 erhältlich. Die Standard-Edition kostet laut Rockstar 79,99 US-Dollar, die Ultimate Edition 99,99 US-Dollar. Wer zum Start loslegen will, sollte also rechtzeitig reichlich Platz auf der Konsole einplanen.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/gta-6-install-size-revealed-210-gb/"}, "weitere_links": [{"name": "Take-Two/Rockstar: Vorbestellung, Vorladen ab 12.11.2026, Start 19.11.2026 (offiziell)", "url": "https://taketwointeractivesoftwareinc.gcs-web.com/news-releases/news-release-details/rockstar-games-announces-pre-orders-grand-theft-auto-vi/"}], "tags": ["GTA 6", "Rockstar", "PS5", "Speicherplatz"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-02T06:19:23.784Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-08T19:51:18.696Z"}, {"id": "2026-11-01-windows11-26h2-alle", "datum": "2026-11-01T18:22:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11 26H2 jetzt für alle geeigneten PCs verfügbar, auch direkt von Windows 10", "schlagzeile": "Windows 11 26H2 ist jetzt für alle da – auch für Windows-10-PCs", "kurz": "Microsoft hat die schrittweise Verteilung von Windows 11 26H2 abgeschlossen: Laut Microsoft ist das Update seit dem 28.10.2026 für alle geeigneten Geräte verfügbar. Laut Neowin wird es nun auch kompatiblen Windows-10-PCs direkt über Windows Update angeboten. Voraussetzung bleibt, dass der PC die Hardware-Anforderungen von Windows 11 erfüllt.", "zusammenfassung": "Microsoft hat Windows 11 26H2 Ende September 2026 allgemein veröffentlicht, aber wie üblich schrittweise verteilt. So sollen größere Probleme nicht sofort viele Geräte auf einmal treffen, was vor allem für Unternehmen wichtig ist. Zunächst erreichte die Verteilung laut Neowin die volle Verfügbarkeit für Geräte mit Windows 11 25H2 und 24H2. Nun schreibt Microsoft, dass Windows 11 26H2 mit Stand 28.10.2026 für alle geeigneten Geräte verfügbar ist. Laut Neowin gilt das auch für kompatible Windows-10-PCs, denen das Update jetzt direkt über Windows Update angeboten wird. Die Redaktion hat das nach eigenen Angaben auf einem eigenen Windows-10-Rechner beobachtet. Wer bereits Windows 11 24H2 oder 25H2 nutzt und das Update noch nicht angeboten bekommt, kann laut Neowin das Enablement-Paket eKB5121794 manuell installieren. Das funktioniert allerdings nicht von Windows 10 oder älteren Windows-11-Versionen aus. Für eine Neuinstallation gibt es aktuelle ISO-Dateien über Microsofts Media Creation Tool. Laut Neowin braucht 26H2 weniger Arbeitsspeicher und fühlt sich flotter an, das ist allerdings eine Einschätzung der Redaktion. Ein Haken bleibt: Nur PCs, die die Hardware-Anforderungen von Windows 11 erfüllen, bekommen das Angebot.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-confirms-supported-windows-10-pcs-can-now-directly-update-to-windows-11-26h2/"}, "weitere_links": [], "tags": ["Windows 11", "26H2", "Windows 10", "Windows Update"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-02T06:19:23.876Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-08T18:07:06.246Z"}, {"id": "2026-11-01-rtx2080ti-22gb-pcgh", "datum": "2026-11-01T13:43:00+01:00", "label": "News", "kategorie": "Gebraucht-Hardware", "titel": "Gebrauchte RTX 2080 Ti mit 22 GB: PCGH testet den Speicher-Mod aus China", "schlagzeile": "22 GB auf einer alten RTX 2080 Ti: Wie gut ist der China-Mod wirklich?", "kurz": "PC Games Hardware hat eine RTX 2080 Ti getestet, deren Grafikspeicher in China von 11 auf 22 GB verdoppelt wurde. In 1440p ist der Unterschied meist klein, in 4K und bei KI-Aufgaben hängt die Mod-Karte das Original aber deutlich ab. Garantie gibt es für so einen Umbau keine.", "zusammenfassung": "PC Games Hardware hat eine modifizierte GeForce RTX 2080 Ti mit verdoppeltem Grafikspeicher getestet, die ein Leser über Alibaba gekauft hatte. Statt 11 GB sitzen auf der Platine elf 2-GB-Chips von Samsung, also 22 GB GDDR6 am unveränderten 352-Bit-Interface mit 616 GB/s. Ein geänderter Strap-Widerstand sorgt dafür, dass die Karte ohne modifiziertes BIOS und mit normalen Treibern läuft. In 1440p mit DLSS Quality fallen die Unterschiede zur 11-GB-Version meist klein aus, die Frametimes sind aber gleichmäßiger. In Microsoft Flight Simulator 2024 und Spider-Man 2 lag die Original-Karte laut Test rund 20 Prozent zurück. In 4K mit DLSS Performance und FSR Frame Generation stotterte die 11-GB-Karte stark, Indiana Jones stürzte sogar ab. Gemessen wurde eine Speicherbelegung von bis zu 13,9 GB in Spider-Man 2. Beim KI-Test mit ComfyUI brauchte die 22-GB-Karte etwa 315 Sekunden statt rund 540 Sekunden – eine RTX 5070 Ti schaffte dasselbe in etwa 85 Sekunden. Für Gebraucht-Käufer heißt das: Der Mod kann sich lohnen, ist aber ein Eingriff ohne Herstellergarantie, und die Qualität solcher Umbauten schwankt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/modded-geforce-rtx-2080-ti-22gb-tested-in-modern-games-doubled-vram-reduces-stuttering"}, "weitere_links": [{"name": "PCGH-Test (Original)", "url": "https://www.pcgameshardware.de/Geforce-RTX-2080-Ti-Grafikkarte-267862/Tests/RTX-2080-Ti-22GB-Alibaba-Hardware-Mod-Test-1554585/"}], "tags": ["NVIDIA", "Turing", "VRAM", "Mod", "Gebraucht"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-08T18:07:06.249Z"}, {"id": "2026-11-01-larrabee-fund", "datum": "2026-11-01T11:15:00+01:00", "label": "News", "kategorie": "Hardware-Geschichte", "titel": "Komplettes Intel-Larrabee-Entwicklersystem in Lagerraum entdeckt", "schlagzeile": "Fund im Lagerraum: Nie erschienene Intel-GPU samt Entwickler-PC entdeckt", "kurz": "Ein Reddit-Nutzer hat in einem ersteigerten Lagerabteil ein komplettes Entwicklersystem für Intels Larrabee-GPU entdeckt, die nie auf den Markt kam. Der Rechner startet Windows 7 und soll sogar Crysis darstellen, die FPS-Angaben sind allerdings nicht unabhängig geprüft. Die Original-Software liegt inzwischen im Internet Archive.", "zusammenfassung": "Ein Reddit-Nutzer hat bei der Versteigerung eines Lagerabteils ein vollständiges Entwicklungssystem für Intels nie erschienene Larrabee-GPU gefunden. Im Rechner steckt ein Intel-DX58SO-Mainboard mit einem Engineering-Sample im C0-Stepping, das als 'Intel Visual Adrenaline' bezeichnet wird. Dazu gehörten zwei USB-Sticks mit der Original-Software, die der Finder inzwischen im Internet Archive hochgeladen hat. Das System startet Windows 7 und unterstützt Direct3D. Laut Besitzer lief Crysis in 720p auf mittleren Details mit etwa 17 FPS, mit einem anderen Treiber angeblich mit rund 36 FPS – diese Werte sind nicht unabhängig geprüft. Intel hatte Larrabee als Grafikkarte 2010 eingestellt; die Technik lebte später in den Xeon-Phi-Beschleunigern weiter. Für Hardware-Sammler ist so ein vollständiges System mit Software eine echte Rarität.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/full-intel-larrabee-gpu-development-system-has-been-found-in-storage-unit-reportedly-runs-crysis"}, "weitere_links": [], "tags": ["Intel", "Larrabee", "Retro"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-08T18:07:06.250Z"}, {"id": "2026-10-31-nv-uefi-unlocker", "datum": "2026-10-31T16:10:00+01:00", "label": "News", "kategorie": "Tools & Mods", "titel": "Open-Source-Tool schaltet mehr KI-Leistung bei RTX 20, 30 und 40 frei", "schlagzeile": "Gratis-Tool holt bis zu 75 % mehr KI-Leistung aus RTX-Karten – mit Haken", "kurz": "Das Open-Source-Werkzeug „nv-uefi-unlocker“ schaltet bei RTX 20, 30 und 40 gedrosselte Recheneinheiten für KI-Aufgaben frei. In den genannten Tests stieg die Leistung je nach Karte und Aufgabe um rund 29 bis 75 Prozent. Für Spiele ist kein Vorteil belegt, Secure Boot muss aus, und die Nutzung erfolgt auf eigenes Risiko.", "zusammenfassung": "Der Entwickler physicsdolphin hat mit 'nv-uefi-unlocker' ein Open-Source-Werkzeug veröffentlicht, das bei GeForce-Karten gedrosselte Recheneinheiten für KI-Workloads freischalten soll. Das Tool startet per USB-Stick vor dem eigentlichen Treiber und funktioniert anschließend auch unter Windows. Die Änderung ist nicht dauerhaft und muss nach jedem Kaltstart erneut angewendet werden. Unterstützt werden RTX 20, 30 und 40, GTX 16 nur experimentell, RTX 50 gar nicht. Voraussetzung ist ein deaktiviertes Secure Boot, Turing-Karten brauchen zusätzlich GSP-Firmware. Genannte Ergebnisse: Eine RTX 2070 legte bei FP32-GEMM um 67 bis 75 Prozent zu, eine RTX 4060 Laptop-GPU stieg bei FP16 von 29,89 auf 49,33 TFLOPS. Ein Nutzer mit RTX 3080 LHR meldete in ComfyUI mit SDXL etwa 29 Prozent mehr Tempo, bei der Textgenerierung mit LLMs bringt das Tool dagegen wenig. Wer das ausprobiert, tut das auf eigenes Risiko – für Spiele-Performance ist kein Vorteil belegt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/modders-create-automated-tool-to-unlock-ai-performance-on-nvidia-geforce-rtx-20-30-and-40-series-gpus"}, "weitere_links": [], "tags": ["NVIDIA", "KI", "Tool", "Gebraucht"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-07T18:12:56.605Z"}, {"id": "2026-10-31-amd-adrenalin-26-10-2", "datum": "2026-10-31T13:30:00+01:00", "label": "News", "bereich": "software", "themen": ["Treiber"], "kategorie": "Grafiktreiber", "titel": "AMD Adrenalin 26.10.2: Optionaler Radeon-Treiber behebt zehn Fehler, mehrere Probleme bleiben offen", "schlagzeile": "Radeon-Abstürze: AMDs neuer Treiber behebt zehn Fehler – aber nicht alle", "kurz": "AMD hat den optionalen Grafiktreiber Adrenalin 26.10.2 veröffentlicht, der zehn Fehler behebt, darunter Treiber-Timeouts, Abstürze und Systemabschaltungen auf Radeon RX 7000 und RX 9000. Neue Spiele-Unterstützung bringt er nicht. Mehrere bekannte Probleme, etwa in Cyberpunk 2077 und Assassin's Creed Black Flag Resynced, bleiben offen.", "zusammenfassung": "AMD hat am 30.10.2026 den optionalen Grafiktreiber Adrenalin Edition 26.10.2 für Windows veröffentlicht. Laut den offiziellen Release Notes ist es ein reines Fehlerbehebungs-Update mit zehn Korrekturen. Behoben sind unter anderem Abstürze oder Treiber-Timeouts, wenn bei aktivem AMD-Leistungs-Overlay weitere Overlays wie die Xbox Game Bar geöffnet oder geschlossen werden. Auch der Steam-Client stürzte auf Radeon-Karten teils beim Start ab, das soll nun behoben sein. Auf der RX 7600 beseitigt der Treiber Systemabschaltungen in Valor Mortis, auf der übrigen RX-7000-Serie Treiber-Timeouts im selben Spiel. Für die RX-9000-Serie behebt AMD Hänger in Death Stranding 2 mit aktiviertem FSR und Abstürze beim Wechseln zwischen Anwendungen mit FSR Frame Generation. Dazu kommen Korrekturen bei der Videowiedergabe unter Windows 11 mit hardwarebeschleunigter GPU-Planung (HAGS) und ein Fehler im AMD Install Manager. Nicht alles ist gelöst: In Assassin's Creed Black Flag Resynced kann es auf der RX 7000 weiter zu Abstürzen kommen, in War Thunder auf der RX 5000 zu Timeouts. Für War Thunder empfiehlt AMD vorerst den älteren Treiber 26.9.1. In Cyberpunk 2077 kann es auf einigen RX-9000-Karten abstürzen, wenn FSR-Upscaling, Anti-Lag und Frame Generation aktiv sind und auf einem zweiten Bildschirm ein Video läuft; AMD rät dann, die Frame Generation im Spiel abzuschalten. Außerdem kann laut AMD unter Windows 10 nach der Installation Smart Access Memory deaktiviert sein, das sollte man im Zweifel im Treiber prüfen. Wer keines der behobenen Probleme hat, muss den optionalen Treiber nicht sofort installieren.", "quelle": {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/AMD-Adrenalin-26-10-2-Update-behebt-Treiberabstuerze-auf-Radeon-Grafikkarten-1558489/"}, "weitere_links": [{"name": "AMD: Release Notes Adrenalin Edition 26.10.2 (offiziell)", "url": "https://www.amd.com/en/resources/support-articles/release-notes/RN-RAD-WIN-26-10-2.html"}], "tags": ["AMD", "Radeon", "Treiber", "Adrenalin"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-02T06:19:23.915Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-07T18:12:56.606Z"}, {"id": "2026-10-31-altman-pc-ram", "datum": "2026-10-31T09:31:00+01:00", "label": "News", "kategorie": "Speicher & Markt", "titel": "Sam Altman: PC-RAM sei eine 'ziemlich schlechte' Nutzung knapper DRAM-Kapazität", "schlagzeile": "Sam Altman: Der RAM in deinem PC ist „ziemlich schlecht“ genutzt", "kurz": "Im Podcast „Cheeky Pint“ nannte OpenAI-Chef Sam Altman es „quite terrible“, dass DRAM in PCs steckt, die nach seiner groben Schätzung nur etwa fünf Prozent der Zeit laufen. Hintergrund ist die Speicherknappheit, weil Hersteller immer mehr Server- und KI-Speicher produzieren. Für PC-Bastler heißt das: RAM dürfte so schnell nicht billiger werden.", "zusammenfassung": "OpenAI-Chef Sam Altman hat im Podcast 'Cheeky Pint' mit Stripe-Mitgründer John Collison über die aktuelle Speicherknappheit gesprochen. Er bezeichnete es dort als 'quite terrible', dass DRAM in PCs stecke, die nur etwa fünf Prozent der Zeit genutzt würden. Die fünf Prozent sind seine eigene grobe Schätzung und keine belegte Zahl. Hintergrund ist, dass Speicherhersteller ihre Produktion zunehmend auf Server- und KI-Speicher verlagern, was die Preise für Endkunden-RAM treibt. VideoCardz widerspricht Altman in seinem Kommentar deutlich. Für PC-Bastler ist die Aussage vor allem ein Hinweis darauf, dass die RAM-Preise so schnell nicht wieder fallen dürften.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/openai-ceo-sam-altman-calls-pc-ram-a-quite-terrible-use-of-limited-dram-supply"}, "weitere_links": [], "tags": ["DRAM", "OpenAI", "Preise"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-07T18:12:56.606Z"}, {"id": "2026-10-30-linux-kernel-tcp-luecke", "datum": "2026-10-30T22:09:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux"], "kategorie": "Linux & Sicherheit", "titel": "Linux-Kernel: Schwere Lücke im TCP-Code ermöglicht Root-Angriffe aus der Ferne auf MPTCP-Server", "schlagzeile": "Linux: Kernel-Lücke erlaubt Root-Zugriff aus der Ferne – jetzt updaten", "kurz": "Eine Use-after-free-Lücke im IPv4-TCP-Code des Linux-Kernels (CVE-2026-98432) betrifft Kernel bis zurück zu Version 4.4. Forscher haben einen Root-Zugriff aus der Ferne auf Servern gezeigt, die Multipath-TCP (MPTCP) anbieten. Debian hat bereits Updates, andere Distributionen ziehen nach.", "zusammenfassung": "Laut BleepingComputer steckt im IPv4-TCP-Code des Linux-Kernels eine Use-after-free-Lücke, die durch eine Race Condition entsteht (CVE-2026-98432). Betroffen sind Kernel bis zurück zu Version 4.4. Das CVE-Team des Kernels bewertet die Lücke mit 9,8 von 10, Red Hat dagegen nur mit 5,9, weil die Ausnutzung komplex sei und vor allem Abstürze drohten. Forscher von Anthropic zeigten einen Root-Zugriff aus der Ferne auf Servern mit MPTCP-Listener; den Exploit erstellte laut Bericht ein unveröffentlichtes Claude-Modell in rund 53 Minuten. Normales TCP ist ebenfalls betroffen, dort wurde eine Codeausführung aber nicht gezeigt. Angriffe in freier Wildbahn sind nicht bestätigt. Heikel: Programme, die mit Go ab Version 1.24 gebaut sind, aktivieren MPTCP unter Linux standardmäßig. Das Go-Sicherheitsteam rät trotzdem zum Kernel-Update, statt MPTCP pro Programm abzuschalten, und MPTCP nur abzuschalten reicht laut Bericht ohnehin nicht. Debian hat korrigierte Kernel für Bookworm und Trixie veröffentlicht, bei Ubuntu waren Updates am 30. Oktober in Arbeit. RHEL 8 bis 10 sind betroffen, SUSE, Oracle und Amazon Linux hatten zu diesem Zeitpunkt teilweise Updates. Behoben ist die Lücke unter anderem in den Kernel-Versionen 6.1.190, 6.6.159, 6.12.113, 6.18.56 und 7.3. Wer Linux-Server betreibt, sollte den Kernel zügig aktualisieren und neu starten.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/linux-kernel-exploit-enables-remote-root-attacks-on-mptcp-servers/"}, "weitere_links": [{"name": "oss-security: Hinweis des Go-Sicherheitsteams zu MPTCP", "url": "https://www.openwall.com/lists/oss-security/2026/10/30/1"}, {"name": "LWN.net: Neue Stable-Kernel", "url": "https://lwn.net/Articles/1104192/"}], "tags": ["Linux", "Kernel", "Sicherheit", "CVE-2026-98432"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T22:22:29.601Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-07T01:52:19.889Z"}, {"id": "2026-10-30-windows-insider-suche", "datum": "2026-10-30T18:05:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows-Insider-Builds: Neue Suche mit Schiebereglern und Handy-Aktionen, Beta regelt App-Berechtigungen einzeln", "schlagzeile": "Windows 11 testet neue Suche mit Schiebereglern und Handy-Aktionen", "kurz": "Microsoft testet in neuen Insider-Builds eine überarbeitete Windows-Suche. Sie zeigt Schieberegler etwa für Lautstärke und Helligkeit direkt in den Ergebnissen und kann über Smartphone-Link Anrufe oder SMS starten. Die Beta-Build 26220.9836 erlaubt außerdem Kamera-, Mikrofon- und Standortrechte pro Desktop-App.", "zusammenfassung": "Microsoft hat am 30. Oktober neue Windows-11-Insider-Builds veröffentlicht, darunter Beta 26220.9836 und Experimental 26340.9843. In den Experimental-Kanälen startet eine neue Windows-Suche. Sie zeigt Schieberegler für Lautstärke, Helligkeit oder Mauszeigergröße direkt in den Ergebnissen. Über Smartphone-Link sollen sich Anrufe, SMS und „Nicht stören“ am Handy steuern lassen – zunächst mit Android, iPhone-Unterstützung soll Anfang nächsten Jahres folgen. Dazu kommen ausführlichere Ergebnisse mit Dateivorschau, Web-Antworten etwa zu Wetter und Aktien sowie Apps aus dem Store; das lässt sich unter Datenschutz und Sicherheit > Suche abschalten. Ergebnisse lassen sich filtern und per Daumen hoch oder runter bewerten. Die Suche öffnet sich vorerst unten in der Mitte, eine Anpassung an die Position der Taskleiste ist laut Microsoft in Arbeit. Laut Windows Report bringt die Beta-Build zudem Kamera-, Mikrofon- und Standortberechtigungen für einzelne Desktop-Apps, bisherige Entscheidungen bleiben erhalten. Wie bei allen Insider-Funktionen ist offen, ob und wann sie in der regulären Windows-Version landen.", "quelle": {"name": "Windows Insider Blog (Microsoft)", "url": "https://blogs.windows.com/windows-insider/2026/10/30/announcing-new-builds-for-30-october-2026/"}, "weitere_links": [{"name": "Windows Report: Beta-Build 26220.9836 mit Berechtigungen pro App", "url": "https://windowsreport.com/new-windows-11-beta-build-26220-9836-adds-individual-app-permissions-for-camera-microphone-and-location/"}], "tags": ["Windows 11", "Insider", "Suche"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T22:22:29.643Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-06T18:19:35.339Z"}, {"id": "2026-10-30-nova-lake-28c-prognose", "datum": "2026-10-30T14:25:00+01:00", "label": "Leak", "kategorie": "CPU", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Angebliche interne Intel-Folien, über Dritte geteilt; nicht unabhängig verifiziert, Ziele können sich geändert haben."}, "titel": "Nova Lake-S mit 28 Kernen: Interne Prognose nennt 16 bis 33 % mehr Gaming-Leistung", "schlagzeile": "Leak: Intels nächste Gaming-CPU soll bis zu 33 % schneller sein", "kurz": "Laut VideoCardz versprechen interne Intel-Prognosen für Nova Lake-S je nach Variante 16 bis 33 Prozent mehr Gaming-Leistung als der Core Ultra 9 285K. Ein Teil des Vorsprungs kommt allerdings vom schnelleren DDR5-8000-Speicher im Vergleich. Es sind unbestätigte Zielwerte, die sich bis zum Marktstart noch ändern können.", "zusammenfassung": "Laut VideoCardz zeigen interne Intel-Projektionen vom August 2026, wie viel schneller Nova Lake-S in Spielen werden soll. Grundlage ist Intels eigener 'Gaming Index', verglichen wird mit dem Core Ultra 9 285K. Eine 28-Kern-Variante mit 285 Watt PL1 soll bis zu 1,16-mal so schnell sein wie der 285K bei 250 Watt. Eine Variante mit zwei Compute-Tiles und 296 Watt soll bis zu 1,33-mal so schnell sein. Wichtig: Nova Lake lief dabei mit DDR5-8000 per XMP, Arrow Lake nur mit DDR5-6400 – ein Teil des Vorsprungs kommt also vom schnelleren Speicher. Weitere Angaben des X-Nutzers Haze, etwa +8 Prozent Single-Thread ohne und +17 Prozent mit großem Last-Level-Cache, sind laut VideoCardz nicht verifiziert. Solche Vorab-Prognosen sind Zielwerte und können sich bis zum Marktstart noch ändern. Offiziell hat Intel bislang nur bestätigt, dass Nova Lake auf dem 18A-P-Prozess basiert und weitere Details zur CES im Januar folgen.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/intel-nova-lake-s-28c-with-ddr5-8000-projected-to-deliver-16-to-33-higher-gaming-performance-than-core-ultra-9-285k-with-ddr5-6400"}, "weitere_links": [], "tags": ["Intel", "Nova Lake", "CPU"], "ursprungsquelle": "Haze (@Haze2K1) / angebliche Intel-Folien", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-06T18:19:35.340Z"}, {"id": "2026-10-30-rtx5080-marketplace", "datum": "2026-10-30T13:13:00+01:00", "label": "News", "kategorie": "GPU", "titel": "RTX 5080 verschwindet aus NVIDIAs US-Shop – nach der RTX 5090", "schlagzeile": "Erst die RTX 5090, jetzt die RTX 5080: NVIDIAs US-Shop wird leer", "kurz": "Die GeForce RTX 5080 ist aus dem offiziellen NVIDIA-Marketplace in den USA verschwunden, gut zwei Wochen nach der RTX 5090. Bei US-Händlern kostet die günstigste RTX 5080 rund das Doppelte ihrer UVP von 999 Dollar. Ein Produktionsende ist damit nicht belegt, das Angebot ist aber sichtbar knapp.", "zusammenfassung": "Die GeForce RTX 5080 ist aus dem offiziellen NVIDIA-Marketplace in den USA verschwunden, Reddit-Nutzern fiel das zuerst in der Filterliste auf. Bereits am 16. Oktober war die RTX 5090 entfernt worden, tauchte kurz mit 5.599 US-Dollar wieder auf und verschwand erneut – ihre UVP liegt bei 1.999 Dollar. Die günstigste RTX 5080 kostete am 28. Oktober bei US-Händlern 1.979,99 Dollar, bei Best Buy 1.999,99 Dollar, bei einer UVP von 999 Dollar. NVIDIA hatte zuvor bestritten, dass die RTX 5090 eingestellt sei. Alle Karten der RTX-50-Serie werden derzeit deutlich über UVP verkauft. Dass eine Karte aus dem Shop fliegt, beweist für sich genommen noch kein Produktionsende – es zeigt aber, wie knapp das Angebot ist.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/geforce-rtx-5080-disappears-from-nvidias-official-us-marketplace-following-rtx-5090-removal"}, "weitere_links": [], "tags": ["NVIDIA", "RTX 5080", "RTX 5090", "Preise"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-06T18:19:35.342Z"}, {"id": "2026-10-30-witcher4-sprecher", "datum": "2026-10-30T11:52:00+01:00", "label": "Leak", "bereich": "games", "themen": ["The Witcher 4"], "kategorie": "Games", "zuverlaessigkeit": {"stufe": "niedrig-mittel", "hinweis": "Aussagen von Synchronsprechern, teils nur aus zweiter Hand (Reddit, Event-Berichte) und teils unklar, für welches Projekt aufgenommen wurde; CD Projekt RED hat nichts bestätigt."}, "titel": "The Witcher 4: Aussagen von Synchronsprechern nähren Gerüchte um bekannte Figuren", "schlagzeile": "Leak: Kehren Rittersporn und Yennefer in The Witcher 4 zurück?", "kurz": "Mehrere Synchronsprecher haben sich zu The Witcher 4 geäußert und damit Spekulationen über bekannte Figuren ausgelöst. Der polnische Sprecher von Rittersporn sagt, er habe ein paar Sätze aufgenommen, Geralt-Sprecher Doug Cockle dagegen noch nichts. CD Projekt RED hat das nicht kommentiert.", "zusammenfassung": "Geralt-Sprecher Doug Cockle sagte laut ixbt.games Ende Oktober im Podcast von Kinda Funny Games, er habe noch nichts für The Witcher 4 aufgenommen und kenne den Umfang von Geralts Rolle nicht. Er rechne eher mit einer Nebenrolle. Jacek Kopczyński, die polnische Stimme von Rittersporn, sagte laut VGTimes bei der PSX Extreme Party am 5. September, er habe bereits einige Sätze für The Witcher 4 aufgenommen – „nicht viel“. Für das ebenfalls angekündigte Projekt „Songs of the Past“ habe er dagegen noch nichts eingesprochen. Laut Notebookcheck berichtete ein Reddit-Nutzer, Yennefer-Sprecherin Denise Gough habe bei einer Signierstunde erzählt, sie habe neue Dialoge rund um Ciri aufgenommen; für welches Projekt, ist unklar. Gough hatte 2025 gegenüber Eurogamer gesagt, ihre Beteiligung an The Witcher 4 sei ungewiss. CD Projekt RED hat keine dieser Aussagen kommentiert. Offiziell bestätigt ist: Ciri ist die Hauptfigur, und das Spiel erscheint für PC, PS5 und Xbox Series X|S. Co-CEO Michał Nowakowski nannte im August 2028 als angepeiltes Release-Fenster. Die nächsten Quartalszahlen legt CD Projekt am 24. November vor.", "quelle": {"name": "ixbt.games", "url": "https://ixbt.games/en/news/2026/10/30/dag-kokl-do-six-por-ne-nacal-ozvucivat-geralta-v-the-witcher-4.html"}, "weitere_links": [{"name": "VGTimes: Rittersporn-Sprecher hat Sätze für The Witcher 4 aufgenommen", "url": "https://vgtimes.com/gaming-news/166661-dandelion-is-coming-to-the-witcher-4-the-actor-has-already-recorded-lines-for-the-game.html"}, {"name": "Notebookcheck: Witcher-4-Leak deutet auf Rückkehr von beliebtem Charakter", "url": "https://www.notebookcheck.com/Witcher-4-Leak-deutet-auf-Rueckkehr-von-beliebtem-Charakter.1416537.0.html"}], "tags": ["The Witcher 4", "CD Projekt RED", "Ciri", "Gerücht"], "ursprungsquelle": "Aussagen der Sprecher (Kinda Funny Games Podcast, PSX Extreme Party 2026, Signierstunde laut Reddit-Nutzer)", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T22:22:29.677Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-06T18:19:35.342Z"}, {"id": "2026-10-30-amd-preiserhoehung", "datum": "2026-10-30T09:52:00+01:00", "label": "Leak", "kategorie": "GPU & Markt", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Händlerforum Board Channels; Preisdaten von Hardware Unboxed sind belegt, die geplante AMD-Erhöhung nicht."}, "titel": "AMD soll im November erneut Radeon- und GDDR6-Preise anheben", "schlagzeile": "Leak: Radeon-Karten könnten im November schon wieder teurer werden", "kurz": "Laut dem chinesischen Händlerforum Board Channels hat AMD die Radeon-Abgabepreise im Oktober angehoben und könnte im November nachlegen. Unabhängig davon stiegen die Grafikkartenpreise laut Hardware Unboxed in drei Monaten um rund 35 Prozent. AMD hat die geplante Erhöhung nicht bestätigt.", "zusammenfassung": "Nach Informationen aus dem chinesischen Händlerforum Board Channels hat AMD die Abgabepreise für Radeon-GPUs am 1. Oktober angehoben und könnte im November nachlegen. AMD überprüfe seine Preise quartalsweise, heißt es. Auch GDDR6-Speicher wurde im dritten Quartal um etwa 8 bis 10 Prozent teurer. Unabhängig davon hat Hardware Unboxed in zehn Ländern Grafikkartenpreise erfasst: Über drei Monate stiegen sie um rund 35 Prozent, allein im Oktober um 10 Prozent. Die RX 9060 XT 16GB wurde demnach 17 Prozent teurer, RX 9070 und RX 9070 XT jeweils etwa 12 Prozent. AMD hat die geplante Erhöhung nicht bestätigt. Wer eine Grafikkarte braucht, sollte die Preise beobachten – auch der Gebrauchtmarkt dürfte davon beeinflusst werden.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/amd-reportedly-plans-another-radeon-gpu-and-gddr6-price-increase-in-november"}, "weitere_links": [], "tags": ["AMD", "Radeon", "Preise", "GDDR6"], "ursprungsquelle": "Board Channels", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-06T18:19:35.342Z"}, {"id": "2026-10-30-intel-q3-nova-lake-18a-p", "datum": "2026-10-30T09:00:00+01:00", "label": "News", "kategorie": "CPU & Fertigung", "titel": "Intel-Quartalszahlen: Nova Lake auf 18A-P liegt vor dem Zeitplan, Details zur CES", "schlagzeile": "Intel drückt aufs Tempo: Nova Lake liegt vor dem Zeitplan", "kurz": "In der Telefonkonferenz zum dritten Quartal hat Intel bestätigt, dass Nova Lake als erstes Client-Produkt auf dem 18A-P-Prozess kommt und die Entwicklung vor dem Zeitplan liegt. Details soll es zur CES im Januar geben. Den PC-Markt sieht Intel wegen der hohen Speicherpreise allerdings in einer Korrektur.", "zusammenfassung": "In der Telefonkonferenz zum dritten Quartal 2026 (29. Oktober, US-Zeit) hat Intel bestätigt, dass Nova Lake das erste Client-Produkt auf dem 18A-P-Prozess wird. Die Entwicklung liege vor dem Zeitplan, und Intel erwartet doppelt so viele Design-Wins wie bei Panther Lake. Weitere Details sollen zur CES im Januar folgen. Die Ausbeute bei 18A verbessere sich laut Intel im zweistelligen Prozentbereich, 18A-P sei bis Jahresende auf Kurs. 18A-P soll bei gleicher Leistungsaufnahme etwa 9 Prozent mehr Takt oder bei gleichem Takt rund 18 Prozent weniger Verbrauch bringen. Für 14A wurde im Oktober das PDK 0.9 veröffentlicht, Version 1.0 folgt im ersten Quartal 2027, die Produktion ist für 2028 geplant. Bei den Servern kommen Diamond Rapids 2027 auf 18A-P und Coral Rapids 2028 auf 14A. Den PC-Markt sieht Intel dagegen in einer Korrektur, bis sich die Speicherpreise normalisieren – Intel rechnet mit rund 10 Prozent kleinerem Gesamtmarkt. Laut Tom's Hardware nimmt Intel zudem Panther-Lake-Kapazität vom Netz, um mehr Granite-Rapids-Server-CPUs zu bauen.", "quelle": {"name": "Tom's Hardware", "url": "https://www.tomshardware.com/pc-components/cpus/intel-confirms-nova-lake-will-use-advanced-18a-p-node-more-details-at-ces-company-says-its-taking-panther-lake-capacity-offline-to-build-more-granite-rapids-data-center-cpus"}, "weitere_links": [{"name": "Transkript (The Motley Fool)", "url": "https://www.fool.com/earnings/call-transcripts/2026/10/30/intel-intc-q3-2026-earnings-call-transcript/"}, {"name": "Notizen von harukaze5719 auf X", "url": "https://x.com/harukaze5719/status/2115983435156308476"}], "tags": ["Intel", "18A-P", "Nova Lake", "Quartalszahlen"], "datum_hinweis": "Uhrzeit geschätzt (Veröffentlichung am Morgen des 30.10.)", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-06T08:01:04.489Z"}, {"id": "2026-10-30-rtx5080-24gb", "datum": "2026-10-30T08:50:00+01:00", "label": "Leak", "kategorie": "GPU", "zuverlaessigkeit": {"stufe": "mittel", "hinweis": "Händlerforum Board Channels (China) plus BenchLife; mehrere Quellen, aber keine NVIDIA-Bestätigung."}, "titel": "RTX 5080 mit 24 GB soll bis Januar 2027 kommen und die 16-GB-Version ersetzen", "schlagzeile": "Leak: RTX 5080 mit 24 GB soll schon zum Jahreswechsel kommen", "kurz": "Laut Board Channels plant NVIDIA eine GeForce RTX 5080 mit 24 statt 16 GB, die zwischen Dezember 2026 und Januar 2027 zuerst in China starten soll. Die 16-GB-Version soll dort auslaufen. Name, Takt und Preis sind unbekannt, NVIDIA hat nichts bestätigt.", "zusammenfassung": "Laut einem Bericht aus dem chinesischen Händlerforum Board Channels (ChannelGate) plant NVIDIA eine GeForce RTX 5080 mit 24 GB Speicher. Sie soll frühestens im Dezember 2026 und spätestens im Januar 2027 in China starten. Die bisherige 16-GB-Version sowie die RTX 5090 D V2 sollen dort auslaufen, die Restbestände an 16-GB-GPUs reichen angeblich noch etwa zwei Monate. BenchLife hatte bereits am 12. Oktober von einem Start im ersten Quartal 2027 berichtet, Boardpartner hätten aber nur mündliche Hinweise erhalten. Die 50 Prozent mehr Speicher dürften über 3-GB-GDDR7-Module am gleichen Interface realisiert werden. Name, Taktraten und Preis sind unbekannt. Auch die X-Accounts hongxing2020 und MEGAsizeGPU hatten Anfang Oktober über ein Ende der 16-GB-Variante bzw. der GB202-Lieferungen für die RTX 5090 spekuliert. NVIDIA hat nichts davon bestätigt.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/nvidia-rtx-5080-24gb-reportedly-launching-by-january-2027-replacing-16gb-model"}, "weitere_links": [{"name": "harukaze5719 auf X", "url": "https://x.com/harukaze5719/status/2116049396433596798"}, {"name": "hongxing2020 auf X (10.10.)", "url": "https://x.com/hongxing2020/status/2108780640368017543"}, {"name": "MEGAsizeGPU auf X (10.10.)", "url": "https://x.com/Zed__Wang/status/2108815493599801608"}], "tags": ["NVIDIA", "RTX 5080", "GDDR7"], "ursprungsquelle": "Board Channels / BenchLife", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-06T08:01:04.490Z"}, {"id": "2026-10-29-windows11-kb5127936", "datum": "2026-10-29T13:00:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11: Optionales Update KB5127936 bringt neues Kontextmenü und Neuinstallation über die Cloud", "schlagzeile": "Windows 11: Vorschau-Update bringt neues Kontextmenü und Cloud-Reparatur", "kurz": "Microsoft hat für Windows 11 25H2 und 26H2 das optionale Vorschau-Update KB5127936 mit 41 Änderungen veröffentlicht. Dazu gehören ein schnelleres, anpassbares Kontextmenü im Explorer und eine Neuinstallation über Windows Update ohne USB-Stick. Für alle sollen die Neuerungen ab dem Patchday am 10. November ausrollen.", "zusammenfassung": "Microsoft hat am 28. Oktober das optionale Vorschau-Update KB5127936 für Windows 11 25H2 und 26H2 veröffentlicht; es enthält keine Sicherheitskorrekturen. Laut BleepingComputer steigen die Builds auf 26200.9818 bzw. 26300.9818, insgesamt sind es 41 Änderungen und Fehlerbehebungen. Das Kontextmenü im Datei-Explorer soll schneller öffnen und sich anpassen lassen. Mit „Cloud Rebuild“ lässt sich Windows über Windows Update neu installieren, ohne USB-Stick oder ISO-Datei – auch wenn das System nicht mehr startet. Der Xbox-Modus erhält eine überarbeitete Aufgabenansicht mit Navigationsleiste, etwa für „Zum Desktop“ und die Energieoptionen. Die Einstellungsseite „Datenschutz und Sicherheit“ fasst Kamera, Mikrofon und Standort zusammen, und die Wiederherstellungsumgebung WinRE kann gespeicherte WLAN-Profile nutzen. Der Ruhezustand wird adaptiv: Bei mehr als 80 Prozent Akku greift er seltener, unter 10 Prozent früher. Wegen der Aktualisierung von Secure-Boot-Zertifikaten kann ein zusätzlicher Neustart nötig sein. Installiert wird das Update über Einstellungen > Windows Update oder den Microsoft Update-Katalog. Microsoft verteilt die Funktionen schrittweise, sie erscheinen also nicht auf jedem PC sofort. Laut Thurrott sollen die Neuerungen ab dem Patchday am 10. November für alle ausrollen.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/windows-11-kb5127936-update-released-with-41-changes-and-fixes/"}, "weitere_links": [{"name": "Microsoft Support: KB5127936 (Builds 26300.9818 und 26200.9818)", "url": "https://support.microsoft.com/en-us/servicing/os/windows-11/2026/10/kb5127936-windows-11-25h2-26h2-update"}, {"name": "Thurrott: Week-D-Vorschau-Updates für Windows 11", "url": "https://www.thurrott.com/windows/windows-11/343340/microsoft-ships-the-week-d-preview-updates-for-windows-11"}], "tags": ["Windows 11", "Update", "KB5127936"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T22:22:29.720Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-05T18:40:22.540Z"}, {"id": "2026-10-29-gta6-edge-polizei", "datum": "2026-10-29T12:55:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Games", "titel": "GTA 6: Rockstar zeigt Polizei mit Hundestaffel, Busse nach Fahrplan und dynamisches Wetter", "schlagzeile": "GTA 6: Polizei mit Spürhunden, Busse und Züge nach Fahrplan", "kurz": "In einer Titelgeschichte des britischen Magazins Edge hat Rockstar neue Details zu GTA 6 verraten. Die Polizei findet Spieler über Kameras, Ortungsgeräte in Autos und Zeugenhinweise, außerdem gibt es eine Hundestaffel. GTA 6 erscheint am 19. November 2026 für PS5 und Xbox Series X|S.", "zusammenfassung": "Laut Polygon hat Rob Nelson, Co-Studiochef von Rockstar North, dem britischen Magazin Edge exklusiv neue Details zu Grand Theft Auto VI gegeben. Die Polizei soll Spieler über die letzte Sichtung, Überwachungskameras, Ortungsgeräte in Autos und Hinweise von Passanten aufspüren. Neu ist eine Hundestaffel: In der gezeigten Demo stellte ein Schäferhund Jason nach einem Motorradunfall. Passanten sollen eigene Charakterzüge haben – manche fliehen, andere greifen an. Busse und Züge fahren auf festen Routen nach Fahrplan; Entwicklungschef Phil Hooker sagte, er lege größten Wert darauf, dass sie immer pünktlich kommen. Das Wetter ist dynamisch, Wolken werden von Wind, Luftfeuchtigkeit, Nebel, Tageszeit und Jahreszeit geformt. Rockstar selbst hat auf X auf die Titelgeschichte in Edge-Ausgabe 430 hingewiesen. Laut Take-Two erscheint GTA 6 am 19. November 2026 für PlayStation 5 und Xbox Series X|S. Die Standard-Edition kostet in den USA 79,99 US-Dollar, die Ultimate Edition 99,99 US-Dollar. Der digitale Vorab-Download und die physische Edition sind ab 12. November geplant.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/grand-theft-auto-gta-6-rockstar-details-police-dogs-public-transportation-weather/"}, "weitere_links": [{"name": "Rockstar Games auf X: Hinweis auf die Edge-Titelgeschichte (30.10.2026)", "url": "https://x.com/RockstarGames/status/2116287925566550459"}, {"name": "Take-Two: Vorbestellungen, Termin und Preise von GTA VI", "url": "https://take2-games.com/ir/news/rockstar-games-announces-pre-orders-grand-theft-auto-vi"}], "tags": ["GTA 6", "Rockstar", "PS5", "Xbox"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T22:22:29.758Z"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-05T18:40:22.541Z"}, {"id": "2026-10-28-galax-dementi", "datum": "2026-10-28T12:00:00+01:00", "label": "News", "kategorie": "Hersteller", "titel": "Gerücht widerlegt: GALAX zieht sich nicht aus dem Grafikkartengeschäft zurück", "schlagzeile": "GALAX vor dem Aus? Der Hersteller sagt klar: Nein", "kurz": "Eine spanische Seite hatte „exklusiv“ berichtet, GALAX steige aus dem Grafikkartengeschäft aus. GALAX und Partner Palit haben das offiziell zurückgewiesen, die Produktion läuft normal weiter. Für Käufer von KFA2-Karten, wie GALAX in Europa heißt, ändert sich nichts.", "zusammenfassung": "Die spanische Seite El Chapuzas Informático hatte 'exklusiv' berichtet, GALAX steige wegen fehlender NVIDIA-Chips aus dem GPU-Markt aus und Palit schließe die zugehörige Fabrik. GALAX hat das in einer offiziellen Stellungnahme zurückgewiesen: Es seien keine Produktionsstätten geschlossen worden, das Geschäft laufe normal weiter. Auch Palit, das sich mit GALAX Fabriken teilt, bestätigte gegenüber Medien, dass die Produktion weitergeht. Ein ähnliches Gerücht gab es bereits im April im Zusammenhang mit einer Umstrukturierung unter dem Palit-Hauptsitz in Taiwan. Erst am 22. Oktober hatte GALAX noch die RTX 5080 HOF Extreme vorgestellt. Für Käufer von KFA2-Karten – so heißt GALAX in Europa – ändert sich nach jetzigem Stand nichts an Garantie oder Support. Der Fall zeigt, warum wir 'exklusive' Einzelberichte ohne Zweitquelle als unbestätigt kennzeichnen.", "quelle": {"name": "GALAX (offizielle Stellungnahme)", "url": "https://galax.com/en/news/official-statement-regarding-galaxs-business-operations/"}, "weitere_links": [{"name": "VideoCardz", "url": "https://videocardz.com/newz/palit-denies-galax-factory-closure-says-gpu-production-continues"}, {"name": "Tom's Hardware", "url": "https://www.tomshardware.com/pc-components/gpus/nvidia-rtx-gpu-vendor-palit-denies-its-galax-factory-has-closed-due-to-a-shortage-of-chips-company-says-brand-continues-to-operate-as-usual"}, {"name": "Ursprüngliches Gerücht (El Chapuzas Informático)", "url": "https://elchapuzasinformatico.com/2026/10/exclusiva-galax-abandona-el-mercado-de-las-gpu-no-hay-suficientes-chips-de-nvidia/"}], "tags": ["GALAX", "KFA2", "Palit", "Dementi"], "datum_hinweis": "Uhrzeit geschätzt", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "bereich": "hardware", "archiviert_am": "2026-11-04T11:08:46.948Z"}, {"id": "2026-10-25-ddr6-camm2", "datum": "2026-10-25T12:00:00+02:00", "label": "News", "kategorie": "Speicher", "titel": "DDR6: 192-Bit-Speicherinterfaces und CAMM2 statt klassischer DIMMs", "schlagzeile": "DDR6 kommt – und die klassischen RAM-Riegel könnten verschwinden", "kurz": "Für DDR6 ist nach bisherigem Stand das flache CAMM2-Format statt klassischer DIMM-Riegel vorgesehen, Desktop-CPUs sollen ein 192-Bit-Speicherinterface bekommen. Genannt werden Datenraten von 8.800 bis über 17.600 MT/s. Bei Endkunden ist DDR6 laut einer SK-Hynix-Roadmap aber nicht vor 2030 zu erwarten.", "zusammenfassung": "3DCenter hat zusammengetragen, was zum kommenden DDR6-Standard bekannt ist, und am 25. Oktober um einen Nachtrag ergänzt. DDR6 soll auf PAM4-Signalisierung setzen und mit 24 Bit breiten Speicherchips arbeiten. Ein Modul besteht demnach aus vier 24-Bit-Kanälen, die Speicherinterfaces der CPUs wachsen in 96-Bit-Schritten – im Desktop typischerweise auf 192 Bit. Als Bauform ist CAMM2 vorgesehen statt der heutigen UDIMM- und SO-DIMM-Riegel. Genannt werden Datenraten von 8.800 bis über 17.600 MT/s. Laut einer SK-Hynix-Roadmap ist mit DDR6 nicht vor 2029 im Server und 2030 bei Endkunden zu rechnen. Die JEDEC-Spezifikation ist noch nicht final, ein alternativer Vorschlag mit 16-Bit-Kanälen wird ebenfalls diskutiert.", "quelle": {"name": "3DCenter.org", "url": "https://www.3dcenter.org/news/ddr6-speicher-fuer-192-bit-speicherinterfaces-camm2-bauform-anstatt-udimm-sodimm"}, "weitere_links": [], "tags": ["DDR6", "CAMM2", "JEDEC"], "datum_hinweis": "Datum des Nachtrags; Uhrzeit geschätzt", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-01T21:15:01.074Z", "bereich": "hardware"}, {"id": "2026-10-02-core-ultra-4000-lineup", "datum": "2026-10-02T00:15:00+02:00", "label": "Leak", "kategorie": "CPU", "zuverlaessigkeit": {"stufe": "mittel-hoch", "hinweis": "Lineup-Leak, von kopite7kimi (hohe Zuverlässigkeit) kommentiert; von Intel nicht bestätigt."}, "titel": "Core Ultra 4000 'Nova Lake-S': Lineup mit Core Ultra 9 4970K BFC an der Spitze", "schlagzeile": "Leak: Intels 28-Kern-Flaggschiff mit Riesen-Cache soll AMDs X3D-Chips jagen", "kurz": "Eine durchgesickerte Liste nennt sieben Desktop-CPUs der Core-Ultra-4000-Serie, an der Spitze ein Core Ultra 9 4970K mit 28 Kernen und großem Cache. Der Extra-Cache gilt als Intels Antwort auf AMDs X3D-Prozessoren. Intel hat keine Modellnamen bestätigt, Details können sich noch ändern.", "zusammenfassung": "Anfang Oktober ist eine Liste mit sieben Desktop-Prozessoren der kommenden Core-Ultra-4000-Serie aufgetaucht. An der Spitze steht demnach ein Core Ultra 9 4970K 'BFC' mit 28 Kernen, großem Last-Level-Cache (bLLC) und 125 Watt Basis-Leistungsaufnahme, noch über dem 4950K. Der bLLC gilt als Intels Antwort auf AMDs X3D-Prozessoren mit 3D V-Cache. Der bekannte Leaker kopite7kimi kommentierte den Bericht am 13. Oktober: Der große Cache solle die Gaming-Leistung von Nova Lake retten, denn die regulären Modelle ohne bLLC seien in Spielen ähnlich schnell wie Arrow Lake. Intel selbst hat bisher keine Modellnamen genannt – offiziell ist nur der 18A-P-Prozess und eine Vorstellung zur CES. Modellnamen, Kernzahlen und TDP-Werte können sich bis zum Start noch ändern.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/intel-core-ultra-4000-nova-lake-s-lineup-leaks-core-ultra-9-4970k-bfc-appears-above-4950k"}, "weitere_links": [{"name": "kopite7kimi auf X (13.10.)", "url": "https://x.com/kopite7kimi/status/2109836679263711292"}], "tags": ["Intel", "Nova Lake", "Core Ultra 4000"], "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-01T21:15:01.074Z", "bereich": "hardware"}, {"id": "2026-09-21-kopite-gr20x-2028", "datum": "2026-09-21T05:46:00+02:00", "label": "Leak", "kategorie": "GPU", "zuverlaessigkeit": {"stufe": "hoch", "hinweis": "kopite7kimi hat eine lange Historie bei NVIDIA-Leaks; Zeitangaben sind aber unsicherer als technische Details."}, "titel": "kopite7kimi: NVIDIAs GR20x-Generation erst 2028", "schlagzeile": "Leak: Auf NVIDIAs nächste Gaming-Generation müssen wir wohl bis 2028 warten", "kurz": "Der bekannte Leaker kopite7kimi schreibt, NVIDIAs GR20x-Chips seien ein Produkt für 2028, die nächste Generation verschiebt sich also. Für 2027 wären damit eher Auffrischungen der RTX-50-Reihe denkbar. NVIDIA hat diesen Zeitplan nicht bestätigt.", "zusammenfassung": "Der bekannte NVIDIA-Leaker kopite7kimi schreibt auf X, dass die GR20x-Chips ein Produkt für 2028 seien – NVIDIA habe also erneut verschoben. Gemeint ist nach gängiger Lesart die Gaming-Generation nach Blackwell, die nach NVIDIAs Rechenzentrums-Architektur 'Rubin' benannt sein dürfte. Er kündigte zudem an, bis zu gesicherten Neuigkeiten weniger Updates zu posten, und verwies dabei auf 'Lessons learned' – offenbar eine Reaktion auf geänderte Pläne bei früheren Leaks. Unsere Einordnung: Für 2027 wären damit eher Auffrischungen der RTX-50-Reihe denkbar, etwa mit mehr Speicher wie bei der gemeldeten RTX 5080 24GB. NVIDIA selbst hat zu diesem Zeitplan nichts bestätigt. Auch bei zuverlässigen Leakern gilt: Termine verschieben sich häufiger als technische Eckdaten.", "quelle": {"name": "kopite7kimi auf X", "url": "https://x.com/kopite7kimi/status/2101880826422313319"}, "weitere_links": [], "tags": ["NVIDIA", "Rubin", "Roadmap"], "ursprungsquelle": "kopite7kimi", "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-01T17:57:00+01:00"}, "ki_unterstuetzt": true, "archiviert_am": "2026-11-01T21:15:01.075Z", "bereich": "hardware"}]};
